// ============================================================================
// Automatic Query Path Routing
// ============================================================================

/// Execution path for a query, automatically selected based on query analysis.
///
/// Inspired by Google Spanner's unified OLTP/OLAP routing (2025) and
/// pg_duckdb's embedded OLAP engine approach.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum QueryExecutionPath {
    /// B-tree path: best for point lookups and small range scans
    BTree,
    /// Columnar path: best for analytical queries (aggregations, full scans)
    Columnar,
    /// HDC/Holographic path: best for similarity search and fuzzy matching
    Holographic,
    /// Hybrid path: combines multiple paths for complex queries
    Hybrid,
}

/// Query characteristics used to select execution path
#[derive(Debug, Clone, Default)]
pub struct QueryProfile {
    /// Whether the query has equality predicates on indexed columns
    pub has_point_lookup: bool,
    /// Whether the query does a range scan
    pub has_range_scan: bool,
    /// Whether the query has aggregations (COUNT, SUM, AVG, etc.)
    pub has_aggregation: bool,
    /// Whether the query has GROUP BY
    pub has_group_by: bool,
    /// Whether the query involves similarity/fuzzy matching
    pub has_similarity_search: bool,
    /// Whether the query targets holographic/kv tables
    pub is_holographic_table: bool,
    /// Estimated result set size (0 = unknown)
    pub estimated_rows: usize,
    /// Number of columns projected
    pub projected_columns: usize,
}

/// Automatic query path router that profiles queries and selects optimal execution.
///
/// Based on:
/// - Google Spanner's automatic OLTP/OLAP routing (InfoQ 2025)
/// - HTAP architecture lessons showing vectorized execution is standard for OLAP
/// - Runtime feedback loop for adaptive optimization
pub struct QueryPathRouter {
    /// Historical execution statistics per path
    stats: QueryPathStats,
}

/// Statistics for query path routing decisions
#[derive(Debug, Clone, Default)]
pub struct QueryPathStats {
    /// Total queries routed to each path
    pub btree_count: u64,
    pub columnar_count: u64,
    pub holographic_count: u64,
    pub hybrid_count: u64,
    /// Average execution time per path (in microseconds)
    pub btree_avg_us: f64,
    pub columnar_avg_us: f64,
    pub holographic_avg_us: f64,
    pub hybrid_avg_us: f64,
}

impl QueryPathRouter {
    /// Create a new query path router
    pub fn new() -> Self {
        Self {
            stats: QueryPathStats::default(),
        }
    }

    /// Profile a SQL statement and determine its characteristics
    pub fn profile_query(&self, stmt: &joule_db_query::sql::SqlStatement) -> QueryProfile {
        let mut profile = QueryProfile::default();

        match stmt {
            joule_db_query::sql::SqlStatement::Select(query) => {
                // Check if targeting holographic table
                if let Some(ref from) = query.from {
                    match &from.source {
                        joule_db_query::sql::FromSource::Table(t) => {
                            if t == "holographic" || t == "kv" {
                                profile.is_holographic_table = true;
                            }
                        }
                        _ => {}
                    }
                }

                // Check for aggregations
                for col in &query.columns {
                    if is_aggregate_expr(&col.expr) {
                        profile.has_aggregation = true;
                    }
                }

                // Check GROUP BY
                if !query.group_by.is_empty() {
                    profile.has_group_by = true;
                }

                // Check WHERE clause for point lookups vs range scans
                if let Some(ref where_clause) = query.where_clause {
                    profile.has_point_lookup = is_point_lookup(where_clause);
                    profile.has_range_scan = is_range_scan(where_clause);
                    profile.has_similarity_search = is_similarity_search(where_clause);
                }

                profile.projected_columns = query.columns.len();
            }
            _ => {
                // INSERT/UPDATE/DELETE always use B-tree path
                profile.has_point_lookup = true;
            }
        }

        profile
    }

    /// Select the optimal execution path based on query profile
    pub fn select_path(&self, profile: &QueryProfile) -> QueryExecutionPath {
        // Rule 1: Holographic tables always use HDC path
        if profile.is_holographic_table || profile.has_similarity_search {
            return QueryExecutionPath::Holographic;
        }

        // Rule 2: Point lookups -> B-tree (fastest for single-row access)
        if profile.has_point_lookup && !profile.has_aggregation && !profile.has_group_by {
            return QueryExecutionPath::BTree;
        }

        // Rule 3: Aggregations and GROUP BY -> Columnar (vectorized execution)
        if profile.has_aggregation || profile.has_group_by {
            return QueryExecutionPath::Columnar;
        }

        // Rule 4: Large range scans -> Columnar
        if profile.has_range_scan && profile.estimated_rows > 1000 {
            return QueryExecutionPath::Columnar;
        }

        // Rule 5: Small range scans -> B-tree
        if profile.has_range_scan {
            return QueryExecutionPath::BTree;
        }

        // Default: B-tree for simple queries
        QueryExecutionPath::BTree
    }

    /// Record execution statistics for a path
    pub fn record_execution(&mut self, path: QueryExecutionPath, execution_us: u64) {
        match path {
            QueryExecutionPath::BTree => {
                self.stats.btree_count += 1;
                let n = self.stats.btree_count as f64;
                self.stats.btree_avg_us =
                    self.stats.btree_avg_us * (n - 1.0) / n + execution_us as f64 / n;
            }
            QueryExecutionPath::Columnar => {
                self.stats.columnar_count += 1;
                let n = self.stats.columnar_count as f64;
                self.stats.columnar_avg_us =
                    self.stats.columnar_avg_us * (n - 1.0) / n + execution_us as f64 / n;
            }
            QueryExecutionPath::Holographic => {
                self.stats.holographic_count += 1;
                let n = self.stats.holographic_count as f64;
                self.stats.holographic_avg_us =
                    self.stats.holographic_avg_us * (n - 1.0) / n + execution_us as f64 / n;
            }
            QueryExecutionPath::Hybrid => {
                self.stats.hybrid_count += 1;
                let n = self.stats.hybrid_count as f64;
                self.stats.hybrid_avg_us =
                    self.stats.hybrid_avg_us * (n - 1.0) / n + execution_us as f64 / n;
            }
        }
    }

    /// Get routing statistics
    pub fn stats(&self) -> &QueryPathStats {
        &self.stats
    }
}

impl Default for QueryPathRouter {
    fn default() -> Self {
        Self::new()
    }
}

fn is_point_lookup(expr: &Expression) -> bool {
    matches!(
        expr,
        Expression::Binary {
            op: Operator::Eq,
            ..
        }
    )
}

fn is_range_scan(expr: &Expression) -> bool {
    matches!(
        expr,
        Expression::Binary {
            op: Operator::Gt | Operator::Lt | Operator::Ge | Operator::Le,
            ..
        }
    )
}

fn is_similarity_search(expr: &Expression) -> bool {
    match expr {
        Expression::Function { name, .. } => {
            matches!(
                name.to_uppercase().as_str(),
                "SIMILAR_TO" | "FUZZY_MATCH" | "K_NEAREST" | "COSINE_SIMILARITY"
            )
        }
        Expression::Binary { left, right, .. } => {
            is_similarity_search(left) || is_similarity_search(right)
        }
        _ => false,
    }
}

/// Build query router
pub fn query_router(executor: Arc<dyn QueryExecutor>) -> axum::Router {
    use axum::routing::post;

    let state = QueryState { executor };

    // Provide a default AuthInfo with full access when no auth middleware is present
    let default_auth = crate::AuthInfo {
        user_id: "anonymous".to_string(),
        roles: vec!["superuser".to_string()],
        tenant_id: None,
    };

    axum::Router::new()
        .route("/api/v1/query", post(query_handler))
        .layer(Extension(default_auth))
        .with_state(state)
}

impl SimpleQueryExecutor {
    /// Try to short-circuit a simple aggregate query using columnar pre-computed data.
    /// Returns Some(response) if the query matches the pattern, None otherwise.
    fn try_columnar_aggregate(&self, query: &SqlQuery, start: Instant) -> Option<QueryResponse> {
        // Must be FROM a single real table
        let table_name = match &query.from {
            Some(from) => match &from.source {
                FromSource::Table(t) => t.clone(),
                _ => return None,
            },
            None => return None,
        };

        // All SELECT columns must be simple aggregate calls or COUNT(*)
        let mut result_cols = Vec::new();
        let mut result_vals = Vec::new();

        for col in &query.columns {
            match &col.expr {
                Expression::Function { name, args } => {
                    let agg_name = name.to_uppercase();
                    match agg_name.as_str() {
                        "COUNT" => {
                            if args.len() == 1 {
                                if let Expression::Column(ref c) = args[0] {
                                    if c == "*" {
                                        // COUNT(*) — use table row count
                                        let stats =
                                            self.amorphic.get_table_statistics(&table_name).ok()?;
                                        let alias = col
                                            .alias
                                            .clone()
                                            .unwrap_or_else(|| "COUNT(*)".to_string());
                                        result_cols.push(alias);
                                        result_vals.push(serde_json::json!(stats.row_count));
                                        continue;
                                    }
                                }
                            }
                            // COUNT(col) — count non-null values
                            if args.len() == 1 {
                                if let Expression::Column(ref c) = args[0] {
                                    let val = self
                                        .amorphic
                                        .columnar_aggregate(&table_name, "COUNT", c)
                                        .ok()??;
                                    let alias = col
                                        .alias
                                        .clone()
                                        .unwrap_or_else(|| format!("COUNT({})", c));
                                    result_cols.push(alias);
                                    result_vals.push(serde_json::json!(val as i64));
                                    continue;
                                }
                            }
                            return None;
                        }
                        "SUM" | "AVG" | "MIN" | "MAX" => {
                            if args.len() != 1 {
                                return None;
                            }
                            if let Expression::Column(ref c) = args[0] {
                                let val = self
                                    .amorphic
                                    .columnar_aggregate(&table_name, &agg_name, c)
                                    .ok()??;
                                let alias = col
                                    .alias
                                    .clone()
                                    .unwrap_or_else(|| format!("{}({})", agg_name, c));
                                result_cols.push(alias);
                                // Preserve integer type: if val is a whole number and the
                                // aggregate is SUM/MIN/MAX, return as integer
                                let json_val = if agg_name != "AVG"
                                    && val.fract() == 0.0
                                    && val >= i64::MIN as f64
                                    && val <= i64::MAX as f64
                                {
                                    serde_json::json!(val as i64)
                                } else {
                                    serde_json::json!(val)
                                };
                                result_vals.push(json_val);
                                continue;
                            }
                            return None;
                        }
                        _ => return None,
                    }
                }
                _ => return None, // Non-aggregate column — can't short-circuit
            }
        }

        if result_cols.is_empty() {
            return None;
        }

        Some(QueryResponse {
            columns: result_cols,
            rows: vec![result_vals],
            affected_rows: None,
            execution_time_ms: start.elapsed().as_millis() as u64,
            truncated: false,
            warnings: Vec::new(),
            energy_joules: None,
            power_watts: None,
            device_target: None,
            algorithm_type: None,
            session_id: None,
            viz_hint: None,
        })
    }

    fn execute_holographic_select(
        &self,
        query: &joule_db_query::sql::SqlQuery,
        _params: &[serde_json::Value],
        limit: Option<usize>,
        start: Instant,
    ) -> Result<QueryResponse, QueryErrorResponse> {
        // Optimization: Check for point lookup on key
        let rows = if let Some(ref where_clause) = query.where_clause {
            // Check if it's a simple key = literal lookup
            let is_point_lookup = match where_clause {
                Expression::Binary {
                    left,
                    op: Operator::Eq,
                    right,
                } => {
                    let left_col = match left.as_ref() {
                        Expression::Column(c) => Some(c.as_str()),
                        _ => None,
                    };
                    if left_col == Some("key") {
                        matches!(right.as_ref(), Expression::Literal(_))
                    } else {
                        // try reverse
                        let right_col = match right.as_ref() {
                            Expression::Column(c) => Some(c.as_str()),
                            _ => None,
                        };
                        right_col == Some("key") && matches!(left.as_ref(), Expression::Literal(_))
                    }
                }
                _ => false,
            };

            if is_point_lookup {
                self.holographic
                    .index_scan("holographic", "key", where_clause)
                    .map_err(|e| QueryErrorResponse::execution_error(&e.to_string()))?
            } else {
                self.holographic
                    .scan("holographic")
                    .map_err(|e| QueryErrorResponse::execution_error(&e.to_string()))?
            }
        } else {
            self.holographic
                .scan("holographic")
                .map_err(|e| QueryErrorResponse::execution_error(&e.to_string()))?
        };

        let mut result_rows = Vec::new();
        for row in rows {
            let k = match row.get("key") {
                Some(joule_db_query::ast::Value::Bytes(b)) => {
                    serde_json::Value::String(String::from_utf8_lossy(b).to_string())
                }
                Some(joule_db_query::ast::Value::String(s)) => serde_json::Value::String(s.clone()),
                _ => serde_json::Value::Null,
            };
            let v = match row.get("value") {
                Some(joule_db_query::ast::Value::Bytes(b)) => {
                    serde_json::Value::String(String::from_utf8_lossy(b).to_string())
                }
                Some(joule_db_query::ast::Value::String(s)) => serde_json::Value::String(s.clone()),
                _ => serde_json::Value::Null,
            };
            result_rows.push(vec![k, v]);
        }

        if let Some(l) = limit {
            if result_rows.len() > l {
                result_rows.truncate(l);
            }
        }

        Ok(QueryResponse {
            columns: vec!["key".to_string(), "value".to_string()],
            rows: result_rows,
            affected_rows: None,
            execution_time_ms: start.elapsed().as_millis() as u64,
            truncated: false,
            warnings: Vec::new(),
            energy_joules: None,
            power_watts: None,
            device_target: None,
            algorithm_type: None,
            session_id: None,
            viz_hint: None,
        })
    }

    fn execute_holographic_insert(
        &self,
        insert: &joule_db_query::sql::SqlInsert,
        _params: &[serde_json::Value],
        start: Instant,
    ) -> Result<QueryResponse, QueryErrorResponse> {
        let mut inserted = 0;

        let value_rows = match &insert.source {
            InsertSource::Values(v) => v.clone(),
            InsertSource::Select(_) => {
                return Err(QueryErrorResponse::execution_error(
                    "INSERT...SELECT not supported for holographic tables",
                ));
            }
        };
        for row_exprs in &value_rows {
            let cols = if !insert.columns.is_empty() {
                insert.columns.clone()
            } else {
                vec!["key".to_string(), "value".to_string()]
            };

            let mut key_val = joule_db_query::ast::Value::Null;
            let mut val_val = joule_db_query::ast::Value::Null;

            for (i, expr) in row_exprs.iter().enumerate() {
                let col_name = cols.get(i).map(|s| s.as_str()).unwrap_or("unknown");
                let val = match expr {
                    joule_db_query::ast::Expression::Literal(v) => v.clone(),
                    _ => joule_db_query::ast::Value::Null,
                };

                if col_name == "key" {
                    key_val = val;
                } else if col_name == "value" {
                    val_val = val;
                }
            }

            use joule_db_query::executor::RowData;
            let rd = RowData::new(
                vec!["key".to_string(), "value".to_string()],
                vec![key_val, val_val],
            );

            self.holographic
                .insert("holographic", &rd)
                .map_err(|e| QueryErrorResponse::execution_error(&e.to_string()))?;
            inserted += 1;
        }

        Ok(QueryResponse {
            columns: Vec::new(),
            rows: Vec::new(),
            affected_rows: Some(inserted),
            execution_time_ms: start.elapsed().as_millis() as u64,
            truncated: false,
            warnings: Vec::new(),
            energy_joules: None,
            power_watts: None,
            device_target: None,
            algorithm_type: None,
            session_id: None,
            viz_hint: None,
        })
    }
}

