    #[tokio::test]
    async fn test_columnar_aggregate_via_sql() {
        let executor = SimpleQueryExecutor::new();

        executor
            .execute(&QueryRequest {
                sql: "CREATE TABLE scores (name TEXT, score INT)".to_string(),
                params: Default::default(),
                args: Vec::new(),
                explain: false,
                limit: None,
                session_id: None,
                query_timeout_ms: None,
                branch_id: None,
                tenant_id: None,
            })
            .unwrap();

        for (name, score) in &[("Alice", 10), ("Bob", 20), ("Charlie", 30)] {
            executor
                .execute(&QueryRequest {
                    sql: format!("INSERT INTO scores VALUES ('{}', {})", name, score),
                    params: Default::default(),
                    args: Vec::new(),
                    explain: false,
                    limit: None,
                    session_id: None,
                    query_timeout_ms: None,
                    branch_id: None,
                    tenant_id: None,
                })
                .unwrap();
        }

        // SUM aggregate
        let response = executor
            .execute(&QueryRequest {
                sql: "SELECT SUM(score) FROM scores".to_string(),
                params: Default::default(),
                args: Vec::new(),
                explain: false,
                limit: None,
                session_id: None,
                query_timeout_ms: None,
                branch_id: None,
                tenant_id: None,
            })
            .unwrap();
        assert_eq!(response.rows.len(), 1);
        // SUM should be 60.0
        let sum_val = &response.rows[0][0];
        assert!(sum_val.as_f64().unwrap() - 60.0 < 0.001);

        // AVG aggregate
        let response = executor
            .execute(&QueryRequest {
                sql: "SELECT AVG(score) FROM scores".to_string(),
                params: Default::default(),
                args: Vec::new(),
                explain: false,
                limit: None,
                session_id: None,
                query_timeout_ms: None,
                branch_id: None,
                tenant_id: None,
            })
            .unwrap();
        assert_eq!(response.rows.len(), 1);
        let avg_val = &response.rows[0][0];
        assert!(avg_val.as_f64().unwrap() - 20.0 < 0.001);
    }

