    #[test]
    fn test_stale_session_cleanup() {
        let executor = SimpleQueryExecutor::new();

        // Create two transactions
        let r1 = executor
            .execute(&QueryRequest {
                sql: "BEGIN".to_string(),
                params: Default::default(),
                args: Vec::new(),
                explain: false,
                limit: None,
                session_id: None,
                query_timeout_ms: None,
                branch_id: None,
                tenant_id: None,
            })
            .unwrap();
        let _sid1 = r1.session_id.unwrap();

        let r2 = executor
            .execute(&QueryRequest {
                sql: "BEGIN".to_string(),
                params: Default::default(),
                args: Vec::new(),
                explain: false,
                limit: None,
                session_id: None,
                query_timeout_ms: None,
                branch_id: None,
                tenant_id: None,
            })
            .unwrap();
        let _sid2 = r2.session_id.unwrap();

        assert_eq!(executor.mvcc().active_session_count(), 2);

        // Cleanup with zero timeout should reap both
        let reaped = executor
            .mvcc()
            .cleanup_stale_sessions(std::time::Duration::from_secs(0));
        assert_eq!(reaped, 2);
        assert_eq!(executor.mvcc().active_session_count(), 0);
    }

