    #[test]
    fn test_having_with_sum() {
        let executor = SimpleQueryExecutor::new();
        executor
            .execute(&QueryRequest {
                sql: "CREATE TABLE sales (region TEXT, amount INT)".to_string(),
                params: Default::default(),
                args: Vec::new(),
                explain: false,
                limit: None,
                session_id: None,
                query_timeout_ms: None,
                branch_id: None,
                tenant_id: None,
            })
            .unwrap();

        for (region, amount) in &[("East", 100), ("East", 200), ("West", 50), ("North", 500)] {
            executor
                .execute(&QueryRequest {
                    sql: format!(
                        "INSERT INTO sales (region, amount) VALUES ('{}', {})",
                        region, amount
                    ),
                    params: Default::default(),
                    args: Vec::new(),
                    explain: false,
                    limit: None,
                    session_id: None,
                    query_timeout_ms: None,
                    branch_id: None,
                    tenant_id: None,
                })
                .unwrap();
        }

        let resp = executor
            .execute(&QueryRequest {
                sql:
                    "SELECT region, SUM(amount) FROM sales GROUP BY region HAVING SUM(amount) > 100"
                        .to_string(),
                params: Default::default(),
                args: Vec::new(),
                explain: false,
                limit: None,
                session_id: None,
                query_timeout_ms: None,
                branch_id: None,
                tenant_id: None,
            })
            .unwrap();

        // East: 300, West: 50, North: 500  =>  HAVING > 100 keeps East and North
        assert_eq!(resp.rows.len(), 2);
    }

