    #[tokio::test]
    async fn test_update_column_reference() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE t (id INT, age INT)");
        exec(&e, "INSERT INTO t (id, age) VALUES (1, 25)");
        exec(&e, "INSERT INTO t (id, age) VALUES (2, 30)");

        let resp = exec(&e, "UPDATE t SET age = age + 1");
        assert_eq!(resp.affected_rows, Some(2));

        let resp = exec(&e, "SELECT age FROM t WHERE id = 1");
        assert_eq!(resp.rows[0][0].as_i64().unwrap(), 26);
        let resp = exec(&e, "SELECT age FROM t WHERE id = 2");
        assert_eq!(resp.rows[0][0].as_i64().unwrap(), 31);
    }

