    #[tokio::test]
    async fn test_update_with_where_and_expression() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE emp (id INT, dept TEXT, salary INT)");
        exec(
            &e,
            "INSERT INTO emp (id, dept, salary) VALUES (1, 'eng', 100)",
        );
        exec(
            &e,
            "INSERT INTO emp (id, dept, salary) VALUES (2, 'sales', 80)",
        );
        exec(
            &e,
            "INSERT INTO emp (id, dept, salary) VALUES (3, 'eng', 120)",
        );

        let resp = exec(&e, "UPDATE emp SET salary = salary + 10 WHERE dept = 'eng'");
        assert_eq!(resp.affected_rows, Some(2));

        let resp = exec(&e, "SELECT salary FROM emp WHERE id = 1");
        assert_eq!(resp.rows[0][0].as_i64().unwrap(), 110); // eng: 100+10
        let resp = exec(&e, "SELECT salary FROM emp WHERE id = 2");
        assert_eq!(resp.rows[0][0].as_i64().unwrap(), 80); // sales: unchanged
        let resp = exec(&e, "SELECT salary FROM emp WHERE id = 3");
        assert_eq!(resp.rows[0][0].as_i64().unwrap(), 130); // eng: 120+10
    }

