    #[tokio::test]
    async fn test_order_by_expression_execution() {
        let e = SimpleQueryExecutor::new();
        exec(
            &e,
            "CREATE TABLE items (name TEXT, price INT, quantity INT)",
        );
        exec(
            &e,
            "INSERT INTO items (name, price, quantity) VALUES ('A', 10, 3)",
        );
        exec(
            &e,
            "INSERT INTO items (name, price, quantity) VALUES ('B', 5, 8)",
        );
        exec(
            &e,
            "INSERT INTO items (name, price, quantity) VALUES ('C', 20, 1)",
        );

        let resp = exec(
            &e,
            "SELECT name, price * quantity AS total FROM items ORDER BY price * quantity",
        );
        assert_eq!(resp.rows.len(), 3);
        assert_eq!(resp.rows[0][0].as_str().unwrap(), "C"); // 20*1=20
        assert_eq!(resp.rows[1][0].as_str().unwrap(), "A"); // 10*3=30
        assert_eq!(resp.rows[2][0].as_str().unwrap(), "B"); // 5*8=40
    }

