    #[tokio::test]
    async fn test_order_by_multiple_expressions() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE data (a INT, b INT, c TEXT)");
        exec(&e, "INSERT INTO data (a, b, c) VALUES (1, 2, 'x')");
        exec(&e, "INSERT INTO data (a, b, c) VALUES (1, 3, 'y')");
        exec(&e, "INSERT INTO data (a, b, c) VALUES (2, 1, 'z')");

        // ORDER BY a + b ASC, then c DESC as tiebreaker
        let resp = exec(&e, "SELECT c FROM data ORDER BY a + b, c DESC");
        assert_eq!(resp.rows.len(), 3);
        assert_eq!(resp.rows[0][0].as_str().unwrap(), "z"); // a+b=3, c='z' (DESC: z > x)
        assert_eq!(resp.rows[1][0].as_str().unwrap(), "x"); // a+b=3, c='x'
        assert_eq!(resp.rows[2][0].as_str().unwrap(), "y"); // a+b=4
    }

