    #[tokio::test]
    async fn test_count_col_filters_nulls() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE t (id INT, val INT)");
        exec(&e, "INSERT INTO t (id, val) VALUES (1, 10)");
        exec(&e, "INSERT INTO t (id, val) VALUES (2, NULL)");
        exec(&e, "INSERT INTO t (id, val) VALUES (3, 30)");
        exec(&e, "INSERT INTO t (id, val) VALUES (4, NULL)");

        // COUNT(*) should count all rows including NULLs
        let resp = exec(&e, "SELECT COUNT(*) FROM t");
        assert_eq!(resp.rows.len(), 1);
        assert_eq!(resp.rows[0][0], serde_json::json!(4));

        // COUNT(val) should only count non-NULL values
        let resp = exec(&e, "SELECT COUNT(val) FROM t");
        assert_eq!(resp.rows.len(), 1);
        assert_eq!(resp.rows[0][0], serde_json::json!(2));
    }

    #[tokio::test]
    async fn test_count_col_with_group_by() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE t (grp TEXT, val INT)");
        exec(&e, "INSERT INTO t (grp, val) VALUES ('a', 10)");
        exec(&e, "INSERT INTO t (grp, val) VALUES ('a', NULL)");
        exec(&e, "INSERT INTO t (grp, val) VALUES ('b', NULL)");
        exec(&e, "INSERT INTO t (grp, val) VALUES ('b', NULL)");

        let resp = exec(
            &e,
            "SELECT grp, COUNT(val) FROM t GROUP BY grp ORDER BY grp",
        );
        assert_eq!(resp.rows.len(), 2);
        // Group 'a': one non-null value
        assert_eq!(resp.rows[0][0], serde_json::json!("a"));
        assert_eq!(resp.rows[0][1], serde_json::json!(1));
        // Group 'b': zero non-null values
        assert_eq!(resp.rows[1][0], serde_json::json!("b"));
        assert_eq!(resp.rows[1][1], serde_json::json!(0));
    }

