    #[tokio::test]
    async fn test_ifnull_function() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE t (id INT, val INT)");
        exec(&e, "INSERT INTO t (id, val) VALUES (1, NULL)");
        exec(&e, "INSERT INTO t (id, val) VALUES (2, 42)");

        let resp = exec(&e, "SELECT IFNULL(val, 0) FROM t ORDER BY id");
        assert_eq!(resp.rows.len(), 2);
        assert_eq!(resp.rows[0][0], serde_json::json!(0));
        assert_eq!(resp.rows[1][0], serde_json::json!(42));

        // NVL is an alias
        let resp = exec(&e, "SELECT NVL(val, -1) FROM t ORDER BY id");
        assert_eq!(resp.rows[0][0], serde_json::json!(-1));
        assert_eq!(resp.rows[1][0], serde_json::json!(42));
    }

    #[tokio::test]
    async fn test_group_by_upper_function() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE t (name TEXT, val INT)");
        exec(&e, "INSERT INTO t (name, val) VALUES ('alice', 10)");
        exec(&e, "INSERT INTO t (name, val) VALUES ('Alice', 20)");
        exec(&e, "INSERT INTO t (name, val) VALUES ('BOB', 5)");
        exec(&e, "INSERT INTO t (name, val) VALUES ('bob', 15)");

        let resp = exec(
            &e,
            "SELECT UPPER(name), SUM(val) FROM t GROUP BY UPPER(name)",
        );
        assert_eq!(resp.rows.len(), 2);
        // Collect results into a map for order-independent assertion
        let mut results: std::collections::HashMap<String, f64> = std::collections::HashMap::new();
        for row in &resp.rows {
            let name = row[0].as_str().unwrap().to_string();
            let val = row[1].as_f64().unwrap();
            results.insert(name, val);
        }
        assert_eq!(results["ALICE"], 30.0);
        assert_eq!(results["BOB"], 20.0);
    }

    #[tokio::test]
    async fn test_group_by_arithmetic() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE t (price INT, qty INT)");
        exec(&e, "INSERT INTO t (price, qty) VALUES (10, 2)");
        exec(&e, "INSERT INTO t (price, qty) VALUES (10, 2)");
        exec(&e, "INSERT INTO t (price, qty) VALUES (20, 3)");

        let resp = exec(
            &e,
            "SELECT price * qty, COUNT(*) FROM t GROUP BY price * qty",
        );
        assert_eq!(resp.rows.len(), 2);
        // Collect results: key=product, value=count
        let mut results: std::collections::HashMap<i64, i64> = std::collections::HashMap::new();
        for row in &resp.rows {
            let product = row[0].as_i64().unwrap();
            let count = row[1].as_i64().unwrap();
            results.insert(product, count);
        }
        // 10*2=20 appears twice, 20*3=60 appears once
        assert_eq!(results[&20], 2);
        assert_eq!(results[&60], 1);
    }

