        let resp = exec(&e, "SELECT LPAD(s, 5, '*'), RPAD(s, 5, '*') FROM t");
        assert_eq!(resp.rows[0][0], serde_json::json!("***hi"));
        assert_eq!(resp.rows[0][1], serde_json::json!("hi***"));

        let resp = exec(&e, "SELECT REVERSE(s), REPEAT(s, 3) FROM t");
