    #[tokio::test]
    async fn test_full_outer_join() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE fj_emp (id INT, name TEXT, dept_id INT)");
        exec(&e, "CREATE TABLE fj_dept (id INT, dept_name TEXT)");
        exec(
            &e,
            "INSERT INTO fj_emp (id, name, dept_id) VALUES (1, 'Alice', 10)",
        );
        exec(
            &e,
            "INSERT INTO fj_emp (id, name, dept_id) VALUES (2, 'Bob', 99)",
        ); // no matching dept
        exec(
            &e,
            "INSERT INTO fj_dept (id, dept_name) VALUES (10, 'Engineering')",
        );
        exec(&e, "INSERT INTO fj_dept (id, dept_name) VALUES (30, 'HR')"); // no matching emp

        let resp = exec(
            &e,
            "SELECT fj_emp.name, fj_dept.dept_name FROM fj_emp FULL OUTER JOIN fj_dept ON fj_emp.dept_id = fj_dept.id",
        );
        assert_eq!(resp.rows.len(), 3);
        // Collect results for order-independent assertions
        let mut names: Vec<(Option<String>, Option<String>)> = resp
            .rows
            .iter()
            .map(|r| {
                (
                    r[0].as_str().map(String::from),
                    r[1].as_str().map(String::from),
                )
            })
            .collect();
        names.sort();
        assert_eq!(names[0], (None, Some("HR".to_string()))); // unmatched dept
        assert_eq!(
            names[1],
            (Some("Alice".to_string()), Some("Engineering".to_string()))
        );
        assert_eq!(names[2], (Some("Bob".to_string()), None)); // unmatched emp
    }

