    #[tokio::test]
    async fn test_ctas_if_not_exists() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE ctas_existing (id INT, name TEXT)");
        exec(
            &e,
            "INSERT INTO ctas_existing (id, name) VALUES (1, 'data')",
        );

        // Without IF NOT EXISTS, should fail
        let result = e.execute(&QueryRequest {
            sql: "CREATE TABLE ctas_existing AS SELECT 1 AS x".to_string(),
            params: Default::default(),
            args: Vec::new(),
            explain: false,
            limit: None,
            session_id: None,
            query_timeout_ms: None,
            branch_id: None,
            tenant_id: None,
        });
        assert!(result.is_err());

        // With IF NOT EXISTS, should succeed without modifying table
        exec(
            &e,
            "CREATE TABLE IF NOT EXISTS ctas_existing AS SELECT 42 AS x",
        );

        // Original data should remain
        let resp = exec(&e, "SELECT name FROM ctas_existing");
        assert_eq!(resp.rows.len(), 1);
        assert_eq!(resp.rows[0][0], serde_json::json!("data"));
    }

    // ── Step 4: INSERT ON CONFLICT (UPSERT) tests ──

    #[tokio::test]
    async fn test_upsert_do_nothing() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE ups_dn (id INT PRIMARY KEY, name TEXT)");
        exec(&e, "INSERT INTO ups_dn (id, name) VALUES (1, 'alice')");

        // This should not fail even though PK 1 already exists
        exec(
            &e,
            "INSERT INTO ups_dn (id, name) VALUES (1, 'bob') ON CONFLICT (id) DO NOTHING",
        );

        let resp = exec(&e, "SELECT name FROM ups_dn WHERE id = 1");
        assert_eq!(resp.rows.len(), 1);
        assert_eq!(resp.rows[0][0], serde_json::json!("alice")); // unchanged
    }

    #[tokio::test]
    async fn test_upsert_do_update() {
        let e = SimpleQueryExecutor::new();
        exec(
            &e,
            "CREATE TABLE ups_du (id INT PRIMARY KEY, name TEXT, score INT)",
        );
        exec(
            &e,
            "INSERT INTO ups_du (id, name, score) VALUES (1, 'alice', 80)",
        );

        // Upsert with DO UPDATE SET
        exec(
            &e,
            "INSERT INTO ups_du (id, name, score) VALUES (1, 'alice', 95) ON CONFLICT (id) DO UPDATE SET score = excluded.score",
        );

        let resp = exec(&e, "SELECT score FROM ups_du WHERE id = 1");
        assert_eq!(resp.rows.len(), 1);
        assert_eq!(resp.rows[0][0], serde_json::json!(95));
    }

