        // Insert multiple — first conflicts, second doesn't
        exec(
            &e,
            "INSERT INTO ups_mr (id, val) VALUES (1, 'x') ON CONFLICT (id) DO NOTHING",
        );
        exec(
            &e,
            "INSERT INTO ups_mr (id, val) VALUES (3, 'c') ON CONFLICT (id) DO NOTHING",
        );

