    #[tokio::test]
    async fn test_extract_chrono_accuracy() {
        let e = SimpleQueryExecutor::new();
        // 1710513045 = 2024-03-15 14:30:45 UTC
        exec(&e, "CREATE TABLE dt_ext (id INT PRIMARY KEY, ts TIMESTAMP)");
        exec(&e, "INSERT INTO dt_ext VALUES (1, 1710513045)");

        let resp = exec(
            &e,
            "SELECT EXTRACT(YEAR FROM ts), EXTRACT(MONTH FROM ts), EXTRACT(DAY FROM ts) FROM dt_ext WHERE id = 1",
        );
        assert_eq!(resp.rows[0][0], serde_json::json!(2024));
        assert_eq!(resp.rows[0][1], serde_json::json!(3));
        assert_eq!(resp.rows[0][2], serde_json::json!(15));

        let resp2 = exec(
            &e,
            "SELECT EXTRACT(HOUR FROM ts), EXTRACT(MINUTE FROM ts), EXTRACT(SECOND FROM ts) FROM dt_ext WHERE id = 1",
        );
        assert_eq!(resp2.rows[0][0], serde_json::json!(14));
        assert_eq!(resp2.rows[0][1], serde_json::json!(30));
        assert_eq!(resp2.rows[0][2], serde_json::json!(45));

        let resp3 = exec(
            &e,
            "SELECT EXTRACT(DOW FROM ts), EXTRACT(DOY FROM ts), EXTRACT(EPOCH FROM ts) FROM dt_ext WHERE id = 1",
        );
        assert_eq!(resp3.rows[0][0], serde_json::json!(5)); // Friday, Sun=0
        assert_eq!(resp3.rows[0][1], serde_json::json!(75)); // 75th day of 2024
        assert_eq!(resp3.rows[0][2], serde_json::json!(1710513045));
    }

