    #[tokio::test]
    async fn test_date_trunc_year_month() {
        let e = SimpleQueryExecutor::new();
        // 1710513045 = 2024-03-15 14:30:45 UTC
        exec(
            &e,
            "CREATE TABLE dt_trunc (id INT PRIMARY KEY, ts TIMESTAMP)",
        );
        exec(&e, "INSERT INTO dt_trunc VALUES (1, 1710513045)");

        // DATE_TRUNC('YEAR', ...) -> 2024-01-01 00:00:00 = 1704067200
        let resp = exec(
            &e,
            "SELECT DATE_TRUNC('YEAR', ts) FROM dt_trunc WHERE id = 1",
        );
        assert_eq!(resp.rows[0][0], serde_json::json!(1704067200));

        // DATE_TRUNC('MONTH', ...) -> 2024-03-01 00:00:00
        let resp2 = exec(
            &e,
            "SELECT DATE_TRUNC('MONTH', ts) FROM dt_trunc WHERE id = 1",
        );
        let march_1 = resp2.rows[0][0].as_i64().unwrap();
        // Verify it's March 1 by checking it's a round number
        let dt = chrono::DateTime::from_timestamp(march_1, 0).unwrap();
        assert_eq!(dt.day(), 1);
        assert_eq!(dt.month(), 3);
    }

    #[tokio::test]
    async fn test_date_trunc_day_hour() {
        let e = SimpleQueryExecutor::new();
        // 1710513045 = 2024-03-15 14:30:45 UTC
        exec(
            &e,
            "CREATE TABLE dt_trunc2 (id INT PRIMARY KEY, ts TIMESTAMP)",
        );
        exec(&e, "INSERT INTO dt_trunc2 VALUES (1, 1710513045)");

        // DATE_TRUNC('DAY', ...) -> 2024-03-15 00:00:00
        let resp = exec(
            &e,
            "SELECT DATE_TRUNC('DAY', ts) FROM dt_trunc2 WHERE id = 1",
        );
        let day_ts = resp.rows[0][0].as_i64().unwrap();
        // Should be exactly at midnight
        assert_eq!(day_ts % 86400, 0);

        // DATE_TRUNC('HOUR', ...) -> 2024-03-15 14:00:00
        let resp2 = exec(
            &e,
            "SELECT DATE_TRUNC('HOUR', ts) FROM dt_trunc2 WHERE id = 1",
        );
        let hour_ts = resp2.rows[0][0].as_i64().unwrap();
        assert_eq!(hour_ts % 3600, 0);
        assert!(hour_ts > day_ts);
    }

