    // --- information_schema + SHOW Tests ---

    #[tokio::test]
    async fn test_information_schema_tables() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE users (id INT, name TEXT)");
        exec(&e, "CREATE TABLE orders (id INT, total REAL)");
        let resp = exec(&e, "SELECT * FROM information_schema.tables");
        assert!(resp.columns.contains(&"table_name".to_string()));
        assert!(resp.columns.contains(&"table_type".to_string()));
        let table_names: Vec<&str> = resp
            .rows
            .iter()
            .map(|r| r[2].as_str().unwrap()) // table_name is 3rd column
            .collect();
        assert!(
            table_names.contains(&"users"),
            "tables should contain 'users': {:?}",
            table_names
        );
        assert!(
            table_names.contains(&"orders"),
            "tables should contain 'orders': {:?}",
            table_names
        );
    }

    #[tokio::test]
    async fn test_information_schema_columns() {
        let e = SimpleQueryExecutor::new();
        exec(
            &e,
            "CREATE TABLE products (id INT PRIMARY KEY, name TEXT NOT NULL, price REAL)",
        );
        let resp = exec(&e, "SELECT * FROM information_schema.columns");
        assert!(resp.columns.contains(&"column_name".to_string()));
        assert!(resp.columns.contains(&"data_type".to_string()));
        // Should have columns for 'products' table
        let col_names: Vec<&str> = resp
            .rows
            .iter()
            .filter(|r| r[2].as_str() == Some("products"))
            .map(|r| r[3].as_str().unwrap()) // column_name is 4th column
            .collect();
        assert!(col_names.contains(&"id"), "columns: {:?}", col_names);
        assert!(col_names.contains(&"name"), "columns: {:?}", col_names);
        assert!(col_names.contains(&"price"), "columns: {:?}", col_names);
    }

