    #[tokio::test]
    async fn test_information_schema_after_create_drop() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE temp_table (id INT)");
        let resp = exec(&e, "SELECT table_name FROM information_schema.tables");
        let names: Vec<&str> = resp.rows.iter().map(|r| r[0].as_str().unwrap()).collect();
        assert!(names.contains(&"temp_table"));

        exec(&e, "DROP TABLE temp_table");
        let resp2 = exec(&e, "SELECT table_name FROM information_schema.tables");
        let names2: Vec<&str> = resp2.rows.iter().map(|r| r[0].as_str().unwrap()).collect();
        assert!(!names2.contains(&"temp_table"));
    }

    #[tokio::test]
    async fn test_information_schema_column_ordering() {
        let e = SimpleQueryExecutor::new();
        exec(
            &e,
            "CREATE TABLE ordered (first_col INT, second_col TEXT, third_col REAL)",
        );
        let resp = exec(
            &e,
            "SELECT column_name, ordinal_position FROM information_schema.columns WHERE table_name = 'ordered'",
        );
        assert_eq!(resp.rows.len(), 3);
        // Check ordinal positions are 1, 2, 3
        for row in &resp.rows {
            let name = row[0].as_str().unwrap();
            let pos = row[1].as_i64().unwrap();
            match name {
                "first_col" => assert_eq!(pos, 1),
                "second_col" => assert_eq!(pos, 2),
                "third_col" => assert_eq!(pos, 3),
                _ => panic!("unexpected column: {}", name),
            }
        }
    }

