    #[tokio::test]
    async fn test_cte_reference_in_join() {
        let e = SimpleQueryExecutor::new();
        exec(
            &e,
            "CREATE TABLE employees (id INT, name TEXT, dept_id INT)",
        );
        exec(&e, "CREATE TABLE departments (id INT, dept_name TEXT)");
        exec(
            &e,
            "INSERT INTO employees (id, name, dept_id) VALUES (1, 'Alice', 10)",
        );
        exec(
            &e,
            "INSERT INTO employees (id, name, dept_id) VALUES (2, 'Bob', 20)",
        );
        exec(
            &e,
            "INSERT INTO departments (id, dept_name) VALUES (10, 'Engineering')",
        );
        exec(
            &e,
            "INSERT INTO departments (id, dept_name) VALUES (20, 'Marketing')",
        );
        let resp = exec(
            &e,
            "WITH eng AS (SELECT * FROM departments WHERE dept_name = 'Engineering') SELECT employees.name FROM employees INNER JOIN eng ON employees.dept_id = eng.id",
        );
        assert_eq!(resp.rows.len(), 1);
        assert_eq!(resp.rows[0][0], serde_json::json!("Alice"));
    }

