    #[tokio::test]
    async fn test_cte_nested_reference() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE nums (n INT)");
        exec(&e, "INSERT INTO nums (n) VALUES (1)");
        exec(&e, "INSERT INTO nums (n) VALUES (2)");
        exec(&e, "INSERT INTO nums (n) VALUES (3)");
        // CTE2 references CTE1
        let resp = exec(
            &e,
            "WITH base AS (SELECT n FROM nums WHERE n > 1), doubled AS (SELECT n * 2 AS d FROM base) SELECT d FROM doubled ORDER BY d",
        );
        assert_eq!(resp.rows.len(), 2);
        assert_eq!(resp.rows[0][0], serde_json::json!(4));
        assert_eq!(resp.rows[1][0], serde_json::json!(6));
    }

    // --- Statistical Aggregates Tests ---

    #[tokio::test]
    async fn test_stddev_pop() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE stats (val REAL)");
        // Values: 2, 4, 4, 4, 5, 5, 7, 9 — mean=5, var_pop=4, stddev_pop=2
        for v in [2, 4, 4, 4, 5, 5, 7, 9] {
            exec(&e, &format!("INSERT INTO stats (val) VALUES ({})", v));
        }
        let resp = exec(&e, "SELECT STDDEV_POP(val) AS sd FROM stats");
        assert_eq!(resp.rows.len(), 1);
        let sd = resp.rows[0][0].as_f64().unwrap();
        assert!(
            (sd - 2.0).abs() < 0.0001,
            "stddev_pop should be 2.0, got {}",
            sd
        );
    }

    #[tokio::test]
    async fn test_stddev_samp() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE stats (val REAL)");
        // Values: 2, 4, 4, 4, 5, 5, 7, 9 — N=8, mean=5, var_samp = 32/7 ≈ 4.5714
        for v in [2, 4, 4, 4, 5, 5, 7, 9] {
            exec(&e, &format!("INSERT INTO stats (val) VALUES ({})", v));
        }
        let resp = exec(&e, "SELECT STDDEV_SAMP(val) AS sd FROM stats");
        assert_eq!(resp.rows.len(), 1);
        let sd = resp.rows[0][0].as_f64().unwrap();
        let expected = (32.0_f64 / 7.0).sqrt(); // ≈ 2.1381
        assert!(
            (sd - expected).abs() < 0.001,
            "stddev_samp should be ~{}, got {}",
            expected,
            sd
        );
    }

