    #[tokio::test]
    async fn test_statistical_aggregates_with_null() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE stats (val REAL)");
        exec(&e, "INSERT INTO stats (val) VALUES (2)");
        exec(&e, "INSERT INTO stats (val) VALUES (4)");
        exec(&e, "INSERT INTO stats (val) VALUES (NULL)");
        exec(&e, "INSERT INTO stats (val) VALUES (6)");
        // Non-null values: 2, 4, 6 — mean=4, var_pop = (4+0+4)/3 = 8/3 ≈ 2.6667
        let resp = exec(
            &e,
            "SELECT STDDEV_POP(val) AS sd, MEDIAN(val) AS m FROM stats",
        );
        let sd = resp.rows[0][0].as_f64().unwrap();
        let expected_sd = (8.0_f64 / 3.0).sqrt(); // ≈ 1.6330
        assert!(
            (sd - expected_sd).abs() < 0.001,
            "stddev should exclude nulls, expected ~{}, got {}",
            expected_sd,
            sd
        );
        let m = resp.rows[0][1].as_f64().unwrap();
        assert!(
            (m - 4.0).abs() < 0.0001,
            "median should exclude nulls, expected 4.0, got {}",
            m
        );
    }

