    #[tokio::test]
    async fn test_subquery_int_float_comparison() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE ages (name TEXT, age INT)");
        exec(&e, "INSERT INTO ages (name, age) VALUES ('Alice', 20)");
        exec(&e, "INSERT INTO ages (name, age) VALUES ('Bob', 30)");
        exec(&e, "INSERT INTO ages (name, age) VALUES ('Carol', 40)");

        // AVG returns 30.0 (Float); age column is Int
        // WHERE age > (SELECT AVG(age)) should return Carol (40)
        let resp = exec(
            &e,
            "SELECT name FROM ages WHERE age > (SELECT AVG(age) FROM ages)",
        );
        assert_eq!(
            resp.rows.len(),
            1,
            "Expected 1 row for age > AVG, got {}",
            resp.rows.len()
        );
        assert_eq!(resp.rows[0][0].as_str().unwrap(), "Carol");
    }

