    #[tokio::test]
    async fn test_columnar_accel_skips_where() {
        // Queries with WHERE should NOT be columnar-accelerated (they still work via full SQL)
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE data (x INT)");
        exec(&e, "INSERT INTO data (x) VALUES (10)");
        exec(&e, "INSERT INTO data (x) VALUES (20)");

        let resp = exec(&e, "SELECT SUM(x) FROM data WHERE x > 5");
        assert_eq!(resp.rows.len(), 1);
        let sum = resp.rows[0][0]
            .as_f64()
            .unwrap_or(resp.rows[0][0].as_i64().unwrap_or(0) as f64);
        assert_eq!(sum, 30.0);
        // Result should NOT contain the columnar acceleration warning
        assert!(
            !resp.warnings.iter().any(|w| w.contains("columnar")),
            "WHERE queries should not be columnar-accelerated"
        );
    }

