    #[tokio::test]
    async fn test_fts_to_tsvector() {
        let e = SimpleQueryExecutor::new();

        let resp = exec(&e, "SELECT TO_TSVECTOR('The Quick Brown Fox Jumps')");
        assert_eq!(resp.rows.len(), 1);
        let vector = resp.rows[0][0].as_str().unwrap();
        // Standard analyzer: lowercase, stopwords removed, stemmed, sorted, deduped
        assert!(
            vector.contains("quick"),
            "Expected 'quick' in tsvector: {}",
            vector
        );
        assert!(
            vector.contains("brown"),
            "Expected 'brown' in tsvector: {}",
            vector
        );
        assert!(
            vector.contains("fox"),
            "Expected 'fox' in tsvector: {}",
            vector
        );
        assert!(
            vector.contains("jump"),
            "Expected 'jump' (stemmed) in tsvector: {}",
            vector
        );
        // "the" is a stopword and should be removed
        assert!(
            !vector.contains("the"),
            "'the' should be removed as stopword: {}",
            vector
        );
    }

    #[tokio::test]
    async fn test_fts_to_tsquery() {
        let e = SimpleQueryExecutor::new();

        let resp = exec(&e, "SELECT TO_TSQUERY('search AND query')");
        assert_eq!(resp.rows.len(), 1);
        let query = resp.rows[0][0].as_str().unwrap();
        // Standard analyzer: "and" is a stopword (removed), terms are stemmed, joined by &
        assert!(
            query.contains("search"),
            "Expected 'search' in tsquery: {}",
            query
        );
        assert!(
            query.contains("queri"),
            "Expected 'queri' (stemmed) in tsquery: {}",
            query
        );
        assert!(
            query.contains("&"),
            "Expected '&' separator in tsquery: {}",
            query
        );
    }

