    // ==================== RECURSIVE CTE TESTS ====================

    #[tokio::test]
    async fn test_recursive_cte_sequence() {
        let e = SimpleQueryExecutor::new();
        // Generate numbers 1-5 using recursive CTE
        let resp = exec(
            &e,
            "WITH RECURSIVE nums(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM nums WHERE n < 5) SELECT n FROM nums",
        );
        assert_eq!(resp.rows.len(), 5);
        // Check values 1..5
        let values: Vec<i64> = resp
            .rows
            .iter()
            .map(|r| match &r[0] {
                serde_json::Value::Number(n) => n.as_i64().unwrap(),
                _ => panic!("Expected number"),
            })
            .collect();
        assert_eq!(values, vec![1, 2, 3, 4, 5]);
    }

    #[tokio::test]
    async fn test_recursive_cte_hierarchy() {
        let e = SimpleQueryExecutor::new();
        exec(
            &e,
            "CREATE TABLE employees (id INT, name TEXT, manager_id INT)",
        );
        exec(
            &e,
            "INSERT INTO employees (id, name, manager_id) VALUES (1, 'CEO', 0)",
        );
        exec(
            &e,
            "INSERT INTO employees (id, name, manager_id) VALUES (2, 'VP', 1)",
        );
        exec(
            &e,
            "INSERT INTO employees (id, name, manager_id) VALUES (3, 'Director', 2)",
        );
        exec(
            &e,
            "INSERT INTO employees (id, name, manager_id) VALUES (4, 'Manager', 3)",
        );
        exec(
            &e,
            "INSERT INTO employees (id, name, manager_id) VALUES (5, 'Staff', 4)",
        );

        // Find all subordinates of VP (id=2) using recursive CTE
        let resp = exec(
            &e,
            "WITH RECURSIVE subordinates(id, name, manager_id) AS (\
               SELECT id, name, manager_id FROM employees WHERE id = 2 \
               UNION ALL \
               SELECT e.id, e.name, e.manager_id FROM employees e \
               INNER JOIN subordinates s ON e.manager_id = s.id\
             ) SELECT name FROM subordinates",
        );
        // Should include VP, Director, Manager, Staff
        assert_eq!(resp.rows.len(), 4);
    }

