    #[tokio::test]
    async fn test_recursive_cte_graph_path() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE edges (src INT, dst INT)");
        exec(&e, "INSERT INTO edges (src, dst) VALUES (1, 2)");
        exec(&e, "INSERT INTO edges (src, dst) VALUES (2, 3)");
        exec(&e, "INSERT INTO edges (src, dst) VALUES (3, 4)");
        exec(&e, "INSERT INTO edges (src, dst) VALUES (2, 5)");

        // Find all nodes reachable from node 1
        let resp = exec(
            &e,
            "WITH RECURSIVE reachable(node) AS (\
               SELECT 1 \
               UNION ALL \
               SELECT e.dst FROM edges e \
               INNER JOIN reachable r ON e.src = r.node\
             ) SELECT node FROM reachable",
        );
        // 1 -> 2, 2 -> 3, 3 -> 4, 2 -> 5 = 5 nodes total
        assert_eq!(resp.rows.len(), 5);
    }

