    // ====== Window Frame Bounds Tests ======

    #[tokio::test]
    async fn test_window_frame_rows_between_preceding_following() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE wf (id INT, val INT)");
        exec(&e, "INSERT INTO wf VALUES (1, 10)");
        exec(&e, "INSERT INTO wf VALUES (2, 20)");
        exec(&e, "INSERT INTO wf VALUES (3, 30)");
        exec(&e, "INSERT INTO wf VALUES (4, 40)");
        exec(&e, "INSERT INTO wf VALUES (5, 50)");

        // SUM with ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING
        let resp = exec(
            &e,
            "SELECT id, val, SUM(val) OVER (ORDER BY id ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING) as rolling_sum FROM wf ORDER BY id",
        );
        assert_eq!(resp.rows.len(), 5);
        // Row 1 (id=1): frame [1] -> 10+20 = 30
        // Row 2 (id=2): frame [1,2,3] -> 10+20+30 = 60
        // Row 3 (id=3): frame [2,3,4] -> 20+30+40 = 90
        // Row 4 (id=4): frame [3,4,5] -> 30+40+50 = 120
        // Row 5 (id=5): frame [4,5] -> 40+50 = 90
        let sums: Vec<i64> = resp
            .rows
            .iter()
            .map(|r| r[2].as_f64().unwrap() as i64)
            .collect();
        assert_eq!(sums, vec![30, 60, 90, 120, 90]);
    }

