    #[tokio::test]
    async fn test_window_frame_with_partition() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE wf8 (grp TEXT, id INT, val INT)");
        exec(&e, "INSERT INTO wf8 VALUES ('a', 1, 10)");
        exec(&e, "INSERT INTO wf8 VALUES ('a', 2, 20)");
        exec(&e, "INSERT INTO wf8 VALUES ('a', 3, 30)");
        exec(&e, "INSERT INTO wf8 VALUES ('b', 1, 100)");
        exec(&e, "INSERT INTO wf8 VALUES ('b', 2, 200)");

        // Frame within partitions
        let resp = exec(
            &e,
            "SELECT grp, id, val, SUM(val) OVER (PARTITION BY grp ORDER BY id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) as running FROM wf8 ORDER BY grp, id",
        );
        assert_eq!(resp.rows.len(), 5);
        let sums: Vec<i64> = resp
            .rows
            .iter()
            .map(|r| r[3].as_f64().unwrap() as i64)
            .collect();
        // Group 'a': 10, 30, 60
        // Group 'b': 100, 300
        assert_eq!(sums, vec![10, 30, 60, 100, 300]);
    }

    #[tokio::test]
    async fn test_window_frame_min_max() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE wf9 (id INT, val INT)");
        exec(&e, "INSERT INTO wf9 VALUES (1, 50)");
        exec(&e, "INSERT INTO wf9 VALUES (2, 10)");
        exec(&e, "INSERT INTO wf9 VALUES (3, 40)");
        exec(&e, "INSERT INTO wf9 VALUES (4, 20)");

        let resp = exec(
            &e,
            "SELECT id, val, MIN(val) OVER (ORDER BY id ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING) as wmin, \
                    MAX(val) OVER (ORDER BY id ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING) as wmax \
             FROM wf9 ORDER BY id",
        );
        let mins: Vec<i64> = resp
            .rows
            .iter()
            .map(|r| {
                r[2].as_f64()
                    .or_else(|| r[2].as_i64().map(|i| i as f64))
                    .unwrap() as i64
            })
            .collect();
        let maxs: Vec<i64> = resp
            .rows
            .iter()
            .map(|r| {
                r[3].as_f64()
                    .or_else(|| r[3].as_i64().map(|i| i as f64))
                    .unwrap() as i64
            })
            .collect();
        // Row 1 (50): frame [50,10] -> min=10, max=50
        // Row 2 (10): frame [50,10,40] -> min=10, max=50
        // Row 3 (40): frame [10,40,20] -> min=10, max=40
        // Row 4 (20): frame [40,20] -> min=20, max=40
        assert_eq!(mins, vec![10, 10, 10, 20]);
        assert_eq!(maxs, vec![50, 50, 40, 40]);
    }

    // ==================== Session 37: SQL Functions Completeness ====================

    #[tokio::test]
    async fn test_bitwise_operators() {
        let e = SimpleQueryExecutor::new();
        // AND
        let resp = exec(&e, "SELECT 12 & 10");
        assert_eq!(resp.rows[0][0].as_i64().unwrap(), 8); // 1100 & 1010 = 1000
        // OR
        let resp = exec(&e, "SELECT 12 | 10");
        assert_eq!(resp.rows[0][0].as_i64().unwrap(), 14); // 1100 | 1010 = 1110
        // XOR
        let resp = exec(&e, "SELECT 12 ^ 10");
        assert_eq!(resp.rows[0][0].as_i64().unwrap(), 6); // 1100 ^ 1010 = 0110
        // BIT NOT
        let resp = exec(&e, "SELECT ~0");
        assert_eq!(resp.rows[0][0].as_i64().unwrap(), -1);
    }

    #[tokio::test]
    async fn test_bitwise_in_table() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE perms (user_id INT, flags INT)");
        exec(&e, "INSERT INTO perms VALUES (1, 7)"); // rwx = 111
        exec(&e, "INSERT INTO perms VALUES (2, 5)"); // r-x = 101
        let resp = exec(&e, "SELECT user_id, flags & 2 FROM perms ORDER BY user_id");
        assert_eq!(resp.rows[0][1].as_i64().unwrap(), 2); // user 1 has write
        assert_eq!(resp.rows[1][1].as_i64().unwrap(), 0); // user 2 no write
    }

