    #[tokio::test]
    async fn test_regexp_replace() {
        let e = SimpleQueryExecutor::new();
        // Without 'g' flag: only first occurrence replaced
        let resp = exec(
            &e,
            "SELECT REGEXP_REPLACE('hello 123 world 456', '[0-9]+', 'NUM')",
        );
        assert_eq!(resp.rows[0][0].as_str().unwrap(), "hello NUM world 456");
        // With 'g' flag: all occurrences replaced
        let resp = exec(
            &e,
            "SELECT REGEXP_REPLACE('hello 123 world 456', '[0-9]+', 'NUM', 'g')",
        );
        assert_eq!(resp.rows[0][0].as_str().unwrap(), "hello NUM world NUM");
        let resp = exec(&e, "SELECT REGEXP_REPLACE('foo-bar-baz', '-', '_', 'g')");
        assert_eq!(resp.rows[0][0].as_str().unwrap(), "foo_bar_baz");
    }

