        // Create a trigger that inserts into audit_log after insert on users
        exec(
            &e,
            "CREATE TRIGGER trg_user_insert AFTER INSERT ON users FOR EACH ROW EXECUTE INSERT INTO audit_log (id, action, ts) VALUES (1, 'INSERT', 0)",
        );
