    #[tokio::test]
    async fn test_create_or_replace_trigger() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE log (msg TEXT)");
        exec(&e, "CREATE TABLE items (id INT PRIMARY KEY, name TEXT)");
        exec(
            &e,
            "CREATE TRIGGER trg1 AFTER INSERT ON items FOR EACH ROW EXECUTE INSERT INTO log (msg) VALUES ('old')",
        );
        exec(&e, "INSERT INTO items (id, name) VALUES (1, 'a')");
        let resp = exec(&e, "SELECT msg FROM log");
        assert_eq!(resp.rows[0][0].as_str().unwrap(), "old");
        // Replace the trigger
        exec(
            &e,
            "CREATE OR REPLACE TRIGGER trg1 AFTER INSERT ON items FOR EACH ROW EXECUTE INSERT INTO log (msg) VALUES ('new')",
        );
        exec(&e, "INSERT INTO items (id, name) VALUES (2, 'b')");
        let resp = exec(&e, "SELECT msg FROM log ORDER BY msg");
        // Should have 'new' from the replacement trigger and 'old' from earlier
        assert_eq!(resp.rows.len(), 2);
    }

