    #[tokio::test]
    async fn test_spatial_with_table_data() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE places (name TEXT, geom TEXT)");
        exec(
            &e,
            "INSERT INTO places (name, geom) VALUES ('NYC', 'POINT(-74.006 40.7128)')",
        );
        exec(
            &e,
            "INSERT INTO places (name, geom) VALUES ('London', 'POINT(-0.1278 51.5074)')",
        );
        exec(
            &e,
            "INSERT INTO places (name, geom) VALUES ('Paris', 'POINT(2.3522 48.8566)')",
        );

        // Find places within 500km of London
        let resp = exec(
            &e,
            "SELECT name FROM places WHERE ST_DWITHIN(geom, 'POINT(-0.1278 51.5074)', 500000) ORDER BY name",
        );
        assert!(resp.rows.len() >= 1); // At least London itself
        // London should be in the results
        let names: Vec<&str> = resp.rows.iter().map(|r| r[0].as_str().unwrap()).collect();
        assert!(names.contains(&"London"));
        // Paris is about 340km from London, so should be included
        assert!(names.contains(&"Paris"));
    }

