    #[tokio::test]
    async fn test_time_bucket_group_by() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE tb_grp_metrics (ts INT, value FLOAT)");
        exec(
            &e,
            "INSERT INTO tb_grp_metrics (ts, value) VALUES (10, 1.0)",
        );
        exec(
            &e,
            "INSERT INTO tb_grp_metrics (ts, value) VALUES (20, 2.0)",
        );
        exec(
            &e,
            "INSERT INTO tb_grp_metrics (ts, value) VALUES (70, 3.0)",
        );
        exec(
            &e,
            "INSERT INTO tb_grp_metrics (ts, value) VALUES (80, 4.0)",
        );
        // Bucket by 60s: ts 10,20 → bucket 0; ts 70,80 → bucket 60
        let resp = exec(
            &e,
            "SELECT TIME_BUCKET(60, ts) as bucket, AVG(value) FROM tb_grp_metrics GROUP BY TIME_BUCKET(60, ts) ORDER BY bucket",
        );
        assert_eq!(resp.rows.len(), 2);
        assert_eq!(resp.rows[0][0].as_i64().unwrap(), 0);
        assert_eq!(resp.rows[1][0].as_i64().unwrap(), 60);
    }

    #[tokio::test]
    async fn test_delta_window_function() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE delta_test (ts INT, val FLOAT)");
        exec(&e, "INSERT INTO delta_test (ts, val) VALUES (1, 10.0)");
        exec(&e, "INSERT INTO delta_test (ts, val) VALUES (2, 13.0)");
        exec(&e, "INSERT INTO delta_test (ts, val) VALUES (3, 20.0)");
        // Include val in SELECT so window function can reference it
        let resp = exec(
            &e,
            "SELECT ts, val, DELTA(val) OVER (ORDER BY ts) FROM delta_test ORDER BY ts",
        );
        assert_eq!(resp.rows.len(), 3);
        // First row: null
        assert!(resp.rows[0][2].is_null());
        // Second row: 13-10=3
        let d1 = resp.rows[1][2].as_f64().unwrap();
        assert!((d1 - 3.0).abs() < 0.01);
        // Third row: 20-13=7
        let d2 = resp.rows[2][2].as_f64().unwrap();
        assert!((d2 - 7.0).abs() < 0.01);
    }

    #[tokio::test]
    async fn test_rate_window_function() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE rate_test (ts INT, val FLOAT)");
        exec(&e, "INSERT INTO rate_test (ts, val) VALUES (0, 0.0)");
        exec(&e, "INSERT INTO rate_test (ts, val) VALUES (10, 50.0)");
        exec(&e, "INSERT INTO rate_test (ts, val) VALUES (20, 80.0)");
        let resp = exec(
            &e,
            "SELECT ts, val, RATE(val, ts) OVER (ORDER BY ts) FROM rate_test ORDER BY ts",
        );
        assert_eq!(resp.rows.len(), 3);
        // First: null
        assert!(resp.rows[0][2].is_null());
        // Second: (50-0)/(10-0)=5.0
        let r1 = resp.rows[1][2].as_f64().unwrap();
        assert!((r1 - 5.0).abs() < 0.01);
        // Third: (80-50)/(20-10)=3.0
        let r2 = resp.rows[2][2].as_f64().unwrap();
        assert!((r2 - 3.0).abs() < 0.01);
    }

    #[tokio::test]
    async fn test_locf_window_function() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE locf_test (ts INT, val TEXT)");
        exec(&e, "INSERT INTO locf_test (ts, val) VALUES (1, 'A')");
        exec(&e, "INSERT INTO locf_test (ts, val) VALUES (2, NULL)");
        exec(&e, "INSERT INTO locf_test (ts, val) VALUES (3, NULL)");
        exec(&e, "INSERT INTO locf_test (ts, val) VALUES (4, 'B')");
        exec(&e, "INSERT INTO locf_test (ts, val) VALUES (5, NULL)");
        // Include val in SELECT so window function can find it
        let resp = exec(
            &e,
            "SELECT ts, val, LOCF(val) OVER (ORDER BY ts) FROM locf_test ORDER BY ts",
        );
        assert_eq!(resp.rows.len(), 5);
        assert_eq!(resp.rows[0][2].as_str().unwrap(), "A");
        assert_eq!(resp.rows[1][2].as_str().unwrap(), "A"); // carried forward
        assert_eq!(resp.rows[2][2].as_str().unwrap(), "A"); // carried forward
        assert_eq!(resp.rows[3][2].as_str().unwrap(), "B");
        assert_eq!(resp.rows[4][2].as_str().unwrap(), "B"); // carried forward
    }

    #[tokio::test]
    async fn test_interpolate_window_function() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE interp_test (ts INT, val FLOAT)");
        exec(&e, "INSERT INTO interp_test (ts, val) VALUES (1, 10.0)");
        exec(&e, "INSERT INTO interp_test (ts, val) VALUES (2, NULL)");
        exec(&e, "INSERT INTO interp_test (ts, val) VALUES (3, NULL)");
        exec(&e, "INSERT INTO interp_test (ts, val) VALUES (4, 40.0)");
        // Include val in SELECT
        let resp = exec(
            &e,
            "SELECT ts, val, INTERPOLATE(val) OVER (ORDER BY ts) FROM interp_test ORDER BY ts",
        );
        assert_eq!(resp.rows.len(), 4);
        // Row 1: 10.0
        let v0 = resp.rows[0][2].as_f64().unwrap();
        assert!((v0 - 10.0).abs() < 0.01);
        // Row 2: interpolated between 10 and 40 at fraction 1/3 = 20.0
        let v1 = resp.rows[1][2].as_f64().unwrap();
        assert!((v1 - 20.0).abs() < 0.01);
        // Row 3: interpolated at fraction 2/3 = 30.0
        let v2 = resp.rows[2][2].as_f64().unwrap();
        assert!((v2 - 30.0).abs() < 0.01);
        // Row 4: 40.0
        let v3 = resp.rows[3][2].as_f64().unwrap();
        assert!((v3 - 40.0).abs() < 0.01);
    }

    #[tokio::test]
    async fn test_first_last_with_group_by() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE sensor (device TEXT, ts INT, val INT)");
        exec(
            &e,
            "INSERT INTO sensor (device, ts, val) VALUES ('a', 10, 100)",
        );
        exec(
            &e,
            "INSERT INTO sensor (device, ts, val) VALUES ('a', 30, 300)",
        );
        exec(
            &e,
            "INSERT INTO sensor (device, ts, val) VALUES ('a', 20, 200)",
        );
        exec(
            &e,
            "INSERT INTO sensor (device, ts, val) VALUES ('b', 5, 50)",
        );
        exec(
            &e,
            "INSERT INTO sensor (device, ts, val) VALUES ('b', 15, 150)",
        );
        let resp = exec(
            &e,
            "SELECT device, FIRST(val, ts), LAST(val, ts) FROM sensor GROUP BY device ORDER BY device",
        );
        assert_eq!(resp.rows.len(), 2);
        // device 'a': first at ts=10 → val=100, last at ts=30 → val=300
        assert_eq!(resp.rows[0][0].as_str().unwrap(), "a");
        assert_eq!(resp.rows[0][1].as_i64().unwrap(), 100);
        assert_eq!(resp.rows[0][2].as_i64().unwrap(), 300);
        // device 'b': first at ts=5 → val=50, last at ts=15 → val=150
        assert_eq!(resp.rows[1][0].as_str().unwrap(), "b");
        assert_eq!(resp.rows[1][1].as_i64().unwrap(), 50);
        assert_eq!(resp.rows[1][2].as_i64().unwrap(), 150);
    }

