    // ==================== Materialized View Tests ====================

    #[tokio::test]
    async fn test_create_materialized_view() {
        let e = SimpleQueryExecutor::new();
        exec(
            &e,
            "CREATE TABLE mv_src (id INT, category TEXT, amount FLOAT)",
        );
        exec(
            &e,
            "INSERT INTO mv_src (id, category, amount) VALUES (1, 'A', 100.0)",
        );
        exec(
            &e,
            "INSERT INTO mv_src (id, category, amount) VALUES (2, 'B', 200.0)",
        );
        exec(
            &e,
            "INSERT INTO mv_src (id, category, amount) VALUES (3, 'A', 150.0)",
        );

        // Create materialized view
        let resp = exec(
            &e,
            "CREATE MATERIALIZED VIEW mv_summary AS SELECT category, SUM(amount) as total FROM mv_src GROUP BY category",
        );
        assert_eq!(resp.columns[0], "result");

        // Query the materialized view
        let resp = exec(&e, "SELECT * FROM mv_summary ORDER BY category");
        assert_eq!(resp.rows.len(), 2);
    }

    #[tokio::test]
    async fn test_refresh_materialized_view() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE mv_ref_src (id INT, val INT)");
        exec(&e, "INSERT INTO mv_ref_src (id, val) VALUES (1, 10)");
        exec(&e, "INSERT INTO mv_ref_src (id, val) VALUES (2, 20)");

        exec(
            &e,
            "CREATE MATERIALIZED VIEW mv_ref AS SELECT SUM(val) as total FROM mv_ref_src",
        );
        let resp = exec(&e, "SELECT * FROM mv_ref");
        assert_eq!(resp.rows.len(), 1);
        let total = resp.rows[0][0].as_f64().unwrap();
        assert!((total - 30.0).abs() < 0.01);

        // Add more data
        exec(&e, "INSERT INTO mv_ref_src (id, val) VALUES (3, 30)");

        // Materialized view still shows old data
        let resp = exec(&e, "SELECT * FROM mv_ref");
        let total = resp.rows[0][0].as_f64().unwrap();
        assert!((total - 30.0).abs() < 0.01);

        // Refresh
        exec(&e, "REFRESH MATERIALIZED VIEW mv_ref");

        // Now shows updated data
        let resp = exec(&e, "SELECT * FROM mv_ref");
        let total = resp.rows[0][0].as_f64().unwrap();
        assert!((total - 60.0).abs() < 0.01);
    }

    #[tokio::test]
    async fn test_drop_materialized_view() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE mv_drop_src (id INT)");
        exec(&e, "INSERT INTO mv_drop_src (id) VALUES (1)");
        exec(
            &e,
            "CREATE MATERIALIZED VIEW mv_drop AS SELECT COUNT(*) as cnt FROM mv_drop_src",
        );

        // Verify it exists
        let resp = exec(&e, "SELECT * FROM mv_drop");
        assert_eq!(resp.rows.len(), 1);

        // Drop it
        exec(&e, "DROP MATERIALIZED VIEW mv_drop");

        // Querying should fail now (table not found)
        let result = e.execute(&QueryRequest {
            sql: "SELECT * FROM mv_drop".to_string(),
            params: Default::default(),
            args: Vec::new(),
            explain: false,
            limit: None,
            session_id: None,
            query_timeout_ms: None,
            branch_id: None,
            tenant_id: None,
        });
        assert!(result.is_err());
    }

