    #[tokio::test]
    async fn test_approx_count_distinct_basic() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE acd (id INT, category TEXT)");
        for i in 0..100 {
            exec(
                &e,
                &format!(
                    "INSERT INTO acd (id, category) VALUES ({}, 'cat_{}')",
                    i,
                    i % 10
                ),
            );
        }
        let resp = exec(&e, "SELECT APPROX_COUNT_DISTINCT(category) FROM acd");
        assert_eq!(resp.rows.len(), 1);
        let approx = resp.rows[0][0].as_i64().unwrap();
        // Should be approximately 10 (exact is 10)
        assert!(
            approx >= 8 && approx <= 12,
            "APPROX_COUNT_DISTINCT was {}, expected ~10",
            approx
        );
    }

