    #[tokio::test]
    async fn test_vector_index_create_and_knn() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE items (id INT, name TEXT, embedding TEXT)");
        exec(&e, "INSERT INTO items VALUES (1, 'a', '[1.0, 0.0, 0.0]')");
        exec(&e, "INSERT INTO items VALUES (2, 'b', '[0.0, 1.0, 0.0]')");
        exec(&e, "INSERT INTO items VALUES (3, 'c', '[0.0, 0.0, 1.0]')");
        exec(&e, "INSERT INTO items VALUES (4, 'd', '[0.9, 0.1, 0.0]')");
        exec(&e, "INSERT INTO items VALUES (5, 'e', '[-1.0, 0.0, 0.0]')");

        // Create vector index
        exec(&e, "CREATE VECTOR INDEX idx_items ON items (embedding)");

        // KNN query: find top-2 closest to [1.0, 0.0, 0.0]
        let resp = exec(
            &e,
            "SELECT name, L2_DISTANCE(embedding, '[1.0, 0.0, 0.0]') as dist FROM items ORDER BY dist LIMIT 2",
        );
        assert_eq!(resp.rows.len(), 2);
        // 'a' is exact match (distance 0), 'd' is closest (distance ~0.14)
        assert_eq!(resp.rows[0][0].as_str().unwrap(), "a");
        assert_eq!(resp.rows[1][0].as_str().unwrap(), "d");
    }

