    #[tokio::test]
    async fn test_vector_knn_inner_product() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE ip_items (id INT, embedding TEXT)");
        exec(&e, "INSERT INTO ip_items VALUES (1, '[1.0, 0.0, 0.0]')");
        exec(&e, "INSERT INTO ip_items VALUES (2, '[10.0, 0.0, 0.0]')");
        exec(&e, "INSERT INTO ip_items VALUES (3, '[-1.0, 0.0, 0.0]')");

        exec(
            &e,
            "CREATE VECTOR INDEX idx_ip ON ip_items (embedding) WITH (metric = 'inner_product')",
        );

        // SQL INNER_PRODUCT returns raw dot product (not negated).
        // For query [1,0,0]: IP with [10,0,0] = 10, IP with [1,0,0] = 1, IP with [-1,0,0] = -1
        // Ascending: -1 (id=3), 1 (id=1), 10 (id=2)
        // For "most similar" with IP, ORDER BY DESC is typical, but test ASC for consistency.
        let resp = exec(
            &e,
            "SELECT id, INNER_PRODUCT(embedding, '[1.0, 0.0, 0.0]') as ip FROM ip_items ORDER BY ip LIMIT 2",
        );
        assert_eq!(resp.rows.len(), 2);
        assert_eq!(resp.rows[0][0].as_i64().unwrap(), 3); // -1.0 (smallest)
        assert_eq!(resp.rows[1][0].as_i64().unwrap(), 1); // 1.0
    }

