    // ==================== P3: Spatial Index Tests ====================

    #[tokio::test]
    async fn test_spatial_index_distance_query() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE locations (id INT, name TEXT, geom TEXT)");
        exec(
            &e,
            "INSERT INTO locations (id, name, geom) VALUES (1, 'NYC', 'POINT(-74.006 40.7128)')",
        );
        exec(
            &e,
            "INSERT INTO locations (id, name, geom) VALUES (2, 'LA', 'POINT(-118.2437 33.9425)')",
        );
        exec(
            &e,
            "INSERT INTO locations (id, name, geom) VALUES (3, 'Newark', 'POINT(-74.1724 40.7357)')",
        );
        exec(&e, "CREATE SPATIAL INDEX idx_geom ON locations (geom)");

        // ST_DISTANCE uses Haversine (returns meters). NYC↔Newark ≈ 15 km.
        // Query within 25 km (25000 m) of NYC — should find NYC and Newark but not LA.
        let resp = exec(
            &e,
            "SELECT id, name FROM locations WHERE ST_DISTANCE(geom, ST_POINT(-74.006, 40.7128)) < 25000",
        );
        let ids: Vec<i64> = resp.rows.iter().filter_map(|r| r[0].as_i64()).collect();
        assert!(ids.contains(&1), "NYC should be found within radius");
        assert!(ids.contains(&3), "Newark should be found within radius");
        assert!(!ids.contains(&2), "LA should NOT be within 25 km of NYC");
    }

    #[tokio::test]
    async fn test_spatial_index_no_false_negatives() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE points (id INT, geom TEXT)");
        // Create a grid of points spanning 4×4 degrees
        for i in 0..5 {
            for j in 0..5 {
                exec(
                    &e,
                    &format!(
                        "INSERT INTO points (id, geom) VALUES ({}, 'POINT({}.0 {}.0)')",
                        i * 5 + j,
                        i,
                        j
                    ),
                );
            }
        }
        exec(&e, "CREATE SPATIAL INDEX idx_pts ON points (geom)");

        // ST_DISTANCE uses Haversine (meters). Max distance from center (2,2) to
        // corner (0,0) ≈ 314 km. Use 500 km (500000 m) to include all points.
        let resp = exec(
            &e,
            "SELECT id FROM points WHERE ST_DISTANCE(geom, ST_POINT(2.0, 2.0)) < 500000",
        );
        assert_eq!(
            resp.rows.len(),
            25,
            "All points should be within 500 km of center"
        );
    }

