    #[test]
    fn test_replication_broadcast_on_insert() {
        let repl_config = crate::replication::ReplicationConfig {
            listen_addr: "127.0.0.1:0".to_string(),
            ..crate::replication::ReplicationConfig::default()
        };
        let server = Arc::new(crate::replication::ReplicationServer::new(repl_config));
        // Subscribe to the broadcast channel before writing
        let _rx = server.subscribe();

        let mut e = SimpleQueryExecutor::new();
        e.set_replication_server(server.clone());
        e.set_replication_role("leader".to_string());
        exec(&e, "CREATE TABLE data (id INT, val TEXT)");
        exec(&e, "INSERT INTO data (id, val) VALUES (1, 'hello')");

        // Leader's LSN should have advanced (1 for CREATE TABLE, 1 for INSERT = 2 at minimum)
        assert!(server.current_lsn() >= 1, "LSN should advance after write");
    }

    #[test]
    fn test_replication_broadcast_on_update() {
        let repl_config = crate::replication::ReplicationConfig {
            listen_addr: "127.0.0.1:0".to_string(),
            ..crate::replication::ReplicationConfig::default()
        };
        let server = Arc::new(crate::replication::ReplicationServer::new(repl_config));
        let _rx = server.subscribe();

        let mut e = SimpleQueryExecutor::new();
        e.set_replication_server(server.clone());
        e.set_replication_role("leader".to_string());
        exec(&e, "CREATE TABLE data (id INT, val TEXT)");
        exec(&e, "INSERT INTO data (id, val) VALUES (1, 'hello')");

        let lsn_before = server.current_lsn();
        exec(&e, "UPDATE data SET val = 'world' WHERE id = 1");
        assert!(
            server.current_lsn() > lsn_before,
            "LSN should advance after UPDATE"
        );
    }

    #[test]
    fn test_replication_broadcast_on_delete() {
        let repl_config = crate::replication::ReplicationConfig {
            listen_addr: "127.0.0.1:0".to_string(),
            ..crate::replication::ReplicationConfig::default()
        };
        let server = Arc::new(crate::replication::ReplicationServer::new(repl_config));
        let _rx = server.subscribe();

        let mut e = SimpleQueryExecutor::new();
        e.set_replication_server(server.clone());
        e.set_replication_role("leader".to_string());
        exec(&e, "CREATE TABLE data (id INT, val TEXT)");
        exec(&e, "INSERT INTO data (id, val) VALUES (1, 'hello')");

        let lsn_before = server.current_lsn();
        exec(&e, "DELETE FROM data WHERE id = 1");
        assert!(
            server.current_lsn() > lsn_before,
            "LSN should advance after DELETE"
        );
    }

    #[test]
    fn test_replication_next_lsn_monotonic() {
        let repl_config = crate::replication::ReplicationConfig {
            listen_addr: "127.0.0.1:0".to_string(),
            ..crate::replication::ReplicationConfig::default()
        };
        let server = crate::replication::ReplicationServer::new(repl_config);
        let lsn1 = server.next_lsn();
        let lsn2 = server.next_lsn();
        let lsn3 = server.next_lsn();
        assert_eq!(lsn1, 1);
        assert_eq!(lsn2, 2);
        assert_eq!(lsn3, 3);
        assert_eq!(server.current_lsn(), 3);
    }

    #[test]
    fn test_no_replication_server_no_panic() {
        // Without replication_server set, writes should succeed without panicking
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE t (id INT)");
        exec(&e, "INSERT INTO t (id) VALUES (1)");
        exec(&e, "UPDATE t SET id = 2 WHERE id = 1");
        exec(&e, "DELETE FROM t WHERE id = 2");
        let resp = exec(&e, "SELECT * FROM t");
        assert_eq!(resp.rows.len(), 0);
    }

