    #[test]
    fn test_create_table_with_shard_by() {
        let e = SimpleQueryExecutor::new();
        exec(
            &e,
            "CREATE TABLE orders (id INT, customer_id INT, total REAL) SHARD BY (customer_id)",
        );
        // Table should be created
        let resp = exec(
            &e,
            "INSERT INTO orders (id, customer_id, total) VALUES (1, 100, 99.99)",
        );
        assert_eq!(resp.affected_rows, Some(1));
        // Shard metadata should be persisted
        let sk = crate::get_shard_key(&e.amorphic, "orders");
        assert_eq!(sk, Some("customer_id".to_string()));
    }

    #[test]
    fn test_shard_metadata_persisted() {
        let e = SimpleQueryExecutor::new();
        exec(
            &e,
            "CREATE TABLE events (id INT, tenant TEXT) SHARD BY (tenant)",
        );
        let tables = crate::list_sharded_tables(&e.amorphic);
        assert_eq!(tables.len(), 1);
        assert_eq!(tables[0].0, "events");
        assert_eq!(tables[0].1, "tenant");
    }

    #[test]
    fn test_shard_metadata_removed_on_drop() {
        let e = SimpleQueryExecutor::new();
        exec(
            &e,
            "CREATE TABLE sharded (id INT, region TEXT) SHARD BY (region)",
        );
        assert!(crate::get_shard_key(&e.amorphic, "sharded").is_some());
        exec(&e, "DROP TABLE sharded");
        // Shard metadata should be cleaned up
        assert!(crate::get_shard_key(&e.amorphic, "sharded").is_none());
    }

    #[test]
    fn test_non_sharded_table_has_no_shard_key() {
        let e = SimpleQueryExecutor::new();
        exec(&e, "CREATE TABLE plain (id INT, name TEXT)");
        assert!(crate::get_shard_key(&e.amorphic, "plain").is_none());
    }

    #[test]
    fn test_multiple_sharded_tables() {
        let e = SimpleQueryExecutor::new();
        exec(
            &e,
            "CREATE TABLE orders (id INT, tenant_id INT) SHARD BY (tenant_id)",
        );
        exec(
            &e,
            "CREATE TABLE events (id INT, region TEXT) SHARD BY (region)",
        );
        exec(&e, "CREATE TABLE plain (id INT)");

        let tables = crate::list_sharded_tables(&e.amorphic);
        assert_eq!(tables.len(), 2);
        let names: Vec<&str> = tables.iter().map(|(n, _)| n.as_str()).collect();
        assert!(names.contains(&"orders"));
        assert!(names.contains(&"events"));
    }

    #[test]
    fn test_sharded_table_still_operates_normally() {
        let e = SimpleQueryExecutor::new();
        exec(
            &e,
            "CREATE TABLE data (id INT, region TEXT, value TEXT) SHARD BY (region)",
        );
        exec(
            &e,
            "INSERT INTO data (id, region, value) VALUES (1, 'us-east', 'hello')",
        );
        exec(
            &e,
            "INSERT INTO data (id, region, value) VALUES (2, 'eu-west', 'world')",
        );

        let resp = exec(&e, "SELECT * FROM data ORDER BY id");
        assert_eq!(resp.rows.len(), 2);

        exec(&e, "UPDATE data SET value = 'updated' WHERE id = 1");
        let resp2 = exec(&e, "SELECT value FROM data WHERE id = 1");
        assert_eq!(resp2.rows[0][0], serde_json::json!("updated"));

        exec(&e, "DELETE FROM data WHERE id = 2");
        let resp3 = exec(&e, "SELECT * FROM data");
        assert_eq!(resp3.rows.len(), 1);
    }

    #[test]
    fn test_is_read_only_query() {
        assert!(is_read_only_query("SELECT * FROM users"));
        assert!(is_read_only_query("  SELECT id FROM t"));
        assert!(is_read_only_query("SHOW TABLES"));
        assert!(is_read_only_query("DESCRIBE users"));
        assert!(is_read_only_query("EXPLAIN SELECT 1"));
        assert!(!is_read_only_query("INSERT INTO t VALUES (1)"));
        assert!(!is_read_only_query("UPDATE t SET a = 1"));
        assert!(!is_read_only_query("DELETE FROM t"));
        assert!(!is_read_only_query("CREATE TABLE t (id INT)"));
        assert!(!is_read_only_query("DROP TABLE t"));
    }

