    #[cfg(feature = "viz")]
    #[test]
    fn test_extract_select_metadata_group_by() {
        use joule_db_query::sql::{SqlParser, SqlStatement};
        let mut parser = SqlParser::new();
        let stmt = parser
            .parse("SELECT dept, COUNT(*) FROM emp GROUP BY dept ORDER BY dept")
            .unwrap();
        if let SqlStatement::Select(query) = stmt {
            let meta = extract_select_metadata(&query);
            assert!(meta.has_group_by);
            assert!(meta.has_order_by);
            assert!(meta.has_aggregates);
            assert_eq!(meta.aggregate_functions, vec!["COUNT"]);
            assert_eq!(meta.group_by_columns, vec!["dept"]);
            assert_eq!(meta.order_by_columns, vec!["dept"]);
            assert_eq!(meta.source_table, Some("emp".to_string()));
        } else {
            panic!("Expected SELECT statement");
        }
    }

    #[cfg(feature = "viz")]
    #[test]
    fn test_extract_select_metadata_simple() {
        use joule_db_query::sql::{SqlParser, SqlStatement};
        let mut parser = SqlParser::new();
        let stmt = parser.parse("SELECT * FROM users").unwrap();
        if let SqlStatement::Select(query) = stmt {
            let meta = extract_select_metadata(&query);
            assert!(!meta.has_group_by);
            assert!(!meta.has_order_by);
            assert!(!meta.has_aggregates);
            assert!(!meta.has_distinct);
            assert!(meta.aggregate_functions.is_empty());
            assert_eq!(meta.source_table, Some("users".to_string()));
        } else {
            panic!("Expected SELECT statement");
        }
    }

    #[cfg(feature = "viz")]
    #[test]
    fn test_detect_nested_aggregates() {
        use joule_db_query::sql::{SqlParser, SqlStatement};
        let mut parser = SqlParser::new();
        let stmt = parser
            .parse("SELECT SUM(a) + AVG(b), MAX(c) FROM t GROUP BY d")
            .unwrap();
        if let SqlStatement::Select(query) = stmt {
            let meta = extract_select_metadata(&query);
            assert!(meta.has_aggregates);
            assert!(meta.aggregate_functions.contains(&"AVG".to_string()));
            assert!(meta.aggregate_functions.contains(&"MAX".to_string()));
            assert!(meta.aggregate_functions.contains(&"SUM".to_string()));
        } else {
            panic!("Expected SELECT statement");
        }
    }

