    // --- W02: Bulk INSERT ---
    #[tokio::test]
    async fn w02_bulk_insert() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w02 (id INT, val TEXT)");
        // Insert 100 rows using multi-value INSERT
        let mut sql = String::from("INSERT INTO w02 VALUES ");
        for i in 0..100 {
            if i > 0 { sql.push_str(", "); }
            sql.push_str(&format!("({}, 'row_{}')", i, i));
        }
        run(&ex, &sql);
        let r = run(&ex, "SELECT COUNT(*) FROM w02");
        assert_eq!(r.rows.len(), 1);
        // The count should be 100
        let count_val = &r.rows[0][0];
        assert!(count_val.to_string().contains("100"), "Expected 100, got {:?}", count_val);
    }

