    // --- W07: WHERE with AND/OR/NOT ---
    #[tokio::test]
    async fn w07_compound_predicates() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let r = run(&ex, "SELECT * FROM employees WHERE dept_id = 1 AND salary > 115000.0");
        assert_eq!(r.rows.len(), 2); // Alice (120K) and Frank (130K)
        let r2 = run(&ex, "SELECT * FROM employees WHERE dept_id = 1 OR dept_id = 2");
        assert_eq!(r2.rows.len(), 5); // Alice,Bob,Frank(dept1) + Carol,Dave(dept2)
        let r3 = run(&ex, "SELECT * FROM employees WHERE NOT dept_id = 1");
        assert_eq!(r3.rows.len(), 3); // Carol, Dave, Eve
    }

