    // --- W39: BEGIN / COMMIT / ROLLBACK ---
    #[tokio::test]
    async fn w39_transactions_basic() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w39 (id INT, val TEXT)");
        let begin_r = run(&ex, "BEGIN");
        let sid = begin_r.session_id.clone();
        assert!(sid.is_some(), "BEGIN should return session_id");
        // Insert within transaction
        let req = QueryRequest {
            sql: "INSERT INTO w39 VALUES (1, 'in_txn')".to_string(),
            params: Default::default(),
            args: Vec::new(),
            explain: false,
            limit: None,
            session_id: sid.clone(),
            query_timeout_ms: None,
            branch_id: None,
            tenant_id: None,
        };
        ex.execute(&req).unwrap();
        // Commit
        let commit_req = QueryRequest {
            sql: "COMMIT".to_string(),
            params: Default::default(),
            args: Vec::new(),
            explain: false,
            limit: None,
            session_id: sid,
            query_timeout_ms: None,
            branch_id: None,
            tenant_id: None,
        };
        ex.execute(&commit_req).unwrap();
        let r = run(&ex, "SELECT * FROM w39");
        assert_eq!(r.rows.len(), 1);
    }

    // --- W40: Transaction rollback ---
    #[tokio::test]
    async fn w40_transaction_rollback() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w40 (id INT, val TEXT)");
        run(&ex, "INSERT INTO w40 VALUES (1, 'before')");
        let begin_r = run(&ex, "BEGIN");
        let sid = begin_r.session_id.clone();
        let req = QueryRequest {
            sql: "INSERT INTO w40 VALUES (2, 'in_txn')".to_string(),
            params: Default::default(),
            args: Vec::new(),
            explain: false,
            limit: None,
            session_id: sid.clone(),
            query_timeout_ms: None,
            branch_id: None,
            tenant_id: None,
        };
        ex.execute(&req).unwrap();
        let rollback_req = QueryRequest {
            sql: "ROLLBACK".to_string(),
            params: Default::default(),
            args: Vec::new(),
            explain: false,
            limit: None,
            session_id: sid,
            query_timeout_ms: None,
            branch_id: None,
            tenant_id: None,
        };
        ex.execute(&rollback_req).unwrap();
        let r = run(&ex, "SELECT * FROM w40");
        assert_eq!(r.rows.len(), 1); // only the pre-txn row
    }

    // --- W41: Concurrent transaction isolation ---
    #[tokio::test]
    async fn w41_transaction_isolation() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w41 (id INT, val INT)");
        // Start session, insert within transaction, read back, commit
        let begin1 = run(&ex, "BEGIN");
        let sid1 = begin1.session_id.clone();
        let mk_req = |sql: &str, sid: &Option<String>| QueryRequest {
            sql: sql.to_string(),
            params: Default::default(),
            args: Vec::new(),
            explain: false,
            limit: None,
            session_id: sid.clone(),
            query_timeout_ms: None,
            branch_id: None,
            tenant_id: None,
        };
        ex.execute(&mk_req("INSERT INTO w41 VALUES (1, 100)", &sid1)).unwrap();
        // Read within same session (read-your-writes)
        let r1 = ex.execute(&mk_req("SELECT val FROM w41 WHERE id = 1", &sid1)).unwrap();
        assert_eq!(r1.rows.len(), 1, "Session should see its own writes");
        // Commit
        ex.execute(&mk_req("COMMIT", &sid1)).unwrap();
        // Verify data persists after commit
        let r2 = run(&ex, "SELECT * FROM w41");
        assert_eq!(r2.rows.len(), 1, "Data should persist after commit");
    }

