    // --- W78: FOREIGN KEY violation ---
    #[tokio::test]
    async fn w78_fk_violation() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w78_parent (id INT PRIMARY KEY, name TEXT)");
        run(&ex, "INSERT INTO w78_parent VALUES (1, 'parent1')");
        run(&ex, "CREATE TABLE w78_child (id INT PRIMARY KEY, parent_id INT REFERENCES w78_parent(id), val TEXT)");
        run(&ex, "INSERT INTO w78_child VALUES (1, 1, 'valid')");
        // FK violation: reference non-existent parent
        let req = QueryRequest {
            sql: "INSERT INTO w78_child VALUES (2, 999, 'invalid')".to_string(),
            params: Default::default(),
            args: Vec::new(),
            explain: false,
            limit: None,
            session_id: None,
            query_timeout_ms: None,
            branch_id: None,
            tenant_id: None,
        };
        assert!(ex.execute(&req).is_err(), "FK violation should fail");
    }

    // --- W79: FOREIGN KEY CASCADE DELETE ---
    #[tokio::test]
    async fn w79_fk_cascade() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w79_parent (id INT PRIMARY KEY, name TEXT)");
        run(&ex, "INSERT INTO w79_parent VALUES (1, 'p1'), (2, 'p2')");
        run(&ex, "CREATE TABLE w79_child (id INT, parent_id INT REFERENCES w79_parent(id) ON DELETE CASCADE, val TEXT)");
        run(&ex, "INSERT INTO w79_child VALUES (1, 1, 'c1'), (2, 1, 'c2'), (3, 2, 'c3')");
        // Delete parent should cascade to children
        run(&ex, "DELETE FROM w79_parent WHERE id = 1");
        let r = run(&ex, "SELECT * FROM w79_child");
        assert_eq!(r.rows.len(), 1, "Expected 1 child remaining (parent 2's child)");
    }

