    // --- W151: UPDATE with simple WHERE ---
    #[tokio::test]
    async fn w151_update_where() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w151_emp (id INT, name TEXT, dept_id INT, bonus FLOAT)");
        run(&ex, "INSERT INTO w151_emp VALUES (1, 'A', 1, 0.0), (2, 'B', 1, 0.0), (3, 'C', 2, 0.0)");
        run(&ex, "UPDATE w151_emp SET bonus = 500.0 WHERE dept_id = 1");
        let r = run(&ex, "SELECT bonus FROM w151_emp WHERE dept_id = 1");
        assert_eq!(r.rows.len(), 2);
        let val: f64 = r.rows[0][0].as_f64().unwrap_or(0.0);
        assert!((val - 500.0).abs() < 0.01);
    }

