    // --- W176: Bulk insert then aggregate ---
    #[tokio::test]
    async fn w176_bulk_then_agg() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w176 (id INT, category TEXT, amount FLOAT)");
        let mut sql = String::from("INSERT INTO w176 VALUES ");
        for i in 0..50 {
            if i > 0 { sql.push_str(", "); }
            let cat = if i % 3 == 0 { "A" } else if i % 3 == 1 { "B" } else { "C" };
            sql.push_str(&format!("({}, '{}', {})", i, cat, i as f64 * 10.0));
        }
        run(&ex, &sql);
        let r = run(&ex, "SELECT category, COUNT(*) AS cnt, SUM(amount) AS total FROM w176 GROUP BY category ORDER BY category");
        assert_eq!(r.rows.len(), 3);
    }

