    // --- W283: Large multi-row INSERT + aggregate ---
    #[tokio::test]
    async fn w283_large_insert_agg() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w283 (id INT, val INT)");
        let mut vals = Vec::new();
        for i in 1..=50 {
            vals.push(format!("({}, {})", i, i * 10));
        }
        run(&ex, &format!("INSERT INTO w283 VALUES {}", vals.join(", ")));
        let r = run(&ex, "SELECT COUNT(*) AS cnt, SUM(val) AS total FROM w283");
        let cnt: i64 = serde_json::from_value(r.rows[0][0].clone()).unwrap_or(0);
        let total: f64 = serde_json::from_value(r.rows[0][1].clone()).unwrap_or(0.0);
        assert_eq!(cnt, 50);
        // SUM(10+20+...+500) = 10 * SUM(1..50) = 10 * 1275 = 12750
        assert!((total - 12750.0).abs() < 0.01);
    }

