    async fn w350_batch7_grand_finale() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        // CTE with aggregated employee orders, then join to departments
        let r = run(&ex, "WITH emp_orders AS (SELECT e.id AS emp_id, e.name AS emp_name, e.dept_id, COALESCE(SUM(o.amount), 0) AS total_orders FROM employees e LEFT JOIN orders o ON o.employee_id = e.id GROUP BY e.id, e.name, e.dept_id) SELECT emp_name, dept_id, total_orders FROM emp_orders ORDER BY total_orders DESC LIMIT 5");
        assert!(r.rows.len() >= 1, "Expected at least 1 row in grand finale");
    }

