    // --- W351: Transactional consistency — INSERT visible within session ---
    #[tokio::test]
    async fn w351_insert_visible() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w351 (id INT, val TEXT)");
        run(&ex, "INSERT INTO w351 VALUES (1, 'a')");
        run(&ex, "INSERT INTO w351 VALUES (2, 'b')");
        let r = run(&ex, "SELECT COUNT(*) FROM w351");
        let cnt: i64 = serde_json::from_value(r.rows[0][0].clone()).unwrap_or(0);
        assert_eq!(cnt, 2);
        run(&ex, "INSERT INTO w351 VALUES (3, 'c')");
        let r2 = run(&ex, "SELECT COUNT(*) FROM w351");
        let cnt2: i64 = serde_json::from_value(r2.rows[0][0].clone()).unwrap_or(0);
        assert_eq!(cnt2, 3);
    }

