    // --- W512: NULL comparison edge cases ---
    #[tokio::test]
    async fn w512_null_compare() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w512 (id INT, val INT)");
        run(&ex, "INSERT INTO w512 VALUES (1, 10)");
        run(&ex, "INSERT INTO w512 (id) VALUES (2)");
        // NULL != anything should return false, NULL = anything should return false
        let r1 = run(&ex, "SELECT COUNT(*) FROM w512 WHERE val = 10");
        let r2 = run(&ex, "SELECT COUNT(*) FROM w512 WHERE val != 10");
        let c1: i64 = serde_json::from_value(r1.rows[0][0].clone()).unwrap_or(0);
        let c2: i64 = serde_json::from_value(r2.rows[0][0].clone()).unwrap_or(0);
        assert_eq!(c1, 1); // Only id=1
        // In SQL, NULL != 10 is NULL (false), so c2 should be 0 (strict) or 1 (lenient)
        assert!(c2 <= 1);
    }

