    // --- W590: Verify large UPDATE ---
    #[tokio::test]
    async fn w590_large_update() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w590 (id INT, val INT)");
        let mut vals = Vec::new();
        for i in 1..=100 { vals.push(format!("({}, {})", i, i)); }
        run(&ex, &format!("INSERT INTO w590 VALUES {}", vals.join(", ")));
        run(&ex, "UPDATE w590 SET val = val * 2 WHERE id BETWEEN 1 AND 50");
        let r = run(&ex, "SELECT SUM(val) FROM w590");
        let total: f64 = serde_json::from_value(r.rows[0][0].clone()).unwrap_or(0.0);
        // Original SUM(1..100) = 5050. After doubling 1..50: sum = 2*SUM(1..50) + SUM(51..100) = 2*1275 + 3775 = 6325
        assert!((total - 6325.0).abs() < 0.01);
    }

