    // --- W669: Multi-row UPDATE with different conditions ---
    #[tokio::test]
    async fn w669_conditional_updates() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w669 (id INT, tier TEXT, price FLOAT)");
        run(&ex, "INSERT INTO w669 VALUES (1, 'gold', 100.0), (2, 'silver', 50.0), (3, 'bronze', 25.0)");
        run(&ex, "UPDATE w669 SET price = price * 1.2 WHERE tier = 'gold'");
        run(&ex, "UPDATE w669 SET price = price * 1.1 WHERE tier = 'silver'");
        let r = run(&ex, "SELECT price FROM w669 WHERE id = 1");
        let p: f64 = serde_json::from_value(r.rows[0][0].clone()).unwrap();
        assert!((p - 120.0).abs() < 0.01);
        let r2 = run(&ex, "SELECT price FROM w669 WHERE id = 2");
        let p2: f64 = serde_json::from_value(r2.rows[0][0].clone()).unwrap();
        assert!((p2 - 55.0).abs() < 0.01);
    }

