        let r = run(&ex, "WITH dept_summary AS (SELECT d.name AS dept_name, d.id AS dept_id, COUNT(e.id) AS emp_count, SUM(e.salary) AS total_sal FROM departments d JOIN employees e ON e.dept_id = d.id GROUP BY d.name, d.id) SELECT dept_name, emp_count, total_sal FROM dept_summary ORDER BY total_sal DESC");
        assert_eq!(r.rows.len(), 3, "Expected 3 departments in grand finale");
