        let r2 = run(&ex, "SELECT e.name, e.salary, d.name AS dept, RANK() OVER (ORDER BY e.salary DESC) AS overall_rank FROM employees e JOIN departments d ON e.dept_id = d.id ORDER BY e.salary DESC");
