    // --- W703: SELECT with multiple COALESCE ---
    #[tokio::test]
    async fn w703_multi_coalesce() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w703 (id INT, a TEXT, b TEXT, c TEXT)");
        run(&ex, "INSERT INTO w703 VALUES (1, NULL, NULL, 'found')");
        run(&ex, "INSERT INTO w703 VALUES (2, NULL, 'mid', 'also')");
        run(&ex, "INSERT INTO w703 VALUES (3, 'first', NULL, NULL)");
        let r = run(&ex, "SELECT id, COALESCE(a, b, c, 'none') AS val FROM w703 ORDER BY id");
        assert_eq!(r.rows[0][1], serde_json::Value::String("found".to_string()));
        assert_eq!(r.rows[1][1], serde_json::Value::String("mid".to_string()));
        assert_eq!(r.rows[2][1], serde_json::Value::String("first".to_string()));
    }

