    // --- W967: Stress — mixed operations cycle ---
    #[tokio::test]
    async fn w967_mixed_ops() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w967 (id INT, val INT)");
        for cycle in 0..10 {
            let base = cycle * 10;
            let mut vals = Vec::new();
            for i in 1..=10 { vals.push(format!("({}, {})", base + i, i * 10)); }
            run(&ex, &format!("INSERT INTO w967 VALUES {}", vals.join(", ")));
            run(&ex, &format!("UPDATE w967 SET val = val + 1 WHERE id BETWEEN {} AND {}", base + 1, base + 5));
            run(&ex, &format!("DELETE FROM w967 WHERE id = {}", base + 10));
        }
        let r = run(&ex, "SELECT COUNT(*) FROM w967");
        let cnt: i64 = serde_json::from_value(r.rows[0][0].clone()).unwrap();
        assert_eq!(cnt, 90); // 10 cycles * (10 inserts - 1 delete) = 90
    }

