    // --- W1000: THE GRAND FINALE — 1000-test milestone ---
    #[tokio::test]
    async fn w1000_grand_milestone() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);

        // 1. Full department analytics with CTE
        let r1 = run(&ex, "WITH dept_analytics AS (SELECT d.name AS dept, d.budget, COUNT(e.id) AS headcount, SUM(e.salary) AS payroll, AVG(e.salary) AS avg_pay, MAX(e.salary) AS top_pay, MIN(e.salary) AS low_pay FROM departments d JOIN employees e ON e.dept_id = d.id GROUP BY d.name, d.budget) SELECT dept, headcount, payroll, avg_pay, top_pay - low_pay AS pay_spread FROM dept_analytics ORDER BY payroll DESC");
        assert_eq!(r1.rows.len(), 3, "W1000: dept analytics");

        // 2. Employee ranking with window functions
        let r2 = run(&ex, "SELECT e.name, e.salary, d.name AS dept, RANK() OVER (ORDER BY e.salary DESC) AS overall_rank, RANK() OVER (PARTITION BY e.dept_id ORDER BY e.salary DESC) AS dept_rank FROM employees e JOIN departments d ON e.dept_id = d.id ORDER BY e.salary DESC");
        assert_eq!(r2.rows.len(), 6, "W1000: employee ranking");

        // 3. Order revenue analysis
        let r3 = run(&ex, "SELECT e.name, COUNT(o.id) AS order_cnt, COALESCE(SUM(o.amount), 0) AS total_revenue, CASE WHEN COUNT(o.id) >= 3 THEN 'VIP' WHEN COUNT(o.id) >= 1 THEN 'active' ELSE 'inactive' END AS customer_tier FROM employees e LEFT JOIN orders o ON o.employee_id = e.id GROUP BY e.name ORDER BY total_revenue DESC");
        assert_eq!(r3.rows.len(), 6, "W1000: order analysis");

        // 4. Salary distribution
        let r4 = run(&ex, "SELECT CASE WHEN salary >= 120000 THEN 'tier1' WHEN salary >= 100000 THEN 'tier2' ELSE 'tier3' END AS salary_tier, COUNT(*) AS cnt, AVG(salary) AS avg_sal FROM employees GROUP BY CASE WHEN salary >= 120000 THEN 'tier1' WHEN salary >= 100000 THEN 'tier2' ELSE 'tier3' END ORDER BY avg_sal DESC");
        assert_eq!(r4.rows.len(), 3, "W1000: salary distribution");

        // 5. Final verification: total salary matches
        let r5 = run(&ex, "SELECT SUM(salary) FROM employees");
        let total: f64 = serde_json::from_value(r5.rows[0][0].clone()).unwrap();
        assert!((total - 630000.0).abs() < 0.01, "W1000: salary sum verification");
    }

