    // --- W1097: Verify data after multiple operations ---
    #[tokio::test]
    async fn w1097_data_integrity() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w1097 (id INT, balance FLOAT)");
        run(&ex, "INSERT INTO w1097 VALUES (1, 1000.0), (2, 2000.0), (3, 3000.0)");
        let before = run(&ex, "SELECT SUM(balance) FROM w1097");
        let b: f64 = serde_json::from_value(before.rows[0][0].clone()).unwrap();
        // Transfer: subtract from 3, add to 1
        run(&ex, "UPDATE w1097 SET balance = balance - 500 WHERE id = 3");
        run(&ex, "UPDATE w1097 SET balance = balance + 500 WHERE id = 1");
        let after = run(&ex, "SELECT SUM(balance) FROM w1097");
        let a: f64 = serde_json::from_value(after.rows[0][0].clone()).unwrap();
        assert!((b - a).abs() < 0.01, "Total balance should be unchanged after transfer");
    }

