    // --- W1099: Penultimate — comprehensive query battery ---
    #[tokio::test]
    async fn w1099_query_battery() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        // Quick battery of 5 different query patterns
        let r1 = run(&ex, "SELECT COUNT(*) FROM employees WHERE salary > 100000");
        let c1: i64 = serde_json::from_value(r1.rows[0][0].clone()).unwrap();
        assert_eq!(c1, 3);
        let r2 = run(&ex, "SELECT dept_id, MAX(salary) FROM employees GROUP BY dept_id");
        assert_eq!(r2.rows.len(), 3);
        let r3 = run(&ex, "SELECT name FROM employees EXCEPT SELECT e.name FROM employees e JOIN orders o ON o.employee_id = e.id");
        assert_eq!(r3.rows.len(), 1); // Frank
        let r4 = run(&ex, "SELECT name, RANK() OVER (ORDER BY salary DESC) FROM employees");
        assert_eq!(r4.rows.len(), 6);
        let r5 = run(&ex, "WITH top AS (SELECT name FROM employees ORDER BY salary DESC LIMIT 1) SELECT name FROM top");
        assert_eq!(r5.rows[0][0], serde_json::Value::String("Frank".to_string()));
    }

