    // --- W1200: Batch 24 Grand Finale ---
    #[tokio::test]
    async fn w1200_batch24_grand_finale() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        // Full department report with window
        let r1 = run(&ex, "SELECT d.name AS dept, COUNT(e.id) AS headcount, SUM(e.salary) AS payroll, AVG(e.salary) AS avg_sal, RANK() OVER (ORDER BY SUM(e.salary) DESC) AS payroll_rank FROM departments d JOIN employees e ON e.dept_id = d.id GROUP BY d.name ORDER BY payroll_rank");
        assert_eq!(r1.rows.len(), 3, "W1200: dept report");
        // Employee with orders summary
        let r2 = run(&ex, "SELECT e.name, e.salary, d.name AS dept, COUNT(o.id) AS num_orders, COALESCE(SUM(o.amount), 0) AS total_revenue FROM employees e JOIN departments d ON e.dept_id = d.id LEFT JOIN orders o ON o.employee_id = e.id GROUP BY e.name, e.salary, d.name ORDER BY total_revenue DESC");
        assert_eq!(r2.rows.len(), 6, "W1200: employee orders");
        // Top earner per department
        let r3 = run(&ex, "WITH ranked AS (SELECT name, salary, dept_id, ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary DESC) AS rn FROM employees) SELECT name, salary, dept_id FROM ranked WHERE rn = 1 ORDER BY salary DESC");
        assert_eq!(r3.rows.len(), 3, "W1200: top earner per dept");
    }

