    // --- W1249: Comprehensive data lifecycle ---
    #[tokio::test]
    async fn w1249_lifecycle() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w1249 (id INT, status TEXT, amount FLOAT)");
        // Insert
        run(&ex, "INSERT INTO w1249 VALUES (1, 'pending', 100.0), (2, 'pending', 200.0), (3, 'pending', 300.0)");
        let c1: i64 = serde_json::from_value(run(&ex, "SELECT COUNT(*) FROM w1249").rows[0][0].clone()).unwrap();
        assert_eq!(c1, 3);
        // Update
        run(&ex, "UPDATE w1249 SET status = 'approved' WHERE amount >= 200.0");
        let c2: i64 = serde_json::from_value(run(&ex, "SELECT COUNT(*) FROM w1249 WHERE status = 'approved'").rows[0][0].clone()).unwrap();
        assert_eq!(c2, 2);
        // Delete
        run(&ex, "DELETE FROM w1249 WHERE status = 'pending'");
        let c3: i64 = serde_json::from_value(run(&ex, "SELECT COUNT(*) FROM w1249").rows[0][0].clone()).unwrap();
        assert_eq!(c3, 2);
        // Verify remaining
        let r = run(&ex, "SELECT SUM(amount) FROM w1249");
        let total: f64 = serde_json::from_value(r.rows[0][0].clone()).unwrap();
        assert_eq!(total, 500.0);
    }

    // --- W1250: Batch 25 Grand Finale ---
    #[tokio::test]
    async fn w1250_batch25_grand_finale() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        // Department summary with window rank
        let r1 = run(&ex, "SELECT d.name AS dept, COUNT(e.id) AS headcount, SUM(e.salary) AS payroll, RANK() OVER (ORDER BY SUM(e.salary) DESC) AS rnk FROM departments d JOIN employees e ON e.dept_id = d.id GROUP BY d.name ORDER BY rnk");
        assert_eq!(r1.rows.len(), 3, "W1250: dept summary");
        // Employee salary percentiles
        let r2 = run(&ex, "SELECT name, salary, NTILE(4) OVER (ORDER BY salary) AS quartile FROM employees ORDER BY salary");
        assert_eq!(r2.rows.len(), 6, "W1250: salary quartiles");
        // Orders with employee and department info
        let r3 = run(&ex, "SELECT e.name, d.name AS dept, SUM(o.amount) AS total_orders FROM employees e JOIN departments d ON e.dept_id = d.id LEFT JOIN orders o ON o.employee_id = e.id GROUP BY e.name, d.name ORDER BY total_orders DESC");
        assert_eq!(r3.rows.len(), 6, "W1250: orders with dept");
    }

