    // --- W1299: Complex lifecycle with verification ---
    #[tokio::test]
    async fn w1299_complex_lifecycle() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w1299 (id INT, balance FLOAT, frozen INT)");
        run(&ex, "INSERT INTO w1299 VALUES (1, 1000.0, 0), (2, 2000.0, 0), (3, 500.0, 0)");
        // Freeze low balances
        run(&ex, "UPDATE w1299 SET frozen = 1 WHERE balance < 1000.0");
        // Transfer from id=2 to id=1
        run(&ex, "UPDATE w1299 SET balance = balance - 500.0 WHERE id = 2");
        run(&ex, "UPDATE w1299 SET balance = balance + 500.0 WHERE id = 1");
        // Verify total balance unchanged
        let r = run(&ex, "SELECT SUM(balance) FROM w1299");
        let total: f64 = serde_json::from_value(r.rows[0][0].clone()).unwrap();
        assert_eq!(total, 3500.0); // 1500 + 1500 + 500
        // Verify frozen
        let r2 = run(&ex, "SELECT COUNT(*) FROM w1299 WHERE frozen = 1");
        let frozen: i64 = serde_json::from_value(r2.rows[0][0].clone()).unwrap();
        assert_eq!(frozen, 1);
    }

    // --- W1300: Batch 26 Grand Finale ---
    #[tokio::test]
    async fn w1300_batch26_grand_finale() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        // Full analytics query
        let r1 = run(&ex, "SELECT d.name AS dept, COUNT(e.id) AS headcount, SUM(e.salary) AS payroll, MIN(e.salary) AS min_sal, MAX(e.salary) AS max_sal, AVG(e.salary) AS avg_sal FROM departments d JOIN employees e ON e.dept_id = d.id GROUP BY d.name ORDER BY payroll DESC");
        assert_eq!(r1.rows.len(), 3, "W1300: full analytics");
        // Employee ranking across company
        let r2 = run(&ex, "SELECT name, salary, dept_id, ROW_NUMBER() OVER (ORDER BY salary DESC) AS company_rank, ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary DESC) AS dept_rank FROM employees ORDER BY salary DESC");
        assert_eq!(r2.rows.len(), 6, "W1300: employee ranking");
        // Revenue by department
        let r3 = run(&ex, "SELECT d.name, COALESCE(SUM(o.amount), 0) AS revenue FROM departments d LEFT JOIN employees e ON e.dept_id = d.id LEFT JOIN orders o ON o.employee_id = e.id GROUP BY d.name ORDER BY revenue DESC");
        assert_eq!(r3.rows.len(), 3, "W1300: revenue by dept");
    }

