    // --- W1350: Batch 27 Grand Finale ---
    #[tokio::test]
    async fn w1350_batch27_grand_finale() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        // Full employee report with window
        let r1 = run(&ex, "SELECT e.name, e.salary, d.name AS dept, ROW_NUMBER() OVER (ORDER BY e.salary DESC) AS rank, ROW_NUMBER() OVER (PARTITION BY e.dept_id ORDER BY e.salary DESC) AS dept_rank FROM employees e JOIN departments d ON e.dept_id = d.id ORDER BY e.salary DESC");
        assert_eq!(r1.rows.len(), 6, "W1350: full employee report");
        // Department summary
        let r2 = run(&ex, "SELECT d.name, COUNT(e.id) AS headcount, SUM(e.salary) AS payroll, COUNT(o.id) AS orders, COALESCE(SUM(o.amount), 0) AS revenue FROM departments d JOIN employees e ON e.dept_id = d.id LEFT JOIN orders o ON o.employee_id = e.id GROUP BY d.name ORDER BY payroll DESC");
        assert_eq!(r2.rows.len(), 3, "W1350: dept summary");
        // CTE top earners
        let r3 = run(&ex, "WITH top AS (SELECT name, salary FROM employees ORDER BY salary DESC LIMIT 3) SELECT name, salary FROM top ORDER BY salary DESC");
        assert_eq!(r3.rows.len(), 3, "W1350: top earners");
    }

