    // --- W1398: Complex data flow ---
    #[tokio::test]
    async fn w1398_complex_flow() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w1398 (id INT, category TEXT, value FLOAT)");
        run(&ex, "INSERT INTO w1398 VALUES (1, 'A', 100.0), (2, 'B', 200.0), (3, 'A', 150.0), (4, 'C', 300.0), (5, 'B', 250.0)");
        // Aggregate
        let r1 = run(&ex, "SELECT category, SUM(value) AS total FROM w1398 GROUP BY category ORDER BY total DESC");
        assert_eq!(r1.rows.len(), 3);
        // Update
        run(&ex, "UPDATE w1398 SET value = value * 1.1 WHERE category = 'A'");
        let r2 = run(&ex, "SELECT SUM(value) FROM w1398 WHERE category = 'A'");
        let total: f64 = serde_json::from_value(r2.rows[0][0].clone()).unwrap();
        assert!((total - 275.0).abs() < 0.01); // (100+150)*1.1 = 275
        // Delete
        run(&ex, "DELETE FROM w1398 WHERE category = 'C'");
        let r3 = run(&ex, "SELECT COUNT(*) FROM w1398");
        let cnt: i64 = serde_json::from_value(r3.rows[0][0].clone()).unwrap();
        assert_eq!(cnt, 4);
    }

