    // --- W1400: Batch 28 Grand Finale ---
    #[tokio::test]
    async fn w1400_batch28_grand_finale() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        // Employee report with dept info and ranking
        let r1 = run(&ex, "SELECT e.name, e.salary, d.name AS dept, ROW_NUMBER() OVER (ORDER BY e.salary DESC) AS overall_rank, DENSE_RANK() OVER (PARTITION BY e.dept_id ORDER BY e.salary DESC) AS dept_rank FROM employees e JOIN departments d ON e.dept_id = d.id ORDER BY e.salary DESC");
        assert_eq!(r1.rows.len(), 6, "W1400: employee ranking report");
        // Revenue analysis
        let r2 = run(&ex, "SELECT d.name, COUNT(e.id) AS headcount, COALESCE(SUM(o.amount), 0) AS revenue, AVG(e.salary) AS avg_sal FROM departments d JOIN employees e ON e.dept_id = d.id LEFT JOIN orders o ON o.employee_id = e.id GROUP BY d.name ORDER BY revenue DESC");
        assert_eq!(r2.rows.len(), 3, "W1400: revenue analysis");
        // CTE top 3 earners
        let r3 = run(&ex, "WITH top AS (SELECT name, salary, dept_id FROM employees ORDER BY salary DESC LIMIT 3) SELECT t.name, t.salary, d.name AS dept FROM top t JOIN departments d ON t.dept_id = d.id ORDER BY t.salary DESC");
        assert_eq!(r3.rows.len(), 3, "W1400: top 3 with dept");
    }

