    // --- W1450: Batch 29 Grand Finale ---
    #[tokio::test]
    async fn w1450_batch29_grand_finale() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        // Multi-metric department report
        let r1 = run(&ex, "SELECT d.name AS dept, COUNT(e.id) AS headcount, SUM(e.salary) AS payroll, MIN(e.salary) AS lo, MAX(e.salary) AS hi, AVG(e.salary) AS avg_sal, RANK() OVER (ORDER BY SUM(e.salary) DESC) AS rnk FROM departments d JOIN employees e ON e.dept_id = d.id GROUP BY d.name ORDER BY rnk");
        assert_eq!(r1.rows.len(), 3, "W1450: dept multi-metric");
        // Employee with window and join
        let r2 = run(&ex, "SELECT e.name, e.salary, d.name AS dept, ROW_NUMBER() OVER (ORDER BY e.salary DESC) AS overall, ROW_NUMBER() OVER (PARTITION BY e.dept_id ORDER BY e.salary DESC) AS in_dept FROM employees e JOIN departments d ON e.dept_id = d.id ORDER BY e.salary DESC");
        assert_eq!(r2.rows.len(), 6, "W1450: employee windows");
        // Verify schema integrity
        assert_eq!(run_rows(&ex, "SELECT * FROM departments"), 3);
        assert_eq!(run_rows(&ex, "SELECT * FROM employees"), 6);
        assert_eq!(run_rows(&ex, "SELECT * FROM orders"), 7);
    }

