    // --- W1500: 1500 WORKFLOW MILESTONE GRAND FINALE ---
    #[tokio::test]
    async fn w1500_milestone_1500() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);

        // === Query 1: Full department analytics with window ===
        let r1 = run(&ex, "SELECT d.name AS dept, COUNT(e.id) AS headcount, SUM(e.salary) AS payroll, MIN(e.salary) AS lo, MAX(e.salary) AS hi, AVG(e.salary) AS avg_sal, MAX(e.salary) - MIN(e.salary) AS spread, RANK() OVER (ORDER BY SUM(e.salary) DESC) AS payroll_rank FROM departments d JOIN employees e ON e.dept_id = d.id GROUP BY d.name ORDER BY payroll_rank");
        assert_eq!(r1.rows.len(), 3, "W1500: dept analytics");

        // === Query 2: Employee ranking with multiple windows ===
        let r2 = run(&ex, "SELECT e.name, e.salary, d.name AS dept, ROW_NUMBER() OVER (ORDER BY e.salary DESC) AS company_rank, ROW_NUMBER() OVER (PARTITION BY e.dept_id ORDER BY e.salary DESC) AS dept_rank, NTILE(3) OVER (ORDER BY e.salary DESC) AS tercile FROM employees e JOIN departments d ON e.dept_id = d.id ORDER BY e.salary DESC");
        assert_eq!(r2.rows.len(), 6, "W1500: employee multi-window");

        // === Query 3: Revenue by department with COALESCE ===
        let r3 = run(&ex, "SELECT d.name, COUNT(e.id) AS emps, COUNT(o.id) AS orders, COALESCE(SUM(o.amount), 0) AS revenue FROM departments d JOIN employees e ON e.dept_id = d.id LEFT JOIN orders o ON o.employee_id = e.id GROUP BY d.name ORDER BY revenue DESC");
        assert_eq!(r3.rows.len(), 3, "W1500: revenue report");

        // === Query 4: CTE top earners per department ===
        let r4 = run(&ex, "WITH ranked AS (SELECT name, salary, dept_id, ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary DESC) AS rn FROM employees) SELECT name, salary, dept_id FROM ranked WHERE rn = 1 ORDER BY salary DESC");
        assert_eq!(r4.rows.len(), 3, "W1500: top earner per dept");

        // === Query 5: Schema integrity check ===
        assert_eq!(run_rows(&ex, "SELECT * FROM departments"), 3, "W1500: departments");
        assert_eq!(run_rows(&ex, "SELECT * FROM employees"), 6, "W1500: employees");
        assert_eq!(run_rows(&ex, "SELECT * FROM projects"), 4, "W1500: projects");
        assert_eq!(run_rows(&ex, "SELECT * FROM orders"), 7, "W1500: orders");
    }

