    /// Fix 1: NOT LIKE in DELETE WHERE (evaluate_predicate)
    #[tokio::test]
    async fn regression_not_like_in_delete() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        // Delete employees whose name NOT LIKE 'A%' — removes Bob, Carol, Dave, Eve, Frank
        run(&ex, "DELETE FROM employees WHERE name NOT LIKE 'A%'");
        let r = run(&ex, "SELECT name FROM employees ORDER BY name");
        assert_eq!(r.rows.len(), 1, "regression: NOT LIKE in DELETE");
        assert_eq!(r.rows[0][0], "Alice");
    }

    /// Fix 1b: Modulo (%) in UPDATE WHERE
    #[tokio::test]
    async fn regression_modulo_in_update_where() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        // Update employees where id % 2 = 0 (even IDs: 2,4,6)
        run(&ex, "UPDATE employees SET salary = 999 WHERE id % 2 = 0");
        let r = run(&ex, "SELECT salary FROM employees WHERE salary = 999");
        assert_eq!(r.rows.len(), 3, "regression: modulo in UPDATE WHERE");
    }

    /// Fix 2: ROUND(AGG()) wrapping breaks aggregate detection
    #[tokio::test]
    async fn regression_round_aggregate() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let r = run(&ex, "SELECT dept_id, ROUND(AVG(salary)) as avg_sal FROM employees GROUP BY dept_id ORDER BY dept_id");
        assert_eq!(r.rows.len(), 3, "regression: ROUND(AVG()) grouped");
        for row in &r.rows {
            assert!(row[1].is_number(), "regression: ROUND(AVG()) should be number");
        }
    }

