    // --- W1550: Grand finale — all fixed patterns in one test ---
    #[tokio::test]
    async fn w1550_batch31_grand_finale() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);

        // 1: ROUND(AVG()) with GROUP BY
        let r1 = run(&ex, "SELECT dept_id, ROUND(AVG(salary)) FROM employees GROUP BY dept_id ORDER BY dept_id");
        assert_eq!(r1.rows.len(), 3, "W1550: ROUND(AVG()) groups");

        // 2: COALESCE(SUM()) grouped
        let r2 = run(&ex, "SELECT dept_id, COALESCE(SUM(salary), 0) FROM employees GROUP BY dept_id ORDER BY dept_id");
        assert_eq!(r2.rows.len(), 3, "W1550: COALESCE(SUM()) groups");

        // 3: NOT LIKE in DELETE
        run(&ex, "DELETE FROM orders WHERE status NOT LIKE 's%'");
        let r3 = run(&ex, "SELECT * FROM orders");
        // shipped stays, delivered/pending go. shipped: id=1,3,5 → 3 rows
        assert_eq!(r3.rows.len(), 3, "W1550: NOT LIKE DELETE");

        // 4: BETWEEN in HAVING
        let r4 = run(&ex, "SELECT dept_id, COUNT(*) FROM employees GROUP BY dept_id HAVING COUNT(*) BETWEEN 2 AND 3");
        assert_eq!(r4.rows.len(), 2, "W1550: BETWEEN HAVING");

        // 5: CASE in ORDER BY
        let r5 = run(&ex, "SELECT name, dept_id FROM employees ORDER BY CASE WHEN dept_id = 2 THEN 1 WHEN dept_id = 3 THEN 2 ELSE 3 END, name");
        assert_eq!(r5.rows[0][1].as_i64().unwrap(), 2, "W1550: CASE ORDER dept2 first");

        // 6: UNION ORDER BY LIMIT
        let r6 = run(&ex, "SELECT name FROM employees WHERE dept_id = 1 UNION ALL SELECT name FROM employees WHERE dept_id = 2 ORDER BY name LIMIT 2");
        assert_eq!(r6.rows.len(), 2, "W1550: UNION ORDER LIMIT");

        // 7: Multi-CTE JOIN
        let r7 = run(&ex, "WITH ec AS (SELECT dept_id, COUNT(*) as cnt FROM employees GROUP BY dept_id), dn AS (SELECT id, name FROM departments) SELECT dn.name, ec.cnt FROM ec JOIN dn ON ec.dept_id = dn.id ORDER BY dn.name");
        assert_eq!(r7.rows.len(), 3, "W1550: multi-CTE JOIN");

        // 8: Schema integrity
        assert_eq!(run_rows(&ex, "SELECT * FROM departments"), 3, "W1550: departments intact");
        assert_eq!(run_rows(&ex, "SELECT * FROM employees"), 6, "W1550: employees intact");
        assert_eq!(run_rows(&ex, "SELECT * FROM projects"), 4, "W1550: projects intact");
    }

