    // --- W1599: Full mutation cycle ---
    #[tokio::test]
    async fn w1599_full_mutation_cycle() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w1599 (id INT, status TEXT, val INT)");
        for i in 0..20 {
            run(&ex, &format!("INSERT INTO w1599 VALUES ({}, 'active', {})", i, i * 10));
        }
        assert_eq!(run_rows(&ex, "SELECT * FROM w1599"), 20, "W1599: initial 20");
        run(&ex, "UPDATE w1599 SET status = 'archived' WHERE val % 30 = 0");
        // val%30=0: val=0,30,60,90,120,150 → id=0,3,6,9,12,15 → 6 updated (but 180 doesn't exist, only 0-190)
        // Actually 0,30,60,90,120,150,180 → 7... val goes 0,10,20,...190. %30=0: 0,30,60,90,120,150,180 → 7
        let r = run(&ex, "SELECT COUNT(*) FROM w1599 WHERE status = 'archived'");
        assert_eq!(r.rows[0][0].as_i64().unwrap(), 7, "W1599: 7 archived");
        run(&ex, "DELETE FROM w1599 WHERE status = 'archived'");
        assert_eq!(run_rows(&ex, "SELECT * FROM w1599"), 13, "W1599: 13 remain");
    }

    // --- W1600: Batch 32 grand finale — 1600-test milestone ---
    #[tokio::test]
    async fn w1600_batch32_grand_finale() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);

        // 1: ROUND(AVG()) with HAVING BETWEEN
        let r1 = run(&ex, "SELECT dept_id, ROUND(AVG(salary)) FROM employees GROUP BY dept_id HAVING AVG(salary) BETWEEN 85000 AND 100000 ORDER BY dept_id");
        assert_eq!(r1.rows.len(), 2, "W1600: ROUND+HAVING BETWEEN");

        // 2: Multi-CTE with CASE ORDER
        let r2 = run(&ex, "WITH stats AS (SELECT dept_id, COUNT(*) as cnt, SUM(salary) as total FROM employees GROUP BY dept_id) SELECT d.name, s.cnt, s.total FROM stats s JOIN departments d ON s.dept_id = d.id ORDER BY CASE WHEN s.cnt > 2 THEN 1 ELSE 2 END, d.name");
        assert_eq!(r2.rows.len(), 3, "W1600: CTE+CASE ORDER");

        // 3: UNION with ORDER LIMIT
        let r3 = run(&ex, "SELECT name FROM employees WHERE salary > 120000 UNION ALL SELECT name FROM departments WHERE budget > 400000 ORDER BY name LIMIT 3");
        // >120K: Frank(130K). budget>400K: Engineering(500K). → Frank, Engineering → 2 rows (limit 3 but only 2)
        assert_eq!(r3.rows.len(), 2, "W1600: UNION ORDER LIMIT");

        // 4: Schema integrity
        assert_eq!(run_rows(&ex, "SELECT * FROM departments"), 3, "W1600: departments");
        assert_eq!(run_rows(&ex, "SELECT * FROM employees"), 6, "W1600: employees");
        assert_eq!(run_rows(&ex, "SELECT * FROM projects"), 4, "W1600: projects");
        assert_eq!(run_rows(&ex, "SELECT * FROM orders"), 7, "W1600: orders");
    }

