        assert_eq!(r.rows[3][1].as_i64().unwrap(), 4, "W1676: RANK row4");
        // DENSE_RANK: [1,1,2,3]
        assert_eq!(r.rows[0][2].as_i64().unwrap(), 1, "W1676: DENSE_RANK row1");
        assert_eq!(r.rows[1][2].as_i64().unwrap(), 1, "W1676: DENSE_RANK row2");
        assert_eq!(r.rows[2][2].as_i64().unwrap(), 2, "W1676: DENSE_RANK row3");
