        // LEFT JOIN with condition in ON vs WHERE gives different results
        let r1 = run(&ex, "SELECT e.name FROM employees e LEFT JOIN orders o ON e.id = o.employee_id AND o.status = 'shipped' WHERE o.id IS NULL ORDER BY e.name");
        let r2 = run(&ex, "SELECT e.name FROM employees e LEFT JOIN orders o ON e.id = o.employee_id WHERE o.id IS NULL ORDER BY e.name");
