    // ---- CATEGORY J: UPDATE/DELETE MUTATION CORRECTNESS ----
    // Ref: DuckDB #16836, DuckLake #597

    // --- W1683: UPDATE then immediate SELECT consistency ---
    #[tokio::test]
    async fn w1683_update_read_consistency() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w1683 (id INT, val INT)");
        for i in 0..10 {
            run(&ex, &format!("INSERT INTO w1683 VALUES ({}, {})", i, i * 10));
        }
        run(&ex, "UPDATE w1683 SET val = val + 1 WHERE id >= 5");
        // Verify ALL rows, not just updated ones
        let r = run(&ex, "SELECT id, val FROM w1683 ORDER BY id");
        assert_eq!(r.rows.len(), 10, "W1683");
        // id=0: 0, id=4: 40 (unchanged), id=5: 51, id=9: 91
        assert_eq!(r.rows[0][1].as_i64().unwrap(), 0, "W1683: unchanged row");
        assert_eq!(r.rows[4][1].as_i64().unwrap(), 40, "W1683: boundary unchanged");
        assert_eq!(r.rows[5][1].as_i64().unwrap(), 51, "W1683: boundary updated");
        assert_eq!(r.rows[9][1].as_i64().unwrap(), 91, "W1683: last updated");
    }

    // --- W1684: DELETE with complex predicate + verify ---
    #[tokio::test]
    async fn w1684_delete_complex_verify() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w1684 (id INT, a INT, b INT)");
        for i in 0..20 {
            run(&ex, &format!("INSERT INTO w1684 VALUES ({}, {}, {})", i, i % 4, i % 3));
        }
        // DELETE WHERE a = 0 AND b = 0 → id where i%4=0 AND i%3=0 → i%12=0 → id=0,12
        run(&ex, "DELETE FROM w1684 WHERE a = 0 AND b = 0");
        assert_eq!(run_rows(&ex, "SELECT * FROM w1684"), 18, "W1684: 2 deleted");
        // Verify specific rows are gone
        let r = run(&ex, "SELECT COUNT(*) FROM w1684 WHERE id = 0");
        assert_eq!(r.rows[0][0].as_i64().unwrap(), 0, "W1684: id=0 gone");
        let r2 = run(&ex, "SELECT COUNT(*) FROM w1684 WHERE id = 12");
        assert_eq!(r2.rows[0][0].as_i64().unwrap(), 0, "W1684: id=12 gone");
    }

    // --- W1685: Multiple UPDATEs to same row ---
    #[tokio::test]
    async fn w1685_multi_update_same_row() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w1685 (id INT, val INT)");
        run(&ex, "INSERT INTO w1685 VALUES (1, 0)");
        for _ in 0..10 {
            run(&ex, "UPDATE w1685 SET val = val + 1 WHERE id = 1");
        }
        let r = run(&ex, "SELECT val FROM w1685 WHERE id = 1");
        assert_eq!(r.rows[0][0].as_i64().unwrap(), 10, "W1685: 10 increments");
    }

