    // --- W1696: Float precision in SUM ---
    #[tokio::test]
    async fn w1696_float_sum_precision() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w1696 (id INT, val FLOAT)");
        run(&ex, "INSERT INTO w1696 VALUES (1, 0.1)");
        run(&ex, "INSERT INTO w1696 VALUES (2, 0.2)");
        let r = run(&ex, "SELECT SUM(val) FROM w1696");
        let sum = r.rows[0][0].as_f64().unwrap();
        // 0.1 + 0.2 ≈ 0.3 (but IEEE 754 says 0.30000000000000004)
        assert!((sum - 0.3).abs() < 0.001, "W1696: float SUM ≈ 0.3, got {}", sum);
    }

