    // ---- CATEGORY O: COMPLEX REAL-WORLD PATTERNS ----
    // Composite tests mimicking real application queries

    // --- W1699: Anti-join pattern (LEFT JOIN + IS NULL) ---
    #[tokio::test]
    async fn w1699_anti_join_pattern() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        // Find departments with no active projects
        let r = run(&ex, "SELECT d.name FROM departments d LEFT JOIN projects p ON d.id = p.dept_id AND p.status = 'active' WHERE p.id IS NULL ORDER BY d.name");
        // Active projects: Alpha(dept1), Gamma(dept2). No active in dept3(Marketing).
        // But dept1 also has Beta(completed) — LEFT JOIN ON active: dept1 matches Alpha only.
        // Wait, LEFT JOIN with AND status='active' — dept1 has Alpha(active), so p.id is NOT null for dept1.
        // dept2 has Gamma(active), so p.id not null. dept3 has Delta(planning, not active), so p.id IS NULL.
        assert!(r.rows.len() >= 1, "W1699: anti-join finds depts without active projects");
    }

    // --- W1700: Pivot-style query with CASE aggregation ---
    #[tokio::test]
    async fn w1700_pivot_case_agg() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let r = run(&ex, "SELECT dept_id, SUM(CASE WHEN salary > 100000 THEN 1 ELSE 0 END) as high_earners, SUM(CASE WHEN salary <= 100000 THEN 1 ELSE 0 END) as others FROM employees GROUP BY dept_id ORDER BY dept_id");
        assert_eq!(r.rows.len(), 3, "W1700: pivot query");
        // dept1: high=3(Alice120,Bob110,Frank130), others=0
        let high = r.rows[0][1].as_i64().unwrap();
        let others = r.rows[0][2].as_i64().unwrap();
        assert_eq!(high, 3, "W1700: dept1 high earners");
        assert_eq!(others, 0, "W1700: dept1 others");
    }

    // --- W1701–W1710: Stress tests for NULL handling at scale ---
    #[tokio::test]
    async fn w1701_null_heavy_table() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w1701 (id INT, a INT, b INT, c INT)");
        for i in 0..100 {
            let a = if i % 3 == 0 { "NULL".to_string() } else { format!("{}", i) };
            let b = if i % 5 == 0 { "NULL".to_string() } else { format!("{}", i * 2) };
            let c = if i % 7 == 0 { "NULL".to_string() } else { format!("{}", i * 3) };
            run(&ex, &format!("INSERT INTO w1701 VALUES ({}, {}, {}, {})", i, a, b, c));
        }
        let r = run(&ex, "SELECT COUNT(*), COUNT(a), COUNT(b), COUNT(c) FROM w1701");
        assert_eq!(r.rows[0][0].as_i64().unwrap(), 100, "W1701: 100 rows total");
        // NULL counts: a: every 3rd (0,3,6,...99) = 34. b: every 5th = 20. c: every 7th ≈ 15.
        let count_a = r.rows[0][1].as_i64().unwrap();
        assert_eq!(count_a, 66, "W1701: COUNT(a)=66 non-null"); // 100 - 34
    }

