    // --- W1719: CTE with NULL aggregation ---
    #[tokio::test]
    async fn w1719_cte_null_agg() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w1719 (grp TEXT, val INT)");
        run(&ex, "INSERT INTO w1719 VALUES ('a', 10)");
        run(&ex, "INSERT INTO w1719 VALUES ('a', NULL)");
        run(&ex, "INSERT INTO w1719 VALUES ('b', NULL)");
        run(&ex, "INSERT INTO w1719 VALUES ('b', NULL)");
        let r = run(&ex, "WITH stats AS (SELECT grp, COUNT(*) as cnt, COUNT(val) as non_null_cnt, COALESCE(SUM(val), 0) as total FROM w1719 GROUP BY grp) SELECT grp, cnt, non_null_cnt, total FROM stats ORDER BY grp");
        assert_eq!(r.rows.len(), 2, "W1719");
        // grp 'a': cnt=2, non_null=1, total=10
        assert_eq!(r.rows[0][1].as_i64().unwrap(), 2);
        assert_eq!(r.rows[0][2].as_i64().unwrap(), 1);
        let total_a = r.rows[0][3].as_i64().unwrap();
        assert_eq!(total_a, 10);
        // grp 'b': cnt=2, non_null=0, total=0 (COALESCE)
        assert_eq!(r.rows[1][2].as_i64().unwrap(), 0);
        let total_b = r.rows[1][3].as_i64().unwrap();
        assert_eq!(total_b, 0);
    }

