    // --- W1736: Window SUM with NULL values ---
    #[tokio::test]
    async fn w1736_window_sum_null() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w1736 (id INT, val INT)");
        run(&ex, "INSERT INTO w1736 VALUES (1, 10)");
        run(&ex, "INSERT INTO w1736 VALUES (2, NULL)");
        run(&ex, "INSERT INTO w1736 VALUES (3, 30)");
        let r = run(&ex, "SELECT id, val, SUM(val) OVER (ORDER BY id) as running FROM w1736 ORDER BY id");
        assert_eq!(r.rows.len(), 3, "W1736");
        // Window SUM with ORDER BY is a RUNNING sum (default frame: UNBOUNDED PRECEDING to CURRENT ROW)
        let rs0 = r.rows[0][2].as_i64().unwrap();
        assert_eq!(rs0, 10, "W1736: running SUM row1 = 10");
        let rs1 = r.rows[1][2].as_i64().unwrap();
        assert_eq!(rs1, 10, "W1736: running SUM row2 = 10 (NULL skipped)");
        let rs2 = r.rows[2][2].as_i64().unwrap();
        assert_eq!(rs2, 40, "W1736: running SUM row3 = 40");
    }

