    // --- W1749: Full mutation + verify cycle with NULLs ---
    #[tokio::test]
    async fn w1749_full_null_cycle() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w1749 (id INT, val INT)");
        run(&ex, "INSERT INTO w1749 VALUES (1, 10)");
        run(&ex, "INSERT INTO w1749 VALUES (2, NULL)");
        run(&ex, "INSERT INTO w1749 VALUES (3, 30)");
        // UPDATE: set val to NULL where > 20
        run(&ex, "UPDATE w1749 SET val = NULL WHERE val > 20");
        let r = run(&ex, "SELECT COUNT(*), COUNT(val), SUM(val) FROM w1749");
        assert_eq!(r.rows[0][0].as_i64().unwrap(), 3, "W1749: 3 rows");
        // After UPDATE SET val = NULL WHERE val > 20: id=1(10), id=2(NULL), id=3(NULL)
        // COUNT(val) = 1 (only id=1 is non-null)
        let count_val = r.rows[0][1].as_i64().unwrap();
        assert_eq!(count_val, 1, "W1749: COUNT(val)=1 after UPDATE SET NULL");
        // DELETE NULLs — id=2 and id=3 are NULL
        run(&ex, "DELETE FROM w1749 WHERE val IS NULL");
        assert_eq!(run_rows(&ex, "SELECT * FROM w1749"), 1, "W1749: 1 remains");
    }

    // --- W1750: Batch 34 grand finale — 1750-test milestone ---
    #[tokio::test]
    async fn w1750_batch34_grand_finale() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);

        // 1: Empty-set aggregate
        let r1 = run(&ex, "SELECT COUNT(*), SUM(salary) FROM employees WHERE dept_id = 999");
        assert_eq!(r1.rows[0][0].as_i64().unwrap(), 0, "W1750: empty COUNT=0");
        assert!(r1.rows[0][1].is_null(), "W1750: empty SUM=NULL");

        // 2: NULL arithmetic
        let r2 = run(&ex, "SELECT NULL + 1, NULL * 0");
        assert!(r2.rows[0][0].is_null(), "W1750: NULL+1=NULL");
        assert!(r2.rows[0][1].is_null(), "W1750: NULL*0=NULL");

        // 3: BETWEEN boundary
        let r3 = run(&ex, "SELECT COUNT(*) FROM employees WHERE salary BETWEEN 120000 AND 120000");
        assert_eq!(r3.rows[0][0].as_i64().unwrap(), 1, "W1750: exact BETWEEN");

        // 4: CASE no ELSE
        let r4 = run(&ex, "SELECT CASE WHEN 1 = 0 THEN 'yes' END");
        assert!(r4.rows[0][0].is_null(), "W1750: CASE no match → NULL");

        // 5: COALESCE(SUM(all NULL), 0)
        run(&ex, "CREATE TABLE w1750_n (id INT, val INT)");
        run(&ex, "INSERT INTO w1750_n VALUES (1, NULL)");
        let r5 = run(&ex, "SELECT COALESCE(SUM(val), 0) FROM w1750_n");
        assert_eq!(r5.rows[0][0].as_i64().unwrap(), 0, "W1750: COALESCE SUM NULL");

        // 6: COUNT(*) vs COUNT(col)
        let r6 = run(&ex, "SELECT COUNT(*), COUNT(val) FROM w1750_n");
        assert_eq!(r6.rows[0][0].as_i64().unwrap(), 1, "W1750: COUNT(*)=1");
        assert_eq!(r6.rows[0][1].as_i64().unwrap(), 0, "W1750: COUNT(val)=0");

        // 7: Schema intact
        assert_eq!(run_rows(&ex, "SELECT * FROM departments"), 3, "W1750: departments");
        assert_eq!(run_rows(&ex, "SELECT * FROM employees"), 6, "W1750: employees");
        assert_eq!(run_rows(&ex, "SELECT * FROM projects"), 4, "W1750: projects");
        assert_eq!(run_rows(&ex, "SELECT * FROM orders"), 7, "W1750: orders");
    }

    // ========================================================================
    // Batch 35: W1751-W1850 — Real-world DBMS bug patterns
    // Grounded in bugs found by SQLancer (Rigger et al.) across SQLite,
    // PostgreSQL, CockroachDB, DuckDB, MySQL, TiDB. 175+ logic bugs
    // catalogued at manuelrigger.at/dbms-bugs. Categories:
    //   - NULL three-valued logic edge cases
    //   - Aggregate on empty / all-NULL groups
    //   - JOIN + NULL key interactions
    //   - ORDER BY / DISTINCT / GROUP BY interactions
    //   - Window function edge cases
    //   - Type coercion and arithmetic edge cases
    //   - Subquery correlation and scalar subquery bugs
    //   - Set operation (UNION/INTERSECT/EXCEPT) edge cases
    //   - UPDATE/DELETE with complex predicates
    //   - COALESCE / CASE / CAST interactions
    // ========================================================================

    // --- W1751: NULL = NULL is UNKNOWN, not TRUE (SQLite bug #1) ---
    #[tokio::test]
    async fn w1751_null_eq_null() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w1751 (id INT, val INT)");
        run(&ex, "INSERT INTO w1751 VALUES (1, NULL)");
        run(&ex, "INSERT INTO w1751 VALUES (2, NULL)");
        // NULL = NULL should be UNKNOWN → WHERE filters it out
        assert_eq!(run_rows(&ex, "SELECT * FROM w1751 WHERE val = val"), 0, "W1751: NULL=NULL is UNKNOWN");
    }

    // --- W1752: NOT NULL != NULL (three-valued logic) ---
