        run(&ex, "INSERT INTO w1831 VALUES (1, 100)");
        run(&ex, "INSERT INTO w1831 VALUES (2, 100)");
        run(&ex, "INSERT INTO w1831 VALUES (3, 100)");
        run(&ex, "INSERT INTO w1831 VALUES (4, 90)");
        let r = run(&ex, "SELECT id, RANK() OVER (ORDER BY score DESC) as rnk FROM w1831 ORDER BY id");
        // All 100s get rank 1, 90 gets rank 4
