    // --- W1850: Grand finale — full pipeline stress ---
    #[tokio::test]
    async fn w1850_batch35_finale() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);

        // 1: NULL three-valued logic
        run(&ex, "CREATE TABLE w1850_n (id INT, val INT)");
        run(&ex, "INSERT INTO w1850_n VALUES (1, NULL)");
        run(&ex, "INSERT INTO w1850_n VALUES (2, 10)");
        assert_eq!(run_rows(&ex, "SELECT * FROM w1850_n WHERE val = val"), 1, "W1850: NULL=NULL is UNKNOWN");

        // 2: Aggregate consistency
        let r1 = run(&ex, "SELECT COUNT(*), COUNT(val), SUM(val), COALESCE(AVG(val), 0) FROM w1850_n");
        assert_eq!(r1.rows[0][0].as_i64().unwrap(), 2, "W1850: COUNT(*)=2");
        assert_eq!(r1.rows[0][1].as_i64().unwrap(), 1, "W1850: COUNT(val)=1");
        assert_eq!(r1.rows[0][2].as_i64().unwrap(), 10, "W1850: SUM=10");

        // 3: Window + RANK
        let r2 = run(&ex, "SELECT name, RANK() OVER (ORDER BY salary DESC) as rnk FROM employees");
        assert_eq!(r2.rows.len(), 6, "W1850: window rank");

        // 4: CTE + JOIN + aggregate
        let r3 = run(&ex, "WITH dept_stats AS (SELECT dept_id, COUNT(*) as cnt FROM employees GROUP BY dept_id) SELECT d.name, s.cnt FROM dept_stats s JOIN departments d ON s.dept_id = d.id ORDER BY s.cnt DESC");
        assert_eq!(r3.rows.len(), 3, "W1850: CTE+JOIN");

        // 5: UPDATE + verify
        run(&ex, "UPDATE w1850_n SET val = NULL WHERE val = 10");
        let r4 = run(&ex, "SELECT COUNT(val) FROM w1850_n");
        assert_eq!(r4.rows[0][0].as_i64().unwrap(), 0, "W1850: all NULL after UPDATE");

        // 6: Schema intact
        assert_eq!(run_rows(&ex, "SELECT * FROM departments"), 3, "W1850: departments");
        assert_eq!(run_rows(&ex, "SELECT * FROM employees"), 6, "W1850: employees");
    }

