    // --- W1931: ORDER BY expression (salary * -1) ---
    #[tokio::test]
    async fn w1931_order_by_expr() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let r = run(&ex, "SELECT name, salary FROM employees ORDER BY salary * -1");
        // ORDER BY salary * -1 ASC: -130K < -120K < -110K < -95K < -90K < -85K
        // → Frank(130K), Alice(120K), Bob(110K), Carol(95K), Eve(90K), Dave(85K)
        assert_eq!(r.rows[0][0].as_str().unwrap(), "Frank", "W1931: Frank first (highest salary, most negative *-1)");
        assert_eq!(r.rows[5][0].as_str().unwrap(), "Dave", "W1931: Dave last (lowest salary)");
    }

