    // --- W1950: Batch 36 finale — full pipeline ---
    #[tokio::test]
    async fn w1950_batch36_finale() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);

        // 1: CTE + window + aggregate
        let r1 = run(&ex, "WITH ranked AS (SELECT name, salary, RANK() OVER (ORDER BY salary DESC) as rnk FROM employees) SELECT COUNT(*) FROM ranked WHERE rnk <= 3");
        assert_eq!(r1.rows[0][0].as_i64().unwrap(), 3, "W1950: top 3");

        // 2: Derived table (subquery) in JOIN
        let r2 = run(&ex, "SELECT d.name, sub.cnt FROM departments d JOIN (SELECT dept_id, COUNT(*) as cnt FROM employees GROUP BY dept_id) sub ON d.id = sub.dept_id ORDER BY sub.cnt DESC");
        assert_eq!(r2.rows.len(), 3, "W1950: 3 depts via derived table JOIN");

        // 3: Window SUM partitioned
        let r3 = run(&ex, "SELECT name, SUM(salary) OVER (PARTITION BY dept_id) as dept_total FROM employees ORDER BY name");
        assert_eq!(r3.rows.len(), 6, "W1950: window partitioned");

        // 4: HAVING + ORDER BY
        let r4 = run(&ex, "SELECT dept_id, AVG(salary) as avg_sal FROM employees GROUP BY dept_id HAVING AVG(salary) > 100000 ORDER BY avg_sal DESC");
        assert!(r4.rows.len() >= 1, "W1950: at least 1 dept with avg>100K");

        // 5: Schema intact
        assert_eq!(run_rows(&ex, "SELECT * FROM departments"), 3, "W1950: departments");
        assert_eq!(run_rows(&ex, "SELECT * FROM employees"), 6, "W1950: employees");
    }

