    // --- W1984: Window RANK with ties ---
    #[tokio::test]
    async fn w1984_rank_ties() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w1984 (id INT, score INT)");
        run(&ex, "INSERT INTO w1984 VALUES (1, 100)");
        run(&ex, "INSERT INTO w1984 VALUES (2, 100)");
        run(&ex, "INSERT INTO w1984 VALUES (3, 90)");
        let r = run(&ex, "SELECT id, score, RANK() OVER (ORDER BY score DESC) as rnk FROM w1984 ORDER BY id");
        assert_eq!(r.rows.len(), 3, "W1984: 3 rows");
        // Both score=100 should get rank 1, score=90 gets rank 3
        assert_eq!(r.rows[0][2].as_i64().unwrap(), 1, "W1984: rank 1 for tie");
        assert_eq!(r.rows[1][2].as_i64().unwrap(), 1, "W1984: rank 1 for tie");
        assert_eq!(r.rows[2][2].as_i64().unwrap(), 3, "W1984: rank 3 after tie");
    }

