        run(&ex, "INSERT INTO w2000 VALUES (1, 'Alice')");
        run(&ex, "INSERT INTO w2000 VALUES (2, 'Bob')");
        assert_eq!(run_rows(&ex, "SELECT * FROM w2000"), 2, "W2000: 2 rows before alter");
        // Verify data survives schema operations
