    // --- W2050: Batch 37 finale — grand stress test ---
    #[tokio::test]
    async fn w2050_batch37_finale() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);

        // 1: Full aggregate pipeline
        let r1 = run(&ex, "SELECT dept_id, COUNT(*) as cnt, SUM(salary) as total, MIN(salary) as lo, MAX(salary) as hi FROM employees GROUP BY dept_id HAVING COUNT(*) > 1 ORDER BY total DESC");
        assert_eq!(r1.rows.len(), 2, "W2050: 2 depts with >1");

        // 2: CTE + window + filter
        let r2 = run(&ex, "WITH r AS (SELECT name, salary, RANK() OVER (ORDER BY salary DESC) as rnk FROM employees) SELECT name FROM r WHERE rnk = 1");
        assert_eq!(r2.rows[0][0].as_str().unwrap(), "Frank", "W2050: Frank is #1");

        // 3: EXISTS with correlated subquery
        let r3 = run(&ex, "SELECT d.name FROM departments d WHERE EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.id AND e.salary > 100000) ORDER BY d.name");
        assert!(r3.rows.len() >= 1, "W2050: depts with high earners");

        // 4: Window partitioned SUM
        let r4 = run(&ex, "SELECT name, SUM(salary) OVER (PARTITION BY dept_id) as dept_total FROM employees ORDER BY name");
        assert_eq!(r4.rows.len(), 6, "W2050: 6 window rows");

        // 5: Schema intact after all operations
        assert_eq!(run_rows(&ex, "SELECT * FROM departments"), 3, "W2050: departments intact");
        assert_eq!(run_rows(&ex, "SELECT * FROM employees"), 6, "W2050: employees intact");
    }

