    async fn w2105_multi_coalesce() {
        let ex = SimpleQueryExecutor::new();
        run(&ex, "CREATE TABLE w2105 (id INT, a INT, b INT, c INT)");
        run(&ex, "INSERT INTO w2105 VALUES (1, NULL, NULL, 30)");
        run(&ex, "INSERT INTO w2105 VALUES (2, 10, NULL, 30)");
        run(&ex, "INSERT INTO w2105 VALUES (3, NULL, 20, 30)");
        let r = run(&ex, "SELECT id, COALESCE(a, b, c) as first_non_null FROM w2105 ORDER BY id");
        let v1 = r.rows[0][1].as_i64().unwrap_or_else(|| r.rows[0][1].as_f64().unwrap() as i64);
        let v2 = r.rows[1][1].as_i64().unwrap_or_else(|| r.rows[1][1].as_f64().unwrap() as i64);
        let v3 = r.rows[2][1].as_i64().unwrap_or_else(|| r.rows[2][1].as_f64().unwrap() as i64);
        assert_eq!(v1, 30, "W2105: NULL,NULL,30→30");
        assert_eq!(v2, 10, "W2105: 10,NULL,30→10");
        assert_eq!(v3, 20, "W2105: NULL,20,30→20");
    }

