    // --- W2150: Batch 38 finale — all new features stress ---
    #[tokio::test]
    async fn w2150_batch38_finale() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);

        // 1: Scalar subquery in SELECT
        let r1 = run(&ex, "SELECT name, (SELECT MAX(salary) FROM employees) as max_sal FROM employees WHERE name = 'Dave'");
        let max_v = r1.rows[0][1].as_i64().unwrap_or_else(|| r1.rows[0][1].as_f64().unwrap() as i64);
        assert_eq!(max_v, 130000, "W2150: scalar subquery");

        // 2: Derived table in JOIN
        let r2 = run(&ex, "SELECT d.name, sub.cnt FROM departments d JOIN (SELECT dept_id, COUNT(*) as cnt FROM employees GROUP BY dept_id) sub ON d.id = sub.dept_id ORDER BY sub.cnt DESC");
        assert_eq!(r2.rows.len(), 3, "W2150: derived table join");

        // 3: ORDER BY positional
        let r3 = run(&ex, "SELECT name, salary FROM employees ORDER BY 2 DESC LIMIT 1");
        assert_eq!(r3.rows[0][0].as_str().unwrap(), "Frank", "W2150: positional order");

        // 4: EXISTS + HAVING
        let r4 = run(&ex, "SELECT name FROM departments d WHERE EXISTS (SELECT dept_id FROM employees WHERE dept_id = d.id GROUP BY dept_id HAVING COUNT(*) > 2)");
        assert_eq!(r4.rows.len(), 1, "W2150: EXISTS+HAVING");

        // 5: Schema intact
        assert_eq!(run_rows(&ex, "SELECT * FROM departments"), 3, "W2150: depts");
        assert_eq!(run_rows(&ex, "SELECT * FROM employees"), 6, "W2150: emps");
    }

