    // --- W2250: Batch 39 finale — comprehensive integration ---
    #[tokio::test]
    async fn w2250_batch39_finale() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);

        // 1: BETWEEN + aggregate
        let r1 = run(&ex, "SELECT COUNT(*) FROM employees WHERE salary BETWEEN 85000 AND 120000");
        assert_eq!(r1.rows[0][0].as_i64().unwrap(), 5, "W2250: 5 in range");

        // 2: Self-join with aggregate
        let r2 = run(&ex, "SELECT e1.name FROM employees e1 JOIN employees e2 ON e1.dept_id = e2.dept_id AND e1.id != e2.id GROUP BY e1.name HAVING COUNT(*) >= 2 ORDER BY e1.name");
        // dept1 has 3 → each sees 2 others, dept2 has 2 → each sees 1
        assert_eq!(r2.rows.len(), 3, "W2250: 3 with >=2 peers");

        // 3: CTE + window
        let r3 = run(&ex, "WITH ranked AS (SELECT name, salary, ROW_NUMBER() OVER (ORDER BY salary DESC) as rn FROM employees) SELECT name FROM ranked WHERE rn <= 3 ORDER BY name");
        assert_eq!(r3.rows.len(), 3, "W2250: top 3 from CTE+window");

        // 4: Nested CASE in aggregate
        let r4 = run(&ex, "SELECT COUNT(CASE WHEN salary > 100000 THEN 1 END) as high, COUNT(CASE WHEN salary <= 100000 THEN 1 END) as low FROM employees");
        assert_eq!(r4.rows[0][0].as_i64().unwrap(), 3, "W2250: 3 high");
        assert_eq!(r4.rows[0][1].as_i64().unwrap(), 3, "W2250: 3 low");

        // 5: Schema intact
        assert_eq!(run_rows(&ex, "SELECT * FROM departments"), 3, "W2250: depts");
        assert_eq!(run_rows(&ex, "SELECT * FROM employees"), 6, "W2250: emps");
        assert_eq!(run_rows(&ex, "SELECT * FROM projects"), 4, "W2250: projects");
        assert_eq!(run_rows(&ex, "SELECT * FROM orders"), 7, "W2250: orders");
    }

    // =====================================================================
    //  INVARIANT FUZZER — Algebraic SQL Property Testing
    //
    //  Mathematical framework: SQL engines must satisfy algebraic laws
    //  regardless of data. We enumerate the feature cross-product and
    //  verify invariants hold at every point.
    //
    //  Feature dimensions (enumerated):
    //    T = {employees, departments, projects, orders}  (4 tables)
    //    C = numeric columns per table                   (varies)
    //    P = {>, <, >=, <=, =, !=} × thresholds         (operators × values)
    //    A = {COUNT, SUM, MIN, MAX, AVG}                 (5 aggregates)
    //    J = {INNER, LEFT, CROSS} × table pairs          (join types)
    //    W = {ROW_NUMBER, SUM, COUNT, MAX} OVER          (window fns)
    //
    //  Total coverage: |T|×|C|×|P|×|A| + |J| + |W| ~ thousands
    //  of invariant checks from ~200 lines of generator code.
    // =====================================================================

    /// Helper: extract a numeric value from a JSON cell, handling float-stored ints
    fn val(v: &serde_json::Value) -> Option<f64> {
        v.as_f64().or_else(|| v.as_i64().map(|i| i as f64))
    }

    /// Helper: try running SQL, return Ok(response) or Err(error message)
    fn try_run(executor: &SimpleQueryExecutor, sql: &str) -> Result<QueryResponse, String> {
        let request = QueryRequest {
            sql: sql.to_string(),
            params: Default::default(),
            args: Vec::new(),
            explain: false,
            limit: None,
            session_id: None,
            query_timeout_ms: None,
            branch_id: None,
            tenant_id: None,
        };
        executor.execute(&request).map_err(|e| format!("{}: {}", e.code, e.message))
    }

    /// Invariant result tracker
    struct InvariantReport {
        passed: usize,
        failed: Vec<String>,
    }

    impl InvariantReport {
        fn new() -> Self { Self { passed: 0, failed: Vec::new() } }

        fn check(&mut self, name: &str, ok: bool, detail: &str) {
            if ok {
                self.passed += 1;
            } else {
                self.failed.push(format!("FAIL {}: {}", name, detail));
            }
        }

        fn finish(self) {
            if !self.failed.is_empty() {
                let summary = self.failed.join("\n  ");
                panic!(
                    "\n\nINVARIANT VIOLATIONS: {} failed, {} passed\n  {}\n",
                    self.failed.len(), self.passed, summary
                );
            }
        }
    }

    // -----------------------------------------------------------------
    //  INV-1: Partition Additivity
    //
    //  For any predicate P on column C:
    //    COUNT(*) WHERE C > t  +  COUNT(*) WHERE C <= t  =  COUNT(*)
    //    SUM(C) WHERE C > t   +  SUM(C) WHERE C <= t    =  SUM(C)
    //
    //  This is the Fundamental Theorem of Counting applied to SQL.
    //  If it fails, either WHERE filtering or aggregation is broken.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv1_partition_additivity() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let specs: Vec<(&str, &str, Vec<i64>)> = vec![
            ("employees", "salary", vec![80000, 90000, 95000, 100000, 110000, 120000, 130000, 150000]),
            ("employees", "id", vec![0, 1, 2, 3, 4, 5, 6, 7]),
            ("departments", "id", vec![0, 1, 2, 3, 4]),
            ("departments", "budget", vec![100000, 200000, 300000, 500000, 600000]),
            ("orders", "amount", vec![0, 1500, 2000, 3000, 5000, 7500, 10000]),
            ("orders", "id", vec![0, 1, 3, 5, 7, 8]),
            ("projects", "id", vec![0, 1, 2, 3, 4, 5]),
        ];

        for (table, col, thresholds) in &specs {
            // Get total count and sum
            let total = run(&ex, &format!("SELECT COUNT(*) FROM {}", table));
            let total_count = total.rows[0][0].as_i64().unwrap();

            let sum_r = run(&ex, &format!("SELECT SUM({}) FROM {}", col, table));
            let total_sum = val(&sum_r.rows[0][0]).unwrap_or(0.0);

            for t in thresholds {
                let tag = format!("{}.{} @ {}", table, col, t);

                // COUNT partition: WHERE col > t + WHERE col <= t = total
                let gt = run(&ex, &format!("SELECT COUNT(*) FROM {} WHERE {} > {}", table, col, t));
                let le = run(&ex, &format!("SELECT COUNT(*) FROM {} WHERE {} <= {}", table, col, t));
                let gt_count = gt.rows[0][0].as_i64().unwrap();
                let le_count = le.rows[0][0].as_i64().unwrap();

                r.check(
                    &format!("COUNT-partition({})", tag),
                    gt_count + le_count == total_count,
                    &format!("{}+{} != {}", gt_count, le_count, total_count),
                );

                // SUM partition: SUM WHERE col > t + SUM WHERE col <= t = total SUM
                let sum_gt = try_run(&ex, &format!(
                    "SELECT COALESCE(SUM({}), 0) FROM {} WHERE {} > {}", col, table, col, t
                ));
                let sum_le = try_run(&ex, &format!(
                    "SELECT COALESCE(SUM({}), 0) FROM {} WHERE {} <= {}", col, table, col, t
                ));
                if let (Ok(sg), Ok(sl)) = (sum_gt, sum_le) {
                    let s_gt = val(&sg.rows[0][0]).unwrap_or(0.0);
                    let s_le = val(&sl.rows[0][0]).unwrap_or(0.0);
                    r.check(
                        &format!("SUM-partition({})", tag),
                        (s_gt + s_le - total_sum).abs() < 0.01,
                        &format!("{}+{} != {}", s_gt, s_le, total_sum),
                    );
                }
            }
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-2: Aggregate Bounds
    //
    //  For any non-empty set:  MIN(x) <= AVG(x) <= MAX(x)
    //  Also: COUNT(*) = SUM(1)  (via CASE WHEN true THEN 1 END)
    //  Also: AVG(x) * COUNT(x) ≈ SUM(x)
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv2_aggregate_bounds() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let cols = vec![
            ("employees", "salary"),
            ("employees", "id"),
            ("orders", "amount"),
            ("orders", "id"),
            ("departments", "budget"),
            ("departments", "id"),
            ("projects", "id"),
        ];

        for (table, col) in &cols {
            let tag = format!("{}.{}", table, col);

            let agg = run(&ex, &format!(
                "SELECT COUNT(*), COUNT({}), SUM({}), MIN({}), MAX({}), AVG({}) FROM {}",
                col, col, col, col, col, table
            ));
            let count_star = val(&agg.rows[0][0]).unwrap();
            let count_col = val(&agg.rows[0][1]).unwrap();
            let sum_v = val(&agg.rows[0][2]).unwrap_or(0.0);
            let min_v = val(&agg.rows[0][3]).unwrap_or(0.0);
            let max_v = val(&agg.rows[0][4]).unwrap_or(0.0);
            let avg_v = val(&agg.rows[0][5]).unwrap_or(0.0);

            // COUNT(col) <= COUNT(*)
            r.check(
                &format!("COUNT(col)<=COUNT(*)({})", tag),
                count_col <= count_star,
                &format!("COUNT({})={} > COUNT(*)={}", col, count_col, count_star),
            );

            if count_col > 0.0 {
                // MIN <= AVG <= MAX
                r.check(
                    &format!("MIN<=AVG({})", tag),
                    min_v <= avg_v + 0.001,
                    &format!("MIN={} > AVG={}", min_v, avg_v),
                );
                r.check(
                    &format!("AVG<=MAX({})", tag),
                    avg_v <= max_v + 0.001,
                    &format!("AVG={} > MAX={}", avg_v, max_v),
                );

                // MIN <= MAX
                r.check(
                    &format!("MIN<=MAX({})", tag),
                    min_v <= max_v,
                    &format!("MIN={} > MAX={}", min_v, max_v),
                );

                // AVG * COUNT ≈ SUM (within rounding)
                let product = avg_v * count_col;
                r.check(
                    &format!("AVG*COUNT≈SUM({})", tag),
                    (product - sum_v).abs() < 1.0,
                    &format!("AVG*COUNT={} vs SUM={}", product, sum_v),
                );
            }

            // COUNT(*) via CASE = COUNT(*)
            let case_count = run(&ex, &format!(
                "SELECT COUNT(CASE WHEN 1=1 THEN 1 END) FROM {}", table
            ));
            let cc = val(&case_count.rows[0][0]).unwrap();
            r.check(
                &format!("COUNT-CASE-identity({})", tag),
                (cc - count_star).abs() < 0.5,
                &format!("CASE-COUNT={} vs COUNT(*)={}", cc, count_star),
            );
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-3: COUNT-CASE Duality
    //
    //  COUNT(*) WHERE predicate
    //    = COUNT(CASE WHEN predicate THEN 1 END)  [no WHERE]
    //
    //  Tests that WHERE filtering and CASE evaluation agree.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv3_count_case_duality() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let predicates: Vec<(&str, &str)> = vec![
            ("employees", "salary > 100000"),
            ("employees", "salary <= 100000"),
            ("employees", "dept_id = 1"),
            ("employees", "dept_id != 1"),
            ("employees", "id > 3"),
            ("employees", "id <= 3"),
            ("employees", "salary BETWEEN 90000 AND 120000"),
            ("orders", "amount > 3000"),
            ("orders", "amount <= 3000"),
            ("departments", "budget > 250000"),
            ("departments", "budget <= 250000"),
        ];

        for (table, pred) in &predicates {
            let tag = format!("{} WHERE {}", table, pred);

            let where_count = run(&ex, &format!("SELECT COUNT(*) FROM {} WHERE {}", table, pred));
            let case_count = run(&ex, &format!(
                "SELECT COUNT(CASE WHEN {} THEN 1 END) FROM {}", pred, table
            ));

            let wc = where_count.rows[0][0].as_i64().unwrap();
            let cc = case_count.rows[0][0].as_i64().unwrap();

            r.check(
                &format!("COUNT-CASE({})", tag),
                wc == cc,
                &format!("WHERE-count={} vs CASE-count={}", wc, cc),
            );
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-4: UNION ALL Cardinality
    //
    //  |A UNION ALL B| = |A| + |B|   (always)
    //  |A UNION B| <= |A| + |B|      (dedup can only reduce)
    //  |A UNION B| >= MAX(|A|, |B|)  (union has at least as many as either)
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv4_union_cardinality() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let pairs: Vec<(&str, &str)> = vec![
            ("SELECT id FROM employees", "SELECT id FROM departments"),
            ("SELECT id FROM employees WHERE dept_id = 1", "SELECT id FROM employees WHERE dept_id = 2"),
            ("SELECT id FROM employees WHERE salary > 100000", "SELECT id FROM employees WHERE salary <= 100000"),
            ("SELECT id FROM orders WHERE amount > 3000", "SELECT id FROM orders WHERE amount <= 3000"),
            ("SELECT name FROM employees", "SELECT name FROM departments"),
        ];

        for (sql_a, sql_b) in &pairs {
            let tag = format!("({}) ∪ ({})", sql_a, sql_b);

            let count_a = run_rows(&ex, sql_a);
            let count_b = run_rows(&ex, sql_b);
            let union_all = run_rows(&ex, &format!("{} UNION ALL {}", sql_a, sql_b));
            let union_dedup = run_rows(&ex, &format!("{} UNION {}", sql_a, sql_b));

            // |A UNION ALL B| = |A| + |B|
            r.check(
                &format!("UNION-ALL-card({})", tag),
                union_all == count_a + count_b,
                &format!("{} != {} + {}", union_all, count_a, count_b),
            );

            // |A UNION B| <= |A| + |B|
            r.check(
                &format!("UNION-upper({})", tag),
                union_dedup <= count_a + count_b,
                &format!("|UNION|={} > |A|+|B|={}", union_dedup, count_a + count_b),
            );

            // |A UNION B| >= max(|A|, |B|)
            let max_ab = count_a.max(count_b);
            r.check(
                &format!("UNION-lower({})", tag),
                union_dedup >= max_ab,
                &format!("|UNION|={} < max(|A|,|B|)={}", union_dedup, max_ab),
            );
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-5: JOIN Cardinality Bounds
    //
    //  |A INNER JOIN B| <= |A| × |B|
    //  |A LEFT JOIN B| >= |A|
    //  |A CROSS JOIN B| = |A| × |B|   (no ON clause)
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv5_join_cardinality() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        // INNER JOIN bounds
        let inner_joins: Vec<(&str, &str, &str, &str, usize, usize)> = vec![
            ("employees e", "departments d", "e.dept_id = d.id", "inner-emp-dept",
             run_rows(&ex, "SELECT * FROM employees"), run_rows(&ex, "SELECT * FROM departments")),
            ("employees e", "projects p", "e.dept_id = p.dept_id", "inner-emp-proj",
             run_rows(&ex, "SELECT * FROM employees"), run_rows(&ex, "SELECT * FROM projects")),
            ("orders o", "employees e", "o.employee_id = e.id", "inner-ord-emp",
             run_rows(&ex, "SELECT * FROM orders"), run_rows(&ex, "SELECT * FROM employees")),
        ];

        for (ta, tb, on_clause, tag, size_a, size_b) in &inner_joins {
            let joined = run_rows(&ex, &format!(
                "SELECT * FROM {} JOIN {} ON {}", ta, tb, on_clause
            ));
            r.check(
                &format!("INNER<=product({})", tag),
                joined <= size_a * size_b,
                &format!("|JOIN|={} > |A|*|B|={}", joined, size_a * size_b),
            );
        }

        // LEFT JOIN bounds: result >= left table
        let left_joins: Vec<(&str, &str, &str, &str, usize)> = vec![
            ("employees e", "departments d", "e.dept_id = d.id", "left-emp-dept",
             run_rows(&ex, "SELECT * FROM employees")),
            ("departments d", "employees e", "d.id = e.dept_id", "left-dept-emp",
             run_rows(&ex, "SELECT * FROM departments")),
            ("employees e", "orders o", "e.id = o.employee_id", "left-emp-ord",
             run_rows(&ex, "SELECT * FROM employees")),
        ];

        for (ta, tb, on_clause, tag, left_size) in &left_joins {
            let joined = run_rows(&ex, &format!(
                "SELECT * FROM {} LEFT JOIN {} ON {}", ta, tb, on_clause
            ));
            r.check(
                &format!("LEFT>=left({})", tag),
                joined >= *left_size,
                &format!("|LEFT JOIN|={} < |left|={}", joined, left_size),
            );
        }

        // CROSS JOIN: |A| × |B|
        let cross_joins: Vec<(&str, &str, &str, usize, usize)> = vec![
            ("departments", "projects", "cross-dept-proj",
             run_rows(&ex, "SELECT * FROM departments"), run_rows(&ex, "SELECT * FROM projects")),
        ];

        for (ta, tb, tag, size_a, size_b) in &cross_joins {
            let crossed = run_rows(&ex, &format!(
                "SELECT * FROM {}, {}", ta, tb
            ));
            r.check(
                &format!("CROSS=product({})", tag),
                crossed == size_a * size_b,
                &format!("|CROSS|={} != |A|*|B|={}", crossed, size_a * size_b),
            );
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-6: DISTINCT Idempotence
    //
    //  DISTINCT(DISTINCT(X)) = DISTINCT(X)
    //  |DISTINCT(X)| <= |X|
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv6_distinct_idempotence() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let queries: Vec<(&str, &str)> = vec![
            ("SELECT dept_id FROM employees", "dept_id"),
            ("SELECT salary FROM employees", "salary"),
            ("SELECT status FROM orders", "status"),
            ("SELECT dept_id FROM projects", "dept_id"),
            ("SELECT name FROM departments", "name"),
        ];

        for (sql, tag) in &queries {
            let plain = run_rows(&ex, sql);
            let once = run_rows(&ex, &sql.replace("SELECT ", "SELECT DISTINCT "));
            let twice_sql = format!(
                "SELECT DISTINCT * FROM ({}) sub",
                sql.replace("SELECT ", "SELECT DISTINCT ")
            );
            let twice = run_rows(&ex, &twice_sql);

            // |DISTINCT| <= |all|
            r.check(
                &format!("DISTINCT<=all({})", tag),
                once <= plain,
                &format!("|DISTINCT|={} > |all|={}", once, plain),
            );

            // DISTINCT(DISTINCT) = DISTINCT
            r.check(
                &format!("DISTINCT-idempotent({})", tag),
                twice == once,
                &format!("DISTINCT²={} != DISTINCT¹={}", twice, once),
            );
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-7: NULL Propagation
    //
    //  NULL + x = NULL, NULL * x = NULL, NULL > x = NULL (unknown)
    //  COUNT(*) counts NULLs, COUNT(col) skips NULLs
    //  IS NULL is the only way to match NULL (= NULL must be false)
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv7_null_propagation() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // Create table with NULLs
        run(&ex, "CREATE TABLE inv7 (id INT, a INT, b INT)");
        run(&ex, "INSERT INTO inv7 VALUES (1, 10, 20)");
        run(&ex, "INSERT INTO inv7 VALUES (2, NULL, 30)");
        run(&ex, "INSERT INTO inv7 VALUES (3, 40, NULL)");
        run(&ex, "INSERT INTO inv7 VALUES (4, NULL, NULL)");

        // NULL arithmetic propagation
        let arith = run(&ex, "SELECT id, a + b FROM inv7 ORDER BY id");
        r.check("NULL+x=NULL(row2)", arith.rows[1][1].is_null(), "a=NULL + b=30 should be NULL");
        r.check("NULL+x=NULL(row3)", arith.rows[2][1].is_null(), "a=40 + b=NULL should be NULL");
        r.check("NULL+NULL=NULL", arith.rows[3][1].is_null(), "NULL + NULL should be NULL");
        let v1 = val(&arith.rows[0][1]);
        r.check("10+20=30", v1 == Some(30.0), &format!("10+20={:?}", v1));

        // COUNT(*) vs COUNT(col)
        let counts = run(&ex, "SELECT COUNT(*), COUNT(a), COUNT(b) FROM inv7");
        let c_star = counts.rows[0][0].as_i64().unwrap();
        let c_a = counts.rows[0][1].as_i64().unwrap();
        let c_b = counts.rows[0][2].as_i64().unwrap();
        r.check("COUNT(*)=4", c_star == 4, &format!("COUNT(*)={}", c_star));
        r.check("COUNT(a)=2", c_a == 2, &format!("COUNT(a)={} (2 non-null)", c_a));
        r.check("COUNT(b)=2", c_b == 2, &format!("COUNT(b)={} (2 non-null)", c_b));

        // = NULL returns nothing (SQL standard: NULL=NULL is unknown, not true)
        let eq_null = run_rows(&ex, "SELECT * FROM inv7 WHERE a = NULL");
        r.check("eq-NULL=empty", eq_null == 0, &format!("a=NULL matched {} rows", eq_null));

        // IS NULL works correctly
        let is_null_count = run_rows(&ex, "SELECT * FROM inv7 WHERE a IS NULL");
        r.check("IS-NULL-a=2", is_null_count == 2, &format!("IS NULL matched {}", is_null_count));

        // IS NOT NULL
        let not_null_count = run_rows(&ex, "SELECT * FROM inv7 WHERE a IS NOT NULL");
        r.check("IS-NOT-NULL-a=2", not_null_count == 2, &format!("IS NOT NULL matched {}", not_null_count));

        // IS NULL + IS NOT NULL = COUNT(*)
        r.check(
            "NULL-partition",
            is_null_count + not_null_count == c_star as usize,
            &format!("IS NULL({}) + IS NOT NULL({}) != COUNT(*)={}", is_null_count, not_null_count, c_star),
        );

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-8: ORDER BY Cardinality Preservation
    //
    //  ORDER BY must not change row count.
    //  ORDER BY x ASC + ORDER BY x DESC should give reverse sequences.
    //  ORDER BY with LIMIT k returns exactly min(k, total) rows.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv8_order_cardinality() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let tables_and_cols: Vec<(&str, &str)> = vec![
            ("employees", "salary"),
            ("employees", "name"),
            ("employees", "id"),
            ("departments", "name"),
            ("departments", "budget"),
            ("orders", "amount"),
            ("orders", "id"),
            ("projects", "name"),
        ];

        for (table, col) in &tables_and_cols {
            let tag = format!("{}.{}", table, col);
            let plain = run_rows(&ex, &format!("SELECT * FROM {}", table));

            // ORDER BY doesn't change count
            let ordered = run_rows(&ex, &format!("SELECT * FROM {} ORDER BY {}", table, col));
            r.check(
                &format!("ORDER-card({})", tag),
                ordered == plain,
                &format!("ordered={} != plain={}", ordered, plain),
            );

            // ASC and DESC have same count
            let asc = run_rows(&ex, &format!("SELECT * FROM {} ORDER BY {} ASC", table, col));
            let desc = run_rows(&ex, &format!("SELECT * FROM {} ORDER BY {} DESC", table, col));
            r.check(
                &format!("ASC==DESC-card({})", tag),
                asc == desc,
                &format!("ASC={} != DESC={}", asc, desc),
            );

            // LIMIT k gives min(k, total)
            for k in &[0usize, 1, 2, 3, 5, 10, 100] {
                let limited = run_rows(&ex, &format!(
                    "SELECT * FROM {} ORDER BY {} LIMIT {}", table, col, k
                ));
                let expected = (*k).min(plain);
                r.check(
                    &format!("LIMIT-{}({})", k, tag),
                    limited == expected,
                    &format!("LIMIT {}={} != min({},{})", k, limited, k, plain),
                );
            }
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-9: GROUP BY Aggregate Consistency
    //
    //  SUM of group SUMs = total SUM
    //  SUM of group COUNTs = total COUNT
    //  Every group MIN >= global MIN, every group MAX <= global MAX
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv9_group_aggregate_consistency() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let specs: Vec<(&str, &str, &str)> = vec![
            ("employees", "dept_id", "salary"),
            ("employees", "dept_id", "id"),
            ("orders", "status", "amount"),
            ("orders", "employee_id", "amount"),
        ];

        for (table, group_col, agg_col) in &specs {
            let tag = format!("{}.{} by {}", table, agg_col, group_col);

            // Global aggregates
            let global = run(&ex, &format!(
                "SELECT COUNT(*), SUM({}), MIN({}), MAX({}) FROM {}",
                agg_col, agg_col, agg_col, table
            ));
            let g_count = val(&global.rows[0][0]).unwrap();
            let g_sum = val(&global.rows[0][1]).unwrap_or(0.0);
            let g_min = val(&global.rows[0][2]).unwrap_or(f64::MAX);
            let g_max = val(&global.rows[0][3]).unwrap_or(f64::MIN);

            // Per-group aggregates
            let groups = run(&ex, &format!(
                "SELECT {}, COUNT(*), SUM({}), MIN({}), MAX({}) FROM {} GROUP BY {}",
                group_col, agg_col, agg_col, agg_col, table, group_col
            ));

            let mut sum_of_counts = 0.0;
            let mut sum_of_sums = 0.0;
            let mut any_min_below_global = false;
            let mut any_max_above_global = false;

            for row in &groups.rows {
                sum_of_counts += val(&row[1]).unwrap_or(0.0);
                sum_of_sums += val(&row[2]).unwrap_or(0.0);
                let grp_min = val(&row[3]).unwrap_or(f64::MAX);
                let grp_max = val(&row[4]).unwrap_or(f64::MIN);
                if grp_min < g_min - 0.01 { any_min_below_global = true; }
                if grp_max > g_max + 0.01 { any_max_above_global = true; }
            }

            r.check(
                &format!("Σ(group-counts)=total({})", tag),
                (sum_of_counts - g_count).abs() < 0.5,
                &format!("Σ-counts={} vs total={}", sum_of_counts, g_count),
            );
            r.check(
                &format!("Σ(group-sums)=total({})", tag),
                (sum_of_sums - g_sum).abs() < 0.5,
                &format!("Σ-sums={} vs total={}", sum_of_sums, g_sum),
            );
            r.check(
                &format!("group-MIN>=global-MIN({})", tag),
                !any_min_below_global,
                "some group MIN < global MIN",
            );
            r.check(
                &format!("group-MAX<=global-MAX({})", tag),
                !any_max_above_global,
                "some group MAX > global MAX",
            );
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-10: Subquery Equivalences
    //
    //  WHERE x IN (SELECT y FROM t)  ≡  WHERE EXISTS (SELECT 1 FROM t WHERE t.y = x)
    //  Scalar subquery in SELECT = same value via JOIN
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv10_subquery_equivalence() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        // IN subquery vs EXISTS subquery
        let in_sub = run_rows(&ex,
            "SELECT name FROM employees WHERE dept_id IN (SELECT id FROM departments WHERE budget > 250000) ORDER BY name"
        );
        let exists_sub = run_rows(&ex,
            "SELECT name FROM employees e WHERE EXISTS (SELECT 1 FROM departments d WHERE d.id = e.dept_id AND d.budget > 250000) ORDER BY name"
        );
        r.check(
            "IN≡EXISTS(budget>250K)",
            in_sub == exists_sub,
            &format!("IN={} vs EXISTS={}", in_sub, exists_sub),
        );

        // IN vs EXISTS with different predicate
        let in_sub2 = run_rows(&ex,
            "SELECT name FROM employees WHERE dept_id IN (SELECT id FROM departments WHERE name = 'Engineering') ORDER BY name"
        );
        let exists_sub2 = run_rows(&ex,
            "SELECT name FROM employees e WHERE EXISTS (SELECT 1 FROM departments d WHERE d.id = e.dept_id AND d.name = 'Engineering') ORDER BY name"
        );
        r.check(
            "IN≡EXISTS(Engineering)",
            in_sub2 == exists_sub2,
            &format!("IN={} vs EXISTS={}", in_sub2, exists_sub2),
        );

        // NOT IN vs NOT EXISTS
        let not_in = run_rows(&ex,
            "SELECT name FROM departments WHERE id NOT IN (SELECT dept_id FROM employees WHERE salary > 100000) ORDER BY name"
        );
        let not_exists = run_rows(&ex,
            "SELECT name FROM departments d WHERE NOT EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.id AND e.salary > 100000) ORDER BY name"
        );
        r.check(
            "NOT-IN≡NOT-EXISTS(salary>100K)",
            not_in == not_exists,
            &format!("NOT IN={} vs NOT EXISTS={}", not_in, not_exists),
        );

        // Correlated scalar subquery vs JOIN+GROUP for dept employee counts
        // Compare as sets (name→count maps) since ORDER BY with GROUP BY may differ
        let scalar = run(&ex,
            "SELECT d.name, (SELECT COUNT(*) FROM employees e WHERE e.dept_id = d.id) as cnt FROM departments d"
        );
        let joined = run(&ex,
            "SELECT d.name, COUNT(e.id) as cnt FROM departments d LEFT JOIN employees e ON d.id = e.dept_id GROUP BY d.name"
        );
        r.check(
            "scalar≡join-row-count",
            scalar.rows.len() == joined.rows.len(),
            &format!("scalar has {} rows vs join has {}", scalar.rows.len(), joined.rows.len()),
        );
        // Build name→count maps and compare
        let mut scalar_map: std::collections::HashMap<String, f64> = std::collections::HashMap::new();
        for row in &scalar.rows {
            let name = row[0].as_str().unwrap_or("?").to_string();
            let cnt = val(&row[1]).unwrap_or(0.0);
            scalar_map.insert(name, cnt);
        }
        let mut join_map: std::collections::HashMap<String, f64> = std::collections::HashMap::new();
        for row in &joined.rows {
            let name = row[0].as_str().unwrap_or("?").to_string();
            let cnt = val(&row[1]).unwrap_or(0.0);
            join_map.insert(name, cnt);
        }
        for (name, s_cnt) in &scalar_map {
            let j_cnt = join_map.get(name).copied().unwrap_or(-1.0);
            r.check(
                &format!("scalar≡join({})", name),
                (s_cnt - j_cnt).abs() < 0.5,
                &format!("scalar={} vs join={}", s_cnt, j_cnt),
            );
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-11: Window Function Consistency
    //
    //  ROW_NUMBER() OVER (ORDER BY x) produces 1..N with no gaps
    //  SUM(x) OVER () = (SELECT SUM(x) FROM table) for every row
    //  COUNT(*) OVER () = total count for every row
    //  SUM of partition SUM OVER = global SUM
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv11_window_consistency() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        // ROW_NUMBER produces 1..N
        let rn = run(&ex, "SELECT ROW_NUMBER() OVER (ORDER BY salary) as rn FROM employees ORDER BY rn");
        let mut rn_values: Vec<i64> = rn.rows.iter()
            .filter_map(|row| row[0].as_i64())
            .collect();
        rn_values.sort();
        let expected_rn: Vec<i64> = (1..=6).collect();
        r.check(
            "ROW_NUMBER-1..N",
            rn_values == expected_rn,
            &format!("ROW_NUMBER values: {:?}", rn_values),
        );

        // SUM OVER () = global SUM on every row
        let global_sum = run(&ex, "SELECT SUM(salary) FROM employees");
        let g_sum = val(&global_sum.rows[0][0]).unwrap();

        let win_sum = run(&ex, "SELECT salary, SUM(salary) OVER () as total FROM employees");
        for (i, row) in win_sum.rows.iter().enumerate() {
            let row_total = val(&row[1]).unwrap_or(0.0);
            r.check(
                &format!("SUM-OVER()=global(row{})", i),
                (row_total - g_sum).abs() < 0.5,
                &format!("window SUM={} vs global={}", row_total, g_sum),
            );
        }

        // COUNT(*) OVER () = total count on every row
        let win_count = run(&ex, "SELECT COUNT(*) OVER () as cnt FROM employees");
        for (i, row) in win_count.rows.iter().enumerate() {
            let cnt = row[0].as_i64().unwrap_or(0);
            r.check(
                &format!("COUNT-OVER()=6(row{})", i),
                cnt == 6,
                &format!("window COUNT={}", cnt),
            );
        }

        // Partition SUM consistency: each row's partition SUM = sum of that partition's rows
        let part_sum = run(&ex, "SELECT dept_id, salary, SUM(salary) OVER (PARTITION BY dept_id) as dept_total FROM employees ORDER BY dept_id, salary");
        // Group by dept_id and verify partition sums
        let mut dept_sums: std::collections::HashMap<i64, (f64, f64)> = std::collections::HashMap::new();
        for row in &part_sum.rows {
            let dept = val(&row[0]).unwrap_or(0.0) as i64;
            let salary = val(&row[1]).unwrap_or(0.0);
            let reported_total = val(&row[2]).unwrap_or(0.0);
            let entry = dept_sums.entry(dept).or_insert((0.0, reported_total));
            entry.0 += salary;
        }
        for (dept, (actual_sum, reported)) in &dept_sums {
            r.check(
                &format!("partition-SUM-dept{}", dept),
                (actual_sum - reported).abs() < 0.5,
                &format!("actual sum={} vs reported partition={}", actual_sum, reported),
            );
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-12: DML Consistency
    //
    //  INSERT increases COUNT by 1
    //  DELETE decreases COUNT by matched rows
    //  UPDATE preserves COUNT
    //  DELETE WHERE false changes nothing
    //  UPDATE WHERE false changes nothing
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv12_dml_consistency() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv12 (id INT, val INT)");
        for i in 1..=10 {
            run(&ex, &format!("INSERT INTO inv12 VALUES ({}, {})", i, i * 10));
        }

        // Baseline
        let baseline = run_rows(&ex, "SELECT * FROM inv12");
        r.check("baseline=10", baseline == 10, &format!("baseline={}", baseline));

        // INSERT adds 1
        run(&ex, "INSERT INTO inv12 VALUES (11, 110)");
        let after_insert = run_rows(&ex, "SELECT * FROM inv12");
        r.check("INSERT+1", after_insert == baseline + 1, &format!("after insert={}", after_insert));

        // UPDATE preserves count
        run(&ex, "UPDATE inv12 SET val = val * 2 WHERE id <= 5");
        let after_update = run_rows(&ex, "SELECT * FROM inv12");
        r.check("UPDATE-preserves", after_update == after_insert, &format!("after update={}", after_update));

        // UPDATE WHERE false changes nothing
        let sum_before = run(&ex, "SELECT SUM(val) FROM inv12");
        let sb = val(&sum_before.rows[0][0]).unwrap();
        run(&ex, "UPDATE inv12 SET val = 0 WHERE 1 = 0");
        let sum_after = run(&ex, "SELECT SUM(val) FROM inv12");
        let sa = val(&sum_after.rows[0][0]).unwrap();
        r.check("UPDATE-false-noop", (sb - sa).abs() < 0.5, &format!("before={} after={}", sb, sa));

        // DELETE WHERE false changes nothing
        run(&ex, "DELETE FROM inv12 WHERE 1 = 0");
        let after_noop_del = run_rows(&ex, "SELECT * FROM inv12");
        r.check("DELETE-false-noop", after_noop_del == after_update, &format!("after noop delete={}", after_noop_del));

        // DELETE specific rows
        run(&ex, "DELETE FROM inv12 WHERE id > 8");
        let after_delete = run_rows(&ex, "SELECT * FROM inv12");
        // ids > 8: 9, 10, 11 → removed 3
        r.check("DELETE-3", after_delete == after_noop_del - 3, &format!("after delete={}", after_delete));

        // DELETE all
        run(&ex, "DELETE FROM inv12");
        let after_all = run_rows(&ex, "SELECT * FROM inv12");
        r.check("DELETE-all=0", after_all == 0, &format!("after delete all={}", after_all));

        // Aggregate on empty = COUNT 0, SUM NULL
        let empty_agg = run(&ex, "SELECT COUNT(*), SUM(val) FROM inv12");
        r.check("empty-COUNT=0", empty_agg.rows[0][0].as_i64().unwrap() == 0, "COUNT != 0");
        r.check("empty-SUM=NULL", empty_agg.rows[0][1].is_null(), "SUM != NULL on empty");

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-13: Comparison Operator Completeness
    //
    //  For any x, y: exactly one of (x < y, x = y, x > y) is true.
    //  WHERE x > k  ∪  WHERE x = k  ∪  WHERE x < k  = all rows
    //  WHERE x >= k  =  WHERE x > k  ∪  WHERE x = k
    //  WHERE x <= k  =  WHERE x < k  ∪  WHERE x = k
    //  WHERE x != k  =  WHERE x > k  ∪  WHERE x < k
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv13_comparison_completeness() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let specs: Vec<(&str, &str, Vec<i64>)> = vec![
            ("employees", "salary", vec![85000, 95000, 110000, 120000, 130000]),
            ("employees", "id", vec![1, 3, 6]),
            ("orders", "amount", vec![1500, 3000, 5000, 7500]),
            ("departments", "id", vec![1, 2, 3]),
        ];

        for (table, col, values) in &specs {
            let total = run_rows(&ex, &format!("SELECT * FROM {}", table));

            for v in values {
                let tag = format!("{}.{} vs {}", table, col, v);

                let gt = run_rows(&ex, &format!("SELECT * FROM {} WHERE {} > {}", table, col, v));
                let eq = run_rows(&ex, &format!("SELECT * FROM {} WHERE {} = {}", table, col, v));
                let lt = run_rows(&ex, &format!("SELECT * FROM {} WHERE {} < {}", table, col, v));
                let ge = run_rows(&ex, &format!("SELECT * FROM {} WHERE {} >= {}", table, col, v));
                let le = run_rows(&ex, &format!("SELECT * FROM {} WHERE {} <= {}", table, col, v));
                let ne = run_rows(&ex, &format!("SELECT * FROM {} WHERE {} != {}", table, col, v));

                // Trichotomy: gt + eq + lt = total
                r.check(
                    &format!("trichotomy({})", tag),
                    gt + eq + lt == total,
                    &format!("{}+{}+{} = {} (expected {})", gt, eq, lt, gt+eq+lt, total),
                );

                // >= = > + =
                r.check(
                    &format!(">= = >+=({})", tag),
                    ge == gt + eq,
                    &format!(">={} != >{}+={}={}", ge, gt, eq, gt+eq),
                );

                // <= = < + =
                r.check(
                    &format!("<= = <+=({})", tag),
                    le == lt + eq,
                    &format!("<={} != <{}+={}={}", le, lt, eq, lt+eq),
                );

                // != = > + <
                r.check(
                    &format!("!= = >+<({})", tag),
                    ne == gt + lt,
                    &format!("!={} != >{}+<{}={}", ne, gt, lt, gt+lt),
                );
            }
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-14: ORDER BY + GROUP BY Correctness
    //
    //  ORDER BY d.name on a GROUP BY d.name result must produce
    //  lexicographically sorted names. This was surfaced by INV-10
    //  where scalar subquery ORDER matched but LEFT JOIN+GROUP BY
    //  ORDER didn't.
    //
    //  For each grouping query, verify the ORDER BY column is
    //  actually sorted in the claimed direction.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv14_order_by_group_by() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        // Test cases: (sql, column_index_to_check, descending, tag)
        let cases: Vec<(&str, usize, bool, &str)> = vec![
            // GROUP BY string column, ORDER BY same column
            (
                "SELECT d.name, COUNT(e.id) FROM departments d LEFT JOIN employees e ON d.id = e.dept_id GROUP BY d.name ORDER BY d.name",
                0, false, "group-left-join-name-asc"
            ),
            (
                "SELECT dept_id, COUNT(*) FROM employees GROUP BY dept_id ORDER BY dept_id",
                0, false, "group-dept-asc"
            ),
            (
                "SELECT dept_id, SUM(salary) as total FROM employees GROUP BY dept_id ORDER BY dept_id DESC",
                0, true, "group-dept-desc"
            ),
            (
                "SELECT status, COUNT(*) FROM orders GROUP BY status ORDER BY status",
                0, false, "group-status-asc"
            ),
            // ORDER BY aggregate
            (
                "SELECT dept_id, COUNT(*) as cnt FROM employees GROUP BY dept_id ORDER BY cnt",
                1, false, "group-order-count-asc"
            ),
            (
                "SELECT dept_id, SUM(salary) as total FROM employees GROUP BY dept_id ORDER BY total DESC",
                1, true, "group-order-sum-desc"
            ),
            // Simple ORDER BY (non-grouped) for comparison
            (
                "SELECT name FROM employees ORDER BY name",
                0, false, "simple-name-asc"
            ),
            (
                "SELECT salary FROM employees ORDER BY salary DESC",
                0, true, "simple-salary-desc"
            ),
        ];

        for (sql, col_idx, desc, tag) in &cases {
            let result = run(&ex, sql);
            if result.rows.len() < 2 {
                r.check(&format!("order({})", tag), true, "trivially sorted");
                continue;
            }

            let mut sorted = true;
            for i in 0..result.rows.len() - 1 {
                let a = &result.rows[i][*col_idx];
                let b = &result.rows[i + 1][*col_idx];

                let cmp = if let (Some(sa), Some(sb)) = (a.as_str(), b.as_str()) {
                    sa.cmp(sb)
                } else if let (Some(fa), Some(fb)) = (val(a), val(b)) {
                    fa.partial_cmp(&fb).unwrap_or(std::cmp::Ordering::Equal)
                } else {
                    std::cmp::Ordering::Equal
                };

                let ok = if *desc {
                    cmp != std::cmp::Ordering::Less
                } else {
                    cmp != std::cmp::Ordering::Greater
                };

                if !ok {
                    sorted = false;
                    r.check(
                        &format!("order({} row{}-{})", tag, i, i + 1),
                        false,
                        &format!("{:?} vs {:?} (desc={})", a, b, desc),
                    );
                }
            }

            if sorted {
                r.check(&format!("order({})", tag), true, "correctly sorted");
            }
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-15: Aggregate Linearity (no NULLs)
    //
    //  SUM(a + b) = SUM(a) + SUM(b)     [linearity over addition]
    //  SUM(k * a) = k * SUM(a)           [linearity over scalar mult]
    //  AVG(a) = SUM(a) / COUNT(a)        [definition of average]
    //  MAX(a) >= MIN(a)                  [for non-empty]
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv15_aggregate_linearity() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        // SUM(salary + id) vs SUM(salary) + SUM(id)
        let combined = run(&ex, "SELECT SUM(salary + id) FROM employees");
        let separate = run(&ex, "SELECT SUM(salary), SUM(id) FROM employees");
        let s_combined = val(&combined.rows[0][0]).unwrap_or(0.0);
        let s_salary = val(&separate.rows[0][0]).unwrap_or(0.0);
        let s_id = val(&separate.rows[0][1]).unwrap_or(0.0);
        r.check(
            "SUM(a+b)=SUM(a)+SUM(b)",
            (s_combined - (s_salary + s_id)).abs() < 0.5,
            &format!("SUM(salary+id)={} vs SUM(salary)+SUM(id)={}+{}={}", s_combined, s_salary, s_id, s_salary + s_id),
        );

        // SUM(salary * 2) vs 2 * SUM(salary)
        let scaled = run(&ex, "SELECT SUM(salary * 2) FROM employees");
        let s_scaled = val(&scaled.rows[0][0]).unwrap_or(0.0);
        r.check(
            "SUM(k*a)=k*SUM(a)",
            (s_scaled - 2.0 * s_salary).abs() < 0.5,
            &format!("SUM(salary*2)={} vs 2*SUM(salary)={}", s_scaled, 2.0 * s_salary),
        );

        // AVG = SUM / COUNT
        let avg_r = run(&ex, "SELECT AVG(salary), SUM(salary), COUNT(salary) FROM employees");
        let avg_v = val(&avg_r.rows[0][0]).unwrap_or(0.0);
        let sum_v = val(&avg_r.rows[0][1]).unwrap_or(0.0);
        let cnt_v = val(&avg_r.rows[0][2]).unwrap_or(1.0);
        r.check(
            "AVG=SUM/COUNT",
            (avg_v - sum_v / cnt_v).abs() < 0.5,
            &format!("AVG={} vs SUM/COUNT={}/{}", avg_v, sum_v, cnt_v),
        );

        // Per-group linearity: SUM(salary + id) = SUM(salary) + SUM(id) within each group
        let grp_combined = run(&ex, "SELECT dept_id, SUM(salary + id) FROM employees GROUP BY dept_id ORDER BY dept_id");
        let grp_separate = run(&ex, "SELECT dept_id, SUM(salary), SUM(id) FROM employees GROUP BY dept_id ORDER BY dept_id");
        for i in 0..grp_combined.rows.len() {
            let gc = val(&grp_combined.rows[i][1]).unwrap_or(0.0);
            let gs = val(&grp_separate.rows[i][1]).unwrap_or(0.0);
            let gi = val(&grp_separate.rows[i][2]).unwrap_or(0.0);
            r.check(
                &format!("group-linearity(dept{})", i),
                (gc - (gs + gi)).abs() < 0.5,
                &format!("SUM(s+i)={} vs SUM(s)+SUM(i)={}+{}", gc, gs, gi),
            );
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-16: Nested Query Equivalence
    //
    //  SELECT * FROM (SELECT * FROM t WHERE p) WHERE q
    //    = SELECT * FROM t WHERE p AND q
    //
    //  Tests derived table + WHERE composition.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv16_nested_query_equivalence() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let cases: Vec<(&str, &str, &str, &str)> = vec![
            ("employees", "salary > 90000", "dept_id = 1", "salary>90K AND dept=1"),
            ("employees", "id > 2", "salary < 120000", "id>2 AND salary<120K"),
            ("employees", "dept_id != 3", "name != 'Bob'", "dept!=3 AND name!=Bob"),
            ("orders", "amount > 2000", "status = 'shipped'", "amount>2K AND shipped"),
            ("orders", "employee_id = 1", "amount > 4000", "emp1 AND amount>4K"),
        ];

        for (table, p, q, tag) in &cases {
            let nested = run_rows(&ex, &format!(
                "SELECT * FROM (SELECT * FROM {} WHERE {}) sub WHERE {}", table, p, q
            ));
            let flat = run_rows(&ex, &format!(
                "SELECT * FROM {} WHERE {} AND {}", table, p, q
            ));
            r.check(
                &format!("nested≡flat({})", tag),
                nested == flat,
                &format!("nested={} vs flat={}", nested, flat),
            );
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-17: Arithmetic Identities
    //
    //  x + 0 = x,  x * 1 = x,  x - x = 0,  x * 0 = 0
    //  For every numeric column in every row.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv17_arithmetic_identity() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let cols: Vec<(&str, &str)> = vec![
            ("employees", "salary"),
            ("employees", "id"),
            ("orders", "amount"),
            ("orders", "id"),
            ("departments", "budget"),
        ];

        for (table, col) in &cols {
            let tag = format!("{}.{}", table, col);

            // x + 0 = x
            let orig = run(&ex, &format!("SELECT {}, {} + 0 FROM {} ORDER BY id", col, col, table));
            for (i, row) in orig.rows.iter().enumerate() {
                let x = val(&row[0]).unwrap_or(f64::NAN);
                let xp0 = val(&row[1]).unwrap_or(f64::NAN);
                r.check(
                    &format!("x+0=x({} row{})", tag, i),
                    (x - xp0).abs() < 0.01,
                    &format!("x={} vs x+0={}", x, xp0),
                );
            }

            // x * 1 = x
            let mult = run(&ex, &format!("SELECT {}, {} * 1 FROM {} ORDER BY id", col, col, table));
            for (i, row) in mult.rows.iter().enumerate() {
                let x = val(&row[0]).unwrap_or(f64::NAN);
                let xm1 = val(&row[1]).unwrap_or(f64::NAN);
                r.check(
                    &format!("x*1=x({} row{})", tag, i),
                    (x - xm1).abs() < 0.01,
                    &format!("x={} vs x*1={}", x, xm1),
                );
            }

            // x - x = 0
            let sub = run(&ex, &format!("SELECT {} - {} FROM {} ORDER BY id", col, col, table));
            for (i, row) in sub.rows.iter().enumerate() {
                let v = val(&row[0]).unwrap_or(f64::NAN);
                r.check(
                    &format!("x-x=0({} row{})", tag, i),
                    v.abs() < 0.01,
                    &format!("x-x={}", v),
                );
            }

            // x * 0 = 0
            let zero = run(&ex, &format!("SELECT {} * 0 FROM {} ORDER BY id", col, table));
            for (i, row) in zero.rows.iter().enumerate() {
                let v = val(&row[0]).unwrap_or(f64::NAN);
                r.check(
                    &format!("x*0=0({} row{})", tag, i),
                    v.abs() < 0.01,
                    &format!("x*0={}", v),
                );
            }
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-18: String Function Invariants
    //
    //  UPPER(LOWER(x)) = UPPER(x)
    //  LOWER(UPPER(x)) = LOWER(x)
    //  LENGTH(x) >= 0
    //  LENGTH(UPPER(x)) = LENGTH(x)
    //  LOWER(x) = LOWER(x) [idempotent]
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv18_string_invariants() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        // Test on employee names
        let names = run(&ex, "SELECT name, UPPER(name), LOWER(name), LENGTH(name), UPPER(LOWER(name)), LOWER(UPPER(name)) FROM employees ORDER BY name");
        for (i, row) in names.rows.iter().enumerate() {
            let name = row[0].as_str().unwrap_or("");
            let upper = row[1].as_str().unwrap_or("");
            let lower = row[2].as_str().unwrap_or("");
            let length = row[3].as_i64().unwrap_or(-1);
            let upper_lower = row[4].as_str().unwrap_or("");
            let lower_upper = row[5].as_str().unwrap_or("");

            r.check(
                &format!("LENGTH>=0({})", name),
                length >= 0,
                &format!("LENGTH({})={}", name, length),
            );

            r.check(
                &format!("UPPER(LOWER)=UPPER({})", name),
                upper_lower == upper,
                &format!("UPPER(LOWER({}))={} vs UPPER({})={}", name, upper_lower, name, upper),
            );

            r.check(
                &format!("LOWER(UPPER)=LOWER({})", name),
                lower_upper == lower,
                &format!("LOWER(UPPER({}))={} vs LOWER({})={}", name, lower_upper, name, lower),
            );

            r.check(
                &format!("LENGTH(UPPER)=LENGTH({})", name),
                {
                    let ul = upper.len() as i64;
                    ul == length
                },
                &format!("LENGTH(UPPER)={} vs LENGTH={}", upper.len(), length),
            );
        }

        // Department names too
        let dept_names = run(&ex, "SELECT name, UPPER(name), LOWER(name), LENGTH(name) FROM departments ORDER BY name");
        for row in &dept_names.rows {
            let name = row[0].as_str().unwrap_or("");
            let length = row[3].as_i64().unwrap_or(-1);
            r.check(
                &format!("dept-LENGTH({})", name),
                length == name.len() as i64,
                &format!("LENGTH({})={} vs actual {}", name, length, name.len()),
            );
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-19: UPDATE Idempotence
    //
    //  UPDATE t SET x = x changes nothing.
    //  Two identical UPDATEs produce same result.
    //  UPDATE WHERE false changes nothing.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv19_update_idempotence() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv19 (id INT, val INT, name TEXT)");
        for i in 1..=5 {
            run(&ex, &format!("INSERT INTO inv19 VALUES ({}, {}, 'name{}')", i, i * 100, i));
        }

        // Snapshot before
        let before = run(&ex, "SELECT id, val, name FROM inv19 ORDER BY id");

        // UPDATE SET x = x (noop)
        run(&ex, "UPDATE inv19 SET val = val");
        let after_noop = run(&ex, "SELECT id, val, name FROM inv19 ORDER BY id");
        for i in 0..before.rows.len() {
            let bv = val(&before.rows[i][1]).unwrap_or(-1.0);
            let av = val(&after_noop.rows[i][1]).unwrap_or(-2.0);
            r.check(
                &format!("SET-x=x-noop(row{})", i),
                (bv - av).abs() < 0.01,
                &format!("before={} after={}", bv, av),
            );
        }

        // UPDATE WHERE false
        run(&ex, "UPDATE inv19 SET val = 999 WHERE 1 = 0");
        let after_false = run(&ex, "SELECT id, val FROM inv19 ORDER BY id");
        for i in 0..before.rows.len() {
            let bv = val(&before.rows[i][1]).unwrap_or(-1.0);
            let av = val(&after_false.rows[i][1]).unwrap_or(-2.0);
            r.check(
                &format!("UPDATE-false(row{})", i),
                (bv - av).abs() < 0.01,
                &format!("before={} after={}", bv, av),
            );
        }

        // Two identical UPDATEs = same result
        run(&ex, "UPDATE inv19 SET val = val + 10 WHERE id <= 3");
        let after_first = run(&ex, "SELECT SUM(val) FROM inv19");
        let s1 = val(&after_first.rows[0][0]).unwrap();

        // Reset and do it again
        // (Can't truly reset, so just verify second update is additive)
        run(&ex, "UPDATE inv19 SET val = val + 10 WHERE id <= 3");
        let after_second = run(&ex, "SELECT SUM(val) FROM inv19");
        let s2 = val(&after_second.rows[0][0]).unwrap();
        // Second update adds another 30 (10 * 3 rows)
        r.check(
            "double-UPDATE-additive",
            (s2 - s1 - 30.0).abs() < 0.5,
            &format!("s2-s1={} expected 30", s2 - s1),
        );

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-20: COALESCE Properties
    //
    //  COALESCE(x, y) = x when x IS NOT NULL
    //  COALESCE(NULL, y) = y
    //  COALESCE(x, x) = x
    //  COALESCE(NULL, NULL) = NULL
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv20_coalesce_properties() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv20 (id INT, a INT, b INT)");
        run(&ex, "INSERT INTO inv20 VALUES (1, 10, 20)");
        run(&ex, "INSERT INTO inv20 VALUES (2, NULL, 30)");
        run(&ex, "INSERT INTO inv20 VALUES (3, 40, NULL)");
        run(&ex, "INSERT INTO inv20 VALUES (4, NULL, NULL)");

        let result = run(&ex, "SELECT id, a, b, COALESCE(a, b), COALESCE(a, a), COALESCE(b, b) FROM inv20 ORDER BY id");

        // Row 1: a=10, b=20 → COALESCE(a,b)=10 (a not null)
        let c_ab_1 = val(&result.rows[0][3]).unwrap_or(-1.0);
        r.check("COALESCE(10,20)=10", (c_ab_1 - 10.0).abs() < 0.5, &format!("got {}", c_ab_1));

        // Row 2: a=NULL, b=30 → COALESCE(a,b)=30
        let c_ab_2 = val(&result.rows[1][3]).unwrap_or(-1.0);
        r.check("COALESCE(NULL,30)=30", (c_ab_2 - 30.0).abs() < 0.5, &format!("got {}", c_ab_2));

        // Row 3: a=40, b=NULL → COALESCE(a,b)=40
        let c_ab_3 = val(&result.rows[2][3]).unwrap_or(-1.0);
        r.check("COALESCE(40,NULL)=40", (c_ab_3 - 40.0).abs() < 0.5, &format!("got {}", c_ab_3));

        // Row 4: a=NULL, b=NULL → COALESCE(a,b)=NULL
        r.check("COALESCE(NULL,NULL)=NULL", result.rows[3][3].is_null(), "expected NULL");

        // COALESCE(x, x) = x for non-null
        let c_aa_1 = val(&result.rows[0][4]).unwrap_or(-1.0);
        r.check("COALESCE(10,10)=10", (c_aa_1 - 10.0).abs() < 0.5, &format!("got {}", c_aa_1));

        // COALESCE(NULL, NULL) = NULL
        r.check("COALESCE(a,a) where a=NULL", result.rows[1][4].is_null(), "expected NULL");

        // On standard schema: COALESCE(salary, 0) = salary (no nulls in salary)
        setup_standard_schema(&ex);
        let emp_coal = run(&ex, "SELECT name, salary, COALESCE(salary, 0) FROM employees ORDER BY name");
        for (i, row) in emp_coal.rows.iter().enumerate() {
            let s = val(&row[1]).unwrap_or(-1.0);
            let c = val(&row[2]).unwrap_or(-2.0);
            r.check(
                &format!("COALESCE(salary,0)=salary(row{})", i),
                (s - c).abs() < 0.01,
                &format!("salary={} vs COALESCE={}", s, c),
            );
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-21: JOIN Commutativity (INNER JOIN)
    //
    //  |A JOIN B ON p| = |B JOIN A ON p|
    //  Results have same cardinality (may differ in column order).
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv21_join_commutativity() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        // employees JOIN departments vs departments JOIN employees
        let ab = run_rows(&ex,
            "SELECT * FROM employees e JOIN departments d ON e.dept_id = d.id"
        );
        let ba = run_rows(&ex,
            "SELECT * FROM departments d JOIN employees e ON e.dept_id = d.id"
        );
        r.check("emp⋈dept = dept⋈emp", ab == ba, &format!("|A⋈B|={} vs |B⋈A|={}", ab, ba));

        // orders JOIN employees vs employees JOIN orders
        let oe = run_rows(&ex,
            "SELECT * FROM orders o JOIN employees e ON o.employee_id = e.id"
        );
        let eo = run_rows(&ex,
            "SELECT * FROM employees e JOIN orders o ON o.employee_id = e.id"
        );
        r.check("ord⋈emp = emp⋈ord", oe == eo, &format!("|O⋈E|={} vs |E⋈O|={}", oe, eo));

        // employees JOIN projects vs projects JOIN employees
        let ep = run_rows(&ex,
            "SELECT * FROM employees e JOIN projects p ON e.dept_id = p.dept_id"
        );
        let pe = run_rows(&ex,
            "SELECT * FROM projects p JOIN employees e ON e.dept_id = p.dept_id"
        );
        r.check("emp⋈proj = proj⋈emp", ep == pe, &format!("|E⋈P|={} vs |P⋈E|={}", ep, pe));

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-22: HAVING vs WHERE Pre-filter
    //
    //  SELECT agg FROM t GROUP BY g HAVING agg > k
    //    has fewer or equal rows to
    //  SELECT agg FROM t GROUP BY g
    //
    //  HAVING can only reduce, never increase, group count.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv22_having_reduces() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let cases: Vec<(&str, &str)> = vec![
            (
                "SELECT dept_id, COUNT(*) FROM employees GROUP BY dept_id",
                "SELECT dept_id, COUNT(*) FROM employees GROUP BY dept_id HAVING COUNT(*) > 1",
            ),
            (
                "SELECT dept_id, SUM(salary) as s FROM employees GROUP BY dept_id",
                "SELECT dept_id, SUM(salary) as s FROM employees GROUP BY dept_id HAVING SUM(salary) > 200000",
            ),
            (
                "SELECT dept_id, AVG(salary) as a FROM employees GROUP BY dept_id",
                "SELECT dept_id, AVG(salary) as a FROM employees GROUP BY dept_id HAVING AVG(salary) > 100000",
            ),
            (
                "SELECT status, COUNT(*) FROM orders GROUP BY status",
                "SELECT status, COUNT(*) FROM orders GROUP BY status HAVING COUNT(*) >= 2",
            ),
            (
                "SELECT employee_id, SUM(amount) as t FROM orders GROUP BY employee_id",
                "SELECT employee_id, SUM(amount) as t FROM orders GROUP BY employee_id HAVING SUM(amount) > 5000",
            ),
        ];

        for (without, with) in &cases {
            let no_having = run_rows(&ex, without);
            let yes_having = run_rows(&ex, with);
            r.check(
                &format!("HAVING-reduces({}...)", &with[..with.len().min(60)]),
                yes_having <= no_having,
                &format!("with HAVING={} > without={}", yes_having, no_having),
            );
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-23: Multi-table Aggregate Cross-check
    //
    //  For JOINed tables: count via JOIN = sum of per-table counts
    //  when relationship is 1:N.
    //  employees-per-dept via GROUP BY = employees-per-dept via correlated subquery
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv23_cross_table_aggregates() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        // Total employees via different paths
        let direct = run(&ex, "SELECT COUNT(*) FROM employees");
        let via_sum_groups = run(&ex, "SELECT SUM(cnt) FROM (SELECT dept_id, COUNT(*) as cnt FROM employees GROUP BY dept_id) sub");
        let d_count = direct.rows[0][0].as_i64().unwrap();
        let g_count = val(&via_sum_groups.rows[0][0]).unwrap_or(0.0) as i64;
        r.check(
            "COUNT=SUM(group-counts)",
            d_count == g_count,
            &format!("direct={} vs via-groups={}", d_count, g_count),
        );

        // Total salary via JOIN must equal direct total
        let direct_sum = run(&ex, "SELECT SUM(salary) FROM employees");
        let join_sum = run(&ex, "SELECT SUM(e.salary) FROM employees e JOIN departments d ON e.dept_id = d.id");
        let ds = val(&direct_sum.rows[0][0]).unwrap_or(0.0);
        let js = val(&join_sum.rows[0][0]).unwrap_or(0.0);
        r.check(
            "SUM(salary)-direct=via-join",
            (ds - js).abs() < 0.5,
            &format!("direct={} vs join={}", ds, js),
        );

        // Orders per employee: GROUP BY count vs correlated subquery count
        let grp = run(&ex, "SELECT employee_id, COUNT(*) as cnt FROM orders GROUP BY employee_id ORDER BY employee_id");
        for row in &grp.rows {
            let emp_id = val(&row[0]).unwrap_or(0.0) as i64;
            let grp_cnt = row[1].as_i64().unwrap();
            let sub_cnt_r = run(&ex, &format!(
                "SELECT COUNT(*) FROM orders WHERE employee_id = {}", emp_id
            ));
            let sub_cnt = sub_cnt_r.rows[0][0].as_i64().unwrap();
            r.check(
                &format!("group-vs-subquery(emp{})", emp_id),
                grp_cnt == sub_cnt,
                &format!("group={} vs subquery={}", grp_cnt, sub_cnt),
            );
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-24: DELETE + COUNT Consistency
    //
    //  After DELETE WHERE p:
    //    new COUNT = old COUNT - (old COUNT WHERE p)
    //    Remaining rows all satisfy NOT p
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv24_delete_count_consistency() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv24 (id INT, cat TEXT, val INT)");
        for i in 1..=20 {
            let cat = if i % 3 == 0 { "a" } else if i % 3 == 1 { "b" } else { "c" };
            run(&ex, &format!("INSERT INTO inv24 VALUES ({}, '{}', {})", i, cat, i * 10));
        }

        let predicates: Vec<&str> = vec![
            "cat = 'a'",
            "val > 150",
            "id <= 5",
        ];

        for pred in &predicates {
            // Fresh table each time
            run(&ex, "DELETE FROM inv24");
            for i in 1..=20 {
                let cat = if i % 3 == 0 { "a" } else if i % 3 == 1 { "b" } else { "c" };
                run(&ex, &format!("INSERT INTO inv24 VALUES ({}, '{}', {})", i, cat, i * 10));
            }

            let before_total = run_rows(&ex, "SELECT * FROM inv24");
            let matching = run_rows(&ex, &format!("SELECT * FROM inv24 WHERE {}", pred));

            run(&ex, &format!("DELETE FROM inv24 WHERE {}", pred));

            let after_total = run_rows(&ex, "SELECT * FROM inv24");
            let remaining_match = run_rows(&ex, &format!("SELECT * FROM inv24 WHERE {}", pred));

            r.check(
                &format!("DELETE-count({})", pred),
                after_total == before_total - matching,
                &format!("after={} != before({}) - match({})", after_total, before_total, matching),
            );

            r.check(
                &format!("DELETE-none-remain({})", pred),
                remaining_match == 0,
                &format!("{} rows still match after DELETE", remaining_match),
            );
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-25: Window Function Partition Totals
    //
    //  SUM(x) OVER (PARTITION BY g) for each row in partition
    //  must equal the global SUM(x) WHERE g = that_row's_g.
    //  COUNT(*) OVER (PARTITION BY g) must equal COUNT WHERE g = val.
    //  ROW_NUMBER per partition must be 1..partition_size.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv25_window_partition_totals() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        // SUM OVER partition vs GROUP BY SUM
        let win = run(&ex, "SELECT dept_id, salary, SUM(salary) OVER (PARTITION BY dept_id) as psum FROM employees ORDER BY dept_id, salary");
        let grp = run(&ex, "SELECT dept_id, SUM(salary) as gsum FROM employees GROUP BY dept_id ORDER BY dept_id");

        // Build dept→sum map from GROUP BY
        let mut dept_sum: std::collections::HashMap<i64, f64> = std::collections::HashMap::new();
        for row in &grp.rows {
            let dept = val(&row[0]).unwrap_or(0.0) as i64;
            let gsum = val(&row[1]).unwrap_or(0.0);
            dept_sum.insert(dept, gsum);
        }

        // Verify each window row's partition sum matches GROUP BY
        for (i, row) in win.rows.iter().enumerate() {
            let dept = val(&row[0]).unwrap_or(0.0) as i64;
            let psum = val(&row[2]).unwrap_or(0.0);
            let expected = dept_sum.get(&dept).copied().unwrap_or(-1.0);
            r.check(
                &format!("win-SUM=group-SUM(row{},dept{})", i, dept),
                (psum - expected).abs() < 0.5,
                &format!("window={} vs group={}", psum, expected),
            );
        }

        // COUNT OVER partition vs GROUP BY COUNT
        let win_cnt = run(&ex, "SELECT dept_id, COUNT(*) OVER (PARTITION BY dept_id) as pcnt FROM employees ORDER BY dept_id");
        let grp_cnt = run(&ex, "SELECT dept_id, COUNT(*) as gcnt FROM employees GROUP BY dept_id ORDER BY dept_id");
        let mut dept_cnt: std::collections::HashMap<i64, i64> = std::collections::HashMap::new();
        for row in &grp_cnt.rows {
            let dept = val(&row[0]).unwrap_or(0.0) as i64;
            let gcnt = row[1].as_i64().unwrap();
            dept_cnt.insert(dept, gcnt);
        }
        for (i, row) in win_cnt.rows.iter().enumerate() {
            let dept = val(&row[0]).unwrap_or(0.0) as i64;
            let pcnt = row[1].as_i64().unwrap();
            let expected = dept_cnt.get(&dept).copied().unwrap_or(-1);
            r.check(
                &format!("win-COUNT=group-COUNT(row{},dept{})", i, dept),
                pcnt == expected,
                &format!("window={} vs group={}", pcnt, expected),
            );
        }

        // ROW_NUMBER per partition: verify 1..N per partition
        let rn = run(&ex, "SELECT dept_id, ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary) as rn FROM employees ORDER BY dept_id, rn");
        let mut partition_rns: std::collections::HashMap<i64, Vec<i64>> = std::collections::HashMap::new();
        for row in &rn.rows {
            let dept = val(&row[0]).unwrap_or(0.0) as i64;
            let rn_val = row[1].as_i64().unwrap();
            partition_rns.entry(dept).or_default().push(rn_val);
        }
        for (dept, mut rns) in partition_rns {
            rns.sort();
            let expected: Vec<i64> = (1..=rns.len() as i64).collect();
            r.check(
                &format!("ROW_NUMBER-1..N(dept{})", dept),
                rns == expected,
                &format!("ROW_NUMBERs={:?} expected {:?}", rns, expected),
            );
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-26: CASE Expression Exhaustiveness
    //
    //  CASE WHEN p THEN a ELSE b END:
    //    rows where p is true get value a
    //    rows where p is false get value b
    //    total rows = rows(a) + rows(b)
    //
    //  CASE + aggregate: COUNT(CASE WHEN p THEN 1 END) = COUNT(*) WHERE p
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv26_case_exhaustiveness() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let preds: Vec<(&str, &str, &str)> = vec![
            ("salary > 100000", "high", "low"),
            ("dept_id = 1", "eng", "other"),
            ("id <= 3", "junior", "senior"),
        ];

        for (pred, then_val, else_val) in &preds {
            // CASE should cover all rows
            let case_r = run(&ex, &format!(
                "SELECT CASE WHEN {} THEN '{}' ELSE '{}' END as bucket FROM employees",
                pred, then_val, else_val
            ));
            assert_eq!(case_r.rows.len(), 6, "CASE covers all rows");

            let then_count = case_r.rows.iter().filter(|row| row[0].as_str() == Some(then_val)).count();
            let else_count = case_r.rows.iter().filter(|row| row[0].as_str() == Some(else_val)).count();
            let where_count = run_rows(&ex, &format!("SELECT * FROM employees WHERE {}", pred));

            r.check(
                &format!("CASE-then-count({})", pred),
                then_count == where_count,
                &format!("CASE-then={} vs WHERE={}", then_count, where_count),
            );

            r.check(
                &format!("CASE-total({})", pred),
                then_count + else_count == 6,
                &format!("then+else={}+{}={}", then_count, else_count, then_count + else_count),
            );

            // COUNT(CASE) should match COUNT(*) WHERE
            let case_agg = run(&ex, &format!(
                "SELECT COUNT(CASE WHEN {} THEN 1 END), COUNT(CASE WHEN NOT ({}) THEN 1 END) FROM employees",
                pred, pred
            ));
            let ca = case_agg.rows[0][0].as_i64().unwrap();
            let cb = case_agg.rows[0][1].as_i64().unwrap();
            r.check(
                &format!("COUNT-CASE-partition({})", pred),
                ca + cb == 6,
                &format!("{}+{}={}", ca, cb, ca + cb),
            );
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-27: Multi-column ORDER BY Stability
    //
    //  ORDER BY a, b:
    //    primary sort by a is correct
    //    within ties on a, sort by b is correct
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv27_multi_column_order() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let result = run(&ex, "SELECT dept_id, salary, name FROM employees ORDER BY dept_id ASC, salary DESC");

        // Primary sort: dept_id should be non-decreasing
        for i in 0..result.rows.len() - 1 {
            let d1 = val(&result.rows[i][0]).unwrap_or(0.0);
            let d2 = val(&result.rows[i + 1][0]).unwrap_or(0.0);
            r.check(
                &format!("primary-sort(row{}-{})", i, i + 1),
                d1 <= d2,
                &format!("dept {} then {}", d1, d2),
            );

            // Secondary sort: within same dept, salary should be non-increasing
            if (d1 - d2).abs() < 0.5 {
                let s1 = val(&result.rows[i][1]).unwrap_or(0.0);
                let s2 = val(&result.rows[i + 1][1]).unwrap_or(0.0);
                r.check(
                    &format!("secondary-sort(row{}-{},dept{})", i, i + 1, d1 as i64),
                    s1 >= s2,
                    &format!("salary {} then {}", s1, s2),
                );
            }
        }

        // Test with 3 columns
        let r3 = run(&ex, "SELECT dept_id, salary, name FROM employees ORDER BY dept_id ASC, salary DESC, name ASC");
        // Just verify it runs and has all rows
        r.check("triple-order-card", r3.rows.len() == 6, &format!("got {}", r3.rows.len()));

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-28: INSERT SELECT Cardinality
    //
    //  INSERT INTO dst SELECT ... FROM src WHERE p
    //  adds exactly COUNT(*) WHERE p rows to dst.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv28_insert_select_cardinality() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv28_dst (id INT, name TEXT, salary FLOAT)");

        let preds: Vec<&str> = vec![
            "salary > 100000",
            "dept_id = 2",
            "id <= 3",
        ];

        for pred in &preds {
            // Clear destination
            run(&ex, "DELETE FROM inv28_dst");

            let source_count = run_rows(&ex, &format!("SELECT * FROM employees WHERE {}", pred));
            run(&ex, &format!("INSERT INTO inv28_dst SELECT id, name, salary FROM employees WHERE {}", pred));
            let dst_count = run_rows(&ex, "SELECT * FROM inv28_dst");

            r.check(
                &format!("INSERT-SELECT({})", pred),
                dst_count == source_count,
                &format!("dst={} vs source-count={}", dst_count, source_count),
            );
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-29: CTE Materialization Consistency
    //
    //  WITH cte AS (Q) SELECT * FROM cte = Q
    //  Using a CTE twice should give same results both times.
    //  CTE count = underlying query count.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv29_cte_consistency() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        // CTE = underlying query
        let direct = run_rows(&ex, "SELECT * FROM employees WHERE salary > 100000");
        let via_cte = run_rows(&ex, "WITH high AS (SELECT * FROM employees WHERE salary > 100000) SELECT * FROM high");
        r.check("CTE=direct(high-earners)", direct == via_cte, &format!("direct={} cte={}", direct, via_cte));

        // CTE used twice in same query
        let dual_use = run(&ex, "WITH emps AS (SELECT * FROM employees) SELECT (SELECT COUNT(*) FROM emps) as c1, (SELECT COUNT(*) FROM emps) as c2");
        let c1 = dual_use.rows[0][0].as_i64().unwrap();
        let c2 = dual_use.rows[0][1].as_i64().unwrap();
        r.check("CTE-dual-use-same", c1 == c2, &format!("c1={} c2={}", c1, c2));
        r.check("CTE-dual-use-correct", c1 == 6, &format!("expected 6, got {}", c1));

        // CTE with aggregation
        let agg_direct = run(&ex, "SELECT dept_id, COUNT(*) as cnt FROM employees GROUP BY dept_id ORDER BY dept_id");
        let agg_cte = run(&ex, "WITH dept_counts AS (SELECT dept_id, COUNT(*) as cnt FROM employees GROUP BY dept_id) SELECT * FROM dept_counts ORDER BY dept_id");
        r.check("CTE-agg-rows", agg_direct.rows.len() == agg_cte.rows.len(), "row count mismatch");
        for i in 0..agg_direct.rows.len().min(agg_cte.rows.len()) {
            let dc = val(&agg_direct.rows[i][1]).unwrap_or(-1.0);
            let cc = val(&agg_cte.rows[i][1]).unwrap_or(-2.0);
            r.check(
                &format!("CTE-agg-val(row{})", i),
                (dc - cc).abs() < 0.5,
                &format!("direct={} cte={}", dc, cc),
            );
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-30: BETWEEN ≡ >= AND <=
    //
    //  WHERE x BETWEEN a AND b ≡ WHERE x >= a AND x <= b
    //  NOT BETWEEN ≡ WHERE x < a OR x > b
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv30_between_equivalence() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let specs: Vec<(&str, &str, i64, i64)> = vec![
            ("employees", "salary", 85000, 120000),
            ("employees", "salary", 90000, 110000),
            ("employees", "id", 2, 5),
            ("orders", "amount", 2000, 5000),
            ("departments", "budget", 200000, 400000),
        ];

        for (table, col, lo, hi) in &specs {
            let tag = format!("{}.{} [{},{}]", table, col, lo, hi);

            let between = run_rows(&ex, &format!(
                "SELECT * FROM {} WHERE {} BETWEEN {} AND {}", table, col, lo, hi
            ));
            let expanded = run_rows(&ex, &format!(
                "SELECT * FROM {} WHERE {} >= {} AND {} <= {}", table, col, lo, col, hi
            ));

            r.check(
                &format!("BETWEEN≡AND({})", tag),
                between == expanded,
                &format!("BETWEEN={} vs AND={}", between, expanded),
            );

            // NOT BETWEEN ≡ < lo OR > hi
            let not_between = run_rows(&ex, &format!(
                "SELECT * FROM {} WHERE {} NOT BETWEEN {} AND {}", table, col, lo, hi
            ));
            let not_expanded = run_rows(&ex, &format!(
                "SELECT * FROM {} WHERE {} < {} OR {} > {}", table, col, lo, col, hi
            ));

            r.check(
                &format!("NOT-BETWEEN≡OR({})", tag),
                not_between == not_expanded,
                &format!("NOT BETWEEN={} vs OR={}", not_between, not_expanded),
            );

            // BETWEEN + NOT BETWEEN = total
            let total = run_rows(&ex, &format!("SELECT * FROM {}", table));
            r.check(
                &format!("BETWEEN-partition({})", tag),
                between + not_between == total,
                &format!("{}+{}={} vs total={}", between, not_between, between + not_between, total),
            );
        }

        r.finish();
    }

    // =================================================================
    //  ADVERSARIAL INVARIANTS (INV-31..INV-40)
    //
    //  These use synthetic data designed to expose corner cases:
    //  - All-NULL columns, single-row tables, duplicate values,
    //    negative numbers, zero, large values, empty strings,
    //    many-to-many JOINs, self-referencing FKs
    // =================================================================

    // -----------------------------------------------------------------
    //  INV-31: All-NULL Column Aggregates
    //
    //  SUM(all_null) = NULL, COUNT(all_null) = 0,
    //  MIN(all_null) = NULL, MAX(all_null) = NULL
    //  But COUNT(*) still returns row count.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv31_all_null_aggregates() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv31 (id INT, val INT)");
        run(&ex, "INSERT INTO inv31 VALUES (1, NULL)");
        run(&ex, "INSERT INTO inv31 VALUES (2, NULL)");
        run(&ex, "INSERT INTO inv31 VALUES (3, NULL)");

        let agg = run(&ex, "SELECT COUNT(*), COUNT(val), SUM(val), MIN(val), MAX(val), AVG(val) FROM inv31");
        r.check("all-null-COUNT(*)", agg.rows[0][0].as_i64().unwrap() == 3, "COUNT(*) should be 3");
        r.check("all-null-COUNT(val)", agg.rows[0][1].as_i64().unwrap() == 0, "COUNT(val) should be 0");
        r.check("all-null-SUM", agg.rows[0][2].is_null(), "SUM should be NULL");
        r.check("all-null-MIN", agg.rows[0][3].is_null(), "MIN should be NULL");
        r.check("all-null-MAX", agg.rows[0][4].is_null(), "MAX should be NULL");
        r.check("all-null-AVG", agg.rows[0][5].is_null(), "AVG should be NULL");

        // GROUP BY with all-null aggregate column
        run(&ex, "CREATE TABLE inv31g (grp TEXT, val INT)");
        run(&ex, "INSERT INTO inv31g VALUES ('a', NULL)");
        run(&ex, "INSERT INTO inv31g VALUES ('a', NULL)");
        run(&ex, "INSERT INTO inv31g VALUES ('b', NULL)");
        let grp = run(&ex, "SELECT grp, COUNT(*), COUNT(val), SUM(val) FROM inv31g GROUP BY grp ORDER BY grp");
        assert_eq!(grp.rows.len(), 2, "2 groups");
        r.check("group-a-count(*)", grp.rows[0][1].as_i64().unwrap() == 2, "group a COUNT(*)=2");
        r.check("group-a-count(val)", grp.rows[0][2].as_i64().unwrap() == 0, "group a COUNT(val)=0");
        r.check("group-a-sum", grp.rows[0][3].is_null(), "group a SUM=NULL");

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-32: Single-Row Table Edge Cases
    //
    //  Table with exactly 1 row: aggregates, window functions,
    //  self-join, GROUP BY, DISTINCT all must work.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv32_single_row() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv32 (id INT, val INT)");
        run(&ex, "INSERT INTO inv32 VALUES (1, 42)");

        // Aggregates on single row
        let agg = run(&ex, "SELECT COUNT(*), SUM(val), MIN(val), MAX(val), AVG(val) FROM inv32");
        r.check("single-COUNT", agg.rows[0][0].as_i64().unwrap() == 1, "COUNT=1");
        let sum = val(&agg.rows[0][1]).unwrap();
        r.check("single-SUM", (sum - 42.0).abs() < 0.5, &format!("SUM={}", sum));
        r.check("single-MIN=MAX", {
            let mn = val(&agg.rows[0][2]).unwrap();
            let mx = val(&agg.rows[0][3]).unwrap();
            (mn - mx).abs() < 0.5
        }, "MIN != MAX for single row");

        // AVG = the value itself
        let avg = val(&agg.rows[0][4]).unwrap();
        r.check("single-AVG=val", (avg - 42.0).abs() < 0.5, &format!("AVG={}", avg));

        // Window function on single row
        let win = run(&ex, "SELECT id, ROW_NUMBER() OVER (ORDER BY id) as rn, SUM(val) OVER () as total FROM inv32");
        r.check("single-ROW_NUMBER", win.rows[0][1].as_i64().unwrap() == 1, "ROW_NUMBER=1");

        // Self-join with = (1 match)
        let sj = run_rows(&ex, "SELECT * FROM inv32 a JOIN inv32 b ON a.id = b.id");
        r.check("single-self-join", sj == 1, &format!("self-join rows={}", sj));

        // Self-join with != (0 matches)
        let sjn = run_rows(&ex, "SELECT * FROM inv32 a JOIN inv32 b ON a.id != b.id");
        r.check("single-self-join-neq", sjn == 0, &format!("neq self-join={}", sjn));

        // DISTINCT on single row = 1
        r.check("single-DISTINCT", run_rows(&ex, "SELECT DISTINCT val FROM inv32") == 1, "DISTINCT != 1");

        // GROUP BY on single row
        let grp = run(&ex, "SELECT id, COUNT(*) FROM inv32 GROUP BY id");
        r.check("single-GROUP-BY", grp.rows.len() == 1, &format!("groups={}", grp.rows.len()));

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-33: Duplicate Values
    //
    //  Table where every row has the same value for a column.
    //  MIN = MAX = AVG = value. COUNT DISTINCT = 1.
    //  DISTINCT returns 1 row. GROUP BY returns 1 group.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv33_all_duplicates() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv33 (id INT, val INT, cat TEXT)");
        for i in 1..=10 {
            run(&ex, &format!("INSERT INTO inv33 VALUES ({}, 42, 'same')", i));
        }

        // MIN = MAX = AVG = 42
        let agg = run(&ex, "SELECT MIN(val), MAX(val), AVG(val), COUNT(DISTINCT val) FROM inv33");
        let mn = val(&agg.rows[0][0]).unwrap();
        let mx = val(&agg.rows[0][1]).unwrap();
        let av = val(&agg.rows[0][2]).unwrap();
        let cd = agg.rows[0][3].as_i64().unwrap();
        r.check("dup-MIN=42", (mn - 42.0).abs() < 0.5, &format!("MIN={}", mn));
        r.check("dup-MAX=42", (mx - 42.0).abs() < 0.5, &format!("MAX={}", mx));
        r.check("dup-AVG=42", (av - 42.0).abs() < 0.5, &format!("AVG={}", av));
        r.check("dup-COUNT-DISTINCT=1", cd == 1, &format!("COUNT(DISTINCT)={}", cd));

        // DISTINCT returns 1 row
        r.check("dup-DISTINCT-rows=1", run_rows(&ex, "SELECT DISTINCT val FROM inv33") == 1, "");

        // GROUP BY returns 1 group
        r.check("dup-GROUP-BY=1", run_rows(&ex, "SELECT val, COUNT(*) FROM inv33 GROUP BY val") == 1, "");

        // But COUNT(*) is still 10
        let cnt = run(&ex, "SELECT COUNT(*) FROM inv33");
        r.check("dup-COUNT(*)=10", cnt.rows[0][0].as_i64().unwrap() == 10, "");

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-34: Negative and Zero Values
    //
    //  Arithmetic with negatives: SUM can be negative.
    //  ABS(SUM) invariants. Zero handling: x / 1 = x, 0 * x = 0.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv34_negative_zero() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv34 (id INT, val INT)");
        run(&ex, "INSERT INTO inv34 VALUES (1, -100)");
        run(&ex, "INSERT INTO inv34 VALUES (2, -50)");
        run(&ex, "INSERT INTO inv34 VALUES (3, 0)");
        run(&ex, "INSERT INTO inv34 VALUES (4, 50)");
        run(&ex, "INSERT INTO inv34 VALUES (5, 100)");

        // SUM = 0 (symmetric around 0)
        let sum_r = run(&ex, "SELECT SUM(val) FROM inv34");
        let sum = val(&sum_r.rows[0][0]).unwrap();
        r.check("symmetric-SUM=0", sum.abs() < 0.5, &format!("SUM={}", sum));

        // MIN < 0 < MAX
        let mm = run(&ex, "SELECT MIN(val), MAX(val) FROM inv34");
        let mn = val(&mm.rows[0][0]).unwrap();
        let mx = val(&mm.rows[0][1]).unwrap();
        r.check("neg-MIN<0", mn < 0.0, &format!("MIN={}", mn));
        r.check("neg-MAX>0", mx > 0.0, &format!("MAX={}", mx));

        // ABS(MIN) = MAX for symmetric data
        r.check("ABS(MIN)=MAX", (mn.abs() - mx).abs() < 0.5, &format!("ABS(MIN)={} MAX={}", mn.abs(), mx));

        // WHERE val > 0 gives 2 rows, val < 0 gives 2, val = 0 gives 1
        r.check("positive=2", run_rows(&ex, "SELECT * FROM inv34 WHERE val > 0") == 2, "");
        r.check("negative=2", run_rows(&ex, "SELECT * FROM inv34 WHERE val < 0") == 2, "");
        r.check("zero=1", run_rows(&ex, "SELECT * FROM inv34 WHERE val = 0") == 1, "");

        // ABS function: ABS(val) ORDER BY ABS(val) should give 0,50,50,100,100
        let abs_r = run(&ex, "SELECT ABS(val) FROM inv34 ORDER BY ABS(val)");
        let first = val(&abs_r.rows[0][0]).unwrap();
        r.check("ABS-sort-first=0", first.abs() < 0.5, &format!("first ABS={}", first));

        // val * -1 negates: SUM(val * -1) = -SUM(val) = 0
        let neg_sum = run(&ex, "SELECT SUM(val * -1) FROM inv34");
        let ns = val(&neg_sum.rows[0][0]).unwrap();
        r.check("SUM(val*-1)=-SUM(val)", ns.abs() < 0.5, &format!("SUM(val*-1)={}", ns));

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-35: Empty String Handling
    //
    //  '' (empty string) IS NOT NULL.
    //  LENGTH('') = 0.
    //  UPPER('') = LOWER('') = ''.
    //  Empty string in WHERE, GROUP BY, ORDER BY.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv35_empty_string() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv35 (id INT, name TEXT)");
        run(&ex, "INSERT INTO inv35 VALUES (1, '')");
        run(&ex, "INSERT INTO inv35 VALUES (2, 'hello')");
        run(&ex, "INSERT INTO inv35 VALUES (3, '')");
        run(&ex, "INSERT INTO inv35 VALUES (4, NULL)");

        // Empty string is NOT NULL
        let not_null = run_rows(&ex, "SELECT * FROM inv35 WHERE name IS NOT NULL");
        r.check("empty-IS-NOT-NULL", not_null == 3, &format!("NOT NULL count={}", not_null));

        // Empty string in WHERE
        let empty = run_rows(&ex, "SELECT * FROM inv35 WHERE name = ''");
        r.check("empty-WHERE", empty == 2, &format!("WHERE ''={}", empty));

        // LENGTH('') = 0
        let len = run(&ex, "SELECT LENGTH(name) FROM inv35 WHERE id = 1");
        r.check("LENGTH('')=0", len.rows[0][0].as_i64().unwrap() == 0, "");

        // GROUP BY with empty string
        let grp = run(&ex, "SELECT name, COUNT(*) FROM inv35 WHERE name IS NOT NULL GROUP BY name ORDER BY name");
        r.check("group-with-empty", grp.rows.len() == 2, &format!("groups={}", grp.rows.len()));

        // DISTINCT counts empty as 1 value + 'hello' + NULL = 3 distinct (or 2 if NULL excluded)
        let dist = run_rows(&ex, "SELECT DISTINCT name FROM inv35");
        r.check("DISTINCT-with-empty", dist >= 2, &format!("DISTINCT={}", dist));

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-36: Large Value Boundaries
    //
    //  Integer overflow edges, large sums, division precision.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv36_large_values() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv36 (id INT, val INT)");
        run(&ex, "INSERT INTO inv36 VALUES (1, 1000000000)");  // 1 billion
        run(&ex, "INSERT INTO inv36 VALUES (2, 2000000000)");  // 2 billion
        run(&ex, "INSERT INTO inv36 VALUES (3, -1000000000)"); // -1 billion

        // SUM should handle large values: 1B + 2B - 1B = 2B
        let sum_r = run(&ex, "SELECT SUM(val) FROM inv36");
        let s = val(&sum_r.rows[0][0]).unwrap();
        r.check("large-SUM", (s - 2_000_000_000.0).abs() < 1.0, &format!("SUM={}", s));

        // MAX and MIN
        let mm = run(&ex, "SELECT MIN(val), MAX(val) FROM inv36");
        let mn = val(&mm.rows[0][0]).unwrap();
        let mx = val(&mm.rows[0][1]).unwrap();
        r.check("large-MIN=-1B", (mn - (-1_000_000_000.0)).abs() < 1.0, &format!("MIN={}", mn));
        r.check("large-MAX=2B", (mx - 2_000_000_000.0).abs() < 1.0, &format!("MAX={}", mx));

        // Arithmetic: val * 2 for 2B
        let dbl = run(&ex, "SELECT val * 2 FROM inv36 WHERE id = 2");
        let d = val(&dbl.rows[0][0]).unwrap();
        r.check("large-mul", (d - 4_000_000_000.0).abs() < 1.0, &format!("2B*2={}", d));

        // Partition additivity still holds for large values
        let total = run(&ex, "SELECT COUNT(*) FROM inv36");
        let gt = run(&ex, "SELECT COUNT(*) FROM inv36 WHERE val > 0");
        let le = run(&ex, "SELECT COUNT(*) FROM inv36 WHERE val <= 0");
        let tc = total.rows[0][0].as_i64().unwrap();
        let gc = gt.rows[0][0].as_i64().unwrap();
        let lc = le.rows[0][0].as_i64().unwrap();
        r.check("large-partition", gc + lc == tc, &format!("{}+{}!={}", gc, lc, tc));

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-37: Many-to-Many JOIN Cardinality
    //
    //  When both sides have duplicates, JOIN can produce more rows
    //  than either table. Verify cardinality bounds.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv37_many_to_many() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv37a (id INT, k INT)");
        run(&ex, "CREATE TABLE inv37b (id INT, k INT)");
        // 3 rows in A with key=1, 2 rows in B with key=1 → 6 matches
        run(&ex, "INSERT INTO inv37a VALUES (1, 1)");
        run(&ex, "INSERT INTO inv37a VALUES (2, 1)");
        run(&ex, "INSERT INTO inv37a VALUES (3, 1)");
        run(&ex, "INSERT INTO inv37a VALUES (4, 2)");
        run(&ex, "INSERT INTO inv37b VALUES (1, 1)");
        run(&ex, "INSERT INTO inv37b VALUES (2, 1)");
        run(&ex, "INSERT INTO inv37b VALUES (3, 2)");
        run(&ex, "INSERT INTO inv37b VALUES (4, 3)");

        let joined = run_rows(&ex, "SELECT * FROM inv37a a JOIN inv37b b ON a.k = b.k");
        // key=1: 3*2=6, key=2: 1*1=1, total=7
        r.check("M:N-inner-join", joined == 7, &format!("joined={}", joined));

        // LEFT JOIN >= left table
        let left_j = run_rows(&ex, "SELECT * FROM inv37a a LEFT JOIN inv37b b ON a.k = b.k");
        r.check("M:N-left>=left", left_j >= 4, &format!("left join={}", left_j));

        // JOIN cardinality <= A * B
        let size_a = run_rows(&ex, "SELECT * FROM inv37a");
        let size_b = run_rows(&ex, "SELECT * FROM inv37b");
        r.check("M:N-inner<=product", joined <= size_a * size_b, &format!("joined={} product={}", joined, size_a * size_b));

        // Commutativity
        let reversed = run_rows(&ex, "SELECT * FROM inv37b b JOIN inv37a a ON a.k = b.k");
        r.check("M:N-commutative", joined == reversed, &format!("A⋈B={} B⋈A={}", joined, reversed));

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-38: LIKE Pattern Edge Cases
    //
    //  LIKE '%' matches everything non-NULL.
    //  LIKE '' matches only empty string.
    //  NOT LIKE '%' matches nothing.
    //  LIKE with consecutive wildcards.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv38_like_edge_cases() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv38 (id INT, val TEXT)");
        run(&ex, "INSERT INTO inv38 VALUES (1, 'hello')");
        run(&ex, "INSERT INTO inv38 VALUES (2, 'world')");
        run(&ex, "INSERT INTO inv38 VALUES (3, '')");
        run(&ex, "INSERT INTO inv38 VALUES (4, 'h')");
        run(&ex, "INSERT INTO inv38 VALUES (5, NULL)");

        let non_null = 4;  // 4 non-NULL rows

        // LIKE '%' matches all non-NULL
        let all_like = run_rows(&ex, "SELECT * FROM inv38 WHERE val LIKE '%'");
        r.check("LIKE-%=all-non-null", all_like == non_null, &format!("LIKE '%'={}", all_like));

        // NOT LIKE '%' matches nothing (that is non-NULL)
        let none_like = run_rows(&ex, "SELECT * FROM inv38 WHERE val NOT LIKE '%'");
        r.check("NOT-LIKE-%=0", none_like == 0, &format!("NOT LIKE '%'={}", none_like));

        // LIKE '' matches empty string only
        let empty_like = run_rows(&ex, "SELECT * FROM inv38 WHERE val LIKE ''");
        r.check("LIKE-empty=1", empty_like == 1, &format!("LIKE ''={}", empty_like));

        // LIKE 'h%' matches 'hello' and 'h'
        let h_like = run_rows(&ex, "SELECT * FROM inv38 WHERE val LIKE 'h%'");
        r.check("LIKE-h%=2", h_like == 2, &format!("LIKE 'h%'={}", h_like));

        // LIKE '%o%' matches 'hello' and 'world'
        let o_like = run_rows(&ex, "SELECT * FROM inv38 WHERE val LIKE '%o%'");
        r.check("LIKE-%o%=2", o_like == 2, &format!("LIKE '%%o%%'={}", o_like));

        // LIKE + NOT LIKE = all non-null rows
        let like_h = run_rows(&ex, "SELECT * FROM inv38 WHERE val LIKE 'h%'");
        let not_like_h = run_rows(&ex, "SELECT * FROM inv38 WHERE val NOT LIKE 'h%'");
        r.check("LIKE+NOT-LIKE=all", like_h + not_like_h == non_null, &format!("{}+{}={}", like_h, not_like_h, like_h + not_like_h));

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-39: Stress: 100-row Table Invariants
    //
    //  Build a 100-row table and verify all core invariants hold
    //  at scale: partition additivity, aggregate bounds, ORDER,
    //  GROUP BY, DISTINCT, window functions.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv39_hundred_row_stress() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv39 (id INT, grp INT, val INT, name TEXT)");
        for i in 1..=100 {
            let grp = (i - 1) % 10;  // 10 groups of 10
            run(&ex, &format!("INSERT INTO inv39 VALUES ({}, {}, {}, 'name{}')", i, grp, i * 7, i));
        }

        // Partition additivity at multiple thresholds
        let total = run(&ex, "SELECT COUNT(*), SUM(val) FROM inv39");
        let total_c = total.rows[0][0].as_i64().unwrap();
        let total_s = val(&total.rows[0][1]).unwrap();
        r.check("100-total-count", total_c == 100, &format!("COUNT={}", total_c));
        r.check("100-total-sum", (total_s - (100.0 * 101.0 / 2.0 * 7.0)).abs() < 0.5, &format!("SUM={}", total_s));

        for t in &[100, 200, 350, 500, 700] {
            let gt = run(&ex, &format!("SELECT COUNT(*) FROM inv39 WHERE val > {}", t));
            let le = run(&ex, &format!("SELECT COUNT(*) FROM inv39 WHERE val <= {}", t));
            let gc = gt.rows[0][0].as_i64().unwrap();
            let lc = le.rows[0][0].as_i64().unwrap();
            r.check(
                &format!("100-partition({})", t),
                gc + lc == total_c,
                &format!("{}+{} != {}", gc, lc, total_c),
            );
        }

        // GROUP BY: 10 groups, each with 10 rows
        let grps = run(&ex, "SELECT grp, COUNT(*) as cnt FROM inv39 GROUP BY grp ORDER BY grp");
        r.check("100-group-count", grps.rows.len() == 10, &format!("groups={}", grps.rows.len()));
        for row in &grps.rows {
            let cnt = row[1].as_i64().unwrap();
            r.check(
                &format!("100-group-size(grp{})", val(&row[0]).unwrap() as i64),
                cnt == 10,
                &format!("count={}", cnt),
            );
        }

        // SUM of group SUMs = total SUM
        let grp_sums = run(&ex, "SELECT SUM(s) FROM (SELECT grp, SUM(val) as s FROM inv39 GROUP BY grp) sub");
        let gs = val(&grp_sums.rows[0][0]).unwrap();
        r.check("100-sum-of-sums", (gs - total_s).abs() < 0.5, &format!("SUM(sums)={} vs total={}", gs, total_s));

        // ORDER BY + LIMIT
        let top5 = run(&ex, "SELECT val FROM inv39 ORDER BY val DESC LIMIT 5");
        r.check("100-top5-count", top5.rows.len() == 5, &format!("top5={}", top5.rows.len()));
        // Top value should be 100 * 7 = 700
        let top = val(&top5.rows[0][0]).unwrap();
        r.check("100-top-value", (top - 700.0).abs() < 0.5, &format!("top={}", top));

        // DISTINCT: 100 unique vals (all different since i*7 is unique)
        let dist = run_rows(&ex, "SELECT DISTINCT val FROM inv39");
        r.check("100-DISTINCT=100", dist == 100, &format!("DISTINCT={}", dist));

        // Window: ROW_NUMBER 1..100
        let rn = run(&ex, "SELECT ROW_NUMBER() OVER (ORDER BY id) as rn FROM inv39");
        let mut rn_vals: Vec<i64> = rn.rows.iter().filter_map(|row| row[0].as_i64()).collect();
        rn_vals.sort();
        let expected_rn: Vec<i64> = (1..=100).collect();
        r.check("100-ROW_NUMBER-1..100", rn_vals == expected_rn, "ROW_NUMBER doesn't produce 1..100");

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-40: Cross-Query State Isolation
    //
    //  DML on one table must not affect another table.
    //  Verify that SELECT/UPDATE/DELETE on table A leaves table B
    //  completely unchanged.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv40_state_isolation() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv40a (id INT, val INT)");
        run(&ex, "CREATE TABLE inv40b (id INT, val INT)");
        for i in 1..=5 {
            run(&ex, &format!("INSERT INTO inv40a VALUES ({}, {})", i, i * 10));
            run(&ex, &format!("INSERT INTO inv40b VALUES ({}, {})", i, i * 100));
        }

        // Snapshot B
        let b_before = run(&ex, "SELECT SUM(val), COUNT(*) FROM inv40b");
        let b_sum = val(&b_before.rows[0][0]).unwrap();
        let b_cnt = b_before.rows[0][1].as_i64().unwrap();

        // Mutate A heavily
        run(&ex, "UPDATE inv40a SET val = val * 2");
        run(&ex, "DELETE FROM inv40a WHERE id > 3");
        run(&ex, "INSERT INTO inv40a VALUES (6, 999)");

        // Verify B is unchanged
        let b_after = run(&ex, "SELECT SUM(val), COUNT(*) FROM inv40b");
        let b_sum2 = val(&b_after.rows[0][0]).unwrap();
        let b_cnt2 = b_after.rows[0][1].as_i64().unwrap();
        r.check("isolation-SUM", (b_sum - b_sum2).abs() < 0.5, &format!("before={} after={}", b_sum, b_sum2));
        r.check("isolation-COUNT", b_cnt == b_cnt2, &format!("before={} after={}", b_cnt, b_cnt2));

        // Verify A changed correctly
        let a_after = run(&ex, "SELECT COUNT(*), SUM(val) FROM inv40a");
        let a_cnt = a_after.rows[0][0].as_i64().unwrap();
        r.check("a-mutated", a_cnt == 4, &format!("a count={}", a_cnt)); // 3 remaining + 1 inserted

        r.finish();
    }

    // =================================================================
    //  MULTI-PARADIGM INVARIANTS (INV-41..INV-52)
    //
    //  Test ALL query languages through the same SimpleQueryExecutor.
    //  Dispatch is automatic: run() sends the string, execute_inner()
    //  detects the language and routes to the right executor.
    //
    //  Paradigms: Cypher, CQL, GraphQL, SigQL,
    //             TimeSeries, Vector, Full-Text, Columnar
    // =================================================================

    // -----------------------------------------------------------------
    //  INV-41: Cypher — Graph Node CRUD Invariants
    //
    //  CREATE n nodes → MATCH returns n nodes.
    //  DELETE a node → count decreases by 1.
    //  SET property → property readable.
    //  Node count is consistent across queries.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv41_cypher_node_crud() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // Create nodes
        run(&ex, "CREATE (n:CyPerson {name: 'Alice', age: 30})");
        run(&ex, "CREATE (n:CyPerson {name: 'Bob', age: 25})");
        run(&ex, "CREATE (n:CyPerson {name: 'Carol', age: 35})");

        // MATCH all → 3 nodes
        let all = run(&ex, "MATCH (n:CyPerson) RETURN n.name");
        r.check("cypher-create-3", all.rows.len() == 3, &format!("got {}", all.rows.len()));

        // MATCH with WHERE filter
        let filtered = run(&ex, "MATCH (n:CyPerson) WHERE n.age > 28 RETURN n.name");
        r.check("cypher-where-filter", filtered.rows.len() == 2, &format!("age>28: {}", filtered.rows.len()));

        // Partition: age > 28 + age <= 28 = 3
        let le = run(&ex, "MATCH (n:CyPerson) WHERE n.age <= 28 RETURN n.name");
        r.check(
            "cypher-partition",
            filtered.rows.len() + le.rows.len() == 3,
            &format!("{}+{} != 3", filtered.rows.len(), le.rows.len()),
        );

        // SET property and read back
        run(&ex, "MATCH (n:CyPerson) WHERE n.name = 'Alice' SET n.city = 'NYC'");
        let alice = run(&ex, "MATCH (n:CyPerson) WHERE n.name = 'Alice' RETURN n.city");
        r.check("cypher-set-read", alice.rows.len() == 1, &format!("Alice rows: {}", alice.rows.len()));
        if !alice.rows.is_empty() {
            r.check("cypher-set-value", alice.rows[0][0] == serde_json::json!("NYC"), &format!("city={:?}", alice.rows[0][0]));
        }

        // DELETE one node
        run(&ex, "MATCH (n:CyPerson) WHERE n.name = 'Bob' DETACH DELETE n");
        let after_del = run(&ex, "MATCH (n:CyPerson) RETURN n.name");
        r.check("cypher-delete-1", after_del.rows.len() == 2, &format!("after delete: {}", after_del.rows.len()));

        // COUNT aggregate
        let cnt = run(&ex, "MATCH (n:CyPerson) RETURN count(n)");
        r.check("cypher-count-matches", cnt.rows[0][0] == serde_json::json!(2), &format!("count={:?}", cnt.rows[0][0]));

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-42: Cypher — Relationship Invariants
    //
    //  Creating A->B means MATCH traversal from A finds B.
    //  Relationship count = number of CREATE rel statements.
    //  DETACH DELETE removes node + relationships.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv42_cypher_relationships() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // Create nodes and relationships
        run(&ex, "CREATE (a:CyEmp {name: 'Alice'})-[:WORKS_IN]->(d:CyDept {name: 'Engineering'})");
        run(&ex, "CREATE (b:CyEmp {name: 'Bob'})-[:WORKS_IN]->(d:CyDept {name: 'Engineering'})");
        run(&ex, "CREATE (c:CyEmp {name: 'Carol'})-[:WORKS_IN]->(d:CyDept {name: 'Sales'})");

        // Count employees
        let emps = run(&ex, "MATCH (e:CyEmp) RETURN e.name");
        r.check("cypher-emp-count", emps.rows.len() == 3, &format!("emps={}", emps.rows.len()));

        // Traverse: employees who work in Engineering
        let eng = run(&ex, "MATCH (e:CyEmp)-[:WORKS_IN]->(d:CyDept) WHERE d.name = 'Engineering' RETURN e.name");
        r.check("cypher-eng-emps", eng.rows.len() == 2, &format!("eng emps={}", eng.rows.len()));

        // All relationships
        let rels = run(&ex, "MATCH ()-[r:WORKS_IN]->() RETURN count(r)");
        if !rels.rows.is_empty() {
            let rel_count = rels.rows[0][0].as_i64().unwrap_or_else(|| {
                val(&rels.rows[0][0]).unwrap_or(0.0) as i64
            });
            r.check("cypher-rel-count", rel_count == 3, &format!("rels={}", rel_count));
        }

        // DISTINCT departments
        let depts = run(&ex, "MATCH (d:CyDept) RETURN DISTINCT d.name");
        r.check("cypher-distinct-depts", depts.rows.len() == 2, &format!("depts={}", depts.rows.len()));

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-43: Cypher — ORDER BY, LIMIT, SKIP
    //
    //  ORDER BY preserves count.
    //  LIMIT k returns min(k, total).
    //  SKIP + LIMIT pagination covers all rows.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv43_cypher_ordering() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        for i in 1..=5 {
            run(&ex, &format!("CREATE (n:CyItem {{val: {}}})", i * 10));
        }

        // ORDER BY doesn't change count
        let plain = run(&ex, "MATCH (n:CyItem) RETURN n.val");
        let ordered = run(&ex, "MATCH (n:CyItem) RETURN n.val ORDER BY n.val");
        r.check("cypher-order-card", plain.rows.len() == ordered.rows.len(),
            &format!("plain={} ordered={}", plain.rows.len(), ordered.rows.len()));

        // LIMIT
        let limited = run(&ex, "MATCH (n:CyItem) RETURN n.val ORDER BY n.val LIMIT 3");
        r.check("cypher-limit-3", limited.rows.len() == 3, &format!("limited={}", limited.rows.len()));

        // SKIP + LIMIT covers all: SKIP 0 LIMIT 3 + SKIP 3 LIMIT 5 = 5
        let page1 = run(&ex, "MATCH (n:CyItem) RETURN n.val ORDER BY n.val SKIP 0 LIMIT 3");
        let page2 = run(&ex, "MATCH (n:CyItem) RETURN n.val ORDER BY n.val SKIP 3 LIMIT 5");
        r.check("cypher-pagination",
            page1.rows.len() + page2.rows.len() == 5,
            &format!("{}+{}={}",page1.rows.len(), page2.rows.len(), page1.rows.len() + page2.rows.len()));

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-44: CQL — Keyspace + Table CRUD
    //
    //  CREATE TABLE → INSERT → SELECT round-trip.
    //  COUNT consistency. DELETE removes rows.
    //  UPDATE modifies without changing count.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv44_cql_crud() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // Create keyspace and table
        run(&ex, "CREATE KEYSPACE inv44_ks WITH replication = {'class': 'SimpleStrategy', 'replication_factor': '1'}");
        run(&ex, "CREATE TABLE inv44_ks.users (id INT PRIMARY KEY, name TEXT, age INT)");

        // Insert rows
        run(&ex, "INSERT INTO inv44_ks.users (id, name, age) VALUES (1, 'Alice', 30)");
        run(&ex, "INSERT INTO inv44_ks.users (id, name, age) VALUES (2, 'Bob', 25)");
        run(&ex, "INSERT INTO inv44_ks.users (id, name, age) VALUES (3, 'Carol', 35)");

        // SELECT all
        let all = run(&ex, "SELECT * FROM inv44_ks.users");
        r.check("cql-insert-3", all.rows.len() == 3, &format!("rows={}", all.rows.len()));

        // SELECT with WHERE
        let filtered = run(&ex, "SELECT * FROM inv44_ks.users WHERE id = 1");
        r.check("cql-where-id1", filtered.rows.len() == 1, &format!("filtered={}", filtered.rows.len()));

        // UPDATE preserves count
        run(&ex, "UPDATE inv44_ks.users SET age = 31 WHERE id = 1");
        let after_update = run(&ex, "SELECT * FROM inv44_ks.users");
        r.check("cql-update-preserves", after_update.rows.len() == 3, &format!("after update={}", after_update.rows.len()));

        // DELETE reduces count
        run(&ex, "DELETE FROM inv44_ks.users WHERE id = 2");
        let after_delete = run(&ex, "SELECT * FROM inv44_ks.users");
        r.check("cql-delete-1", after_delete.rows.len() == 2, &format!("after delete={}", after_delete.rows.len()));

        // LIMIT
        let limited = run(&ex, "SELECT * FROM inv44_ks.users LIMIT 1");
        r.check("cql-limit", limited.rows.len() == 1, &format!("limited={}", limited.rows.len()));

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-45: CQL — Batch Operations
    //
    //  BATCH inserts are atomic: all succeed.
    //  TRUNCATE removes all rows.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv45_cql_batch() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE KEYSPACE inv45_ks WITH replication = {'class': 'SimpleStrategy', 'replication_factor': '1'}");
        run(&ex, "CREATE TABLE inv45_ks.items (id INT PRIMARY KEY, val TEXT)");

        // Batch insert
        run(&ex, "BEGIN BATCH INSERT INTO inv45_ks.items (id, val) VALUES (1, 'a'); INSERT INTO inv45_ks.items (id, val) VALUES (2, 'b'); INSERT INTO inv45_ks.items (id, val) VALUES (3, 'c'); APPLY BATCH");

        let all = run(&ex, "SELECT * FROM inv45_ks.items");
        r.check("cql-batch-3", all.rows.len() == 3, &format!("batch rows={}", all.rows.len()));

        // TRUNCATE
        run(&ex, "TRUNCATE inv45_ks.items");
        let after = run(&ex, "SELECT * FROM inv45_ks.items");
        r.check("cql-truncate-0", after.rows.len() == 0, &format!("after truncate={}", after.rows.len()));

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-46: GraphQL — Query + Mutation Round-Trip
    //
    //  Create via mutation → query returns created data.
    //  Field selection returns only requested fields.
    //  Delete via mutation removes the row.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv46_graphql_roundtrip() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // First create a table via SQL (GraphQL queries existing tables)
        run(&ex, "CREATE TABLE gql_users (id INT, name TEXT, email TEXT)");
        run(&ex, "INSERT INTO gql_users VALUES (1, 'Alice', 'alice@test.com')");
        run(&ex, "INSERT INTO gql_users VALUES (2, 'Bob', 'bob@test.com')");
        run(&ex, "INSERT INTO gql_users VALUES (3, 'Carol', 'carol@test.com')");

        // GraphQL query all
        let all = run(&ex, "{ gql_users { id name email } }");
        r.check("gql-query-all", all.rows.len() == 3, &format!("gql rows={}", all.rows.len()));

        // Field selection: only id and name
        let partial = run(&ex, "{ gql_users { id name } }");
        r.check("gql-field-selection", partial.columns.len() == 2, &format!("cols={:?}", partial.columns));
        r.check("gql-partial-rows", partial.rows.len() == 3, &format!("rows={}", partial.rows.len()));

        // Query with limit
        let limited = run(&ex, "{ gql_users(limit: 2) { id name } }");
        r.check("gql-limit", limited.rows.len() == 2, &format!("limited={}", limited.rows.len()));

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-47: GraphQL — Mutation CRUD
    //
    //  createX adds a row, updateX modifies, deleteX removes.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv47_graphql_mutations() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE gql_items (id INT, val TEXT)");
        run(&ex, "INSERT INTO gql_items VALUES (1, 'initial')");

        let before = run(&ex, "{ gql_items { id val } }");
        r.check("gql-before", before.rows.len() == 1, &format!("before={}", before.rows.len()));

        // Create via mutation
        let create_res = run(&ex, "mutation { createGql_items(id: 2, val: \"added\") { id } }");
        r.check("gql-create-ok", create_res.affected_rows.unwrap_or(0) >= 1 || create_res.rows.len() >= 1,
            &format!("create result: rows={} affected={:?}", create_res.rows.len(), create_res.affected_rows));

        let after_create = run(&ex, "{ gql_items { id } }");
        r.check("gql-after-create", after_create.rows.len() == 2, &format!("after create={}", after_create.rows.len()));

        // Delete via mutation
        let del_res = run(&ex, "mutation { deleteGql_items(id: 1) { id } }");
        r.check("gql-delete-ok", del_res.affected_rows.unwrap_or(0) >= 1 || del_res.rows.len() >= 0, "delete failed");

        let after_delete = run(&ex, "{ gql_items { id } }");
        r.check("gql-after-delete", after_delete.rows.len() == 1, &format!("after delete={}", after_delete.rows.len()));

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-48: TimeSeries — Write/Read/Aggregate
    //
    //  TSWRITE n points → TSQUERY returns n points.
    //  TSAGGREGATE SUM = sum of written values.
    //  TSDELETE removes points.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv48_timeseries() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // Write 5 data points with explicit timestamps
        run(&ex, "TSWRITE inv48.cpu 10.0 1000");
        run(&ex, "TSWRITE inv48.cpu 20.0 2000");
        run(&ex, "TSWRITE inv48.cpu 30.0 3000");
        run(&ex, "TSWRITE inv48.cpu 40.0 4000");
        run(&ex, "TSWRITE inv48.cpu 50.0 5000");

        // Query all points
        let all = run(&ex, "TSQUERY inv48.cpu 0 9999");
        r.check("ts-write-5", all.rows.len() == 5, &format!("ts rows={}", all.rows.len()));

        // Query range subset
        let subset = run(&ex, "TSQUERY inv48.cpu 2000 4000");
        r.check("ts-range-3", subset.rows.len() == 3, &format!("range rows={}", subset.rows.len()));

        // Aggregate: SUM should be 150
        // TSAGGREGATE returns [timestamp, value] columns
        let sum_r = run(&ex, "TSAGGREGATE inv48.cpu 0 9999 10000 SUM");
        if !sum_r.rows.is_empty() && sum_r.rows[0].len() >= 2 {
            let sum_val = val(&sum_r.rows[0][1]).unwrap_or(0.0);
            r.check("ts-sum", (sum_val - 150.0).abs() < 0.5, &format!("SUM={}", sum_val));
        }

        // Aggregate: COUNT
        let cnt_r = run(&ex, "TSAGGREGATE inv48.cpu 0 9999 10000 COUNT");
        if !cnt_r.rows.is_empty() && cnt_r.rows[0].len() >= 2 {
            let cnt_val = val(&cnt_r.rows[0][1]).unwrap_or(0.0);
            r.check("ts-count", (cnt_val - 5.0).abs() < 0.5, &format!("COUNT={}", cnt_val));
        }

        // Aggregate: AVG = 30
        let avg_r = run(&ex, "TSAGGREGATE inv48.cpu 0 9999 10000 AVG");
        if !avg_r.rows.is_empty() && avg_r.rows[0].len() >= 2 {
            let avg_val = val(&avg_r.rows[0][1]).unwrap_or(0.0);
            r.check("ts-avg", (avg_val - 30.0).abs() < 0.5, &format!("AVG={}", avg_val));
        }

        // List metrics
        let list = run(&ex, "TSLIST");
        r.check("ts-list", list.rows.len() >= 1, &format!("metrics listed={}", list.rows.len()));

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-49: Vector Search — Distance Metric Invariants
    //
    //  Self-distance = 0 (or score = 1 for cosine).
    //  Symmetric: dist(A,B) = dist(B,A).
    //  Nearest neighbor of A is A itself when A is in the index.
    //  Result count = min(k, index_size).
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv49_vector_search() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // Create index with cosine similarity, dimension 3
        run(&ex, "VECTOR CREATE inv49_idx 3 cosine");

        // Insert vectors
        run(&ex, "VECTOR INSERT inv49_idx v1 [1.0,0.0,0.0]");
        run(&ex, "VECTOR INSERT inv49_idx v2 [0.0,1.0,0.0]");
        run(&ex, "VECTOR INSERT inv49_idx v3 [0.0,0.0,1.0]");
        run(&ex, "VECTOR INSERT inv49_idx v4 [1.0,1.0,0.0]");

        // Search for v1: nearest should be v1 itself (score ~1.0)
        let search1 = run(&ex, "VECTOR SEARCH inv49_idx [1.0,0.0,0.0] 4");
        r.check("vec-search-returns", search1.rows.len() == 4, &format!("results={}", search1.rows.len()));

        // First result should be v1 (exact match → highest cosine similarity)
        if !search1.rows.is_empty() {
            // Find which column has the id
            let first_id = search1.rows[0][0].as_str().unwrap_or("");
            r.check("vec-self-nearest", first_id == "v1", &format!("nearest={}", first_id));

            // Score of exact match should be ~1.0 for cosine
            let first_score = val(&search1.rows[0][1]).unwrap_or(0.0);
            r.check("vec-self-score", first_score > 0.99, &format!("self score={}", first_score));
        }

        // Search for v4 [1,1,0]: should find v4 first, then v1 and v2 (both component matches)
        let search4 = run(&ex, "VECTOR SEARCH inv49_idx [1.0,1.0,0.0] 2");
        r.check("vec-search-k2", search4.rows.len() == 2, &format!("k=2 results={}", search4.rows.len()));

        // LIMIT k: search with k=1 returns exactly 1
        let search_k1 = run(&ex, "VECTOR SEARCH inv49_idx [1.0,0.0,0.0] 1");
        r.check("vec-search-k1", search_k1.rows.len() == 1, &format!("k=1 results={}", search_k1.rows.len()));

        // List indexes
        let list = run(&ex, "VECTOR LIST");
        r.check("vec-list", list.rows.len() >= 1, &format!("indexes={}", list.rows.len()));

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-50: Full-Text Search — Index/Search Round-Trip
    //
    //  FTINDEX doc → FTSEARCH finds it.
    //  Searching for a word in the doc returns that doc.
    //  Searching for a word not in any doc returns 0 results.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv50_fulltext_search() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // Index documents
        run(&ex, "FTINDEX inv50 doc1 The quick brown fox jumps over the lazy dog");
        run(&ex, "FTINDEX inv50 doc2 Rust is a systems programming language");
        run(&ex, "FTINDEX inv50 doc3 JouleDB measures energy in joules per bit");

        // Search for "fox" → should find doc1
        let fox = run(&ex, "FTSEARCH inv50 fox");
        r.check("ft-find-fox", fox.rows.len() >= 1, &format!("fox results={}", fox.rows.len()));

        // Search for "rust" → should find doc2
        let rust = run(&ex, "FTSEARCH inv50 rust");
        r.check("ft-find-rust", rust.rows.len() >= 1, &format!("rust results={}", rust.rows.len()));

        // Search for "joules" → should find doc3
        let joules = run(&ex, "FTSEARCH inv50 joules");
        r.check("ft-find-joules", joules.rows.len() >= 1, &format!("joules results={}", joules.rows.len()));

        // Search for nonexistent word → 0 results
        let nope = run(&ex, "FTSEARCH inv50 xyzzy42nonexistent");
        r.check("ft-no-match", nope.rows.len() == 0, &format!("nonexistent results={}", nope.rows.len()));

        // Delete a document and verify it's gone
        run(&ex, "FTDELETE inv50 doc1");
        let after_del = run(&ex, "FTSEARCH inv50 fox");
        r.check("ft-deleted", after_del.rows.len() == 0, &format!("after delete fox={}", after_del.rows.len()));

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-51: Columnar OLAP — Aggregate Invariants
    //
    //  SUM, AVG, COUNT, MIN, MAX on columnar store.
    //  Same algebraic properties as SQL aggregates.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv51_columnar_aggregates() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // Create columnar table
        run(&ex, "COLUMNAR CREATE inv51_sales amount:float quantity:int");

        // Insert data
        run(&ex, "COLUMNAR INSERT inv51_sales 100.0 5");
        run(&ex, "COLUMNAR INSERT inv51_sales 200.0 3");
        run(&ex, "COLUMNAR INSERT inv51_sales 150.0 7");

        // SUM
        let sum_r = run(&ex, "COLUMNAR AGGREGATE inv51_sales amount SUM");
        if !sum_r.rows.is_empty() {
            // Find the result value in the response
            let sum_val = sum_r.rows[0].iter().find_map(|v| {
                if let Some(f) = val(v) { if f > 1.0 { Some(f) } else { None } } else { None }
            }).unwrap_or(0.0);
            r.check("col-sum", (sum_val - 450.0).abs() < 0.5, &format!("SUM={}", sum_val));
        }

        // COUNT
        let cnt_r = run(&ex, "COLUMNAR AGGREGATE inv51_sales amount COUNT");
        if !cnt_r.rows.is_empty() {
            let cnt_val = cnt_r.rows[0].iter().find_map(|v| {
                val(v).filter(|f| *f >= 1.0)
            }).unwrap_or(0.0);
            r.check("col-count", (cnt_val - 3.0).abs() < 0.5, &format!("COUNT={}", cnt_val));
        }

        // AVG
        let avg_r = run(&ex, "COLUMNAR AGGREGATE inv51_sales amount AVG");
        if !avg_r.rows.is_empty() {
            let avg_val = avg_r.rows[0].iter().find_map(|v| {
                val(v).filter(|f| *f > 1.0)
            }).unwrap_or(0.0);
            r.check("col-avg", (avg_val - 150.0).abs() < 0.5, &format!("AVG={}", avg_val));
        }

        // Quantity SUM
        let qsum = run(&ex, "COLUMNAR AGGREGATE inv51_sales quantity SUM");
        if !qsum.rows.is_empty() {
            let qval = qsum.rows[0].iter().find_map(|v| {
                val(v).filter(|f| *f >= 1.0)
            }).unwrap_or(0.0);
            r.check("col-qty-sum", (qval - 15.0).abs() < 0.5, &format!("qty SUM={}", qval));
        }

        r.finish();
    }

    // -----------------------------------------------------------------
    //  INV-52: Cross-Paradigm Data Isolation
    //
    //  Operations in one paradigm must not affect another.
    //  SQL tables ≠ Cypher nodes ≠ CQL keyspaces ≠ feature stores.
    //  Create data in each, verify independence.
    // -----------------------------------------------------------------
    #[tokio::test]
    async fn inv52_cross_paradigm_isolation() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // Create data in SQL
        run(&ex, "CREATE TABLE iso_sql (id INT, val INT)");
        run(&ex, "INSERT INTO iso_sql VALUES (1, 100)");
        run(&ex, "INSERT INTO iso_sql VALUES (2, 200)");

        // Create data in Cypher
        run(&ex, "CREATE (n:IsoNode {name: 'graphnode1'})");
        run(&ex, "CREATE (n:IsoNode {name: 'graphnode2'})");
        run(&ex, "CREATE (n:IsoNode {name: 'graphnode3'})");

        // Create data in CQL
        run(&ex, "CREATE KEYSPACE iso_ks WITH replication = {'class': 'SimpleStrategy', 'replication_factor': '1'}");
        run(&ex, "CREATE TABLE iso_ks.data (id INT PRIMARY KEY, val TEXT)");
        run(&ex, "INSERT INTO iso_ks.data (id, val) VALUES (1, 'cql1')");

        // Create data in TimeSeries
        run(&ex, "TSWRITE iso.metric 42.0 1000");

        // Create data in Vector
        run(&ex, "VECTOR CREATE iso_vec 2 cosine");
        run(&ex, "VECTOR INSERT iso_vec v1 [1.0,0.0]");

        // Index in Full-Text
        run(&ex, "FTINDEX iso_ft d1 isolation test document");

        // Now verify each paradigm sees only its own data

        // SQL: 2 rows
        let sql_rows = run_rows(&ex, "SELECT * FROM iso_sql");
        r.check("iso-sql", sql_rows == 2, &format!("sql={}", sql_rows));

        // Cypher: 3 nodes
        let cypher_rows = run(&ex, "MATCH (n:IsoNode) RETURN n.name");
        r.check("iso-cypher", cypher_rows.rows.len() == 3, &format!("cypher={}", cypher_rows.rows.len()));

        // CQL: 1 row
        let cql_rows = run(&ex, "SELECT * FROM iso_ks.data");
        r.check("iso-cql", cql_rows.rows.len() == 1, &format!("cql={}", cql_rows.rows.len()));

        // TimeSeries: 1 point
        let ts_rows = run(&ex, "TSQUERY iso.metric 0 9999");
        r.check("iso-ts", ts_rows.rows.len() == 1, &format!("ts={}", ts_rows.rows.len()));

        // Vector: 1 vector
        let vec_rows = run(&ex, "VECTOR SEARCH iso_vec [1.0,0.0] 10");
        r.check("iso-vec", vec_rows.rows.len() == 1, &format!("vec={}", vec_rows.rows.len()));

        // Full-text: finds "isolation"
        let ft_rows = run(&ex, "FTSEARCH iso_ft isolation");
        r.check("iso-ft", ft_rows.rows.len() >= 1, &format!("ft={}", ft_rows.rows.len()));

        // Mutate SQL — Cypher/CQL/TS unaffected
        run(&ex, "DELETE FROM iso_sql");
        let sql_after = run_rows(&ex, "SELECT * FROM iso_sql");
        r.check("iso-sql-deleted", sql_after == 0, "sql not deleted");

        let cypher_after = run(&ex, "MATCH (n:IsoNode) RETURN n.name");
        r.check("iso-cypher-unaffected", cypher_after.rows.len() == 3, &format!("cypher after sql delete={}", cypher_after.rows.len()));

        let cql_after = run(&ex, "SELECT * FROM iso_ks.data");
        r.check("iso-cql-unaffected", cql_after.rows.len() == 1, &format!("cql after sql delete={}", cql_after.rows.len()));

        let ts_after = run(&ex, "TSQUERY iso.metric 0 9999");
        r.check("iso-ts-unaffected", ts_after.rows.len() == 1, &format!("ts after sql delete={}", ts_after.rows.len()));

        r.finish();
    }

    // =================================================================
    //  INV-53: Cypher — Aggregate Functions (SUM, AVG, MIN, MAX, COLLECT)
    //
    //  SUM of known values = expected.
    //  AVG = SUM / COUNT.
    //  MIN <= AVG <= MAX.
    //  COLLECT returns array of all values.
    // =================================================================
    #[tokio::test]
    async fn inv53_cypher_aggregates() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        for v in [10, 20, 30, 40, 50] {
            run(&ex, &format!("CREATE (n:CyVal {{val: {}}})", v));
        }

        let sum_r = run(&ex, "MATCH (n:CyVal) RETURN sum(n.val)");
        if !sum_r.rows.is_empty() {
            let s = val(&sum_r.rows[0][0]).unwrap_or(0.0);
            r.check("cypher-sum", (s - 150.0).abs() < 0.5, &format!("SUM={}", s));
        }

        let avg_r = run(&ex, "MATCH (n:CyVal) RETURN avg(n.val)");
        if !avg_r.rows.is_empty() {
            let a = val(&avg_r.rows[0][0]).unwrap_or(0.0);
            r.check("cypher-avg", (a - 30.0).abs() < 0.5, &format!("AVG={}", a));
        }

        let min_r = run(&ex, "MATCH (n:CyVal) RETURN min(n.val)");
        let max_r = run(&ex, "MATCH (n:CyVal) RETURN max(n.val)");
        if !min_r.rows.is_empty() && !max_r.rows.is_empty() {
            let mn = val(&min_r.rows[0][0]).unwrap_or(0.0);
            let mx = val(&max_r.rows[0][0]).unwrap_or(0.0);
            r.check("cypher-min", (mn - 10.0).abs() < 0.5, &format!("MIN={}", mn));
            r.check("cypher-max", (mx - 50.0).abs() < 0.5, &format!("MAX={}", mx));
            r.check("cypher-min-le-max", mn <= mx, &format!("{} <= {}", mn, mx));
        }

        let cnt_r = run(&ex, "MATCH (n:CyVal) RETURN count(n)");
        if !cnt_r.rows.is_empty() {
            let c = val(&cnt_r.rows[0][0]).unwrap_or(0.0);
            r.check("cypher-count-5", (c - 5.0).abs() < 0.5, &format!("COUNT={}", c));
        }

        let col_r = run(&ex, "MATCH (n:CyVal) RETURN collect(n.val)");
        if !col_r.rows.is_empty() {
            if let Some(arr) = col_r.rows[0][0].as_array() {
                r.check("cypher-collect-len", arr.len() == 5, &format!("COLLECT len={}", arr.len()));
            } else {
                r.check("cypher-collect-array", false, "COLLECT did not return array");
            }
        }

        r.finish();
    }

    // =================================================================
    //  INV-54: Cypher — MERGE Idempotency
    //
    //  MERGE creates if not exists, matches if exists.
    //  Running MERGE N times produces exactly 1 node.
    // =================================================================
    #[tokio::test]
    async fn inv54_cypher_merge_idempotent() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        for _ in 0..5 {
            run(&ex, "MERGE (n:Singleton {name: 'only_one'})");
        }

        let cnt = run(&ex, "MATCH (n:Singleton) RETURN count(n)");
        if !cnt.rows.is_empty() {
            let c = val(&cnt.rows[0][0]).unwrap_or(0.0);
            r.check("merge-idempotent", (c - 1.0).abs() < 0.5, &format!("after 5 merges count={}", c));
        }

        // MERGE with SET should update, not duplicate
        run(&ex, "MERGE (n:Singleton {name: 'only_one'}) SET n.version = 2");
        let after = run(&ex, "MATCH (n:Singleton) RETURN count(n)");
        if !after.rows.is_empty() {
            let c2 = val(&after.rows[0][0]).unwrap_or(0.0);
            r.check("merge-set-no-dup", (c2 - 1.0).abs() < 0.5, &format!("after merge+set count={}", c2));
        }

        r.finish();
    }

    // =================================================================
    //  INV-55: Cypher — DELETE + COUNT Consistency
    //
    //  Create N, delete K, count = N - K.
    //  Delete all, count = 0.
    // =================================================================
    #[tokio::test]
    async fn inv55_cypher_delete_count() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        for i in 1..=6 {
            run(&ex, &format!("CREATE (n:CyDel {{idx: {}}})", i));
        }

        let before = run(&ex, "MATCH (n:CyDel) RETURN count(n)");
        if !before.rows.is_empty() {
            let b = val(&before.rows[0][0]).unwrap_or(0.0);
            r.check("del-initial-6", (b - 6.0).abs() < 0.5, &format!("initial={}", b));
        }

        // Delete 2 nodes
        run(&ex, "MATCH (n:CyDel {idx: 1}) DELETE n");
        run(&ex, "MATCH (n:CyDel {idx: 2}) DELETE n");

        let mid = run(&ex, "MATCH (n:CyDel) RETURN count(n)");
        if !mid.rows.is_empty() {
            let m = val(&mid.rows[0][0]).unwrap_or(0.0);
            r.check("del-minus-2", (m - 4.0).abs() < 0.5, &format!("after 2 deletes={}", m));
        }

        // Delete all remaining
        run(&ex, "MATCH (n:CyDel) DELETE n");
        let fin = run(&ex, "MATCH (n:CyDel) RETURN count(n)");
        if !fin.rows.is_empty() {
            let f = val(&fin.rows[0][0]).unwrap_or(0.0);
            r.check("del-all-0", f.abs() < 0.5, &format!("after delete all={}", f));
        }

        r.finish();
    }

    // =================================================================
    //  INV-56: Cypher — SET/REMOVE Property Round-Trip
    //
    //  SET adds property. REMOVE deletes it. Original properties unchanged.
    // =================================================================
    #[tokio::test]
    async fn inv56_cypher_set_remove() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE (n:CySR {name: 'test', val: 100})");

        // SET adds new property
        run(&ex, "MATCH (n:CySR {name: 'test'}) SET n.extra = 'added'");
        let after_set = run(&ex, "MATCH (n:CySR {name: 'test'}) RETURN n.extra");
        if !after_set.rows.is_empty() {
            let v = after_set.rows[0][0].as_str().unwrap_or("");
            r.check("set-adds-prop", v == "added", &format!("extra={}", v));
        }

        // Original property unchanged
        let orig = run(&ex, "MATCH (n:CySR {name: 'test'}) RETURN n.val");
        if !orig.rows.is_empty() {
            let ov = val(&orig.rows[0][0]).unwrap_or(0.0);
            r.check("set-preserves-orig", (ov - 100.0).abs() < 0.5, &format!("val={}", ov));
        }

        // REMOVE deletes property
        run(&ex, "MATCH (n:CySR {name: 'test'}) REMOVE n.extra");
        let after_rm = run(&ex, "MATCH (n:CySR {name: 'test'}) RETURN n.extra");
        if !after_rm.rows.is_empty() {
            r.check("remove-deletes-prop", after_rm.rows[0][0].is_null(), &format!("extra after remove={}", after_rm.rows[0][0]));
        }

        r.finish();
    }

    // =================================================================
    //  INV-57: Cypher — OPTIONAL MATCH Returns NULLs
    //
    //  OPTIONAL MATCH on non-existent relationship returns the node
    //  with NULL for the unmatched side.
    // =================================================================
    #[tokio::test]
    async fn inv57_cypher_optional_match() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE (n:CyOpt {name: 'alone'})");
        run(&ex, "CREATE (n:CyOpt {name: 'linked'})");
        run(&ex, "CREATE (n:CyOpt {name: 'target'})");
        run(&ex, "MATCH (a:CyOpt {name: 'linked'}), (b:CyOpt {name: 'target'}) CREATE (a)-[:OPTREL]->(b)");

        let res = run(&ex, "MATCH (n:CyOpt) OPTIONAL MATCH (n)-[:OPTREL]->(m) RETURN n.name, m.name ORDER BY n.name");
        r.check("opt-match-count", res.rows.len() == 3, &format!("rows={}", res.rows.len()));

        // 'alone' should have NULL for m.name
        if res.rows.len() == 3 {
            let alone_row = res.rows.iter().find(|row| row[0].as_str() == Some("alone"));
            if let Some(row) = alone_row {
                r.check("opt-match-null", row[1].is_null(), &format!("alone m.name={}", row[1]));
            }
            let linked_row = res.rows.iter().find(|row| row[0].as_str() == Some("linked"));
            if let Some(row) = linked_row {
                r.check("opt-match-linked", row[1].as_str() == Some("target"), &format!("linked m.name={}", row[1]));
            }
        }

        r.finish();
    }

    // =================================================================
    //  INV-58: CQL — UPDATE Preserves Non-Updated Columns
    //
    //  UPDATE one column; verify other columns unchanged.
    //  Count remains same after UPDATE.
    // =================================================================
    #[tokio::test]
    async fn inv58_cql_update_preserves() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE KEYSPACE inv58_ks WITH replication = {'class': 'SimpleStrategy', 'replication_factor': '1'}");
        run(&ex, "CREATE TABLE inv58_ks.users (id INT PRIMARY KEY, name TEXT, age INT)");
        run(&ex, "INSERT INTO inv58_ks.users (id, name, age) VALUES (1, 'Alice', 30)");
        run(&ex, "INSERT INTO inv58_ks.users (id, name, age) VALUES (2, 'Bob', 25)");

        // Update age only
        run(&ex, "UPDATE inv58_ks.users SET age = 31 WHERE id = 1");

        let all = run(&ex, "SELECT * FROM inv58_ks.users");
        r.check("cql-update-count", all.rows.len() == 2, &format!("count={}", all.rows.len()));

        // Check that name wasn't lost
        let alice = run(&ex, "SELECT * FROM inv58_ks.users WHERE id = 1");
        if !alice.rows.is_empty() {
            let has_alice = alice.rows[0].iter().any(|v| v.as_str() == Some("Alice"));
            r.check("cql-name-preserved", has_alice, "name 'Alice' preserved after update");
        }

        r.finish();
    }

    // =================================================================
    //  INV-59: CQL — TRUNCATE Empties Table, Schema Survives
    //
    //  INSERT rows, TRUNCATE, count = 0.
    //  INSERT again after TRUNCATE succeeds.
    // =================================================================
    #[tokio::test]
    async fn inv59_cql_truncate_recovers() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE KEYSPACE inv59_ks WITH replication = {'class': 'SimpleStrategy', 'replication_factor': '1'}");
        run(&ex, "CREATE TABLE inv59_ks.items (id INT PRIMARY KEY, val TEXT)");
        run(&ex, "INSERT INTO inv59_ks.items (id, val) VALUES (1, 'a')");
        run(&ex, "INSERT INTO inv59_ks.items (id, val) VALUES (2, 'b')");

        let before = run(&ex, "SELECT * FROM inv59_ks.items");
        r.check("cql-pre-truncate", before.rows.len() == 2, &format!("before={}", before.rows.len()));

        run(&ex, "TRUNCATE inv59_ks.items");
        let after = run(&ex, "SELECT * FROM inv59_ks.items");
        r.check("cql-post-truncate-0", after.rows.len() == 0, &format!("after truncate={}", after.rows.len()));

        // Table schema still exists — can insert again
        run(&ex, "INSERT INTO inv59_ks.items (id, val) VALUES (3, 'c')");
        let recovered = run(&ex, "SELECT * FROM inv59_ks.items");
        r.check("cql-post-truncate-insert", recovered.rows.len() == 1, &format!("after re-insert={}", recovered.rows.len()));

        r.finish();
    }

    // =================================================================
    //  INV-60: GraphQL — Nested Object Queries
    //
    //  Create with nested fields → query returns them.
    //  Field names preserved. NULL for missing fields.
    // =================================================================
    #[tokio::test]
    async fn inv60_graphql_nested() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // Create table via SQL, then use GraphQL for mutations and queries
        run(&ex, "CREATE TABLE gql_docs (id INT, title TEXT, author TEXT, priority INT)");
        run(&ex, r#"mutation { createGql_docs(id: 1, title: "Doc1", author: "Alice", priority: 5) { id } }"#);
        run(&ex, r#"mutation { createGql_docs(id: 2, title: "Doc2", author: "Bob", priority: 3) { id } }"#);

        let res = run(&ex, "{ gql_docs { id title author priority } }");
        r.check("gql-nested-count", res.rows.len() == 2, &format!("rows={}", res.rows.len()));

        // Check that fields are returned
        if res.rows.len() == 2 {
            let has_title = res.rows.iter().all(|row| row.iter().any(|v| v.as_str() == Some("Doc1") || v.as_str() == Some("Doc2")));
            r.check("gql-fields-present", has_title, "titles present in results");
        }

        // Field selection: query only title and author
        let partial = run(&ex, "{ gql_docs { title author } }");
        r.check("gql-field-select", partial.columns.len() == 2, &format!("cols={}", partial.columns.len()));

        r.finish();
    }

    // =================================================================
    //  INV-61: TimeSeries — Range Query Boundaries
    //
    //  Points exactly at start/end are included.
    //  Empty range returns 0 points.
    //  Full range returns all points.
    // =================================================================
    #[tokio::test]
    async fn inv61_timeseries_boundaries() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "TSWRITE inv61.m 1.0 100");
        run(&ex, "TSWRITE inv61.m 2.0 200");
        run(&ex, "TSWRITE inv61.m 3.0 300");
        run(&ex, "TSWRITE inv61.m 4.0 400");
        run(&ex, "TSWRITE inv61.m 5.0 500");

        // Full range
        let all = run(&ex, "TSQUERY inv61.m 0 999");
        r.check("ts-full-range", all.rows.len() == 5, &format!("full={}", all.rows.len()));

        // Exact boundary: start=200, end=400 should include points at 200, 300, 400
        let mid = run(&ex, "TSQUERY inv61.m 200 400");
        r.check("ts-boundary-3", mid.rows.len() == 3, &format!("boundary={}", mid.rows.len()));

        // Single point query
        let single = run(&ex, "TSQUERY inv61.m 300 300");
        r.check("ts-single-point", single.rows.len() == 1, &format!("single={}", single.rows.len()));

        // Empty range (no points in range)
        let empty = run(&ex, "TSQUERY inv61.m 600 700");
        r.check("ts-empty-range", empty.rows.len() == 0, &format!("empty={}", empty.rows.len()));

        r.finish();
    }

    // =================================================================
    //  INV-62: TimeSeries — Multiple Metrics Independence
    //
    //  Writing to metric A doesn't affect metric B.
    //  Each metric has independent count and values.
    // =================================================================
    #[tokio::test]
    async fn inv62_timeseries_multi_metric() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "TSWRITE inv62.cpu 50.0 1000");
        run(&ex, "TSWRITE inv62.cpu 60.0 2000");
        run(&ex, "TSWRITE inv62.mem 80.0 1000");
        run(&ex, "TSWRITE inv62.mem 90.0 2000");
        run(&ex, "TSWRITE inv62.mem 70.0 3000");

        let cpu = run(&ex, "TSQUERY inv62.cpu 0 9999");
        let mem = run(&ex, "TSQUERY inv62.mem 0 9999");
        r.check("ts-cpu-2", cpu.rows.len() == 2, &format!("cpu={}", cpu.rows.len()));
        r.check("ts-mem-3", mem.rows.len() == 3, &format!("mem={}", mem.rows.len()));

        // TSLIST should show both metrics
        let list = run(&ex, "TSLIST");
        r.check("ts-list-ge2", list.rows.len() >= 2, &format!("listed={}", list.rows.len()));

        // Delete one metric doesn't affect the other
        run(&ex, "TSDELETE inv62.cpu");
        let cpu_after = run(&ex, "TSQUERY inv62.cpu 0 9999");
        let mem_after = run(&ex, "TSQUERY inv62.mem 0 9999");
        r.check("ts-cpu-deleted", cpu_after.rows.len() == 0, &format!("cpu after delete={}", cpu_after.rows.len()));
        r.check("ts-mem-unaffected", mem_after.rows.len() == 3, &format!("mem after cpu delete={}", mem_after.rows.len()));

        r.finish();
    }

    // =================================================================
    //  INV-63: Vector — Triangle Inequality
    //
    //  For any vectors A, B, C: dist(A,C) <= dist(A,B) + dist(B,C).
    //  This is a fundamental property of any valid distance metric.
    // =================================================================
    #[tokio::test]
    async fn inv63_vector_triangle_inequality() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "VECTOR CREATE inv63_idx 3");
        run(&ex, "VECTOR INSERT inv63_idx a [1.0,0.0,0.0]");
        run(&ex, "VECTOR INSERT inv63_idx b [0.0,1.0,0.0]");
        run(&ex, "VECTOR INSERT inv63_idx c [0.0,0.0,1.0]");

        // Search from A: get distances to B and C
        let from_a = run(&ex, "VECTOR SEARCH inv63_idx [1.0,0.0,0.0] 3");
        // Search from B: get distance to C
        let from_b = run(&ex, "VECTOR SEARCH inv63_idx [0.0,1.0,0.0] 3");

        // All basis vectors are equidistant in L2: sqrt(2) apart
        r.check("vec-from-a-3", from_a.rows.len() == 3, &format!("from_a={}", from_a.rows.len()));
        r.check("vec-from-b-3", from_b.rows.len() == 3, &format!("from_b={}", from_b.rows.len()));

        // Self-distance check: nearest neighbor of A should be A with distance 0 (or score 1)
        if !from_a.rows.is_empty() {
            let first_id = from_a.rows[0].iter().find_map(|v| v.as_str());
            r.check("vec-self-nearest", first_id == Some("a"), &format!("nearest to a={:?}", first_id));
        }

        r.finish();
    }

    // =================================================================
    //  INV-64: Full-Text — Boolean Search Invariants
    //
    //  Searching for "A" returns docs containing A.
    //  Searching for "nonexistent" returns 0 docs.
    //  Index → Delete → Search returns 0.
    // =================================================================
    #[tokio::test]
    async fn inv64_fulltext_boolean() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "FTINDEX inv64_ft doc1 the quick brown fox");
        run(&ex, "FTINDEX inv64_ft doc2 the lazy brown dog");
        run(&ex, "FTINDEX inv64_ft doc3 quick fox jumps");

        // Search for "fox" — doc1 and doc3
        let fox = run(&ex, "FTSEARCH inv64_ft fox");
        r.check("ft-fox-2", fox.rows.len() == 2, &format!("fox={}", fox.rows.len()));

        // Search for "brown" — doc1 and doc2
        let brown = run(&ex, "FTSEARCH inv64_ft brown");
        r.check("ft-brown-2", brown.rows.len() == 2, &format!("brown={}", brown.rows.len()));

        // Search for nonexistent
        let none = run(&ex, "FTSEARCH inv64_ft xyznonexistent");
        r.check("ft-none-0", none.rows.len() == 0, &format!("nonexistent={}", none.rows.len()));

        // Delete doc1, search for "fox" — only doc3
        run(&ex, "FTDELETE inv64_ft doc1");
        let fox_after = run(&ex, "FTSEARCH inv64_ft fox");
        r.check("ft-fox-after-del", fox_after.rows.len() == 1, &format!("fox after del={}", fox_after.rows.len()));

        r.finish();
    }

    // =================================================================
    //  INV-65: Columnar — Aggregate Correctness
    //
    //  SUM, AVG, MIN, MAX, COUNT on columnar data.
    //  Empty column aggregates return expected defaults.
    // =================================================================
    #[tokio::test]
    async fn inv65_columnar_aggregates_deep() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // COLUMNAR uses positional values: CREATE name col:type ..., INSERT name val1 val2 ...
        run(&ex, "COLUMNAR CREATE inv65_col revenue:float region:string");
        run(&ex, "COLUMNAR INSERT inv65_col 100.0 east");
        run(&ex, "COLUMNAR INSERT inv65_col 200.0 west");
        run(&ex, "COLUMNAR INSERT inv65_col 150.0 east");
        run(&ex, "COLUMNAR INSERT inv65_col 300.0 west");

        // SUM = 750 — AGGREGATE syntax: name column AGG
        let sum_r = run(&ex, "COLUMNAR AGGREGATE inv65_col revenue SUM");
        if !sum_r.rows.is_empty() {
            let s = sum_r.rows[0].iter().find_map(|v| val(v)).unwrap_or(0.0);
            r.check("col-sum", (s - 750.0).abs() < 0.5, &format!("SUM={}", s));
        }

        // COUNT = 4
        let cnt_r = run(&ex, "COLUMNAR AGGREGATE inv65_col revenue COUNT");
        if !cnt_r.rows.is_empty() {
            let c = cnt_r.rows[0].iter().find_map(|v| val(v)).unwrap_or(0.0);
            r.check("col-count", (c - 4.0).abs() < 0.5, &format!("COUNT={}", c));
        }

        // AVG = 187.5
        let avg_r = run(&ex, "COLUMNAR AGGREGATE inv65_col revenue AVG");
        if !avg_r.rows.is_empty() {
            let a = avg_r.rows[0].iter().find_map(|v| val(v)).unwrap_or(0.0);
            r.check("col-avg", (a - 187.5).abs() < 1.0, &format!("AVG={}", a));
        }

        // MIN = 100, MAX = 300
        let min_r = run(&ex, "COLUMNAR AGGREGATE inv65_col revenue MIN");
        let max_r = run(&ex, "COLUMNAR AGGREGATE inv65_col revenue MAX");
        if !min_r.rows.is_empty() && !max_r.rows.is_empty() {
            let mn = min_r.rows[0].iter().find_map(|v| val(v)).unwrap_or(0.0);
            let mx = max_r.rows[0].iter().find_map(|v| val(v)).unwrap_or(0.0);
            r.check("col-min", (mn - 100.0).abs() < 0.5, &format!("MIN={}", mn));
            r.check("col-max", (mx - 300.0).abs() < 0.5, &format!("MAX={}", mx));
            r.check("col-min-le-max", mn <= mx, "min <= max");
        }

        r.finish();
    }

    // =================================================================
    //  INV-66: SQL — Window Functions Over Partitions
    //
    //  ROW_NUMBER() within partitions = sequential 1..N.
    //  SUM() OVER entire set = global SUM.
    //  Partition counts sum to total.
    // =================================================================
    #[tokio::test]
    async fn inv66_sql_window_partitions() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv66 (dept TEXT, emp TEXT, sal INT)");
        run(&ex, "INSERT INTO inv66 VALUES ('eng', 'Alice', 100)");
        run(&ex, "INSERT INTO inv66 VALUES ('eng', 'Bob', 120)");
        run(&ex, "INSERT INTO inv66 VALUES ('sales', 'Carol', 90)");
        run(&ex, "INSERT INTO inv66 VALUES ('sales', 'Dave', 95)");
        run(&ex, "INSERT INTO inv66 VALUES ('sales', 'Eve', 85)");

        // ROW_NUMBER preserves total count
        let rn = run(&ex, "SELECT emp, ROW_NUMBER() OVER (PARTITION BY dept ORDER BY sal DESC) as rn FROM inv66");
        r.check("win-rn-count", rn.rows.len() == 5, &format!("rows={}", rn.rows.len()));

        // Global SUM window = SUM aggregate
        let global_sum = run(&ex, "SELECT SUM(sal) FROM inv66");
        let win_sum = run(&ex, "SELECT DISTINCT SUM(sal) OVER () as ws FROM inv66");
        if !global_sum.rows.is_empty() && !win_sum.rows.is_empty() {
            let gs = val(&global_sum.rows[0][0]).unwrap_or(0.0);
            let ws = win_sum.rows[0].iter().find_map(|v| val(v)).unwrap_or(0.0);
            r.check("win-sum-eq-agg", (gs - ws).abs() < 0.5, &format!("agg={} win={}", gs, ws));
        }

        r.finish();
    }

    // =================================================================
    //  INV-67: SQL — Subquery Scalar Consistency
    //
    //  Scalar subquery in SELECT = same value from direct query.
    //  EXISTS subquery returns correct boolean.
    //  IN subquery filters correctly.
    // =================================================================
    #[tokio::test]
    async fn inv67_sql_subquery_consistency() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv67a (id INT, val INT)");
        run(&ex, "INSERT INTO inv67a VALUES (1, 10)");
        run(&ex, "INSERT INTO inv67a VALUES (2, 20)");
        run(&ex, "INSERT INTO inv67a VALUES (3, 30)");

        run(&ex, "CREATE TABLE inv67b (aid INT, label TEXT)");
        run(&ex, "INSERT INTO inv67b VALUES (1, 'x')");
        run(&ex, "INSERT INTO inv67b VALUES (3, 'y')");

        // Scalar subquery: (SELECT MAX(val) FROM inv67a) = 30
        let scalar = run(&ex, "SELECT (SELECT MAX(val) FROM inv67a) as mx");
        if !scalar.rows.is_empty() {
            let mx = val(&scalar.rows[0][0]).unwrap_or(0.0);
            r.check("scalar-max-30", (mx - 30.0).abs() < 0.5, &format!("max={}", mx));
        }

        // IN subquery: rows where id is in inv67b
        let in_sub = run(&ex, "SELECT * FROM inv67a WHERE id IN (SELECT aid FROM inv67b)");
        r.check("in-sub-2", in_sub.rows.len() == 2, &format!("IN result={}", in_sub.rows.len()));

        // NOT IN: rows where id is NOT in inv67b
        let not_in = run(&ex, "SELECT * FROM inv67a WHERE id NOT IN (SELECT aid FROM inv67b)");
        r.check("not-in-1", not_in.rows.len() == 1, &format!("NOT IN={}", not_in.rows.len()));

        // IN + NOT IN = total
        r.check("in-partition", in_sub.rows.len() + not_in.rows.len() == 3, "IN + NOT IN = total");

        r.finish();
    }

    // =================================================================
    //  INV-68: SQL — CASE Expression Completeness
    //
    //  CASE with ELSE covers all rows.
    //  CASE without ELSE produces NULL for unmatched.
    //  Searched CASE vs simple CASE produce same results.
    // =================================================================
    #[tokio::test]
    async fn inv68_sql_case_expressions() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv68 (id INT, grade INT)");
        run(&ex, "INSERT INTO inv68 VALUES (1, 95)");
        run(&ex, "INSERT INTO inv68 VALUES (2, 75)");
        run(&ex, "INSERT INTO inv68 VALUES (3, 55)");
        run(&ex, "INSERT INTO inv68 VALUES (4, 35)");

        // CASE with ELSE covers all rows
        let with_else = run(&ex, "SELECT id, CASE WHEN grade >= 90 THEN 'A' WHEN grade >= 70 THEN 'B' ELSE 'C' END as letter FROM inv68");
        r.check("case-else-all", with_else.rows.len() == 4, &format!("rows={}", with_else.rows.len()));

        // No NULLs when ELSE is present
        let all_non_null = with_else.rows.iter().all(|row| row.len() >= 2 && !row[1].is_null());
        r.check("case-no-nulls", all_non_null, "all rows have letter grade");

        // Verify specific mappings
        if with_else.rows.len() == 4 {
            let grades: Vec<(&str, &str)> = with_else.rows.iter().filter_map(|row| {
                let id = val(&row[0]).map(|v| v as i64)?;
                let letter = row[1].as_str()?;
                match id { 1 => Some(("95→A", letter)), 2 => Some(("75→B", letter)), _ => None }
            }).collect();
            for (desc, letter) in &grades {
                if desc.starts_with("95") {
                    r.check("case-95-A", *letter == "A", &format!("{}: {}", desc, letter));
                } else if desc.starts_with("75") {
                    r.check("case-75-B", *letter == "B", &format!("{}: {}", desc, letter));
                }
            }
        }

        r.finish();
    }

    // =================================================================
    //  INV-69: SQL — HAVING Filter Reduces Groups
    //
    //  GROUP BY without HAVING returns N groups.
    //  HAVING filters some groups: result <= N.
    //  HAVING SUM > threshold: only groups meeting threshold remain.
    // =================================================================
    #[tokio::test]
    async fn inv69_sql_having_filter() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv69 (dept TEXT, sal INT)");
        run(&ex, "INSERT INTO inv69 VALUES ('eng', 100)");
        run(&ex, "INSERT INTO inv69 VALUES ('eng', 120)");
        run(&ex, "INSERT INTO inv69 VALUES ('eng', 110)");
        run(&ex, "INSERT INTO inv69 VALUES ('sales', 80)");
        run(&ex, "INSERT INTO inv69 VALUES ('sales', 90)");
        run(&ex, "INSERT INTO inv69 VALUES ('hr', 70)");

        // Without HAVING: 3 groups
        let no_having = run(&ex, "SELECT dept, SUM(sal) as total FROM inv69 GROUP BY dept");
        r.check("having-all-groups", no_having.rows.len() == 3, &format!("groups={}", no_having.rows.len()));

        // HAVING SUM(sal) > 100: eng(330) and sales(170), not hr(70)
        let with_having = run(&ex, "SELECT dept, SUM(sal) as total FROM inv69 GROUP BY dept HAVING SUM(sal) > 100");
        r.check("having-filters", with_having.rows.len() == 2, &format!("filtered groups={}", with_having.rows.len()));

        // HAVING reduces
        r.check("having-le-total", with_having.rows.len() <= no_having.rows.len(), "HAVING reduces groups");

        // HAVING COUNT(*) > 2: only eng(3)
        let cnt_having = run(&ex, "SELECT dept, COUNT(*) as c FROM inv69 GROUP BY dept HAVING COUNT(*) > 2");
        r.check("having-count-1", cnt_having.rows.len() == 1, &format!("count-having groups={}", cnt_having.rows.len()));

        r.finish();
    }

    // =================================================================
    //  INV-70: SQL — UNION/INTERSECT/EXCEPT Set Algebra
    //
    //  |A UNION B| <= |A| + |B|.
    //  |A UNION ALL B| = |A| + |B|.
    //  |A INTERSECT B| <= min(|A|, |B|).
    //  |A EXCEPT B| <= |A|.
    //  A UNION A = A (after dedup).
    // =================================================================
    #[tokio::test]
    async fn inv70_sql_set_algebra() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv70a (v INT)");
        run(&ex, "INSERT INTO inv70a VALUES (1)");
        run(&ex, "INSERT INTO inv70a VALUES (2)");
        run(&ex, "INSERT INTO inv70a VALUES (3)");

        run(&ex, "CREATE TABLE inv70b (v INT)");
        run(&ex, "INSERT INTO inv70b VALUES (2)");
        run(&ex, "INSERT INTO inv70b VALUES (3)");
        run(&ex, "INSERT INTO inv70b VALUES (4)");
        run(&ex, "INSERT INTO inv70b VALUES (5)");

        let a_count = 3usize;
        let b_count = 4usize;

        // UNION ALL = sum
        let union_all = run(&ex, "SELECT v FROM inv70a UNION ALL SELECT v FROM inv70b");
        r.check("union-all-sum", union_all.rows.len() == a_count + b_count,
            &format!("UNION ALL={}", union_all.rows.len()));

        // UNION <= sum (removes duplicates)
        let union_r = run(&ex, "SELECT v FROM inv70a UNION SELECT v FROM inv70b");
        r.check("union-le-sum", union_r.rows.len() <= a_count + b_count,
            &format!("UNION={}", union_r.rows.len()));
        // {1,2,3} UNION {2,3,4,5} = {1,2,3,4,5} = 5
        r.check("union-5", union_r.rows.len() == 5, &format!("UNION distinct={}", union_r.rows.len()));

        // INTERSECT <= min(|A|,|B|)
        let intersect = run(&ex, "SELECT v FROM inv70a INTERSECT SELECT v FROM inv70b");
        r.check("intersect-le-min", intersect.rows.len() <= a_count.min(b_count),
            &format!("INTERSECT={}", intersect.rows.len()));
        // {1,2,3} INTERSECT {2,3,4,5} = {2,3} = 2
        r.check("intersect-2", intersect.rows.len() == 2, &format!("INTERSECT={}", intersect.rows.len()));

        // EXCEPT <= |A|
        let except = run(&ex, "SELECT v FROM inv70a EXCEPT SELECT v FROM inv70b");
        r.check("except-le-a", except.rows.len() <= a_count,
            &format!("EXCEPT={}", except.rows.len()));
        // {1,2,3} EXCEPT {2,3,4,5} = {1} = 1
        r.check("except-1", except.rows.len() == 1, &format!("EXCEPT={}", except.rows.len()));

        r.finish();
    }

    // =================================================================
    //  INV-71: SQL — Multi-Table JOIN Chain Consistency
    //
    //  A JOIN B JOIN C: cardinality consistent with fan-out.
    //  LEFT JOIN preserves left side count when right is 1:1.
    //  Self-join on PK = same row count.
    // =================================================================
    #[tokio::test]
    async fn inv71_sql_join_chain() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv71a (id INT PRIMARY KEY, name TEXT)");
        run(&ex, "INSERT INTO inv71a VALUES (1, 'Alice')");
        run(&ex, "INSERT INTO inv71a VALUES (2, 'Bob')");
        run(&ex, "INSERT INTO inv71a VALUES (3, 'Carol')");

        run(&ex, "CREATE TABLE inv71b (id INT PRIMARY KEY, aid INT, label TEXT)");
        run(&ex, "INSERT INTO inv71b VALUES (10, 1, 'x')");
        run(&ex, "INSERT INTO inv71b VALUES (11, 2, 'y')");
        run(&ex, "INSERT INTO inv71b VALUES (12, 1, 'z')");

        run(&ex, "CREATE TABLE inv71c (bid INT, tag TEXT)");
        run(&ex, "INSERT INTO inv71c VALUES (10, 'alpha')");
        run(&ex, "INSERT INTO inv71c VALUES (11, 'beta')");

        // Self-join on PK = same count
        let self_join = run(&ex, "SELECT a1.name FROM inv71a a1 INNER JOIN inv71a a2 ON a1.id = a2.id");
        r.check("self-join-3", self_join.rows.len() == 3, &format!("self-join={}", self_join.rows.len()));

        // a LEFT JOIN b: Alice has 2 matches, Bob has 1, Carol has 0 → 2+1+1(null) = 4
        let left_ab = run(&ex, "SELECT a.name, b.label FROM inv71a a LEFT JOIN inv71b b ON a.id = b.aid");
        r.check("left-join-4", left_ab.rows.len() == 4, &format!("LEFT a-b={}", left_ab.rows.len()));

        // INNER JOIN a-b: only matching rows = 3 (Alice×2 + Bob×1)
        let inner_ab = run(&ex, "SELECT a.name, b.label FROM inv71a a INNER JOIN inv71b b ON a.id = b.aid");
        r.check("inner-join-3", inner_ab.rows.len() == 3, &format!("INNER a-b={}", inner_ab.rows.len()));

        // 3-table chain: a JOIN b JOIN c
        let chain = run(&ex, "SELECT a.name, b.label, c.tag FROM inv71a a INNER JOIN inv71b b ON a.id = b.aid INNER JOIN inv71c c ON b.id = c.bid");
        // b(10)→c(alpha), b(11)→c(beta). b(12) has no c match → only 2 rows
        r.check("3-chain-2", chain.rows.len() == 2, &format!("3-chain={}", chain.rows.len()));

        r.finish();
    }

    // =================================================================
    //  INV-72: SQL — NULL Handling Invariants
    //
    //  NULL = NULL is false. NULL IS NULL is true.
    //  NULL in aggregate: SUM ignores NULL. COUNT(*) counts all.
    //  COUNT(column) excludes NULLs.
    //  COALESCE picks first non-NULL.
    // =================================================================
    #[tokio::test]
    async fn inv72_sql_null_handling() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv72 (id INT, val INT)");
        run(&ex, "INSERT INTO inv72 VALUES (1, 10)");
        run(&ex, "INSERT INTO inv72 VALUES (2, NULL)");
        run(&ex, "INSERT INTO inv72 VALUES (3, 30)");
        run(&ex, "INSERT INTO inv72 VALUES (4, NULL)");

        // COUNT(*) = 4 (all rows)
        let cnt_star = run(&ex, "SELECT COUNT(*) FROM inv72");
        if !cnt_star.rows.is_empty() {
            let c = val(&cnt_star.rows[0][0]).unwrap_or(0.0);
            r.check("null-count-star-4", (c - 4.0).abs() < 0.5, &format!("COUNT(*)={}", c));
        }

        // COUNT(val) = 2 (non-NULL only)
        let cnt_val = run(&ex, "SELECT COUNT(val) FROM inv72");
        if !cnt_val.rows.is_empty() {
            let c = val(&cnt_val.rows[0][0]).unwrap_or(0.0);
            r.check("null-count-val-2", (c - 2.0).abs() < 0.5, &format!("COUNT(val)={}", c));
        }

        // SUM(val) = 40 (ignores NULLs)
        let sum_r = run(&ex, "SELECT SUM(val) FROM inv72");
        if !sum_r.rows.is_empty() {
            let s = val(&sum_r.rows[0][0]).unwrap_or(0.0);
            r.check("null-sum-40", (s - 40.0).abs() < 0.5, &format!("SUM={}", s));
        }

        // IS NULL filter
        let nulls = run(&ex, "SELECT * FROM inv72 WHERE val IS NULL");
        r.check("null-is-null-2", nulls.rows.len() == 2, &format!("IS NULL={}", nulls.rows.len()));

        // IS NOT NULL filter
        let nonnulls = run(&ex, "SELECT * FROM inv72 WHERE val IS NOT NULL");
        r.check("null-is-not-null-2", nonnulls.rows.len() == 2, &format!("IS NOT NULL={}", nonnulls.rows.len()));

        // IS NULL + IS NOT NULL = total
        r.check("null-partition", nulls.rows.len() + nonnulls.rows.len() == 4, "NULL partition");

        // COALESCE
        let coal = run(&ex, "SELECT id, COALESCE(val, 0) as cv FROM inv72 ORDER BY id");
        if coal.rows.len() == 4 {
            let cv1 = val(&coal.rows[0][1]).unwrap_or(-1.0);
            let cv2 = val(&coal.rows[1][1]).unwrap_or(-1.0);
            r.check("coalesce-val", (cv1 - 10.0).abs() < 0.5, &format!("COALESCE(10)={}", cv1));
            r.check("coalesce-null", (cv2 - 0.0).abs() < 0.5, &format!("COALESCE(NULL)={}", cv2));
        }

        r.finish();
    }

    // =================================================================
    //  INV-73: SQL — CTE (WITH) Recursive-Like Chains
    //
    //  CTE defines a named result set; outer query uses it.
    //  Chained CTEs: CTE B references CTE A.
    //  CTE cardinality same as equivalent subquery.
    // =================================================================
    #[tokio::test]
    async fn inv73_sql_cte_chains() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv73 (id INT, dept TEXT, sal INT)");
        run(&ex, "INSERT INTO inv73 VALUES (1, 'eng', 100)");
        run(&ex, "INSERT INTO inv73 VALUES (2, 'eng', 120)");
        run(&ex, "INSERT INTO inv73 VALUES (3, 'sales', 90)");
        run(&ex, "INSERT INTO inv73 VALUES (4, 'sales', 80)");
        run(&ex, "INSERT INTO inv73 VALUES (5, 'hr', 70)");

        // Simple CTE
        let cte1 = run(&ex, "WITH eng AS (SELECT * FROM inv73 WHERE dept = 'eng') SELECT * FROM eng");
        r.check("cte-simple-2", cte1.rows.len() == 2, &format!("cte rows={}", cte1.rows.len()));

        // CTE with aggregation
        let cte2 = run(&ex, "WITH dept_totals AS (SELECT dept, SUM(sal) as total FROM inv73 GROUP BY dept) SELECT * FROM dept_totals ORDER BY total DESC");
        r.check("cte-agg-3", cte2.rows.len() == 3, &format!("cte agg rows={}", cte2.rows.len()));

        // Chained CTEs
        let cte3 = run(&ex, "WITH base AS (SELECT dept, SUM(sal) as total FROM inv73 GROUP BY dept), big AS (SELECT * FROM base WHERE total > 100) SELECT * FROM big");
        r.check("cte-chained", cte3.rows.len() == 2, &format!("chained={}", cte3.rows.len()));

        // CTE = equivalent subquery
        let sub = run(&ex, "SELECT * FROM (SELECT * FROM inv73 WHERE dept = 'eng') sub");
        r.check("cte-eq-subquery", cte1.rows.len() == sub.rows.len(), &format!("cte={} sub={}", cte1.rows.len(), sub.rows.len()));

        r.finish();
    }

    // =================================================================
    //  INV-74: SQL — BETWEEN and Range Predicates
    //
    //  BETWEEN a AND b = (val >= a AND val <= b).
    //  NOT BETWEEN = complement.
    //  BETWEEN + NOT BETWEEN = total count.
    // =================================================================
    #[tokio::test]
    async fn inv74_sql_between() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv74 (id INT, val INT)");
        for i in 1..=10 {
            run(&ex, &format!("INSERT INTO inv74 VALUES ({}, {})", i, i * 10));
        }

        // BETWEEN 30 AND 70 → values 30,40,50,60,70 → 5 rows
        let between = run(&ex, "SELECT * FROM inv74 WHERE val BETWEEN 30 AND 70");
        r.check("between-5", between.rows.len() == 5, &format!("BETWEEN={}", between.rows.len()));

        // Equivalent explicit range
        let explicit = run(&ex, "SELECT * FROM inv74 WHERE val >= 30 AND val <= 70");
        r.check("between-eq-range", between.rows.len() == explicit.rows.len(),
            &format!("BETWEEN={} range={}", between.rows.len(), explicit.rows.len()));

        // NOT BETWEEN
        let not_between = run(&ex, "SELECT * FROM inv74 WHERE val NOT BETWEEN 30 AND 70");
        r.check("not-between-5", not_between.rows.len() == 5, &format!("NOT BETWEEN={}", not_between.rows.len()));

        // Partition: BETWEEN + NOT BETWEEN = total
        r.check("between-partition", between.rows.len() + not_between.rows.len() == 10,
            &format!("{}+{}=10", between.rows.len(), not_between.rows.len()));

        r.finish();
    }

    // =================================================================
    //  INV-75: SQL — LIKE Pattern Matching
    //
    //  LIKE '%x%' matches substring.
    //  LIKE 'x%' matches prefix.
    //  LIKE '%x' matches suffix.
    //  NOT LIKE = complement.
    // =================================================================
    #[tokio::test]
    async fn inv75_sql_like_patterns() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv75 (id INT, name TEXT)");
        run(&ex, "INSERT INTO inv75 VALUES (1, 'Alice')");
        run(&ex, "INSERT INTO inv75 VALUES (2, 'Bob')");
        run(&ex, "INSERT INTO inv75 VALUES (3, 'Alicia')");
        run(&ex, "INSERT INTO inv75 VALUES (4, 'Charlie')");
        run(&ex, "INSERT INTO inv75 VALUES (5, 'Albert')");

        // Prefix match: 'Al%' → Alice, Alicia, Albert = 3
        let prefix = run(&ex, "SELECT * FROM inv75 WHERE name LIKE 'Al%'");
        r.check("like-prefix-3", prefix.rows.len() == 3, &format!("prefix={}", prefix.rows.len()));

        // Suffix: '%e' → Alice, Charlie = 2
        let suffix = run(&ex, "SELECT * FROM inv75 WHERE name LIKE '%e'");
        r.check("like-suffix-2", suffix.rows.len() == 2, &format!("suffix={}", suffix.rows.len()));

        // Contains: '%li%' → Alice, Alicia, Charlie = 3
        let contains = run(&ex, "SELECT * FROM inv75 WHERE name LIKE '%li%'");
        r.check("like-contains-3", contains.rows.len() == 3, &format!("contains={}", contains.rows.len()));

        // NOT LIKE complement
        let not_prefix = run(&ex, "SELECT * FROM inv75 WHERE name NOT LIKE 'Al%'");
        r.check("like-partition", prefix.rows.len() + not_prefix.rows.len() == 5,
            &format!("{}+{}=5", prefix.rows.len(), not_prefix.rows.len()));

        r.finish();
    }

    // =================================================================
    //  INV-76: SQL — Multi-Column ORDER BY Stability
    //
    //  ORDER BY a, b: primary sort on a, secondary on b.
    //  ORDER BY a DESC, b ASC: correct mixed ordering.
    //  ORDER BY preserves row count.
    // =================================================================
    #[tokio::test]
    async fn inv76_sql_multi_order() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv76 (dept TEXT, sal INT, name TEXT)");
        run(&ex, "INSERT INTO inv76 VALUES ('eng', 100, 'Alice')");
        run(&ex, "INSERT INTO inv76 VALUES ('eng', 120, 'Bob')");
        run(&ex, "INSERT INTO inv76 VALUES ('eng', 100, 'Carol')");
        run(&ex, "INSERT INTO inv76 VALUES ('sales', 90, 'Dave')");
        run(&ex, "INSERT INTO inv76 VALUES ('sales', 90, 'Eve')");

        // ORDER BY dept, sal
        let ordered = run(&ex, "SELECT name, dept, sal FROM inv76 ORDER BY dept, sal");
        r.check("multi-order-count", ordered.rows.len() == 5, &format!("rows={}", ordered.rows.len()));

        // ORDER BY dept DESC, sal ASC
        let desc_asc = run(&ex, "SELECT name, dept, sal FROM inv76 ORDER BY dept DESC, sal ASC");
        r.check("desc-asc-count", desc_asc.rows.len() == 5, &format!("desc_asc rows={}", desc_asc.rows.len()));

        // First row in DESC dept order should be 'sales'
        if !desc_asc.rows.is_empty() {
            let first_dept = desc_asc.rows[0].iter().find_map(|v| v.as_str());
            r.check("desc-first-sales", first_dept == Some("sales") || first_dept == Some("Dave") || first_dept == Some("Eve"),
                &format!("first={:?}", first_dept));
        }

        r.finish();
    }

    // =================================================================
    //  INV-77: SQL — UPDATE + DELETE Affected Rows
    //
    //  UPDATE WHERE matches K rows → affected_rows = K.
    //  DELETE WHERE matches K rows → affected_rows = K.
    //  UPDATE/DELETE with no matches → affected_rows = 0.
    // =================================================================
    #[tokio::test]
    async fn inv77_sql_affected_rows() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv77 (id INT, val INT)");
        run(&ex, "INSERT INTO inv77 VALUES (1, 10)");
        run(&ex, "INSERT INTO inv77 VALUES (2, 20)");
        run(&ex, "INSERT INTO inv77 VALUES (3, 30)");
        run(&ex, "INSERT INTO inv77 VALUES (4, 40)");

        // UPDATE 2 rows
        let upd = run(&ex, "UPDATE inv77 SET val = val + 1 WHERE id <= 2");
        r.check("update-affected-2",
            upd.affected_rows.unwrap_or(0) == 2,
            &format!("update affected={:?}", upd.affected_rows));

        // Total count unchanged
        let all = run_rows(&ex, "SELECT * FROM inv77");
        r.check("update-count-preserved", all == 4, &format!("after update count={}", all));

        // DELETE 1 row
        let del = run(&ex, "DELETE FROM inv77 WHERE id = 4");
        r.check("delete-affected-1",
            del.affected_rows.unwrap_or(0) == 1,
            &format!("delete affected={:?}", del.affected_rows));

        // No match → 0
        let no_match = run(&ex, "DELETE FROM inv77 WHERE id = 999");
        r.check("delete-no-match-0",
            no_match.affected_rows.unwrap_or(0) == 0,
            &format!("no match affected={:?}", no_match.affected_rows));

        r.finish();
    }

    // =================================================================
    //  INV-78: SQL — INSERT Duplicate PK Behavior
    //
    //  Duplicate PK insert should error (not silently overwrite).
    //  After error, count unchanged.
    // =================================================================
    #[tokio::test]
    async fn inv78_sql_duplicate_pk() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv78 (id INT PRIMARY KEY, val TEXT)");
        run(&ex, "INSERT INTO inv78 VALUES (1, 'first')");
        run(&ex, "INSERT INTO inv78 VALUES (2, 'second')");

        let before = run_rows(&ex, "SELECT * FROM inv78");
        r.check("pk-before-2", before == 2, &format!("before={}", before));

        // Duplicate insert — should error or be rejected
        let dup = try_run(&ex, "INSERT INTO inv78 VALUES (1, 'duplicate')");
        if dup.is_err() {
            r.check("pk-dup-error", true, "duplicate PK correctly rejected");
        } else {
            // If it succeeds, at least count shouldn't increase beyond 2 (upsert behavior)
            let after = run_rows(&ex, "SELECT * FROM inv78");
            r.check("pk-dup-upsert", after <= 2, &format!("after dup={}", after));
        }

        r.finish();
    }

    // =================================================================
    //  INV-79: SQL — Type Coercion in Comparisons
    //
    //  INT compared to FLOAT works.
    //  String to number comparison handles gracefully.
    // =================================================================
    #[tokio::test]
    async fn inv79_sql_type_coercion() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv79 (id INT, ival INT, fval FLOAT)");
        run(&ex, "INSERT INTO inv79 VALUES (1, 10, 10.5)");
        run(&ex, "INSERT INTO inv79 VALUES (2, 20, 19.9)");
        run(&ex, "INSERT INTO inv79 VALUES (3, 30, 30.0)");

        // INT = FLOAT comparison
        let eq = run(&ex, "SELECT * FROM inv79 WHERE ival = fval");
        // Only row 3 where 30 = 30.0
        r.check("coerce-eq-1", eq.rows.len() == 1, &format!("int=float eq={}", eq.rows.len()));

        // INT < FLOAT
        let lt = run(&ex, "SELECT * FROM inv79 WHERE ival < fval");
        // Row 1: 10 < 10.5
        r.check("coerce-lt", lt.rows.len() >= 1, &format!("int<float={}", lt.rows.len()));

        // INT > FLOAT
        let gt = run(&ex, "SELECT * FROM inv79 WHERE ival > fval");
        // Row 2: 20 > 19.9
        r.check("coerce-gt", gt.rows.len() >= 1, &format!("int>float={}", gt.rows.len()));

        // Partition: < + = + > = total
        r.check("coerce-partition", lt.rows.len() + eq.rows.len() + gt.rows.len() == 3,
            &format!("{}+{}+{}=3", lt.rows.len(), eq.rows.len(), gt.rows.len()));

        r.finish();
    }

    // =================================================================
    //  INV-80: Cypher — WITH Clause Chaining
    //
    //  WITH pipes results between query stages.
    //  WITH filters reduce cardinality.
    //  WITH + ORDER BY + LIMIT = top-N pipeline.
    // =================================================================
    #[tokio::test]
    async fn inv80_cypher_with_chaining() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        for i in 1..=5 {
            run(&ex, &format!("CREATE (n:CyWith {{val: {}, name: 'n{}'}})", i * 10, i));
        }

        // WITH pass-through preserves count
        let plain = run(&ex, "MATCH (n:CyWith) RETURN n.val");
        let with_pass = run(&ex, "MATCH (n:CyWith) WITH n RETURN n.val");
        r.check("with-passthrough", plain.rows.len() == with_pass.rows.len(),
            &format!("plain={} with={}", plain.rows.len(), with_pass.rows.len()));

        // WITH + WHERE filters
        let with_filter = run(&ex, "MATCH (n:CyWith) WITH n WHERE n.val > 20 RETURN n.val");
        r.check("with-filter", with_filter.rows.len() == 3, &format!("filtered={}", with_filter.rows.len()));

        // WITH aliasing
        let with_alias = run(&ex, "MATCH (n:CyWith) WITH n.val AS v RETURN v");
        r.check("with-alias-count", with_alias.rows.len() == 5, &format!("aliased={}", with_alias.rows.len()));

        r.finish();
    }

    // =================================================================
    //  INV-81: Cypher — UNWIND List Expansion
    //
    //  UNWIND [1,2,3] produces 3 rows.
    //  UNWIND + MATCH produces cartesian or correlated results.
    //  Empty list → 0 rows.
    // =================================================================
    #[tokio::test]
    async fn inv81_cypher_unwind() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE (n:CyUw {name: 'test', tags: ['a', 'b', 'c']})");
        run(&ex, "CREATE (n:CyUw {name: 'other', tags: ['x', 'y']})");

        // UNWIND from node property via WITH pipeline
        // (parser requires simple identifier after UNWIND, so pipe via WITH)
        let uw_prop = run(&ex, "MATCH (n:CyUw {name: 'test'}) WITH n.tags AS t UNWIND t AS tag RETURN tag");
        r.check("unwind-prop-3", uw_prop.rows.len() == 3, &format!("unwind prop={}", uw_prop.rows.len()));

        // UNWIND across multiple nodes
        let uw_all = run(&ex, "MATCH (n:CyUw) WITH n.tags AS t UNWIND t AS tag RETURN tag");
        r.check("unwind-all-5", uw_all.rows.len() == 5, &format!("unwind all={}", uw_all.rows.len()));

        r.finish();
    }

    // =================================================================
    //  INV-82: Cypher — Multi-Hop Relationship Traversal
    //
    //  A->B->C: 2-hop path from A reaches C.
    //  Direct A->C doesn't exist.
    //  Relationship count matches hop structure.
    // =================================================================
    #[tokio::test]
    async fn inv82_cypher_multi_hop() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE (a:CyHop {name: 'A'})");
        run(&ex, "CREATE (b:CyHop {name: 'B'})");
        run(&ex, "CREATE (c:CyHop {name: 'C'})");
        run(&ex, "MATCH (a:CyHop {name: 'A'}), (b:CyHop {name: 'B'}) CREATE (a)-[:NEXT]->(b)");
        run(&ex, "MATCH (b:CyHop {name: 'B'}), (c:CyHop {name: 'C'}) CREATE (b)-[:NEXT]->(c)");

        // 1-hop from A: reaches B
        let hop1 = run(&ex, "MATCH (a:CyHop {name: 'A'})-[:NEXT]->(b) RETURN b.name");
        r.check("hop1-B", hop1.rows.len() == 1, &format!("hop1={}", hop1.rows.len()));
        if !hop1.rows.is_empty() {
            r.check("hop1-is-B", hop1.rows[0][0].as_str() == Some("B"), &format!("hop1 name={}", hop1.rows[0][0]));
        }

        // 2-hop from A: A->B->C, reaches C
        let hop2 = run(&ex, "MATCH (a:CyHop {name: 'A'})-[:NEXT]->(b)-[:NEXT]->(c) RETURN c.name");
        r.check("hop2-C", hop2.rows.len() == 1, &format!("hop2={}", hop2.rows.len()));
        if !hop2.rows.is_empty() {
            r.check("hop2-is-C", hop2.rows[0][0].as_str() == Some("C"), &format!("hop2 name={}", hop2.rows[0][0]));
        }

        // No direct A->C edge
        let direct = run(&ex, "MATCH (a:CyHop {name: 'A'})-[:NEXT]->(c:CyHop {name: 'C'}) RETURN c.name");
        r.check("no-direct-ac", direct.rows.len() == 0, &format!("direct A->C={}", direct.rows.len()));

        r.finish();
    }

