    // =================================================================
    #[tokio::test]
    async fn inv84_cql_limit() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE KEYSPACE inv84_ks WITH replication = {'class': 'SimpleStrategy', 'replication_factor': '1'}");
        run(&ex, "CREATE TABLE inv84_ks.data (id INT PRIMARY KEY, val INT)");
        for i in 1..=5 {
            run(&ex, &format!("INSERT INTO inv84_ks.data (id, val) VALUES ({}, {})", i, i * 10));
        }

        let all = run(&ex, "SELECT * FROM inv84_ks.data");
        r.check("cql-all-5", all.rows.len() == 5, &format!("all={}", all.rows.len()));

        let lim2 = run(&ex, "SELECT * FROM inv84_ks.data LIMIT 2");
        r.check("cql-lim-2", lim2.rows.len() == 2, &format!("limit 2={}", lim2.rows.len()));

        let lim10 = run(&ex, "SELECT * FROM inv84_ks.data LIMIT 10");
        r.check("cql-lim-10", lim10.rows.len() == 5, &format!("limit 10={}", lim10.rows.len()));

        // LIMIT subset
        r.check("cql-lim-subset", lim2.rows.len() <= all.rows.len(), "limit <= all");

        r.finish();
    }

