    // =================================================================
    //  INV-86: Vector — Duplicate ID Overwrites
    //
    //  Inserting same ID twice: latest value wins.
    //  Search still returns correct count.
    // =================================================================
    #[tokio::test]
    async fn inv86_vector_delete_reinsert() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "VECTOR CREATE inv86_idx 2");
        run(&ex, "VECTOR INSERT inv86_idx v1 [1.0,0.0]");
        run(&ex, "VECTOR INSERT inv86_idx v2 [0.0,1.0]");

        let before = run(&ex, "VECTOR SEARCH inv86_idx [1.0,0.0] 10");
        r.check("vec-before-2", before.rows.len() == 2, &format!("before={}", before.rows.len()));

        // Duplicate ID is rejected
        let dup = try_run(&ex, "VECTOR INSERT inv86_idx v1 [0.5,0.5]");
        r.check("vec-dup-rejected", dup.is_err(), "duplicate ID correctly rejected");

        // Delete then re-insert
        run(&ex, "VECTOR DELETE inv86_idx v1");
        let mid = run(&ex, "VECTOR SEARCH inv86_idx [1.0,0.0] 10");
        r.check("vec-after-del-1", mid.rows.len() == 1, &format!("after delete={}", mid.rows.len()));

        run(&ex, "VECTOR INSERT inv86_idx v3 [0.5,0.5]");
        let after = run(&ex, "VECTOR SEARCH inv86_idx [1.0,0.0] 10");
        r.check("vec-after-reinsert-2", after.rows.len() == 2, &format!("after reinsert={}", after.rows.len()));

        r.finish();
    }

    // =================================================================
    //  INV-87: Full-Text — Multi-Word Search
    //
    //  Each indexed word is independently searchable.
    //  Document with N matching terms ranks higher.
    //  Deleting one doc doesn't affect others.
    // =================================================================
    #[tokio::test]
    async fn inv87_fulltext_multiword() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "FTINDEX inv87_ft d1 machine learning algorithms");
        run(&ex, "FTINDEX inv87_ft d2 deep learning neural networks");
        run(&ex, "FTINDEX inv87_ft d3 algorithms and data structures");
        run(&ex, "FTINDEX inv87_ft d4 cooking recipes");

        // "learning" matches d1, d2
        let learning = run(&ex, "FTSEARCH inv87_ft learning");
        r.check("ft-learning-2", learning.rows.len() == 2, &format!("learning={}", learning.rows.len()));

        // "algorithms" matches d1, d3
        let alg = run(&ex, "FTSEARCH inv87_ft algorithms");
        r.check("ft-algorithms-2", alg.rows.len() == 2, &format!("algorithms={}", alg.rows.len()));

        // "cooking" matches only d4
        let cook = run(&ex, "FTSEARCH inv87_ft cooking");
        r.check("ft-cooking-1", cook.rows.len() == 1, &format!("cooking={}", cook.rows.len()));

        // Delete d1, re-search "learning" → only d2
        run(&ex, "FTDELETE inv87_ft d1");
        let after = run(&ex, "FTSEARCH inv87_ft learning");
        r.check("ft-after-del-1", after.rows.len() == 1, &format!("learning after del={}", after.rows.len()));

        // "algorithms" now only d3 (d1 deleted)
        let alg_after = run(&ex, "FTSEARCH inv87_ft algorithms");
        r.check("ft-alg-after-del-1", alg_after.rows.len() == 1, &format!("alg after del={}", alg_after.rows.len()));

        r.finish();
    }

    // =================================================================
    //  INV-88: TimeSeries — Aggregate Consistency
    //
    //  SUM = COUNT * AVG (within tolerance).
    //  MIN <= each point <= MAX.
    //  COUNT matches query range cardinality.
    // =================================================================
    #[tokio::test]
    async fn inv88_timeseries_aggregate_consistency() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        let values = [12.0, 8.0, 15.0, 3.0, 22.0, 10.0];
        for (i, v) in values.iter().enumerate() {
            run(&ex, &format!("TSWRITE inv88.m {} {}", v, (i + 1) * 1000));
        }

        let all = run(&ex, "TSQUERY inv88.m 0 99999");
        r.check("ts-all-6", all.rows.len() == 6, &format!("points={}", all.rows.len()));

        // Get SUM, COUNT, AVG, MIN, MAX
        let sum_r = run(&ex, "TSAGGREGATE inv88.m 0 99999 100000 SUM");
        let cnt_r = run(&ex, "TSAGGREGATE inv88.m 0 99999 100000 COUNT");
        let avg_r = run(&ex, "TSAGGREGATE inv88.m 0 99999 100000 AVG");
        let min_r = run(&ex, "TSAGGREGATE inv88.m 0 99999 100000 MIN");
        let max_r = run(&ex, "TSAGGREGATE inv88.m 0 99999 100000 MAX");

        let sum_v = sum_r.rows.first().and_then(|r| r.get(1)).and_then(|v| val(v)).unwrap_or(0.0);
        let cnt_v = cnt_r.rows.first().and_then(|r| r.get(1)).and_then(|v| val(v)).unwrap_or(0.0);
        let avg_v = avg_r.rows.first().and_then(|r| r.get(1)).and_then(|v| val(v)).unwrap_or(0.0);
        let min_v = min_r.rows.first().and_then(|r| r.get(1)).and_then(|v| val(v)).unwrap_or(0.0);
        let max_v = max_r.rows.first().and_then(|r| r.get(1)).and_then(|v| val(v)).unwrap_or(0.0);

        // SUM = 12+8+15+3+22+10 = 70
        r.check("ts-sum-70", (sum_v - 70.0).abs() < 0.5, &format!("SUM={}", sum_v));
        r.check("ts-count-6", (cnt_v - 6.0).abs() < 0.5, &format!("COUNT={}", cnt_v));

        // SUM ≈ COUNT * AVG
        if cnt_v > 0.0 {
            r.check("ts-sum-eq-cnt-avg", (sum_v - cnt_v * avg_v).abs() < 1.0,
                &format!("SUM={} COUNT*AVG={}", sum_v, cnt_v * avg_v));
        }

        // MIN <= AVG <= MAX
        r.check("ts-min-le-avg", min_v <= avg_v + 0.01, &format!("{} <= {}", min_v, avg_v));
        r.check("ts-avg-le-max", avg_v <= max_v + 0.01, &format!("{} <= {}", avg_v, max_v));

        // MIN = 3, MAX = 22
        r.check("ts-min-3", (min_v - 3.0).abs() < 0.5, &format!("MIN={}", min_v));
        r.check("ts-max-22", (max_v - 22.0).abs() < 0.5, &format!("MAX={}", max_v));

        r.finish();
    }

    // =================================================================
    //  INV-89: SQL — Nested Aggregates in HAVING
    //
    //  HAVING with multiple conditions.
    //  HAVING AVG + HAVING COUNT combined.
    //  All passing groups satisfy all conditions.
    // =================================================================
    #[tokio::test]
    async fn inv89_sql_nested_having() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv89 (dept TEXT, sal INT)");
        run(&ex, "INSERT INTO inv89 VALUES ('eng', 150)");
        run(&ex, "INSERT INTO inv89 VALUES ('eng', 120)");
        run(&ex, "INSERT INTO inv89 VALUES ('eng', 130)");
        run(&ex, "INSERT INTO inv89 VALUES ('sales', 80)");
        run(&ex, "INSERT INTO inv89 VALUES ('sales', 90)");
        run(&ex, "INSERT INTO inv89 VALUES ('hr', 60)");
        run(&ex, "INSERT INTO inv89 VALUES ('hr', 70)");
        run(&ex, "INSERT INTO inv89 VALUES ('hr', 65)");

        // HAVING AVG > 100: only eng (avg=133)
        let avg_having = run(&ex, "SELECT dept, AVG(sal) as a FROM inv89 GROUP BY dept HAVING AVG(sal) > 100");
        r.check("having-avg-1", avg_having.rows.len() == 1, &format!("avg having={}", avg_having.rows.len()));

        // HAVING COUNT(*) >= 3: eng(3), hr(3) — 2 groups
        let cnt_having = run(&ex, "SELECT dept, COUNT(*) as c FROM inv89 GROUP BY dept HAVING COUNT(*) >= 3");
        r.check("having-cnt-2", cnt_having.rows.len() == 2, &format!("cnt having={}", cnt_having.rows.len()));

        // HAVING AVG > 100 AND COUNT(*) >= 3: only eng
        let combo = run(&ex, "SELECT dept FROM inv89 GROUP BY dept HAVING AVG(sal) > 100 AND COUNT(*) >= 3");
        r.check("having-combo-1", combo.rows.len() == 1, &format!("combo={}", combo.rows.len()));

        // Combo is intersection of both conditions
        r.check("having-combo-le-both",
            combo.rows.len() <= avg_having.rows.len() && combo.rows.len() <= cnt_having.rows.len(),
            "combo <= each condition");

        r.finish();
    }

    // =================================================================
    //  INV-90: SQL — LEFT JOIN NULL Propagation
    //
    //  LEFT JOIN: unmatched right side → NULLs.
    //  All left rows preserved.
    //  NULL columns from right side aggregate correctly.
    // =================================================================
    #[tokio::test]
    async fn inv90_sql_left_join_nulls() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv90a (id INT PRIMARY KEY, name TEXT)");
        run(&ex, "INSERT INTO inv90a VALUES (1, 'Alice')");
        run(&ex, "INSERT INTO inv90a VALUES (2, 'Bob')");
        run(&ex, "INSERT INTO inv90a VALUES (3, 'Carol')");

        run(&ex, "CREATE TABLE inv90b (aid INT, score INT)");
        run(&ex, "INSERT INTO inv90b VALUES (1, 95)");
        run(&ex, "INSERT INTO inv90b VALUES (1, 87)");
        // Bob and Carol have no scores

        let left = run(&ex, "SELECT a.name, b.score FROM inv90a a LEFT JOIN inv90b b ON a.id = b.aid ORDER BY a.name");
        // Alice: 2 matches, Bob: 1 (NULL), Carol: 1 (NULL) = 4
        r.check("lj-count-4", left.rows.len() == 4, &format!("LEFT JOIN={}", left.rows.len()));

        // Left table rows all preserved
        let left_count = run(&ex, "SELECT COUNT(DISTINCT a.name) FROM inv90a a LEFT JOIN inv90b b ON a.id = b.aid");
        if !left_count.rows.is_empty() {
            let lc = val(&left_count.rows[0][0]).unwrap_or(0.0);
            r.check("lj-preserves-left", (lc - 3.0).abs() < 0.5, &format!("distinct left names={}", lc));
        }

        // COUNT(b.score) skips NULLs: only Alice's 2 scores
        let score_cnt = run(&ex, "SELECT COUNT(b.score) FROM inv90a a LEFT JOIN inv90b b ON a.id = b.aid");
        if !score_cnt.rows.is_empty() {
            let sc = val(&score_cnt.rows[0][0]).unwrap_or(0.0);
            r.check("lj-count-non-null", (sc - 2.0).abs() < 0.5, &format!("COUNT(score)={}", sc));
        }

        r.finish();
    }

    // =================================================================
    //  INV-91: SQL — Expression Arithmetic in SELECT
    //
    //  Computed columns: +, -, *, /.
    //  Division by zero handling.
    //  String concatenation via ||.
    // =================================================================
    #[tokio::test]
    async fn inv91_sql_arithmetic() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv91 (id INT, a INT, b INT)");
        run(&ex, "INSERT INTO inv91 VALUES (1, 10, 3)");
        run(&ex, "INSERT INTO inv91 VALUES (2, 20, 5)");
        run(&ex, "INSERT INTO inv91 VALUES (3, 30, 0)");

        // Addition
        let add = run(&ex, "SELECT id, a + b as sum_ab FROM inv91 ORDER BY id");
        if add.rows.len() == 3 {
            let v1 = val(&add.rows[0][1]).unwrap_or(0.0);
            r.check("arith-add", (v1 - 13.0).abs() < 0.5, &format!("10+3={}", v1));
        }

        // Subtraction
        let sub = run(&ex, "SELECT id, a - b as diff FROM inv91 ORDER BY id");
        if sub.rows.len() == 3 {
            let v1 = val(&sub.rows[0][1]).unwrap_or(0.0);
            r.check("arith-sub", (v1 - 7.0).abs() < 0.5, &format!("10-3={}", v1));
        }

        // Multiplication
        let mul = run(&ex, "SELECT id, a * b as prod FROM inv91 ORDER BY id");
        if mul.rows.len() == 3 {
            let v1 = val(&mul.rows[0][1]).unwrap_or(0.0);
            r.check("arith-mul", (v1 - 30.0).abs() < 0.5, &format!("10*3={}", v1));
        }

        // Row count preserved through arithmetic
        r.check("arith-count", add.rows.len() == 3, &format!("rows={}", add.rows.len()));

        r.finish();
    }

    // =================================================================
    //  INV-92: Cross-Paradigm — SQL Table Queryable via GraphQL
    //
    //  Data inserted via SQL is readable via GraphQL.
    //  Mutations via GraphQL are readable via SQL.
    //  Count consistency across paradigms.
    // =================================================================
    #[tokio::test]
    async fn inv92_cross_sql_graphql() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // Create and populate via SQL
        run(&ex, "CREATE TABLE cross92 (id INT, name TEXT, active INT)");
        run(&ex, "INSERT INTO cross92 VALUES (1, 'Alice', 1)");
        run(&ex, "INSERT INTO cross92 VALUES (2, 'Bob', 0)");
        run(&ex, "INSERT INTO cross92 VALUES (3, 'Carol', 1)");

        // Read via SQL
        let sql_count = run_rows(&ex, "SELECT * FROM cross92");
        r.check("cross-sql-3", sql_count == 3, &format!("sql={}", sql_count));

        // Read via GraphQL
        let gql = run(&ex, "{ cross92 { id name active } }");
        r.check("cross-gql-3", gql.rows.len() == 3, &format!("gql={}", gql.rows.len()));

        // Count consistency
        r.check("cross-count-eq", sql_count as usize == gql.rows.len(),
            &format!("sql={} gql={}", sql_count, gql.rows.len()));

        // Mutate via GraphQL, read via SQL
        run(&ex, r#"mutation { createCross92(id: 4, name: "Dave", active: 1) { id } }"#);
        let sql_after = run_rows(&ex, "SELECT * FROM cross92");
        let gql_after = run(&ex, "{ cross92 { id } }");
        r.check("cross-after-4", sql_after == 4, &format!("sql after={}", sql_after));
        r.check("cross-gql-after-4", gql_after.rows.len() == 4, &format!("gql after={}", gql_after.rows.len()));

        r.finish();
    }

    // =================================================================
    //  INV-93: SQL — Multiple CTEs + JOIN Between CTEs
    //
    //  Two CTEs joined together produce correct results.
    //  CTE A JOIN CTE B matches equivalent non-CTE query.
    // =================================================================
    #[tokio::test]
    async fn inv93_sql_cte_join() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv93e (id INT, name TEXT, dept_id INT)");
        run(&ex, "CREATE TABLE inv93d (id INT, dept_name TEXT)");
        run(&ex, "INSERT INTO inv93d VALUES (1, 'eng')");
        run(&ex, "INSERT INTO inv93d VALUES (2, 'sales')");
        run(&ex, "INSERT INTO inv93e VALUES (1, 'Alice', 1)");
        run(&ex, "INSERT INTO inv93e VALUES (2, 'Bob', 1)");
        run(&ex, "INSERT INTO inv93e VALUES (3, 'Carol', 2)");

        // CTE with JOIN
        let cte_join = run(&ex, "WITH emps AS (SELECT * FROM inv93e), depts AS (SELECT * FROM inv93d) SELECT emps.name, depts.dept_name FROM emps INNER JOIN depts ON emps.dept_id = depts.id");
        r.check("cte-join-3", cte_join.rows.len() == 3, &format!("cte join={}", cte_join.rows.len()));

        // Equivalent direct JOIN
        let direct = run(&ex, "SELECT e.name, d.dept_name FROM inv93e e INNER JOIN inv93d d ON e.dept_id = d.id");
        r.check("cte-eq-direct", cte_join.rows.len() == direct.rows.len(),
            &format!("cte={} direct={}", cte_join.rows.len(), direct.rows.len()));

        r.finish();
    }

    // =================================================================
    //  INV-94: SQL — Aggregate + GROUP BY + ORDER BY Combined
    //
    //  GROUP BY + ORDER BY alias: sorted groups.
