    // =================================================================
    //  INV-99: Cypher — UNION / UNION ALL
    //
    //  UNION removes duplicates.
    //  UNION ALL keeps all rows.
    //  |UNION| <= |UNION ALL|.
    // =================================================================
    #[tokio::test]
    async fn inv99_cypher_union() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE (n:CyUA {val: 'a'})");
        run(&ex, "CREATE (n:CyUA {val: 'b'})");
        run(&ex, "CREATE (n:CyUB {val: 'b'})");
        run(&ex, "CREATE (n:CyUB {val: 'c'})");

        // UNION ALL: 2 + 2 = 4
        let union_all = run(&ex, "MATCH (n:CyUA) RETURN n.val UNION ALL MATCH (n:CyUB) RETURN n.val");
        r.check("cy-union-all-4", union_all.rows.len() == 4, &format!("UNION ALL={}", union_all.rows.len()));

        // UNION: a, b, c = 3 (deduplicates 'b')
        let union_r = run(&ex, "MATCH (n:CyUA) RETURN n.val UNION MATCH (n:CyUB) RETURN n.val");
        r.check("cy-union-3", union_r.rows.len() == 3, &format!("UNION={}", union_r.rows.len()));

        // UNION <= UNION ALL
        r.check("cy-union-le-all", union_r.rows.len() <= union_all.rows.len(), "UNION <= ALL");

        r.finish();
    }

    // =================================================================
    //  INV-100: Cypher — SET Multiple Properties
    //
    //  SET can update multiple properties in one statement.
    //  Unmentioned properties preserved.
    // =================================================================
    #[tokio::test]
    async fn inv100_cypher_set_multi() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE (n:CyMulti {name: 'test', a: 1, b: 2, c: 3})");

        // SET two properties
        run(&ex, "MATCH (n:CyMulti {name: 'test'}) SET n.a = 10, n.b = 20");

        let after = run(&ex, "MATCH (n:CyMulti {name: 'test'}) RETURN n.a, n.b, n.c");
        if !after.rows.is_empty() {
            let a = val(&after.rows[0][0]).unwrap_or(0.0);
            let b = val(&after.rows[0][1]).unwrap_or(0.0);
            let c = val(&after.rows[0][2]).unwrap_or(0.0);
            r.check("set-a-10", (a - 10.0).abs() < 0.5, &format!("a={}", a));
            r.check("set-b-20", (b - 20.0).abs() < 0.5, &format!("b={}", b));
            r.check("set-c-preserved", (c - 3.0).abs() < 0.5, &format!("c={}", c));
        }

        r.finish();
    }

    // =================================================================
    //  INV-101: Cypher — DETACH DELETE with Relationships
    //
    //  DETACH DELETE removes node AND all connected edges.
    //  Other nodes unaffected. Relationship count decreases.
    // =================================================================
    #[tokio::test]
    async fn inv101_cypher_detach_delete() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE (a:CyDD {name: 'hub'})");
        run(&ex, "CREATE (b:CyDD {name: 'spoke1'})");
        run(&ex, "CREATE (c:CyDD {name: 'spoke2'})");
        run(&ex, "MATCH (a:CyDD {name: 'hub'}), (b:CyDD {name: 'spoke1'}) CREATE (a)-[:LINKED]->(b)");
        run(&ex, "MATCH (a:CyDD {name: 'hub'}), (c:CyDD {name: 'spoke2'}) CREATE (a)-[:LINKED]->(c)");

        // Before: 3 nodes, 2 relationships
        let nodes_before = run(&ex, "MATCH (n:CyDD) RETURN count(n)");
        let nb = val(&nodes_before.rows[0][0]).unwrap_or(0.0);
        r.check("dd-nodes-3", (nb - 3.0).abs() < 0.5, &format!("nodes before={}", nb));

        // DETACH DELETE hub
        run(&ex, "MATCH (n:CyDD {name: 'hub'}) DETACH DELETE n");

        // After: 2 nodes, 0 relationships
        let nodes_after = run(&ex, "MATCH (n:CyDD) RETURN count(n)");
        let na = val(&nodes_after.rows[0][0]).unwrap_or(0.0);
        r.check("dd-nodes-2", (na - 2.0).abs() < 0.5, &format!("nodes after={}", na));

        // No LINKED relationships remain
        let rels_after = run(&ex, "MATCH ()-[r:LINKED]->() RETURN count(r)");
        let ra = val(&rels_after.rows[0][0]).unwrap_or(-1.0);
        r.check("dd-rels-0", ra.abs() < 0.5, &format!("rels after={}", ra));

        r.finish();
    }

    // =================================================================
    //  INV-102: SQL — Multiple LEFT JOINs Chain
    //
    //  A LEFT JOIN B LEFT JOIN C: preserves all A rows.
    //  NULL propagation through chain.
    // =================================================================
    #[tokio::test]
    async fn inv102_sql_multi_left_join() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv102a (id INT PRIMARY KEY, name TEXT)");
        run(&ex, "INSERT INTO inv102a VALUES (1, 'Alice')");
        run(&ex, "INSERT INTO inv102a VALUES (2, 'Bob')");

        run(&ex, "CREATE TABLE inv102b (aid INT, mid TEXT)");
        run(&ex, "INSERT INTO inv102b VALUES (1, 'meta1')");

        run(&ex, "CREATE TABLE inv102c (mid TEXT, tag TEXT)");
        run(&ex, "INSERT INTO inv102c VALUES ('meta1', 'important')");

        // Double LEFT JOIN
        let res = run(&ex, "SELECT a.name, b.mid, c.tag FROM inv102a a LEFT JOIN inv102b b ON a.id = b.aid LEFT JOIN inv102c c ON b.mid = c.mid");
        // Alice: meta1 → important. Bob: NULL → NULL
        r.check("multi-lj-2", res.rows.len() == 2, &format!("double LEFT JOIN={}", res.rows.len()));

        // All left-side rows preserved
        let left_count = run_rows(&ex, "SELECT * FROM inv102a");
        r.check("multi-lj-preserves", res.rows.len() == left_count as usize,
            &format!("lj={} left={}", res.rows.len(), left_count));

        r.finish();
    }

    // =================================================================
    //  INV-103: SQL — GROUP BY Multiple Columns
    //
    //  GROUP BY a, b: groups by unique (a, b) combinations.
    //  More grouping columns = more groups (or equal).
    // =================================================================
    #[tokio::test]
    async fn inv103_sql_multi_group_by() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv103 (dept TEXT, role TEXT, sal INT)");
        run(&ex, "INSERT INTO inv103 VALUES ('eng', 'dev', 100)");
        run(&ex, "INSERT INTO inv103 VALUES ('eng', 'dev', 120)");
        run(&ex, "INSERT INTO inv103 VALUES ('eng', 'mgr', 150)");
        run(&ex, "INSERT INTO inv103 VALUES ('sales', 'rep', 80)");
        run(&ex, "INSERT INTO inv103 VALUES ('sales', 'rep', 90)");
        run(&ex, "INSERT INTO inv103 VALUES ('sales', 'mgr', 130)");

        // GROUP BY dept: 2 groups
        let g1 = run(&ex, "SELECT dept, COUNT(*) FROM inv103 GROUP BY dept");
        r.check("g1-2", g1.rows.len() == 2, &format!("groups by dept={}", g1.rows.len()));

        // GROUP BY dept, role: 4 groups (eng/dev, eng/mgr, sales/rep, sales/mgr)
        let g2 = run(&ex, "SELECT dept, role, COUNT(*) FROM inv103 GROUP BY dept, role");
        r.check("g2-4", g2.rows.len() == 4, &format!("groups by dept,role={}", g2.rows.len()));

        // More grouping columns >= same groups
        r.check("more-cols-more-groups", g2.rows.len() >= g1.rows.len(),
            &format!("{}≥{}", g2.rows.len(), g1.rows.len()));

        r.finish();
    }

    // =================================================================
    //  INV-104: SQL — Empty Table Queries
    //
    //  SELECT on empty table: 0 rows.
    //  COUNT(*) on empty table: 1 row with 0.
    //  SUM on empty table: NULL or 0.
    //  JOIN with empty table: 0 rows for INNER, preserved for LEFT.
    // =================================================================
    #[tokio::test]
    async fn inv104_sql_empty_table() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv104_empty (id INT, val INT)");
        run(&ex, "CREATE TABLE inv104_full (id INT, val INT)");
        run(&ex, "INSERT INTO inv104_full VALUES (1, 10)");
        run(&ex, "INSERT INTO inv104_full VALUES (2, 20)");

        // SELECT from empty
        let empty = run_rows(&ex, "SELECT * FROM inv104_empty");
        r.check("empty-select-0", empty == 0, &format!("empty={}", empty));

        // COUNT(*) on empty
        let cnt = run(&ex, "SELECT COUNT(*) FROM inv104_empty");
        if !cnt.rows.is_empty() {
            let c = val(&cnt.rows[0][0]).unwrap_or(-1.0);
            r.check("empty-count-0", c.abs() < 0.5, &format!("COUNT(*)={}", c));
        }

        // INNER JOIN with empty: 0
        let inner = run(&ex, "SELECT * FROM inv104_full f INNER JOIN inv104_empty e ON f.id = e.id");
        r.check("inner-empty-0", inner.rows.len() == 0, &format!("INNER JOIN empty={}", inner.rows.len()));

        // LEFT JOIN with empty: preserves left
        let left = run(&ex, "SELECT f.id FROM inv104_full f LEFT JOIN inv104_empty e ON f.id = e.id");
        r.check("left-empty-2", left.rows.len() == 2, &format!("LEFT JOIN empty={}", left.rows.len()));

        r.finish();
    }

