    // =================================================================
    //  INV-110: Full-Text — Empty Index and Edge Cases
    //
    //  Search on empty index: 0 results.
    //  Single-word document found by that word.
    //  Very long text still searchable.
    // =================================================================
    #[tokio::test]
    async fn inv110_fulltext_edge_cases() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // Index a doc first so the index exists, then search for a non-matching term
        run(&ex, "FTINDEX inv110_ft doc0 placeholder");
        let empty = run(&ex, "FTSEARCH inv110_ft zznonexistent");
        r.check("ft-empty-0", empty.rows.len() == 0, &format!("empty={}", empty.rows.len()));
        run(&ex, "FTDELETE inv110_ft doc0");

        // Single word doc
        run(&ex, "FTINDEX inv110_ft doc1 hello");
        let single = run(&ex, "FTSEARCH inv110_ft hello");
        r.check("ft-single-1", single.rows.len() == 1, &format!("single word={}", single.rows.len()));

        // Long text
        run(&ex, "FTINDEX inv110_ft doc2 the quick brown fox jumps over the lazy dog repeatedly and continuously");
        let long = run(&ex, "FTSEARCH inv110_ft continuously");
        r.check("ft-long-1", long.rows.len() == 1, &format!("long text={}", long.rows.len()));

        // Both docs searchable independently
        let hello = run(&ex, "FTSEARCH inv110_ft hello");
        let fox = run(&ex, "FTSEARCH inv110_ft fox");
        r.check("ft-hello-still-1", hello.rows.len() == 1, &format!("hello={}", hello.rows.len()));
        r.check("ft-fox-1", fox.rows.len() == 1, &format!("fox={}", fox.rows.len()));

        r.finish();
    }

    // =================================================================
    //  INV-111: SQL — COUNT DISTINCT
    //
    //  COUNT(DISTINCT col) = number of unique non-NULL values.
    //  COUNT(DISTINCT col) <= COUNT(col).
    //  COUNT(DISTINCT col) <= COUNT(*).
    // =================================================================
    #[tokio::test]
    async fn inv111_sql_count_distinct() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv111 (id INT, cat TEXT)");
        run(&ex, "INSERT INTO inv111 VALUES (1, 'a')");
        run(&ex, "INSERT INTO inv111 VALUES (2, 'b')");
        run(&ex, "INSERT INTO inv111 VALUES (3, 'a')");
        run(&ex, "INSERT INTO inv111 VALUES (4, 'c')");
        run(&ex, "INSERT INTO inv111 VALUES (5, 'b')");
        run(&ex, "INSERT INTO inv111 VALUES (6, 'a')");

        let cnt_star = run(&ex, "SELECT COUNT(*) FROM inv111");
        let cnt_cat = run(&ex, "SELECT COUNT(cat) FROM inv111");
        let cnt_dist = run(&ex, "SELECT COUNT(DISTINCT cat) FROM inv111");

        if !cnt_star.rows.is_empty() && !cnt_cat.rows.is_empty() && !cnt_dist.rows.is_empty() {
            let cs = val(&cnt_star.rows[0][0]).unwrap_or(0.0);
            let cc = val(&cnt_cat.rows[0][0]).unwrap_or(0.0);
            let cd = val(&cnt_dist.rows[0][0]).unwrap_or(0.0);

            r.check("count-star-6", (cs - 6.0).abs() < 0.5, &format!("COUNT(*)={}", cs));
            r.check("count-cat-6", (cc - 6.0).abs() < 0.5, &format!("COUNT(cat)={}", cc));
            r.check("count-distinct-3", (cd - 3.0).abs() < 0.5, &format!("COUNT(DISTINCT)={}", cd));
            r.check("distinct-le-count", cd <= cc, &format!("{} <= {}", cd, cc));
            r.check("distinct-le-star", cd <= cs, &format!("{} <= {}", cd, cs));
        }

        r.finish();
    }

    // =================================================================
    //  INV-112: Cross-Paradigm — Cypher + SQL on Same Executor
    //
    //  SQL CREATE TABLE + Cypher CREATE nodes coexist.
    //  SQL queries don't see Cypher nodes.
    //  Cypher queries don't see SQL tables.
    //  Both maintain independent counts.
    // =================================================================
    #[tokio::test]
    async fn inv112_cross_cypher_sql() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL data
        run(&ex, "CREATE TABLE inv112_sql (id INT, val TEXT)");
        run(&ex, "INSERT INTO inv112_sql VALUES (1, 'sql1')");
        run(&ex, "INSERT INTO inv112_sql VALUES (2, 'sql2')");

        // Cypher data
        run(&ex, "CREATE (n:Inv112Node {name: 'cy1'})");
        run(&ex, "CREATE (n:Inv112Node {name: 'cy2'})");
        run(&ex, "CREATE (n:Inv112Node {name: 'cy3'})");

        // SQL sees only SQL
        let sql = run_rows(&ex, "SELECT * FROM inv112_sql");
        r.check("cross-sql-2", sql == 2, &format!("sql={}", sql));

        // Cypher sees only Cypher
        let cy = run(&ex, "MATCH (n:Inv112Node) RETURN count(n)");
        if !cy.rows.is_empty() {
            let c = val(&cy.rows[0][0]).unwrap_or(0.0);
            r.check("cross-cypher-3", (c - 3.0).abs() < 0.5, &format!("cypher={}", c));
        }

        // Mutate SQL, Cypher unaffected
        run(&ex, "DELETE FROM inv112_sql WHERE id = 1");
        let sql_after = run_rows(&ex, "SELECT * FROM inv112_sql");
        let cy_after = run(&ex, "MATCH (n:Inv112Node) RETURN count(n)");
        r.check("cross-sql-after-1", sql_after == 1, &format!("sql after={}", sql_after));
        if !cy_after.rows.is_empty() {
            let c2 = val(&cy_after.rows[0][0]).unwrap_or(0.0);
            r.check("cross-cypher-unaffected", (c2 - 3.0).abs() < 0.5, &format!("cypher after sql del={}", c2));
        }

        r.finish();
    }

