    /// INV-115: SQL window functions — ROW_NUMBER, RANK, DENSE_RANK
    #[tokio::test]
    async fn inv115_sql_window_ranking() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let res = run(&ex, "SELECT name, salary, ROW_NUMBER() OVER (ORDER BY salary DESC) AS rn FROM employees");
        r.check("window-6rows", res.rows.len() == 6, &format!("rows={}", res.rows.len()));
        // ROW_NUMBER must assign 1..6 (any order in result, but the set is complete)
        if res.rows.len() == 6 {
            let mut rns: Vec<i64> = res.rows.iter().filter_map(|row| val(&row[2]).map(|v| v as i64)).collect();
            rns.sort();
            let expected: Vec<i64> = vec![1, 2, 3, 4, 5, 6];
            r.check("rn-set-1-thru-6", rns == expected, &format!("sorted rns={:?}", rns));
        }

        // RANK with ties
        let res2 = run(&ex, "SELECT dept_id, salary, RANK() OVER (ORDER BY dept_id) AS rnk FROM employees");
        r.check("rank-6rows", res2.rows.len() == 6, &format!("rows={}", res2.rows.len()));

        r.finish();
    }

