    /// INV-120: Cypher MERGE — creates if missing, matches if existing
    #[tokio::test]
    async fn inv120_cypher_merge() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // First MERGE creates node
        run(&ex, "MERGE (n:Inv120 {key: 'abc'})");
        let c1 = run(&ex, "MATCH (n:Inv120) RETURN count(n)");
        if !c1.rows.is_empty() {
            let v = val(&c1.rows[0][0]).unwrap_or(0.0);
            r.check("merge-create-1", (v - 1.0).abs() < 0.5, &format!("count={}", v));
        }

        // Second MERGE with same key should NOT create another
        run(&ex, "MERGE (n:Inv120 {key: 'abc'})");
        let c2 = run(&ex, "MATCH (n:Inv120) RETURN count(n)");
        if !c2.rows.is_empty() {
            let v = val(&c2.rows[0][0]).unwrap_or(0.0);
            r.check("merge-match-still-1", (v - 1.0).abs() < 0.5, &format!("count={}", v));
        }

        // MERGE with different key creates new node
        run(&ex, "MERGE (n:Inv120 {key: 'def'})");
        let c3 = run(&ex, "MATCH (n:Inv120) RETURN count(n)");
        if !c3.rows.is_empty() {
            let v = val(&c3.rows[0][0]).unwrap_or(0.0);
            r.check("merge-new-key-2", (v - 2.0).abs() < 0.5, &format!("count={}", v));
        }

        r.finish();
    }

