    /// INV-126: SQL DELETE + UPDATE interaction — update then delete subset
    #[tokio::test]
    async fn inv126_sql_update_delete() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv126 (id INT, status TEXT, val INT)");
        run(&ex, "INSERT INTO inv126 VALUES (1, 'active', 10)");
        run(&ex, "INSERT INTO inv126 VALUES (2, 'active', 20)");
        run(&ex, "INSERT INTO inv126 VALUES (3, 'inactive', 30)");
        run(&ex, "INSERT INTO inv126 VALUES (4, 'active', 40)");

        // Update active → val doubled
        run(&ex, "UPDATE inv126 SET val = val * 2 WHERE status = 'active'");
        let updated = run(&ex, "SELECT SUM(val) FROM inv126 WHERE status = 'active'");
        if !updated.rows.is_empty() {
            let s = val(&updated.rows[0][0]).unwrap_or(0.0);
            // 10*2+20*2+40*2 = 140
            r.check("update-sum-140", (s - 140.0).abs() < 1.0, &format!("sum={}", s));
        }

        // Delete inactive
        let del = run(&ex, "DELETE FROM inv126 WHERE status = 'inactive'");
        r.check("delete-1", del.affected_rows == Some(1), &format!("affected={:?}", del.affected_rows));

        let remain = run_rows(&ex, "SELECT * FROM inv126");
        r.check("remain-3", remain == 3, &format!("rows={}", remain));

        r.finish();
    }

