    /// INV-131: SQL ORDER BY + LIMIT + OFFSET pagination
    #[tokio::test]
    async fn inv131_sql_pagination() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        // Page 1: first 2 by salary desc
        let p1 = run(&ex, "SELECT name, salary FROM employees ORDER BY salary DESC LIMIT 2");
        r.check("page1-2rows", p1.rows.len() == 2, &format!("rows={}", p1.rows.len()));

        // Page 2: next 2
        let p2 = run(&ex, "SELECT name, salary FROM employees ORDER BY salary DESC LIMIT 2 OFFSET 2");
        r.check("page2-2rows", p2.rows.len() == 2, &format!("rows={}", p2.rows.len()));

        // Pages should not overlap
        if p1.rows.len() == 2 && p2.rows.len() == 2 {
            let s1: Vec<String> = p1.rows.iter().map(|r| r[0].as_str().unwrap_or("").to_string()).collect();
            let s2: Vec<String> = p2.rows.iter().map(|r| r[0].as_str().unwrap_or("").to_string()).collect();
            let overlap = s1.iter().any(|n| s2.contains(n));
            r.check("no-page-overlap", !overlap, &format!("p1={:?} p2={:?}", s1, s2));
        }

        // Page 1 salary >= page 2 salary (descending order)
        if p1.rows.len() == 2 && p2.rows.len() == 2 {
            let min_p1 = val(&p1.rows[1][1]).unwrap_or(0.0);
            let max_p2 = val(&p2.rows[0][1]).unwrap_or(f64::MAX);
            r.check("page-order", min_p1 >= max_p2, &format!("p1_min={} p2_max={}", min_p1, max_p2));
        }

        r.finish();
    }

    /// INV-132: CQL batch operations
    #[tokio::test]
    async fn inv132_cql_batch() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE KEYSPACE inv132_ks WITH replication = {'class': 'SimpleStrategy', 'replication_factor': '1'}");
        run(&ex, "CREATE TABLE inv132_ks.logs (id TEXT PRIMARY KEY, msg TEXT, level TEXT)");

        // BEGIN BATCH ... APPLY BATCH
        run(&ex, "BEGIN BATCH INSERT INTO inv132_ks.logs (id, msg, level) VALUES ('l1', 'start', 'info'); INSERT INTO inv132_ks.logs (id, msg, level) VALUES ('l2', 'error occurred', 'error'); INSERT INTO inv132_ks.logs (id, msg, level) VALUES ('l3', 'recovered', 'info'); APPLY BATCH");

        let all = run(&ex, "SELECT * FROM inv132_ks.logs ALLOW FILTERING");
        r.check("batch-3rows", all.rows.len() == 3, &format!("rows={}", all.rows.len()));

        // TRUNCATE
        run(&ex, "TRUNCATE TABLE inv132_ks.logs");
        let after = run(&ex, "SELECT * FROM inv132_ks.logs ALLOW FILTERING");
        r.check("truncate-0", after.rows.len() == 0, &format!("rows={}", after.rows.len()));

        r.finish();
    }

