    /// INV-137: SQL multiple aggregates in single query
    #[tokio::test]
    async fn inv137_sql_multi_aggregate() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let res = run(&ex, "SELECT COUNT(*), SUM(salary), AVG(salary), MIN(salary), MAX(salary) FROM employees");
        r.check("multi-agg-1row", res.rows.len() == 1, &format!("rows={}", res.rows.len()));
        if !res.rows.is_empty() {
            let cnt = val(&res.rows[0][0]).unwrap_or(0.0);
            let sum = val(&res.rows[0][1]).unwrap_or(0.0);
            let avg = val(&res.rows[0][2]).unwrap_or(0.0);
            let min = val(&res.rows[0][3]).unwrap_or(0.0);
            let max = val(&res.rows[0][4]).unwrap_or(0.0);

            r.check("cnt-6", (cnt - 6.0).abs() < 0.5, &format!("cnt={}", cnt));
            // sum = 120k+110k+95k+85k+90k+130k = 630k
            r.check("sum-630k", (sum - 630000.0).abs() < 1.0, &format!("sum={}", sum));
            // avg = 630k/6 = 105k
            r.check("avg-105k", (avg - 105000.0).abs() < 1.0, &format!("avg={}", avg));
            r.check("min-85k", (min - 85000.0).abs() < 1.0, &format!("min={}", min));
            r.check("max-130k", (max - 130000.0).abs() < 1.0, &format!("max={}", max));
        }

        r.finish();
    }

    /// INV-138: Cypher CREATE path pattern — chain of relationships
    #[tokio::test]
    async fn inv138_cypher_path_chain() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // Create a chain: a-[:NEXT]->b-[:NEXT]->c
        run(&ex, "CREATE (a:Chain138 {pos: 1})-[:NEXT]->(b:Chain138 {pos: 2})-[:NEXT]->(c:Chain138 {pos: 3})");

        let nodes = run(&ex, "MATCH (n:Chain138) RETURN count(n)");
        if !nodes.rows.is_empty() {
            let c = val(&nodes.rows[0][0]).unwrap_or(0.0);
            r.check("chain-3nodes", (c - 3.0).abs() < 0.5, &format!("nodes={}", c));
        }

        let rels = run(&ex, "MATCH ()-[r:NEXT]->() RETURN count(r)");
        if !rels.rows.is_empty() {
            let c = val(&rels.rows[0][0]).unwrap_or(0.0);
            r.check("chain-2rels", (c - 2.0).abs() < 0.5, &format!("rels={}", c));
        }

        // Traverse 2-hop: find node at end of 2-step path
        let path = run(&ex, "MATCH (a:Chain138 {pos: 1})-[:NEXT]->(b)-[:NEXT]->(c) RETURN c.pos");
        r.check("2hop-1row", path.rows.len() == 1, &format!("rows={}", path.rows.len()));
        if !path.rows.is_empty() {
            let p = val(&path.rows[0][0]).unwrap_or(0.0);
            r.check("2hop-pos-3", (p - 3.0).abs() < 0.5, &format!("pos={}", p));
        }

        r.finish();
    }

