    /// INV-143: Cypher WHERE with AND/OR logic
    #[tokio::test]
    async fn inv143_cypher_where_logic() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE (n:Inv143 {age: 25, active: true})");
        run(&ex, "CREATE (n:Inv143 {age: 35, active: false})");
        run(&ex, "CREATE (n:Inv143 {age: 45, active: true})");
        run(&ex, "CREATE (n:Inv143 {age: 20, active: false})");

        // AND
        let and_res = run(&ex, "MATCH (n:Inv143) WHERE n.age > 30 AND n.active = true RETURN n.age");
        r.check("and-1", and_res.rows.len() == 1, &format!("rows={}", and_res.rows.len()));
        if !and_res.rows.is_empty() {
            let a = val(&and_res.rows[0][0]).unwrap_or(0.0);
            r.check("and-age-45", (a - 45.0).abs() < 0.5, &format!("age={}", a));
        }

        // OR
        let or_res = run(&ex, "MATCH (n:Inv143) WHERE n.age > 40 OR n.active = false RETURN count(n)");
        if !or_res.rows.is_empty() {
            let c = val(&or_res.rows[0][0]).unwrap_or(0.0);
            // age>40: {45}, active=false: {35,20} → union: {45,35,20} → 3
            r.check("or-3", (c - 3.0).abs() < 0.5, &format!("count={}", c));
        }

        r.finish();
    }

