    /// INV-145: TimeSeries — write, query window, delete metric
    #[tokio::test]
    async fn inv145_timeseries_lifecycle() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        for i in 0..10 {
            run(&ex, &format!("TSWRITE inv145_temp {} {}", i as f64 * 5.0, i * 1000));
        }

        // Query subset
        let sub = run(&ex, "TSQUERY inv145_temp 3000 7000");
        // timestamps 3000,4000,5000,6000,7000 → 5 points
        r.check("ts-sub-5", sub.rows.len() == 5, &format!("rows={}", sub.rows.len()));

        // Aggregate: min in window
        let mn = run(&ex, "TSAGGREGATE inv145_temp 3000 7000 5000 min");
        if !mn.rows.is_empty() {
            let v = val(&mn.rows[0][1]).unwrap_or(-1.0);
            // min of 15.0,20.0,25.0,30.0,35.0 = 15.0
            r.check("ts-min-15", (v - 15.0).abs() < 1.0, &format!("min={}", v));
        }

        // Delete
        run(&ex, "TSDELETE inv145_temp");
        let after = run(&ex, "TSQUERY inv145_temp 0 99999");
        r.check("ts-deleted-0", after.rows.len() == 0, &format!("rows={}", after.rows.len()));

        r.finish();
    }

