    /// INV-147: Cypher DETACH DELETE — removes node and all relationships
    #[tokio::test]
    async fn inv147_cypher_detach_delete() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE (a:Inv147 {name: 'hub'})-[:LINK]->(b:Inv147 {name: 'spoke1'})");
        run(&ex, "CREATE (a:Inv147 {name: 'hub'})-[:LINK]->(c:Inv147 {name: 'spoke2'})");

        // Verify initial state
        let nodes_before = run(&ex, "MATCH (n:Inv147) RETURN count(n)");
        if !nodes_before.rows.is_empty() {
            let c = val(&nodes_before.rows[0][0]).unwrap_or(0.0);
            // 4 nodes: 2 hub nodes, spoke1, spoke2 (each CREATE makes separate hub)
            r.check("before-4nodes", (c - 4.0).abs() < 0.5, &format!("nodes={}", c));
        }

        // DETACH DELETE all hub nodes
        run(&ex, "MATCH (n:Inv147 {name: 'hub'}) DETACH DELETE n");

        // Hub nodes gone
        let hubs = run(&ex, "MATCH (n:Inv147 {name: 'hub'}) RETURN count(n)");
        if !hubs.rows.is_empty() {
            let c = val(&hubs.rows[0][0]).unwrap_or(0.0);
            r.check("hubs-gone-0", (c - 0.0).abs() < 0.5, &format!("hubs={}", c));
        }

        // Relationships gone
        let rels = run(&ex, "MATCH ()-[r:LINK]->() RETURN count(r)");
        if !rels.rows.is_empty() {
            let c = val(&rels.rows[0][0]).unwrap_or(0.0);
            r.check("rels-gone-0", (c - 0.0).abs() < 0.5, &format!("rels={}", c));
        }

        r.finish();
    }

