    /// INV-151: Vector — duplicate ID rejection
    #[tokio::test]
    async fn inv151_vector_dup_id() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "VECTOR CREATE inv151_idx 2");
        run(&ex, "VECTOR INSERT inv151_idx v1 [1.0,0.0]");

        // Duplicate insert should fail
        let dup = try_run(&ex, "VECTOR INSERT inv151_idx v1 [0.0,1.0]");
        r.check("dup-rejected", dup.is_err(), &format!("dup={:?}", dup.is_ok()));

        // Delete then re-insert should work
        run(&ex, "VECTOR DELETE inv151_idx v1");
        let reinsert = try_run(&ex, "VECTOR INSERT inv151_idx v1 [0.0,1.0]");
        r.check("reinsert-ok", reinsert.is_ok(), &format!("reinsert={:?}", reinsert.is_err()));

        // Search should find the new vector
        let res = run(&ex, "VECTOR SEARCH inv151_idx [0.0,1.0] 1");
        r.check("search-1", res.rows.len() == 1, &format!("rows={}", res.rows.len()));

        r.finish();
    }

