    /// INV-171: SQL transaction-like DELETE + SELECT consistency
    #[tokio::test]
    async fn inv171_sql_delete_consistency() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv171 (id INT, status TEXT)");
        for i in 0..20 {
            let s = if i % 3 == 0 { "remove" } else { "keep" };
            run(&ex, &format!("INSERT INTO inv171 VALUES ({}, '{}')", i, s));
        }

        let before = run_rows(&ex, "SELECT * FROM inv171");
        r.check("before-20", before == 20, &format!("rows={}", before));

        let del = run(&ex, "DELETE FROM inv171 WHERE status = 'remove'");
        // 0,3,6,9,12,15,18 → 7 deleted
        r.check("del-7", del.affected_rows == Some(7), &format!("affected={:?}", del.affected_rows));

        let after = run_rows(&ex, "SELECT * FROM inv171");
        r.check("after-13", after == 13, &format!("rows={}", after));

        // Verify none remaining have status 'remove'
        let removed = run_rows(&ex, "SELECT * FROM inv171 WHERE status = 'remove'");
        r.check("no-remove", removed == 0, &format!("rows={}", removed));

        r.finish();
    }

    /// INV-172: SQL window function — SUM OVER with partition
    #[tokio::test]
    async fn inv172_sql_window_partition() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let res = run(&ex, "SELECT name, dept_id, SUM(salary) OVER (PARTITION BY dept_id) AS dept_total FROM employees");
        r.check("window-6rows", res.rows.len() == 6, &format!("rows={}", res.rows.len()));

        // All employees in same dept should have same dept_total
        // Dept 1: Alice=120k + Bob=110k + Frank=130k = 360k
        let dept1: Vec<f64> = res.rows.iter()
            .filter(|row| val(&row[1]).map(|d| (d - 1.0).abs() < 0.5).unwrap_or(false))
            .filter_map(|row| val(&row[2]))
            .collect();
        if !dept1.is_empty() {
            let all_same = dept1.iter().all(|v| (v - dept1[0]).abs() < 1.0);
            r.check("window-dept1-same", all_same, &format!("dept1_totals={:?}", dept1));
            r.check("window-dept1-360k", (dept1[0] - 360000.0).abs() < 1.0, &format!("total={}", dept1[0]));
        }

        r.finish();
    }

