    /// INV-182: Cypher multiple CREATE + DELETE cycle
    #[tokio::test]
    async fn inv182_cypher_create_delete_cycle() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // Create 6 nodes in two groups
        run(&ex, "CREATE (n:Inv182 {group: 'keep'})");
        run(&ex, "CREATE (n:Inv182 {group: 'remove'})");
        run(&ex, "CREATE (n:Inv182 {group: 'keep'})");
        run(&ex, "CREATE (n:Inv182 {group: 'remove'})");
        run(&ex, "CREATE (n:Inv182 {group: 'keep'})");
        run(&ex, "CREATE (n:Inv182 {group: 'remove'})");

        let c1 = run(&ex, "MATCH (n:Inv182) RETURN count(n)");
        if !c1.rows.is_empty() {
            let v = val(&c1.rows[0][0]).unwrap_or(0.0);
            r.check("created-6", (v - 6.0).abs() < 0.5, &format!("count={}", v));
        }

        // Delete the 'remove' group
        run(&ex, "MATCH (n:Inv182 {group: 'remove'}) DELETE n");
        let c2 = run(&ex, "MATCH (n:Inv182) RETURN count(n)");
        if !c2.rows.is_empty() {
            let v = val(&c2.rows[0][0]).unwrap_or(0.0);
            r.check("after-del-3", (v - 3.0).abs() < 0.5, &format!("count={}", v));
        }

        r.finish();
    }

