    /// INV-189: CQL keyspace isolation — two keyspaces don't interfere
    #[tokio::test]
    async fn inv189_cql_keyspace_isolation() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE KEYSPACE inv189_a WITH replication = {'class': 'SimpleStrategy', 'replication_factor': '1'}");
        run(&ex, "CREATE KEYSPACE inv189_b WITH replication = {'class': 'SimpleStrategy', 'replication_factor': '1'}");
        run(&ex, "CREATE TABLE inv189_a.items (id TEXT PRIMARY KEY, val TEXT)");
        run(&ex, "CREATE TABLE inv189_b.items (id TEXT PRIMARY KEY, val TEXT)");

        run(&ex, "INSERT INTO inv189_a.items (id, val) VALUES ('k1', 'from_a')");
        run(&ex, "INSERT INTO inv189_b.items (id, val) VALUES ('k1', 'from_b')");
        run(&ex, "INSERT INTO inv189_b.items (id, val) VALUES ('k2', 'from_b2')");

        let a = run(&ex, "SELECT * FROM inv189_a.items ALLOW FILTERING");
        r.check("ks-a-1", a.rows.len() == 1, &format!("rows={}", a.rows.len()));

        let b = run(&ex, "SELECT * FROM inv189_b.items ALLOW FILTERING");
        r.check("ks-b-2", b.rows.len() == 2, &format!("rows={}", b.rows.len()));

        r.finish();
    }

