    /// INV-196: SQL 500-row insert + aggregate stress
    #[tokio::test]
    async fn inv196_sql_500_row_stress() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv196 (id INT, val FLOAT)");
        for i in 0..500 {
            run(&ex, &format!("INSERT INTO inv196 VALUES ({}, {})", i, i as f64));
        }

        let cnt = run(&ex, "SELECT COUNT(*) FROM inv196");
        if !cnt.rows.is_empty() {
            let c = val(&cnt.rows[0][0]).unwrap_or(0.0);
            r.check("500-rows", (c - 500.0).abs() < 0.5, &format!("count={}", c));
        }

        // SUM of 0..499 = 499*500/2 = 124750
        let sum = run(&ex, "SELECT SUM(val) FROM inv196");
        if !sum.rows.is_empty() {
            let s = val(&sum.rows[0][0]).unwrap_or(0.0);
            r.check("sum-124750", (s - 124750.0).abs() < 1.0, &format!("sum={}", s));
        }

        // AVG = 124750/500 = 249.5
        let avg = run(&ex, "SELECT AVG(val) FROM inv196");
        if !avg.rows.is_empty() {
            let a = val(&avg.rows[0][0]).unwrap_or(0.0);
            r.check("avg-249.5", (a - 249.5).abs() < 1.0, &format!("avg={}", a));
        }

        r.finish();
    }

