    /// INV-200: Cypher graph traversal — 3-hop path
    #[tokio::test]
    async fn inv200_cypher_3hop() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // Build: a->b->c->d
        run(&ex, "CREATE (a:Inv200 {name: 'a'})-[:STEP]->(b:Inv200 {name: 'b'})-[:STEP]->(c:Inv200 {name: 'c'})-[:STEP]->(d:Inv200 {name: 'd'})");

        // 1-hop from a
        let hop1 = run(&ex, "MATCH (a:Inv200 {name: 'a'})-[:STEP]->(b) RETURN b.name");
        r.check("1hop-1", hop1.rows.len() == 1, &format!("rows={}", hop1.rows.len()));
        if !hop1.rows.is_empty() {
            let n = hop1.rows[0][0].as_str().unwrap_or("");
            r.check("1hop-b", n == "b", &format!("name={}", n));
        }

        // 3-hop from a to d
        let hop3 = run(&ex, "MATCH (a:Inv200 {name: 'a'})-[:STEP]->(b)-[:STEP]->(c)-[:STEP]->(d) RETURN d.name");
        r.check("3hop-1", hop3.rows.len() == 1, &format!("rows={}", hop3.rows.len()));
        if !hop3.rows.is_empty() {
            let n = hop3.rows[0][0].as_str().unwrap_or("");
            r.check("3hop-d", n == "d", &format!("name={}", n));
        }

        r.finish();
    }

