    /// INV-218: SQL SUM invariant — sum(col) = sum(where A) + sum(where NOT A)
    #[tokio::test]
    async fn inv218_sql_sum_partition() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let total = run(&ex, "SELECT SUM(salary) FROM employees");
        let dept1 = run(&ex, "SELECT SUM(salary) FROM employees WHERE dept_id = 1");
        let not_dept1 = run(&ex, "SELECT SUM(salary) FROM employees WHERE dept_id <> 1");

        if !total.rows.is_empty() && !dept1.rows.is_empty() && !not_dept1.rows.is_empty() {
            let t = val(&total.rows[0][0]).unwrap_or(0.0);
            let d1 = val(&dept1.rows[0][0]).unwrap_or(0.0);
            let nd1 = val(&not_dept1.rows[0][0]).unwrap_or(0.0);
            r.check("sum-partition", (t - (d1 + nd1)).abs() < 1.0,
                &format!("total={} d1={} nd1={} d1+nd1={}", t, d1, nd1, d1 + nd1));
        }

        r.finish();
    }

    /// INV-219: SQL COUNT invariant — count(where A) + count(where NOT A) = count(*)
