    /// INV-221: SQL JOIN count invariant — INNER <= LEFT = RIGHT (when all match)
    #[tokio::test]
    async fn inv221_sql_join_count_invariant() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let inner = run_rows(&ex, "SELECT * FROM employees e JOIN departments d ON e.dept_id = d.id");
        let left = run_rows(&ex, "SELECT * FROM employees e LEFT JOIN departments d ON e.dept_id = d.id");

        // INNER JOIN rows <= LEFT JOIN rows (always true)
        r.check("inner-le-left", inner <= left,
            &format!("inner={} left={}", inner, left));

        // Since all employees have valid dept_id, INNER = LEFT = 6
        r.check("inner-6", inner == 6, &format!("inner={}", inner));
        r.check("left-6", left == 6, &format!("left={}", left));

        r.finish();
    }

    /// INV-222: SQL multiple tables — DROP one doesn't affect others
    #[tokio::test]
    async fn inv222_sql_drop_isolation() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv222_a (id INT)");
        run(&ex, "CREATE TABLE inv222_b (id INT)");
        run(&ex, "INSERT INTO inv222_a VALUES (1)");
        run(&ex, "INSERT INTO inv222_b VALUES (2)");

        run(&ex, "DROP TABLE inv222_a");

        // inv222_b should still work
        let b = run_rows(&ex, "SELECT * FROM inv222_b");
        r.check("b-intact-1", b == 1, &format!("rows={}", b));

        // inv222_a should error
        let a = try_run(&ex, "SELECT * FROM inv222_a");
        r.check("a-dropped", a.is_err(), &format!("a={:?}", a.is_ok()));

        r.finish();
    }

    /// INV-223: SQL ORDER BY DESC + ASC on same query give inverse order
    #[tokio::test]
    async fn inv223_sql_order_inverse() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let asc = run(&ex, "SELECT name FROM employees ORDER BY salary ASC");
        let desc = run(&ex, "SELECT name FROM employees ORDER BY salary DESC");

        r.check("both-6", asc.rows.len() == 6 && desc.rows.len() == 6,
            &format!("asc={} desc={}", asc.rows.len(), desc.rows.len()));

        if asc.rows.len() == 6 && desc.rows.len() == 6 {
            // First of ASC = last of DESC
            let asc_first = asc.rows[0][0].as_str().unwrap_or("");
            let desc_last = desc.rows[5][0].as_str().unwrap_or("");
            r.check("inverse-first-last", asc_first == desc_last,
                &format!("asc_first={} desc_last={}", asc_first, desc_last));

            // Last of ASC = first of DESC
            let asc_last = asc.rows[5][0].as_str().unwrap_or("");
            let desc_first = desc.rows[0][0].as_str().unwrap_or("");
            r.check("inverse-last-first", asc_last == desc_first,
                &format!("asc_last={} desc_first={}", asc_last, desc_first));
        }

        r.finish();
    }

