    /// INV-234: SQL DELETE + COUNT integrity across multiple deletes
    #[tokio::test]
    async fn inv234_sql_delete_count_chain() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv234 (id INT, cat TEXT)");
        for i in 0..30 {
            let cat = match i % 3 { 0 => "a", 1 => "b", _ => "c" };
            run(&ex, &format!("INSERT INTO inv234 VALUES ({}, '{}')", i, cat));
        }

        r.check("initial-30", run_rows(&ex, "SELECT * FROM inv234") == 30, "init");

        run(&ex, "DELETE FROM inv234 WHERE cat = 'a'");
        let after_a = run_rows(&ex, "SELECT * FROM inv234");
        r.check("after-del-a-20", after_a == 20, &format!("rows={}", after_a));

        run(&ex, "DELETE FROM inv234 WHERE cat = 'b'");
        let after_b = run_rows(&ex, "SELECT * FROM inv234");
        r.check("after-del-b-10", after_b == 10, &format!("rows={}", after_b));

        run(&ex, "DELETE FROM inv234 WHERE cat = 'c'");
        let after_c = run_rows(&ex, "SELECT * FROM inv234");
        r.check("after-del-c-0", after_c == 0, &format!("rows={}", after_c));

        r.finish();
    }

    /// INV-235: Cypher relationship count before/after DELETE
    #[tokio::test]
    async fn inv235_cypher_rel_delete() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE (a:Inv235 {name: 'a'})-[:LINK]->(b:Inv235 {name: 'b'})");
        run(&ex, "CREATE (c:Inv235 {name: 'c'})-[:LINK]->(d:Inv235 {name: 'd'})");

        let before = run(&ex, "MATCH ()-[r:LINK]->() RETURN count(r)");
        if !before.rows.is_empty() {
            let c = val(&before.rows[0][0]).unwrap_or(0.0);
            r.check("rels-before-2", (c - 2.0).abs() < 0.5, &format!("count={}", c));
        }

        // DETACH DELETE one pair
        run(&ex, "MATCH (n:Inv235 {name: 'a'}) DETACH DELETE n");

        let after = run(&ex, "MATCH ()-[r:LINK]->() RETURN count(r)");
        if !after.rows.is_empty() {
            let c = val(&after.rows[0][0]).unwrap_or(0.0);
            r.check("rels-after-1", (c - 1.0).abs() < 0.5, &format!("count={}", c));
        }

        r.finish();
    }

