    /// INV-238: Cypher WHERE inequality
    #[tokio::test]
    async fn inv238_cypher_where_ineq() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        for i in 1..=8 {
            run(&ex, &format!("CREATE (n:Inv238 {{val: {}}})", i * 10));
        }

        let gt = run(&ex, "MATCH (n:Inv238) WHERE n.val > 50 RETURN count(n)");
        if !gt.rows.is_empty() {
            let c = val(&gt.rows[0][0]).unwrap_or(0.0);
            // 60,70,80 → 3
            r.check("gt-50-3", (c - 3.0).abs() < 0.5, &format!("count={}", c));
        }

        let le = run(&ex, "MATCH (n:Inv238) WHERE n.val <= 50 RETURN count(n)");
        if !le.rows.is_empty() {
            let c = val(&le.rows[0][0]).unwrap_or(0.0);
            // 10,20,30,40,50 → 5
            r.check("le-50-5", (c - 5.0).abs() < 0.5, &format!("count={}", c));
        }

        // gt + le should = 8
        if !gt.rows.is_empty() && !le.rows.is_empty() {
            let g = val(&gt.rows[0][0]).unwrap_or(0.0);
            let l = val(&le.rows[0][0]).unwrap_or(0.0);
            r.check("partition-8", (g + l - 8.0).abs() < 0.5, &format!("gt+le={}", g + l));
        }

        r.finish();
    }

