    /// INV-247: SQL UPDATE then SELECT same transaction
    #[tokio::test]
    async fn inv247_sql_update_read_consistency() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv247 (id INT, balance FLOAT)");
        run(&ex, "INSERT INTO inv247 VALUES (1, 1000.0)");
        run(&ex, "INSERT INTO inv247 VALUES (2, 500.0)");

        // Transfer 200 from account 1 to account 2
        run(&ex, "UPDATE inv247 SET balance = balance - 200 WHERE id = 1");
        run(&ex, "UPDATE inv247 SET balance = balance + 200 WHERE id = 2");

        // Verify balances
        let b1 = run(&ex, "SELECT balance FROM inv247 WHERE id = 1");
        let b2 = run(&ex, "SELECT balance FROM inv247 WHERE id = 2");
        if !b1.rows.is_empty() && !b2.rows.is_empty() {
            let v1 = val(&b1.rows[0][0]).unwrap_or(0.0);
            let v2 = val(&b2.rows[0][0]).unwrap_or(0.0);
            r.check("b1-800", (v1 - 800.0).abs() < 1.0, &format!("b1={}", v1));
            r.check("b2-700", (v2 - 700.0).abs() < 1.0, &format!("b2={}", v2));
            // Total should still be 1500
            r.check("total-1500", (v1 + v2 - 1500.0).abs() < 1.0, &format!("total={}", v1 + v2));
        }

        r.finish();
    }

