    /// INV-272: Cypher CREATE + SET + RETURN lifecycle
    #[tokio::test]
    async fn inv272_cypher_lifecycle() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // Create
        run(&ex, "CREATE (n:Inv272 {stage: 'created', ver: 1})");

        // Read
        let read = run(&ex, "MATCH (n:Inv272) RETURN n.stage, n.ver");
        r.check("read-1row", read.rows.len() == 1, &format!("rows={}", read.rows.len()));

        // Update
        run(&ex, "MATCH (n:Inv272) SET n.stage = 'updated', n.ver = 2");
        let updated = run(&ex, "MATCH (n:Inv272) RETURN n.stage, n.ver");
        if !updated.rows.is_empty() {
            let s = updated.rows[0][0].as_str().unwrap_or("");
            let v = val(&updated.rows[0][1]).unwrap_or(0.0);
            r.check("stage-updated", s == "updated", &format!("stage={}", s));
            r.check("ver-2", (v - 2.0).abs() < 0.5, &format!("ver={}", v));
        }

        // Delete
        run(&ex, "MATCH (n:Inv272) DELETE n");
        let gone = run(&ex, "MATCH (n:Inv272) RETURN count(n)");
        if !gone.rows.is_empty() {
            let c = val(&gone.rows[0][0]).unwrap_or(-1.0);
            r.check("deleted-0", (c - 0.0).abs() < 0.5, &format!("count={}", c));
        }

        r.finish();
    }

