    /// INV-273: SQL COUNT with WHERE = COUNT(*) minus complement
    #[tokio::test]
    async fn inv273_sql_count_complement() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let all = run_rows(&ex, "SELECT * FROM orders");
        let shipped = run_rows(&ex, "SELECT * FROM orders WHERE status = 'shipped'");
        let not_shipped = run_rows(&ex, "SELECT * FROM orders WHERE status <> 'shipped'");

        r.check("complement", all == shipped + not_shipped,
            &format!("all={} shipped={} not={} sum={}", all, shipped, not_shipped, shipped + not_shipped));

        r.finish();
    }

    /// INV-274: SQL ORDER BY stability — same query same order
    #[tokio::test]
    async fn inv274_sql_order_stability() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let r1 = run(&ex, "SELECT name FROM employees ORDER BY salary DESC");
        let r2 = run(&ex, "SELECT name FROM employees ORDER BY salary DESC");

        r.check("stable-same-len", r1.rows.len() == r2.rows.len(),
            &format!("r1={} r2={}", r1.rows.len(), r2.rows.len()));

        if r1.rows.len() == r2.rows.len() {
            let same = r1.rows.iter().zip(r2.rows.iter())
                .all(|(a, b)| a[0] == b[0]);
            r.check("stable-same-order", same, "order differs");
        }

        r.finish();
    }

