    /// INV-278: Cypher relationship direction matters
    #[tokio::test]
    async fn inv278_cypher_rel_direction() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE (a:Inv278 {name: 'parent'})-[:HAS_CHILD]->(b:Inv278 {name: 'child'})");

        // Forward: parent->child
        let fwd = run(&ex, "MATCH (a:Inv278 {name: 'parent'})-[:HAS_CHILD]->(b) RETURN b.name");
        r.check("fwd-1", fwd.rows.len() == 1, &format!("rows={}", fwd.rows.len()));

        // Reverse: child->parent (should be 0)
        let rev = run(&ex, "MATCH (a:Inv278 {name: 'child'})-[:HAS_CHILD]->(b) RETURN b.name");
        r.check("rev-0", rev.rows.len() == 0, &format!("rows={}", rev.rows.len()));

        r.finish();
    }

    /// INV-279: SQL GROUP BY with multiple aggregates
