        run(&ex, "CREATE TABLE inv283_ks.locks (id TEXT PRIMARY KEY, owner TEXT)");
        run(&ex, "INSERT INTO inv283_ks.locks (id, owner) VALUES ('lock1', 'alice')");

        // Second insert — may or may not apply (CQL IF NOT EXISTS)
        let _ = try_run(&ex, "INSERT INTO inv283_ks.locks (id, owner) VALUES ('lock1', 'bob')");

