    /// INV-308: SQL window — ROW_NUMBER partition by dept
    #[tokio::test]
    async fn inv308_sql_window_row_partition() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let res = run(&ex, "SELECT name, dept_id, ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary DESC) AS rn FROM employees");
        r.check("window-rn-6", res.rows.len() == 6, &format!("rows={}", res.rows.len()));

        // For dept 1: rn should include 1,2,3
        let dept1_rns: Vec<i64> = res.rows.iter()
            .filter(|row| val(&row[1]).map(|d| (d - 1.0).abs() < 0.5).unwrap_or(false))
            .filter_map(|row| val(&row[2]).map(|v| v as i64))
            .collect();
        if dept1_rns.len() == 3 {
            let mut sorted = dept1_rns.clone();
            sorted.sort();
            r.check("d1-rn-123", sorted == vec![1, 2, 3], &format!("rns={:?}", sorted));
        }

        r.finish();
    }

    /// INV-309: SQL empty table operations
    #[tokio::test]
    async fn inv309_sql_empty_table_ops() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv309 (id INT, val TEXT)");

        // SELECT on empty → 0 rows
        let sel = run_rows(&ex, "SELECT * FROM inv309");
        r.check("empty-select-0", sel == 0, &format!("rows={}", sel));

        // UPDATE on empty → 0 affected
        let upd = run(&ex, "UPDATE inv309 SET val = 'x' WHERE id = 1");
        r.check("empty-update-0", upd.affected_rows == Some(0), &format!("affected={:?}", upd.affected_rows));

        // DELETE on empty → 0 affected
        let del = run(&ex, "DELETE FROM inv309 WHERE id = 1");
        r.check("empty-delete-0", del.affected_rows == Some(0), &format!("affected={:?}", del.affected_rows));

        // COUNT on empty → 0
        let cnt = run(&ex, "SELECT COUNT(*) FROM inv309");
        if !cnt.rows.is_empty() {
            let c = val(&cnt.rows[0][0]).unwrap_or(-1.0);
            r.check("empty-count-0", (c - 0.0).abs() < 0.5, &format!("count={}", c));
        }

        r.finish();
    }

