    /// INV-311: SQL AVG with GROUP BY preserves min/max bounds
    #[tokio::test]
    async fn inv311_sql_avg_bounds() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let res = run(&ex, "SELECT dept_id, MIN(salary), AVG(salary), MAX(salary) FROM employees GROUP BY dept_id");
        for row in &res.rows {
            let mn = val(&row[1]).unwrap_or(0.0);
            let avg = val(&row[2]).unwrap_or(0.0);
            let mx = val(&row[3]).unwrap_or(0.0);
            let dept = val(&row[0]).unwrap_or(0.0);

            r.check(&format!("d{}-min-le-avg", dept as i64), mn <= avg + 0.01,
                &format!("d{}: min={} avg={}", dept, mn, avg));
            r.check(&format!("d{}-avg-le-max", dept as i64), avg <= mx + 0.01,
                &format!("d{}: avg={} max={}", dept, avg, mx));
        }

        r.finish();
    }

    /// INV-312: Cypher + SQL cross-paradigm — same data accessible via both
    #[tokio::test]
    async fn inv312_cross_paradigm_final() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL data
        run(&ex, "CREATE TABLE inv312_items (id INT, name TEXT)");
        run(&ex, "INSERT INTO inv312_items VALUES (1, 'item_a')");
        run(&ex, "INSERT INTO inv312_items VALUES (2, 'item_b')");

        // Cypher data
        run(&ex, "CREATE (n:Inv312Node {label: 'graph_a'})");
        run(&ex, "CREATE (n:Inv312Node {label: 'graph_b'})");
        run(&ex, "CREATE (n:Inv312Node {label: 'graph_c'})");

        // SQL query
        let sql = run_rows(&ex, "SELECT * FROM inv312_items");
        r.check("sql-2", sql == 2, &format!("sql={}", sql));

        // Cypher query
        let cy = run(&ex, "MATCH (n:Inv312Node) RETURN count(n)");
        if !cy.rows.is_empty() {
            let c = val(&cy.rows[0][0]).unwrap_or(0.0);
            r.check("cypher-3", (c - 3.0).abs() < 0.5, &format!("cypher={}", c));
        }

        // Mutate SQL, Cypher unaffected
        run(&ex, "DELETE FROM inv312_items WHERE id = 1");
        let sql2 = run_rows(&ex, "SELECT * FROM inv312_items");
        r.check("sql-after-del-1", sql2 == 1, &format!("sql={}", sql2));

        let cy2 = run(&ex, "MATCH (n:Inv312Node) RETURN count(n)");
        if !cy2.rows.is_empty() {
            let c = val(&cy2.rows[0][0]).unwrap_or(0.0);
            r.check("cypher-still-3", (c - 3.0).abs() < 0.5, &format!("cypher={}", c));
        }

        r.finish();
    }

