    /// INV-339: Cypher multi-hop + aggregate
    #[tokio::test]
    async fn inv339_cypher_multihop_agg() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // Star topology: center -> spoke1, spoke2, spoke3
        run(&ex, "CREATE (c:Inv339 {name: 'center'})-[:RAY]->(s1:Inv339 {name: 's1', val: 10})");
        run(&ex, "MATCH (c:Inv339 {name: 'center'}) CREATE (c)-[:RAY]->(s2:Inv339 {name: 's2', val: 20})");
        run(&ex, "MATCH (c:Inv339 {name: 'center'}) CREATE (c)-[:RAY]->(s3:Inv339 {name: 's3', val: 30})");

        // Count outgoing from center
        let out = run(&ex, "MATCH (c:Inv339 {name: 'center'})-[:RAY]->(s) RETURN count(s)");
        if !out.rows.is_empty() {
            let c = val(&out.rows[0][0]).unwrap_or(0.0);
            r.check("spokes-3", (c - 3.0).abs() < 0.5, &format!("count={}", c));
        }

        // Sum of spoke values
        let sum = run(&ex, "MATCH (c:Inv339 {name: 'center'})-[:RAY]->(s) RETURN sum(s.val)");
        if !sum.rows.is_empty() {
            let s = val(&sum.rows[0][0]).unwrap_or(0.0);
            r.check("spoke-sum-60", (s - 60.0).abs() < 1.0, &format!("sum={}", s));
        }

        r.finish();
    }

