        let r3 = run(&ex, "SELECT name FROM employees ORDER BY name ASC");

        if r1.rows.len() == 6 && r2.rows.len() == 6 && r3.rows.len() == 6 {
            let same_12 = r1.rows.iter().zip(r2.rows.iter()).all(|(a, b)| a[0] == b[0]);
            let same_23 = r2.rows.iter().zip(r3.rows.iter()).all(|(a, b)| a[0] == b[0]);
            r.check("deterministic-12", same_12, "r1 != r2");
            r.check("deterministic-23", same_23, "r2 != r3");

            // First should be Alice (alphabetically first)
            let first = r1.rows[0][0].as_str().unwrap_or("");
            r.check("alpha-first-alice", first == "Alice", &format!("first={}", first));
        }

