    /// INV-347: SQL SUM of subset = SUM(all) - SUM(complement)
    #[tokio::test]
    async fn inv347_sql_sum_complement() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let total = run(&ex, "SELECT SUM(salary) FROM employees");
        let dept1 = run(&ex, "SELECT SUM(salary) FROM employees WHERE dept_id = 1");
        let not1 = run(&ex, "SELECT SUM(salary) FROM employees WHERE dept_id <> 1");

        if !total.rows.is_empty() && !dept1.rows.is_empty() && !not1.rows.is_empty() {
            let t = val(&total.rows[0][0]).unwrap_or(0.0);
            let d = val(&dept1.rows[0][0]).unwrap_or(0.0);
            let n = val(&not1.rows[0][0]).unwrap_or(0.0);

            // dept1_sum = total - not_dept1_sum
            r.check("sum-complement", (d - (t - n)).abs() < 1.0,
                &format!("d1={} total-not1={}", d, t - n));
        }

        r.finish();
    }

