    /// INV-366: SQL DELETE preserves unmatched data
    #[tokio::test]
    async fn inv366_sql_delete_preserves() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let before = run_rows(&ex, "SELECT * FROM orders");
        let shipped = run_rows(&ex, "SELECT * FROM orders WHERE status = 'shipped'");

        run(&ex, "DELETE FROM orders WHERE status = 'shipped'");

        let after = run_rows(&ex, "SELECT * FROM orders");
        r.check("deleted-correct", after == before - shipped,
            &format!("before={} shipped={} after={}", before, shipped, after));

        // No shipped orders remain
        let remaining_shipped = run_rows(&ex, "SELECT * FROM orders WHERE status = 'shipped'");
        r.check("no-shipped", remaining_shipped == 0, &format!("shipped={}", remaining_shipped));

        r.finish();
    }

