        let res = run(&ex, "SELECT grp, val FROM inv379 ORDER BY grp ASC, val ASC");
        // Expect: (1,10), (1,20), (2,10), (2,30)
        let pairs: Vec<(f64, f64)> = res.rows.iter()
            .map(|row| (val(&row[0]).unwrap_or(0.0), val(&row[1]).unwrap_or(0.0)))
            .collect();
        r.check("row-count-4", pairs.len() == 4, &format!("len={}", pairs.len()));
        if pairs.len() == 4 {
            r.check("first-1-10", pairs[0] == (1.0, 10.0), &format!("{:?}", pairs[0]));
            r.check("second-1-20", pairs[1] == (1.0, 20.0), &format!("{:?}", pairs[1]));
            r.check("third-2-10", pairs[2] == (2.0, 10.0), &format!("{:?}", pairs[2]));
            r.check("fourth-2-30", pairs[3] == (2.0, 30.0), &format!("{:?}", pairs[3]));
        }

