    /// INV-380: SQL DISTINCT removes duplicates
    #[tokio::test]
    async fn inv380_sql_distinct() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let all = run(&ex, "SELECT dept_id FROM employees");
        let distinct = run(&ex, "SELECT DISTINCT dept_id FROM employees");

        r.check("distinct-fewer", distinct.rows.len() <= all.rows.len(),
            &format!("distinct={} all={}", distinct.rows.len(), all.rows.len()));
        r.check("distinct-3", distinct.rows.len() == 3, &format!("distinct={}", distinct.rows.len()));

        r.finish();
    }

