    /// INV-385: Cypher WHERE with AND/OR logic
    #[tokio::test]
    async fn inv385_cypher_where_logic() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE (a:Item385 {name: 'a', price: 10, qty: 5})");
        run(&ex, "CREATE (b:Item385 {name: 'b', price: 20, qty: 0})");
        run(&ex, "CREATE (c:Item385 {name: 'c', price: 5, qty: 10})");

        let res = run(&ex, "MATCH (n:Item385) WHERE n.price > 8 AND n.qty > 0 RETURN n.name");
        // Only 'a' matches (price 10 > 8, qty 5 > 0)
        r.check("and-1", res.rows.len() == 1, &format!("and={}", res.rows.len()));

        let res2 = run(&ex, "MATCH (n:Item385) WHERE n.price > 15 OR n.qty > 8 RETURN n.name");
        // 'b' (price 20) and 'c' (qty 10)
        r.check("or-2", res2.rows.len() == 2, &format!("or={}", res2.rows.len()));

        r.finish();
    }

