    /// INV-394: SQL UNION ALL preserves duplicates
    #[tokio::test]
    async fn inv394_sql_union_all() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let all = run(&ex, "SELECT dept_id FROM employees UNION ALL SELECT dept_id FROM employees");
        let distinct_union = run(&ex, "SELECT dept_id FROM employees UNION SELECT dept_id FROM employees");

        // UNION ALL = 2x rows; UNION = deduplicated
        r.check("all-12", all.rows.len() == 12, &format!("all={}", all.rows.len()));
        r.check("union-fewer", distinct_union.rows.len() < all.rows.len(),
            &format!("union={} all={}", distinct_union.rows.len(), all.rows.len()));

        r.finish();
    }

