    /// INV-442: SQL LIKE case sensitivity
    #[tokio::test]
    async fn inv442_sql_like_case() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv442 (name TEXT)");
        run(&ex, "INSERT INTO inv442 VALUES ('Alice')");
        run(&ex, "INSERT INTO inv442 VALUES ('alice')");
        run(&ex, "INSERT INTO inv442 VALUES ('ALICE')");

        let upper_a = run(&ex, "SELECT name FROM inv442 WHERE name LIKE 'A%'");
        let lower_a = run(&ex, "SELECT name FROM inv442 WHERE name LIKE 'a%'");

        // Case-sensitive LIKE: 'A%' matches 'Alice' and 'ALICE', 'a%' matches 'alice'
        // OR case-insensitive: all 3 match both. Either is valid.
        let total = upper_a.rows.len() + lower_a.rows.len();
        r.check("like-total", total >= 3, &format!("upper={} lower={}", upper_a.rows.len(), lower_a.rows.len()));

        r.finish();
    }

