    /// INV-449: Full-text — FTDELETE then re-index
    #[tokio::test]
    async fn inv449_ft_delete_reindex() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "FTINDEX inv449_docs d1 'original document text'");
        let before = run(&ex, "FTSEARCH inv449_docs original");
        r.check("before-1", before.rows.len() == 1, &format!("before={}", before.rows.len()));

        run(&ex, "FTDELETE inv449_docs d1");
        let deleted = run(&ex, "FTSEARCH inv449_docs original");
        r.check("deleted-0", deleted.rows.is_empty(), &format!("deleted={}", deleted.rows.len()));

        // Re-index with different content
        run(&ex, "FTINDEX inv449_docs d1 'replacement content here'");
        let replaced = run(&ex, "FTSEARCH inv449_docs replacement");
        r.check("replaced-1", replaced.rows.len() == 1, &format!("replaced={}", replaced.rows.len()));

        // Old content gone
        let old = run(&ex, "FTSEARCH inv449_docs original");
        r.check("old-gone", old.rows.is_empty(), &format!("old={}", old.rows.len()));

        r.finish();
    }

