    /// INV-456: SQL multiple ORDER BY with mixed ASC/DESC
    #[tokio::test]
    async fn inv456_sql_mixed_order() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv456 (grp INT, val INT)");
        run(&ex, "INSERT INTO inv456 VALUES (1, 10)");
        run(&ex, "INSERT INTO inv456 VALUES (1, 30)");
        run(&ex, "INSERT INTO inv456 VALUES (2, 20)");
        run(&ex, "INSERT INTO inv456 VALUES (2, 40)");

        let res = run(&ex, "SELECT grp, val FROM inv456 ORDER BY grp ASC, val DESC");
        let pairs: Vec<(f64, f64)> = res.rows.iter()
            .map(|row| (val(&row[0]).unwrap_or(0.0), val(&row[1]).unwrap_or(0.0)))
            .collect();

        if pairs.len() == 4 {
            // grp=1 first, within grp=1 val DESC (30,10)
            r.check("first-1-30", pairs[0] == (1.0, 30.0), &format!("{:?}", pairs[0]));
            r.check("second-1-10", pairs[1] == (1.0, 10.0), &format!("{:?}", pairs[1]));
            // grp=2, val DESC (40,20)
            r.check("third-2-40", pairs[2] == (2.0, 40.0), &format!("{:?}", pairs[2]));
            r.check("fourth-2-20", pairs[3] == (2.0, 20.0), &format!("{:?}", pairs[3]));
        }

        r.finish();
    }

