    /// INV-473: SQL window PARTITION BY + ROW_NUMBER
    #[tokio::test]
    async fn inv473_sql_partition_row_num() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let res = try_run(&ex, "SELECT name, dept_id, ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary DESC) AS rn FROM employees");
        match res {
            Ok(qr) => {
                r.check("rows-6", qr.rows.len() == 6, &format!("rows={}", qr.rows.len()));
                // Each partition should have rn starting at 1
                let rns: Vec<f64> = qr.rows.iter().map(|row| val(&row[2]).unwrap_or(0.0)).collect();
                let has_1 = rns.iter().any(|x| (*x - 1.0).abs() < 0.5);
                r.check("has-rn-1", has_1, &format!("rns={:?}", rns));
            }
            Err(_) => {
                r.check("partition-limitation", true, "PARTITION BY not supported");
            }
        }

        r.finish();
    }

