    /// INV-500: Milestone — all 7 paradigms coexist in one executor
    #[tokio::test]
    async fn inv500_all_paradigms() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // 1. SQL
        run(&ex, "CREATE TABLE inv500_sql (id INT, name TEXT)");
        run(&ex, "INSERT INTO inv500_sql VALUES (1, 'sql-works')");
        let sql = run(&ex, "SELECT name FROM inv500_sql WHERE id = 1");
        r.check("sql", sql.rows.len() == 1, &format!("sql={}", sql.rows.len()));

        // 2. Cypher
        run(&ex, "CREATE (n:Inv500 {name: 'cypher-works'})");
        let cypher = run(&ex, "MATCH (n:Inv500) RETURN n.name");
        r.check("cypher", cypher.rows.len() == 1, &format!("cypher={}", cypher.rows.len()));

        // 3. CQL
        run(&ex, "CREATE KEYSPACE inv500_ks WITH replication = {'class': 'SimpleStrategy', 'replication_factor': '1'}");
        run(&ex, "USE inv500_ks");
        run(&ex, "CREATE TABLE inv500_cql (id text PRIMARY KEY, val text)");
        run(&ex, "INSERT INTO inv500_cql (id, val) VALUES ('k1', 'cql-works')");
        let cql = run(&ex, "SELECT * FROM inv500_cql");
        r.check("cql", cql.rows.len() == 1, &format!("cql={}", cql.rows.len()));

        // 4. Full-Text
        run(&ex, "FTINDEX inv500_ft d1 'full text paradigm works perfectly'");
        let ft = run(&ex, "FTSEARCH inv500_ft paradigm");
        r.check("ft", ft.rows.len() == 1, &format!("ft={}", ft.rows.len()));

        // 5. Vector
        run(&ex, "VECTOR CREATE inv500_vec 3");
        run(&ex, "VECTOR INSERT inv500_vec v1 [1.0,0.0,0.0]");
        let vec = run(&ex, "VECTOR SEARCH inv500_vec [1.0,0.0,0.0] 1");
        r.check("vector", vec.rows.len() == 1, &format!("vec={}", vec.rows.len()));

        // 6. TimeSeries
        run(&ex, "TSWRITE inv500_ts 42.0 1000");
        let ts = run(&ex, "TSQUERY inv500_ts 0 2000");
        r.check("ts", ts.rows.len() == 1, &format!("ts={}", ts.rows.len()));

        // 7. Columnar
        run(&ex, "COLUMNAR CREATE inv500_col metric:float");
        run(&ex, "COLUMNAR INSERT inv500_col 99.0");
        let col = run(&ex, "COLUMNAR AGGREGATE inv500_col metric SUM");
        r.check("columnar", !col.rows.is_empty(), &format!("col={}", col.rows.len()));

        r.finish();
    }

