    /// INV-515: Cypher CREATE + MATCH + SET + verify updated
    #[tokio::test]
    async fn inv515_cypher_crud() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // Create
        run(&ex, "CREATE (n:C515 {name: 'item', qty: 5})");

        // Read
        let read = run(&ex, "MATCH (n:C515) WHERE n.name = 'item' RETURN n.qty");
        if !read.rows.is_empty() {
            let q = val(&read.rows[0][0]).unwrap_or(0.0);
            r.check("initial-5", (q - 5.0).abs() < 0.5, &format!("qty={}", q));
        }

        // Update
        run(&ex, "MATCH (n:C515) WHERE n.name = 'item' SET n.qty = 10");
        let updated = run(&ex, "MATCH (n:C515) WHERE n.name = 'item' RETURN n.qty");
        if !updated.rows.is_empty() {
            let q = val(&updated.rows[0][0]).unwrap_or(0.0);
            r.check("updated-10", (q - 10.0).abs() < 0.5, &format!("qty={}", q));
        }

        // Delete
        run(&ex, "MATCH (n:C515) WHERE n.name = 'item' DELETE n");
        let deleted = run(&ex, "MATCH (n:C515) RETURN count(n)");
        let cnt = val(&deleted.rows[0][0]).unwrap_or(1.0);
        r.check("deleted-0", (cnt - 0.0).abs() < 0.5, &format!("cnt={}", cnt));

        r.finish();
    }

