    /// INV-550: SQL cascading operations — INSERT, UPDATE, DELETE, verify
    #[tokio::test]
    async fn inv550_sql_cascade_ops() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv550 (id INT, val INT)");

        // Insert 10 rows
        for i in 1..=10 { run(&ex, &format!("INSERT INTO inv550 VALUES ({}, {})", i, i * 10)); }
        let c1 = val(&run(&ex, "SELECT COUNT(*) FROM inv550").rows[0][0]).unwrap_or(0.0);
        r.check("insert-10", (c1 - 10.0).abs() < 0.5, &format!("c1={}", c1));

        // Update odd ids
        run(&ex, "UPDATE inv550 SET val = val + 1000 WHERE id IN (1, 3, 5, 7, 9)");
        let high = run(&ex, "SELECT COUNT(*) FROM inv550 WHERE val > 100");
        let h = val(&high.rows[0][0]).unwrap_or(0.0);
        r.check("updated-5", (h - 5.0).abs() < 0.5, &format!("high={}", h));

        // Delete low values (20,40,60,80 — id=10 has val=100 so NOT deleted)
        run(&ex, "DELETE FROM inv550 WHERE val < 100");
        let c2 = val(&run(&ex, "SELECT COUNT(*) FROM inv550").rows[0][0]).unwrap_or(0.0);
        r.check("after-delete-6", (c2 - 6.0).abs() < 0.5, &format!("c2={}", c2));

        r.finish();
    }

