    /// INV-573: SQL GROUP BY preserves all rows via SUM identity
    #[tokio::test]
    async fn inv573_sql_group_sum_identity() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv573 (grp INT, val INT)");
        let mut total = 0;
        for i in 1..=20 {
            let grp = (i % 4) + 1;
            run(&ex, &format!("INSERT INTO inv573 VALUES ({}, {})", grp, i));
            total += i;
        }

        let groups = run(&ex, "SELECT grp, SUM(val) FROM inv573 GROUP BY grp");
        let group_sum: f64 = groups.rows.iter().map(|row| val(&row[1]).unwrap_or(0.0)).sum();
        r.check("sum-identity", (group_sum - total as f64).abs() < 1.0,
            &format!("group_sum={} total={}", group_sum, total));
        r.check("4-groups", groups.rows.len() == 4, &format!("groups={}", groups.rows.len()));

        r.finish();
    }

