    // ── Batch 65: INV-593 through INV-602 ───────────────────────────
    // Post-fix validation: NTILE, threshold identifier, UNION error, EXCEPT/INTERSECT mismatch

    /// INV-593: SQL NTILE window function — 3 buckets over 6 rows
    #[tokio::test]
    async fn inv593_sql_ntile() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let res = try_run(&ex, "SELECT name, NTILE(3) OVER (ORDER BY salary DESC) AS bucket FROM employees");
        match res {
            Ok(qr) => {
                r.check("rows-6", qr.rows.len() == 6, &format!("rows={}", qr.rows.len()));
                let buckets: Vec<f64> = qr.rows.iter().map(|row| val(&row[1]).unwrap_or(0.0)).collect();
                // NTILE(3) over 6 rows: 2 in bucket 1, 2 in bucket 2, 2 in bucket 3
                let count1 = buckets.iter().filter(|b| (**b - 1.0).abs() < 0.5).count();
                let count2 = buckets.iter().filter(|b| (**b - 2.0).abs() < 0.5).count();
                let count3 = buckets.iter().filter(|b| (**b - 3.0).abs() < 0.5).count();
                r.check("bucket1-count-2", count1 == 2, &format!("bucket1={}", count1));
                r.check("bucket2-count-2", count2 == 2, &format!("bucket2={}", count2));
                r.check("bucket3-count-2", count3 == 2, &format!("bucket3={}", count3));
                // All buckets in [1,3]
                let all_valid = buckets.iter().all(|b| *b >= 1.0 && *b <= 3.0);
                r.check("all-in-1-3", all_valid, &format!("buckets={:?}", buckets));
            }
            Err(e) => {
                r.check("ntile-supported", false, &format!("NTILE failed: {}", e));
            }
        }

        r.finish();
    }

    /// INV-594: SQL NTILE(4) over 6 rows — uneven distribution
    #[tokio::test]
    async fn inv594_sql_ntile_uneven() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let res = try_run(&ex, "SELECT name, NTILE(4) OVER (ORDER BY salary) AS bucket FROM employees");
        match res {
            Ok(qr) => {
                r.check("rows-6", qr.rows.len() == 6, &format!("rows={}", qr.rows.len()));
                let buckets: Vec<f64> = qr.rows.iter().map(|row| val(&row[1]).unwrap_or(0.0)).collect();
                // NTILE(4) over 6: floor(i*4/6)+1 — buckets: 1,1,2,2,3,4
                let all_in_range = buckets.iter().all(|b| *b >= 1.0 && *b <= 4.0);
                r.check("all-in-1-4", all_in_range, &format!("buckets={:?}", buckets));
                // Every bucket 1..4 should appear at least once
                for b in 1..=4 {
                    let cnt = buckets.iter().filter(|v| (**v - b as f64).abs() < 0.5).count();
                    r.check(&format!("bucket-{}-present", b), cnt >= 1, &format!("bucket {} count={}", b, cnt));
                }
            }
            Err(e) => {
                r.check("ntile4-supported", false, &format!("NTILE(4) failed: {}", e));
            }
        }

        r.finish();
    }

