    /// INV-617: Multi-column ORDER BY — primary then secondary
    #[tokio::test]
    async fn inv617_multi_order_by() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let res = run(&ex, "SELECT name, dept_id, salary FROM employees ORDER BY dept_id ASC, salary DESC");
        r.check("rows-6", res.rows.len() == 6, &format!("rows={}", res.rows.len()));
        // Within each dept, salary should be descending
        let mut prev_dept = 0.0_f64;
        let mut prev_sal = f64::MAX;
        for row in &res.rows {
            let d = val(&row[1]).unwrap_or(0.0);
            let s = val(&row[2]).unwrap_or(0.0);
            if d > prev_dept {
                prev_sal = f64::MAX; // reset for new department
            }
            r.check("dept-asc", d >= prev_dept, &format!("dept {} < prev {}", d, prev_dept));
            r.check("sal-desc-in-dept", s <= prev_sal, &format!("sal {} > prev {} in dept {}", s, prev_sal, d));
            prev_dept = d;
            prev_sal = s;
        }

        r.finish();
    }

