    // ── Batch 67: INV-623 through INV-642 ───────────────────────────
    // Window frames, nested expressions, division, type coercion, aliased columns

    /// INV-623: Division by zero returns NULL or error (not crash)
    #[tokio::test]
    async fn inv623_division_by_zero() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv623 (id INT, num INT, denom INT)");
        run(&ex, "INSERT INTO inv623 VALUES (1, 10, 2)");
        run(&ex, "INSERT INTO inv623 VALUES (2, 10, 0)");

        let res = try_run(&ex, "SELECT id, num / denom FROM inv623 ORDER BY id");
        match res {
            Ok(qr) => {
                r.check("rows-2", qr.rows.len() == 2, &format!("rows={}", qr.rows.len()));
                if qr.rows.len() == 2 {
                    let v1 = val(&qr.rows[0][1]).unwrap_or(-1.0);
                    r.check("10/2=5", (v1 - 5.0).abs() < 0.5, &format!("10/2={}", v1));
                    // 10/0 should be NULL (SQL standard) or error, not panic
                    let v2_null = qr.rows[1][1].is_null();
                    let v2_inf = val(&qr.rows[1][1]).map(|v| v.is_infinite()).unwrap_or(false);
                    r.check("div0-safe", v2_null || v2_inf, &format!("10/0={:?}", qr.rows[1][1]));
                }
            }
            Err(_) => {
                // Error on division by zero is also acceptable
                r.check("div0-error-ok", true, "div by zero returns error");
            }
        }

        r.finish();
    }

