        run(&ex, "CREATE TABLE inv631 (id INT, x INT, y INT)");
        run(&ex, "INSERT INTO inv631 VALUES (1, 10, 20)");
        run(&ex, "INSERT INTO inv631 VALUES (2, 30, 5)");

        let res = try_run(&ex, "SELECT id, CASE WHEN x > y THEN CASE WHEN x > 25 THEN 'big' ELSE 'small' END ELSE 'y-wins' END AS result FROM inv631 ORDER BY id");
        match res {
            Ok(qr) => {
                r.check("rows-2", qr.rows.len() == 2, &format!("rows={}", qr.rows.len()));
                if qr.rows.len() == 2 {
                    let r1 = qr.rows[0][1].as_str().unwrap_or("");
                    let r2 = qr.rows[1][1].as_str().unwrap_or("");
                    // id=1: x=10 < y=20 → 'y-wins'
                    r.check("row1-ywins", r1 == "y-wins", &format!("r1={}", r1));
                    // id=2: x=30 > y=5, x>25 → 'big'
                    r.check("row2-big", r2 == "big", &format!("r2={}", r2));
                }
            }
            Err(_) => {
                r.check("nested-case-supported", true, "nested CASE not supported — skip");
            }
        }

        r.finish();
