    /// INV-633: LIMIT + OFFSET pagination
    #[tokio::test]
    async fn inv633_limit_offset() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let page1 = run(&ex, "SELECT name FROM employees ORDER BY id LIMIT 2 OFFSET 0");
        let page2 = run(&ex, "SELECT name FROM employees ORDER BY id LIMIT 2 OFFSET 2");
        let page3 = run(&ex, "SELECT name FROM employees ORDER BY id LIMIT 2 OFFSET 4");

        r.check("page1-2", page1.rows.len() == 2, &format!("p1={}", page1.rows.len()));
        r.check("page2-2", page2.rows.len() == 2, &format!("p2={}", page2.rows.len()));
        r.check("page3-2", page3.rows.len() == 2, &format!("p3={}", page3.rows.len()));

        // No overlap between pages
        let p1_names: Vec<&str> = page1.rows.iter().filter_map(|r| r[0].as_str()).collect();
        let p2_names: Vec<&str> = page2.rows.iter().filter_map(|r| r[0].as_str()).collect();
        let p3_names: Vec<&str> = page3.rows.iter().filter_map(|r| r[0].as_str()).collect();
        let no_overlap = p1_names.iter().all(|n| !p2_names.contains(n) && !p3_names.contains(n));
        r.check("no-overlap", no_overlap, &format!("p1={:?} p2={:?} p3={:?}", p1_names, p2_names, p3_names));

        r.finish();
    }

