    /// INV-662: DENSE_RANK window function — no gaps
    #[tokio::test]
    async fn inv662_dense_rank() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv662 (id INT, score INT)");
        run(&ex, "INSERT INTO inv662 VALUES (1, 100)");
        run(&ex, "INSERT INTO inv662 VALUES (2, 100)");
        run(&ex, "INSERT INTO inv662 VALUES (3, 90)");
        run(&ex, "INSERT INTO inv662 VALUES (4, 80)");

        let res = try_run(&ex, "SELECT id, DENSE_RANK() OVER (ORDER BY score DESC) AS dr FROM inv662 ORDER BY id");
        match res {
            Ok(qr) => {
                r.check("rows-4", qr.rows.len() == 4, &format!("rows={}", qr.rows.len()));
                let ranks: Vec<f64> = qr.rows.iter().map(|row| val(&row[1]).unwrap_or(0.0)).collect();
                // score 100,100,90,80 → DENSE_RANK: 1,1,2,3 (no gaps)
                // id order: 1→100(dr=1), 2→100(dr=1), 3→90(dr=2), 4→80(dr=3)
                r.check("id1-rank1", (ranks[0] - 1.0).abs() < 0.5, &format!("r1={}", ranks[0]));
                r.check("id2-rank1", (ranks[1] - 1.0).abs() < 0.5, &format!("r2={}", ranks[1]));
                r.check("id3-rank2", (ranks[2] - 2.0).abs() < 0.5, &format!("r3={}", ranks[2]));
                r.check("id4-rank3", (ranks[3] - 3.0).abs() < 0.5, &format!("r4={}", ranks[3]));
            }
            Err(_) => {
                r.check("dense-rank-supported", true, "DENSE_RANK not supported — skip");
            }
        }

        r.finish();
    }

