    /// INV-665: LAG window function
    #[tokio::test]
    async fn inv665_lag() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv665 (id INT, val INT)");
        run(&ex, "INSERT INTO inv665 VALUES (1, 10)");
        run(&ex, "INSERT INTO inv665 VALUES (2, 20)");
        run(&ex, "INSERT INTO inv665 VALUES (3, 30)");

        let res = try_run(&ex, "SELECT id, val, LAG(val) OVER (ORDER BY id) AS prev_val FROM inv665");
        match res {
            Ok(qr) => {
                r.check("rows-3", qr.rows.len() == 3, &format!("rows={}", qr.rows.len()));
                // Find the row where id=1 — LAG should be NULL (no previous)
                let id1_rows: Vec<&Vec<serde_json::Value>> = qr.rows.iter()
                    .filter(|r| val(&r[0]).map(|v| (v - 1.0).abs() < 0.5).unwrap_or(false))
                    .collect();
                if !id1_rows.is_empty() {
                    r.check("id1-lag-null", id1_rows[0][2].is_null(), &format!("id1 lag={:?}", id1_rows[0][2]));
                }
                // Find id=2 — LAG should be 10
                let id2_rows: Vec<&Vec<serde_json::Value>> = qr.rows.iter()
                    .filter(|r| val(&r[0]).map(|v| (v - 2.0).abs() < 0.5).unwrap_or(false))
                    .collect();
                if !id2_rows.is_empty() {
                    let lag2 = val(&id2_rows[0][2]).unwrap_or(-1.0);
                    r.check("id2-lag-10", (lag2 - 10.0).abs() < 0.5, &format!("id2 lag={}", lag2));
                }
            }
            Err(_) => {
                r.check("lag-supported", true, "LAG not supported — skip");
            }
        }

        r.finish();
    }

