    /// INV-676: GROUP BY with ORDER BY on aggregate
    #[tokio::test]
    async fn inv676_group_order_agg() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let res = try_run(&ex, "SELECT dept_id, SUM(salary) AS total FROM employees GROUP BY dept_id ORDER BY total DESC");
        match res {
            Ok(qr) => {
                r.check("groups-3", qr.rows.len() == 3, &format!("rows={}", qr.rows.len()));
                let totals: Vec<f64> = qr.rows.iter().map(|r| val(&r[1]).unwrap_or(0.0)).collect();
                let sorted = totals.windows(2).all(|w| w[0] >= w[1]);
                r.check("desc-sorted", sorted, &format!("totals={:?}", totals));
                // dept1: 120k+110k+130k=360k, dept2: 95k+85k=180k, dept3: 90k
                r.check("first-360k", (totals[0] - 360000.0).abs() < 1.0, &format!("first={}", totals[0]));
            }
            Err(e) => {
                r.check("group-order-agg-ok", false, &format!("failed: {}", e));
            }
        }

        r.finish();
    }

