        r.check("rows-4", res.rows.len() == 4, &format!("rows={}", res.rows.len()));
        // Non-null values should be sorted ascending; NULL position varies by engine
        let non_null_vals: Vec<f64> = res.rows.iter()
            .filter_map(|r| val(&r[1]))
            .collect();
        let sorted = non_null_vals.windows(2).all(|w| w[0] <= w[1]);
