    /// INV-700: Large INSERT + aggregate stress
    #[tokio::test]
    async fn inv700_large_aggregate() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv700 (id INT, val INT)");
        let mut sql = String::from("INSERT INTO inv700 VALUES ");
        for i in 1..=200 {
            if i > 1 { sql.push_str(", "); }
            sql.push_str(&format!("({}, {})", i, i));
        }
        run(&ex, &sql);

        let res = run(&ex, "SELECT COUNT(*), SUM(val), MIN(val), MAX(val) FROM inv700");
        let cnt = val(&res.rows[0][0]).unwrap_or(0.0);
        let sum = val(&res.rows[0][1]).unwrap_or(0.0);
        let mn = val(&res.rows[0][2]).unwrap_or(0.0);
        let mx = val(&res.rows[0][3]).unwrap_or(0.0);

        r.check("count-200", (cnt - 200.0).abs() < 0.5, &format!("count={}", cnt));
        // SUM(1..200) = 200*201/2 = 20100
        r.check("sum-20100", (sum - 20100.0).abs() < 0.5, &format!("sum={}", sum));
        r.check("min-1", (mn - 1.0).abs() < 0.5, &format!("min={}", mn));
        r.check("max-200", (mx - 200.0).abs() < 0.5, &format!("max={}", mx));

        r.finish();
    }

