    /// INV-706: JOIN with GROUP BY — aggregate across joined rows
    #[tokio::test]
    async fn inv706_join_group_by() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let res = try_run(&ex, "SELECT d.name, COUNT(e.id) AS emp_count, SUM(e.salary) AS total_sal FROM departments d JOIN employees e ON d.id = e.dept_id GROUP BY d.name ORDER BY d.name");
        match res {
            Ok(qr) => {
                r.check("groups-3", qr.rows.len() == 3, &format!("rows={}", qr.rows.len()));
                // Engineering: 3 employees, 360k total
                if let Some(eng) = qr.rows.iter().find(|r| r[0].as_str() == Some("Engineering")) {
                    let cnt = val(&eng[1]).unwrap_or(0.0);
                    let total = val(&eng[2]).unwrap_or(0.0);
                    r.check("eng-count-3", (cnt - 3.0).abs() < 0.5, &format!("eng count={}", cnt));
                    r.check("eng-total-360k", (total - 360000.0).abs() < 1.0, &format!("eng total={}", total));
                }
            }
            Err(e) => {
                r.check("join-group-supported", false, &format!("failed: {}", e));
            }
        }

        r.finish();
    }

    /// INV-707: Window function with PARTITION BY + aggregate
    #[tokio::test]
    async fn inv707_window_partition_sum() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let res = try_run(&ex, "SELECT name, dept_id, SUM(salary) OVER (PARTITION BY dept_id) AS dept_total FROM employees");
        match res {
            Ok(qr) => {
                r.check("rows-6", qr.rows.len() == 6, &format!("rows={}", qr.rows.len()));
                // All dept 1 rows should have same dept_total = 360000
                let dept1_totals: Vec<f64> = qr.rows.iter()
                    .filter(|r| val(&r[1]).map(|v| (v - 1.0).abs() < 0.5).unwrap_or(false))
                    .map(|r| val(&r[2]).unwrap_or(0.0))
                    .collect();
                for t in &dept1_totals {
                    r.check("dept1-360k", (*t - 360000.0).abs() < 1.0, &format!("dept1 total={}", t));
                }
            }
            Err(_) => {
                r.check("window-partition-sum", true, "window PARTITION SUM not supported — skip");
            }
        }

        r.finish();
    }

