    /// INV-746: De Morgan's law — NOT(A AND B) = (NOT A) OR (NOT B)
    #[tokio::test]
    async fn inv746_de_morgan_and() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let lhs = run(&ex, "SELECT COUNT(*) FROM employees WHERE NOT (dept_id = 1 AND salary > 115000)");
        let rhs = run(&ex, "SELECT COUNT(*) FROM employees WHERE dept_id != 1 OR salary <= 115000");

        let l = val(&lhs.rows[0][0]).unwrap_or(-1.0);
        let rv = val(&rhs.rows[0][0]).unwrap_or(-1.0);
        r.check("de-morgan-and", (l - rv).abs() < 0.5, &format!("NOT(A AND B)={} vs (NOT A OR NOT B)={}", l, rv));

        r.finish();
    }

    /// INV-747: De Morgan's law — NOT(A OR B) = (NOT A) AND (NOT B)
