    /// INV-752: SUM over UNION ALL = SUM(A) + SUM(B)
    #[tokio::test]
    async fn inv752_sum_union_all() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv752_a (val INT)");
        run(&ex, "CREATE TABLE inv752_b (val INT)");
        run(&ex, "INSERT INTO inv752_a VALUES (10), (20), (30)");
        run(&ex, "INSERT INTO inv752_b VALUES (40), (50)");

        let sum_a = run(&ex, "SELECT SUM(val) FROM inv752_a");
        let sum_b = run(&ex, "SELECT SUM(val) FROM inv752_b");
        let sum_union = try_run(&ex, "SELECT SUM(val) FROM (SELECT val FROM inv752_a UNION ALL SELECT val FROM inv752_b) AS t");

        let sa = val(&sum_a.rows[0][0]).unwrap_or(0.0);
        let sb = val(&sum_b.rows[0][0]).unwrap_or(0.0);
        match sum_union {
            Ok(qr) => {
                let su = val(&qr.rows[0][0]).unwrap_or(0.0);
                r.check("sum-additive", (su - sa - sb).abs() < 0.5, &format!("sum_union={} sum_a+b={}", su, sa + sb));
            }
            Err(_) => {
                r.check("sum-union-supported", true, "SUM over UNION ALL subquery not supported — skip");
            }
        }

        r.finish();
    }

    /// INV-753: COUNT monotonicity — adding rows never decreases COUNT
    #[tokio::test]
    async fn inv753_count_monotonic() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv753 (id INT, val INT)");
        run(&ex, "INSERT INTO inv753 VALUES (1, 10)");

        let c1 = run(&ex, "SELECT COUNT(*) FROM inv753");
        let cnt1 = val(&c1.rows[0][0]).unwrap_or(0.0);

        run(&ex, "INSERT INTO inv753 VALUES (2, 20)");
        let c2 = run(&ex, "SELECT COUNT(*) FROM inv753");
        let cnt2 = val(&c2.rows[0][0]).unwrap_or(0.0);

        run(&ex, "INSERT INTO inv753 VALUES (3, 30)");
        let c3 = run(&ex, "SELECT COUNT(*) FROM inv753");
        let cnt3 = val(&c3.rows[0][0]).unwrap_or(0.0);

        r.check("monotonic-1-2", cnt2 >= cnt1, &format!("c1={} c2={}", cnt1, cnt2));
        r.check("monotonic-2-3", cnt3 >= cnt2, &format!("c2={} c3={}", cnt2, cnt3));
        r.check("final-3", (cnt3 - 3.0).abs() < 0.5, &format!("final={}", cnt3));

        r.finish();
    }

    /// INV-754: MIN <= AVG <= MAX invariant
    #[tokio::test]
    async fn inv754_min_avg_max() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let res = run(&ex, "SELECT MIN(salary), AVG(salary), MAX(salary) FROM employees");
        let mn = val(&res.rows[0][0]).unwrap_or(0.0);
        let avg = val(&res.rows[0][1]).unwrap_or(0.0);
        let mx = val(&res.rows[0][2]).unwrap_or(0.0);

        r.check("min-le-avg", mn <= avg, &format!("min={} avg={}", mn, avg));
        r.check("avg-le-max", avg <= mx, &format!("avg={} max={}", avg, mx));
        r.check("min-le-max", mn <= mx, &format!("min={} max={}", mn, mx));

        r.finish();
    }

