    /// INV-757: LIMIT n rows <= n
    #[tokio::test]
    async fn inv757_limit_upper_bound() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        for limit in [1, 3, 5, 10, 100] {
            let res = run(&ex, &format!("SELECT * FROM employees LIMIT {}", limit));
            let expected_max = limit.min(6); // only 6 employees
            r.check(
                &format!("limit-{}-le", limit),
                res.rows.len() <= limit,
                &format!("limit {} got {}", limit, res.rows.len()),
            );
            r.check(
                &format!("limit-{}-eq", limit),
                res.rows.len() == expected_max,
                &format!("limit {} expected {} got {}", limit, expected_max, res.rows.len()),
            );
        }

        r.finish();
    }

    /// INV-758: GROUP BY produces <= total rows
    #[tokio::test]
    async fn inv758_group_le_total() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let total = run(&ex, "SELECT COUNT(*) FROM employees");
        let groups = run(&ex, "SELECT dept_id, COUNT(*) FROM employees GROUP BY dept_id");

        let t = val(&total.rows[0][0]).unwrap_or(0.0);
        r.check("groups-le-total", (groups.rows.len() as f64) <= t, &format!("groups={} total={}", groups.rows.len(), t));

        // Sum of group counts = total
        let group_sum: f64 = groups.rows.iter().map(|r| val(&r[1]).unwrap_or(0.0)).sum();
        r.check("group-sum-eq-total", (group_sum - t).abs() < 0.5, &format!("group_sum={} total={}", group_sum, t));

        r.finish();
    }

    /// INV-759: INNER JOIN result <= cross product
    #[tokio::test]
    async fn inv759_join_le_cross() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv759_a (id INT)");
        run(&ex, "CREATE TABLE inv759_b (aid INT)");
        run(&ex, "INSERT INTO inv759_a VALUES (1), (2), (3)");
        run(&ex, "INSERT INTO inv759_b VALUES (1), (2)");

        let inner = try_run(&ex, "SELECT a.id, b.aid FROM inv759_a a JOIN inv759_b b ON a.id = b.aid");
        match inner {
            Ok(qr) => {
                // Cross product = 3×2 = 6; inner join should be <= 6
                r.check("join-le-cross", qr.rows.len() <= 6, &format!("join={}", qr.rows.len()));
                r.check("join-2", qr.rows.len() == 2, &format!("join={}", qr.rows.len()));
            }
            Err(e) => {
                r.check("join-ok", false, &format!("failed: {}", e));
            }
        }

        r.finish();
    }

