    /// INV-775: LIKE case sensitivity
    #[tokio::test]
    async fn inv775_like_case() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let upper = run(&ex, "SELECT COUNT(*) FROM employees WHERE name LIKE 'a%'");
        let lower = run(&ex, "SELECT COUNT(*) FROM employees WHERE name LIKE 'A%'");

        let u = val(&upper.rows[0][0]).unwrap_or(-1.0);
        let l = val(&lower.rows[0][0]).unwrap_or(-1.0);

        // Standard SQL: LIKE is case-sensitive. 'A%' matches Alice, 'a%' matches nothing
        r.check("upper-a-match", (l - 1.0).abs() < 0.5, &format!("A%={}", l));
        // 'a%' should match 0 in case-sensitive LIKE
        r.check("lower-a-distinct", u != l || (u - 1.0).abs() < 0.5, &format!("a%={} A%={}", u, l));

        r.finish();
    }

