    /// INV-779: Window function with all same values — ties
    #[tokio::test]
    async fn inv779_window_ties() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv779 (id INT, val INT)");
        run(&ex, "INSERT INTO inv779 VALUES (1, 100)");
        run(&ex, "INSERT INTO inv779 VALUES (2, 100)");
        run(&ex, "INSERT INTO inv779 VALUES (3, 100)");

        let res = try_run(&ex, "SELECT id, RANK() OVER (ORDER BY val) AS rnk, DENSE_RANK() OVER (ORDER BY val) AS drnk FROM inv779");
        match res {
            Ok(qr) => {
                r.check("rows-3", qr.rows.len() == 3, &format!("rows={}", qr.rows.len()));
                // All same value → RANK = 1 for all, DENSE_RANK = 1 for all
                let ranks: Vec<f64> = qr.rows.iter().map(|r| val(&r[1]).unwrap_or(0.0)).collect();
                let dranks: Vec<f64> = qr.rows.iter().map(|r| val(&r[2]).unwrap_or(0.0)).collect();
                let all_rank1 = ranks.iter().all(|r| (*r - 1.0).abs() < 0.5);
                let all_drank1 = dranks.iter().all(|r| (*r - 1.0).abs() < 0.5);
                r.check("all-rank-1", all_rank1, &format!("ranks={:?}", ranks));
                r.check("all-drank-1", all_drank1, &format!("dranks={:?}", dranks));
            }
            Err(_) => {
                r.check("window-ties", true, "window ties not supported — skip");
            }
        }

        r.finish();
    }

