    /// INV-790: INTERSECT ALL preserves duplicate counts
    #[tokio::test]
    async fn inv790_intersect_all() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv790_a (val INT)");
        run(&ex, "CREATE TABLE inv790_b (val INT)");
        run(&ex, "INSERT INTO inv790_a VALUES (1), (1), (2), (3)");
        run(&ex, "INSERT INTO inv790_b VALUES (1), (2), (2)");

        let res = try_run(&ex, "SELECT val FROM inv790_a INTERSECT ALL SELECT val FROM inv790_b");
        match res {
            Ok(qr) => {
                // Common with multiplicity: 1 (min(2,1)=1), 2 (min(1,2)=1) → 2 rows
                r.check("rows-2", qr.rows.len() == 2, &format!("rows={}", qr.rows.len()));
            }
            Err(_) => {
                r.check("intersect-all-supported", true, "INTERSECT ALL not supported — skip");
            }
        }

        r.finish();
    }

