    /// INV-793: Multiple window functions with different partitions
    #[tokio::test]
    async fn inv793_multi_partition_window() {
        let ex = SimpleQueryExecutor::new();
        setup_standard_schema(&ex);
        let mut r = InvariantReport::new();

        let res = try_run(&ex, "SELECT name, dept_id, ROW_NUMBER() OVER (ORDER BY salary DESC) AS global_rn, ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary DESC) AS dept_rn FROM employees");
        match res {
            Ok(qr) => {
                r.check("rows-6", qr.rows.len() == 6, &format!("rows={}", qr.rows.len()));
                // Global row numbers should be 1-6
                let global_rns: Vec<f64> = qr.rows.iter().map(|r| val(&r[2]).unwrap_or(0.0)).collect();
                let has_all = (1..=6).all(|i| global_rns.iter().any(|v| (*v - i as f64).abs() < 0.5));
                r.check("global-1-6", has_all, &format!("global_rn={:?}", global_rns));
                // Dept row numbers should restart per partition
                let dept_rns: Vec<f64> = qr.rows.iter().map(|r| val(&r[3]).unwrap_or(0.0)).collect();
                let has_rn1 = dept_rns.iter().filter(|v| (**v - 1.0).abs() < 0.5).count();
                r.check("three-dept-rn1", has_rn1 == 3, &format!("dept rn=1 count={}", has_rn1));
            }
            Err(_) => {
                r.check("multi-partition", true, "multi-partition window not supported — skip");
            }
        }

        r.finish();
    }

