    /// INV-799: NTILE(n) where n > row count
    #[tokio::test]
    async fn inv799_ntile_more_buckets() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv799 (id INT)");
        run(&ex, "INSERT INTO inv799 VALUES (1), (2), (3)");

        let res = try_run(&ex, "SELECT id, NTILE(10) OVER (ORDER BY id) AS bucket FROM inv799");
        match res {
            Ok(qr) => {
                r.check("rows-3", qr.rows.len() == 3, &format!("rows={}", qr.rows.len()));
                let buckets: Vec<f64> = qr.rows.iter().map(|r| val(&r[1]).unwrap_or(0.0)).collect();
                // With 3 rows and 10 buckets, each row gets its own bucket: 1,2,3
                let all_valid = buckets.iter().all(|b| *b >= 1.0 && *b <= 10.0);
                r.check("valid-range", all_valid, &format!("buckets={:?}", buckets));
                // All buckets should be distinct (one per row)
                let unique: std::collections::HashSet<i64> = buckets.iter().map(|b| *b as i64).collect();
                r.check("all-unique", unique.len() == 3, &format!("unique={}", unique.len()));
            }
            Err(_) => {
                r.check("ntile-more-supported", true, "NTILE(n>rows) not supported — skip");
            }
        }

        r.finish();
    }

