    /// INV-803: EXCEPT removes rows from first set that appear in second
    #[tokio::test]
    async fn inv803_except_basic() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        setup_standard_schema(&ex);

        let all = run_rows(&ex, "SELECT id FROM employees");
        let high = run_rows(&ex, "SELECT id FROM employees WHERE salary >= 100000");
        let except = run_rows(&ex, "SELECT id FROM employees EXCEPT SELECT id FROM employees WHERE salary >= 100000");

        r.check("except-count", except == all - high,
            &format!("except={}, all={}, high={}", except, all, high));

        r.finish();
    }

    /// INV-804: Multiple aggregates in one SELECT
    #[tokio::test]
    async fn inv804_multi_agg() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        setup_standard_schema(&ex);

        let qr = run(&ex, "SELECT COUNT(*) as c, SUM(salary) as s, AVG(salary) as a, MIN(salary) as mn, MAX(salary) as mx FROM employees");
        r.check("one-row", qr.rows.len() == 1, &format!("rows={}", qr.rows.len()));
        let c = val(&qr.rows[0][0]).unwrap_or(0.0);
        let s = val(&qr.rows[0][1]).unwrap_or(0.0);
        let a = val(&qr.rows[0][2]).unwrap_or(0.0);
        let mn = val(&qr.rows[0][3]).unwrap_or(0.0);
        let mx = val(&qr.rows[0][4]).unwrap_or(0.0);

        r.check("avg-eq-sum-div-count", (a - s / c).abs() < 0.5,
            &format!("avg={}, sum/count={}", a, s / c));
        r.check("min-le-avg", mn <= a + 0.5, &format!("min={}, avg={}", mn, a));
        r.check("avg-le-max", a <= mx + 0.5, &format!("avg={}, max={}", a, mx));

        r.finish();
    }

    /// INV-805: WHERE with multiple AND conditions narrows progressively
    #[tokio::test]
    async fn inv805_progressive_filter() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        setup_standard_schema(&ex);

        let c1 = run_rows(&ex, "SELECT id FROM employees WHERE salary > 80000");
        let c2 = run_rows(&ex, "SELECT id FROM employees WHERE salary > 80000 AND dept_id = 1");
        let c3 = run_rows(&ex, "SELECT id FROM employees WHERE salary > 80000 AND dept_id = 1 AND salary > 115000");

        r.check("filter-narrows-1", c2 <= c1, &format!("c2={} <= c1={}", c2, c1));
        r.check("filter-narrows-2", c3 <= c2, &format!("c3={} <= c2={}", c3, c2));

        r.finish();
    }

    /// INV-806: ORDER BY DESC is reverse of ASC
    #[tokio::test]
    async fn inv806_order_reverse() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        setup_standard_schema(&ex);

        let asc_qr = run(&ex, "SELECT salary FROM employees ORDER BY salary ASC");
        let desc_qr = run(&ex, "SELECT salary FROM employees ORDER BY salary DESC");

        r.check("same-count", asc_qr.rows.len() == desc_qr.rows.len(), "counts differ");
        let mut reversed = desc_qr.rows.clone();
        reversed.reverse();
        for i in 0..asc_qr.rows.len() {
            let a = val(&asc_qr.rows[i][0]).unwrap_or(-1.0);
            let d = val(&reversed[i][0]).unwrap_or(-2.0);
            r.check(&format!("pos-{}", i), (a - d).abs() < 0.5,
                &format!("asc[{}]={}, rev-desc[{}]={}", i, a, i, d));
        }

        r.finish();
    }

    /// INV-807: LEFT JOIN preserves all left rows
