    /// INV-818: Nested CASE expressions
    #[tokio::test]
    async fn inv818_nested_case() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        setup_standard_schema(&ex);

        let qr = run(&ex, "SELECT name, CASE WHEN salary > 100000 THEN CASE WHEN dept_id = 1 THEN 'high-eng' ELSE 'high-other' END ELSE 'standard' END as tier FROM employees ORDER BY name");

        for row in &qr.rows {
            let name = row[0].as_str().unwrap_or("");
            let tier = row[1].as_str().unwrap_or("");
            match name {
                "Alice" => r.check("alice-tier", tier == "high-eng", &format!("tier={}", tier)),
                "Bob" => r.check("bob-tier", tier == "high-eng", &format!("tier={}", tier)),
                "Frank" => r.check("frank-tier", tier == "high-eng", &format!("tier={}", tier)),
                "Carol" | "Dave" | "Eve" => r.check(&format!("{}-tier", name.to_lowercase()), tier == "standard", &format!("tier={}", tier)),
                _ => {}
            }
        }

        r.finish();
    }

