        let qr = run(&ex, "SELECT name FROM employees ORDER BY salary DESC LIMIT 3");
        r.check("limit-3", qr.rows.len() == 3, &format!("rows={}", qr.rows.len()));

        let qr2 = run(&ex, "SELECT name FROM employees ORDER BY salary DESC LIMIT 2 OFFSET 1");
        r.check("limit-offset", qr2.rows.len() == 2, &format!("rows={}", qr2.rows.len()));

        // First row of offset=1 should be second row of offset=0
        let second_no_offset = qr.rows[1][0].as_str().unwrap_or("");
