    /// INV-830: Multiple ORDER BY columns
    #[tokio::test]
    async fn inv830_multi_order() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        setup_standard_schema(&ex);

        let qr = run(&ex, "SELECT dept_id, salary FROM employees ORDER BY dept_id ASC, salary DESC");

        // Within each dept group, salaries should be descending
        let mut prev_dept = 0.0f64;
        let mut prev_sal = f64::MAX;
        for row in &qr.rows {
            let dept = val(&row[0]).unwrap_or(0.0);
            let sal = val(&row[1]).unwrap_or(0.0);
            if dept != prev_dept {
                prev_dept = dept;
                prev_sal = f64::MAX;
            }
            r.check(&format!("dept{}-sal-desc", dept as i64), sal <= prev_sal + 0.5,
                &format!("prev={}, curr={}", prev_sal, sal));
            prev_sal = sal;
        }

        r.finish();
    }

