    /// INV-852: String concatenation with ||
    #[tokio::test]
    async fn inv852_concat() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv852 (first TEXT, last TEXT)");
        run(&ex, "INSERT INTO inv852 VALUES ('John', 'Doe')");

        let res = try_run(&ex, "SELECT first || ' ' || last as fullname FROM inv852");
        match res {
            Ok(qr) => {
                let v = qr.rows[0][0].as_str().unwrap_or("");
                r.check("concat", v == "John Doe", &format!("fullname={}", v));
            }
            Err(_) => {
                // || may not be supported, try CONCAT function
                let qr = run(&ex, "SELECT CONCAT(first, ' ', last) as fullname FROM inv852");
                let v = qr.rows[0][0].as_str().unwrap_or("");
                r.check("concat-fn", v == "John Doe", &format!("fullname={}", v));
            }
        }

        r.finish();
    }

