    /// INV-862: Window SUM() OVER with PARTITION BY
    #[tokio::test]
    async fn inv862_window_sum_partition() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        setup_standard_schema(&ex);

        let qr = run(&ex, "SELECT name, dept_id, SUM(salary) OVER (PARTITION BY dept_id) as dept_total FROM employees ORDER BY dept_id, name");

        // All rows in same dept should have same dept_total
        let mut dept_totals = std::collections::HashMap::new();
        for row in &qr.rows {
            let dept = val(&row[1]).unwrap_or(0.0) as i64;
            let total = val(&row[2]).unwrap_or(0.0);
            dept_totals.entry(dept).or_insert(total);
            let expected = dept_totals[&dept];
            r.check(&format!("dept-{}-consistent", dept), (total - expected).abs() < 0.5,
                &format!("dept={}, total={}, expected={}", dept, total, expected));
        }

        // dept 1: 120k + 110k + 130k = 360k
        r.check("dept1-360k", (*dept_totals.get(&1).unwrap_or(&0.0) - 360000.0).abs() < 0.5,
            &format!("dept1={}", dept_totals.get(&1).unwrap_or(&0.0)));

        r.finish();
    }

