    /// INV-874: Chained comparison operators
    #[tokio::test]
    async fn inv874_chained_compare() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        setup_standard_schema(&ex);

        let gt = run_rows(&ex, "SELECT id FROM employees WHERE salary > 100000");
        let gte = run_rows(&ex, "SELECT id FROM employees WHERE salary >= 100000");
        let lt = run_rows(&ex, "SELECT id FROM employees WHERE salary < 100000");
        let lte = run_rows(&ex, "SELECT id FROM employees WHERE salary <= 100000");
        let total = run_rows(&ex, "SELECT id FROM employees");

        // gt + lte = total, gte + lt = total
        r.check("gt-lte-partition", gt + lte == total,
            &format!("gt={}, lte={}, total={}", gt, lte, total));
        r.check("gte-lt-partition", gte + lt == total,
            &format!("gte={}, lt={}, total={}", gte, lt, total));
        // gte >= gt
        r.check("gte-ge-gt", gte >= gt, &format!("gte={}, gt={}", gte, gt));

        r.finish();
    }

