    /// INV-888: Window ROW_NUMBER with PARTITION BY
    #[tokio::test]
    async fn inv888_row_number_partition() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        setup_standard_schema(&ex);

        let qr = run(&ex, "SELECT name, dept_id, ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary DESC) as rn FROM employees ORDER BY dept_id, rn");

        // First in each partition should be rn=1
        let mut seen_depts = std::collections::HashSet::new();
        for row in &qr.rows {
            let dept = val(&row[1]).unwrap_or(0.0) as i64;
            let rn = val(&row[2]).unwrap_or(0.0) as i64;
            if !seen_depts.contains(&dept) {
                r.check(&format!("dept{}-first-rn1", dept), rn == 1,
                    &format!("dept={}, rn={}", dept, rn));
                seen_depts.insert(dept);
            }
        }
        r.check("3-partitions", seen_depts.len() == 3, &format!("partitions={}", seen_depts.len()));

        r.finish();
    }

