    /// INV-903: EXCEPT ALL preserves duplicates in first set
    #[tokio::test]
    async fn inv903_except_all() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv903a (val INT)");
        run(&ex, "CREATE TABLE inv903b (val INT)");
        run(&ex, "INSERT INTO inv903a VALUES (1), (1), (2), (3)");
        run(&ex, "INSERT INTO inv903b VALUES (1), (2)");

        let res = try_run(&ex, "SELECT val FROM inv903a EXCEPT ALL SELECT val FROM inv903b");
        match res {
            Ok(qr) => {
                // EXCEPT ALL: remove one instance of 1, one of 2 → remaining: 1, 3
                r.check("except-all-2", qr.rows.len() == 2, &format!("rows={}", qr.rows.len()));
            }
            Err(_) => {
                // EXCEPT ALL may not be supported, use plain EXCEPT
                let cnt = run_rows(&ex, "SELECT val FROM inv903a EXCEPT SELECT val FROM inv903b");
                // EXCEPT dedup: {1,2,3} - {1,2} = {3}
                r.check("except-1", cnt == 1, &format!("cnt={}", cnt));
            }
        }

        r.finish();
    }

    /// INV-904: Multiple ORDER BY columns with mixed ASC/DESC
    #[tokio::test]
    async fn inv904_mixed_order() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv904 (grp INT, val INT)");
        run(&ex, "INSERT INTO inv904 VALUES (1, 30), (1, 10), (1, 20), (2, 50), (2, 40)");

        let qr = run(&ex, "SELECT grp, val FROM inv904 ORDER BY grp ASC, val DESC");

        // grp 1 first, then grp 2; within each, val descending
        let g1 = val(&qr.rows[0][0]).unwrap_or(0.0);
        let g_last = val(&qr.rows[4][0]).unwrap_or(0.0);
        r.check("first-grp-1", (g1 - 1.0).abs() < 0.5, &format!("first_grp={}", g1));
        r.check("last-grp-2", (g_last - 2.0).abs() < 0.5, &format!("last_grp={}", g_last));

        // Within grp 1: 30, 20, 10
        let v1 = val(&qr.rows[0][1]).unwrap_or(0.0);
        let v2 = val(&qr.rows[1][1]).unwrap_or(0.0);
        let v3 = val(&qr.rows[2][1]).unwrap_or(0.0);
        r.check("g1-desc", v1 >= v2 && v2 >= v3,
            &format!("g1: {}, {}, {}", v1, v2, v3));

        r.finish();
    }

