    /// INV-907: GROUP BY with MIN and MAX together
    #[tokio::test]
    async fn inv907_group_min_max() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        setup_standard_schema(&ex);

        let qr = run(&ex, "SELECT dept_id, MIN(salary) as mn, MAX(salary) as mx FROM employees GROUP BY dept_id ORDER BY dept_id");

        // dept 1: min=110k(Bob), max=130k(Frank)
        let mn1 = val(&qr.rows[0][1]).unwrap_or(0.0);
        let mx1 = val(&qr.rows[0][2]).unwrap_or(0.0);
        r.check("d1-min-110k", (mn1 - 110000.0).abs() < 0.5, &format!("min={}", mn1));
        r.check("d1-max-130k", (mx1 - 130000.0).abs() < 0.5, &format!("max={}", mx1));

        // For all groups: min <= max
        for row in &qr.rows {
            let mn = val(&row[1]).unwrap_or(0.0);
            let mx = val(&row[2]).unwrap_or(0.0);
            let dept = val(&row[0]).unwrap_or(0.0) as i64;
            r.check(&format!("d{}-min-le-max", dept), mn <= mx + 0.5,
                &format!("min={}, max={}", mn, mx));
        }

        r.finish();
    }

