    /// INV-919: UNION with ORDER BY (applied to entire result)
    #[tokio::test]
    async fn inv919_union_order() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv919 (val INT)");
        run(&ex, "INSERT INTO inv919 VALUES (5), (3), (1)");

        let qr = run(&ex, "SELECT val FROM inv919 WHERE val <= 3 UNION ALL SELECT val FROM inv919 WHERE val >= 3 ORDER BY val");
        // Left: 3, 1; Right: 5, 3 → UNION ALL: 3, 1, 5, 3 → ORDER BY: 1, 3, 3, 5
        r.check("4-rows", qr.rows.len() == 4, &format!("rows={}", qr.rows.len()));

        let first = val(&qr.rows[0][0]).unwrap_or(0.0);
        let last = val(&qr.rows[3][0]).unwrap_or(0.0);
        r.check("first-1", (first - 1.0).abs() < 0.5, &format!("first={}", first));
        r.check("last-5", (last - 5.0).abs() < 0.5, &format!("last={}", last));

        r.finish();
    }

