    /// INV-921: GROUP BY column index (SQL extension)
    #[tokio::test]
    async fn inv921_group_by_index() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        setup_standard_schema(&ex);

        // GROUP BY positional index is a MySQL/PostgreSQL extension, not SQL standard.
        // If the engine treats `1` as a literal, it produces 1 group. Either is valid.
        let res = try_run(&ex, "SELECT dept_id, COUNT(*) as cnt FROM employees GROUP BY 1 ORDER BY 1");
        match res {
            Ok(qr) => {
                // 3 groups (positional) or 1 group (literal) — both are valid
                r.check("group-by-1-valid", qr.rows.len() == 1 || qr.rows.len() == 3,
                    &format!("groups={}", qr.rows.len()));
            }
            Err(_) => {
                r.check("group-by-index-skip", true, "not supported");
            }
        }

        r.finish();
    }

    /// INV-922: Verify idempotent SELECT (same query twice = same result)
    #[tokio::test]
    async fn inv922_idempotent_select() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        setup_standard_schema(&ex);

        let qr1 = run(&ex, "SELECT name, salary FROM employees ORDER BY id");
        let qr2 = run(&ex, "SELECT name, salary FROM employees ORDER BY id");

        r.check("same-count", qr1.rows.len() == qr2.rows.len(), "counts differ");
        for i in 0..qr1.rows.len() {
            let n1 = qr1.rows[i][0].as_str().unwrap_or("");
            let n2 = qr2.rows[i][0].as_str().unwrap_or("");
            let s1 = val(&qr1.rows[i][1]).unwrap_or(0.0);
            let s2 = val(&qr2.rows[i][1]).unwrap_or(0.0);
            r.check(&format!("row-{}-match", i),
                n1 == n2 && (s1 - s2).abs() < 0.5,
                &format!("[{}] {}={}, {}={}", i, n1, s1, n2, s2));
        }

        r.finish();
    }

