    /// INV-934: Multiple DELETE operations
    #[tokio::test]
    async fn inv934_multi_delete() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv934 (id INT)");
        run(&ex, "INSERT INTO inv934 VALUES (1), (2), (3), (4), (5)");

        run(&ex, "DELETE FROM inv934 WHERE id = 1");
        r.check("after-1", run_rows(&ex, "SELECT id FROM inv934") == 4, "del 1");
        run(&ex, "DELETE FROM inv934 WHERE id = 3");
        r.check("after-2", run_rows(&ex, "SELECT id FROM inv934") == 3, "del 3");
        run(&ex, "DELETE FROM inv934 WHERE id = 5");
        r.check("after-3", run_rows(&ex, "SELECT id FROM inv934") == 2, "del 5");

        // Remaining: 2, 4
        let qr = run(&ex, "SELECT id FROM inv934 ORDER BY id");
        let id1 = val(&qr.rows[0][0]).unwrap_or(0.0);
        let id2 = val(&qr.rows[1][0]).unwrap_or(0.0);
        r.check("remaining-2", (id1 - 2.0).abs() < 0.5, &format!("id={}", id1));
        r.check("remaining-4", (id2 - 4.0).abs() < 0.5, &format!("id={}", id2));

        r.finish();
    }

