    /// INV-941: ORDER BY with NULL values
    #[tokio::test]
    async fn inv941_order_nulls() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv941 (id INT, val INT)");
        run(&ex, "INSERT INTO inv941 VALUES (1, 30), (2, NULL), (3, 10), (4, NULL), (5, 20)");

        let qr = run(&ex, "SELECT id, val FROM inv941 ORDER BY val");
        r.check("5-rows", qr.rows.len() == 5, &format!("rows={}", qr.rows.len()));
        // NULLs typically sort first or last — just verify non-null values are ordered
        let non_null: Vec<f64> = qr.rows.iter()
            .filter_map(|r| if r[1].is_null() { None } else { val(&r[1]) })
            .collect();
        for i in 0..non_null.len() - 1 {
            r.check(&format!("sorted-{}", i), non_null[i] <= non_null[i + 1] + 0.5,
                &format!("[{}]={}, [{}]={}", i, non_null[i], i + 1, non_null[i + 1]));
        }

        r.finish();
    }

