    /// INV-947: Complex CASE with IN
    #[tokio::test]
    async fn inv947_case_in() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        setup_standard_schema(&ex);

        let qr = run(&ex, "SELECT name, CASE WHEN name IN ('Alice', 'Bob') THEN 'team-a' WHEN name IN ('Carol', 'Dave') THEN 'team-b' ELSE 'team-c' END as team FROM employees ORDER BY name");

        for row in &qr.rows {
            let name = row[0].as_str().unwrap_or("");
            let team = row[1].as_str().unwrap_or("");
            match name {
                "Alice" | "Bob" => r.check(&format!("{}-a", name), team == "team-a", &format!("team={}", team)),
                "Carol" | "Dave" => r.check(&format!("{}-b", name), team == "team-b", &format!("team={}", team)),
                "Eve" | "Frank" => r.check(&format!("{}-c", name), team == "team-c", &format!("team={}", team)),
                _ => {}
            }
        }

        r.finish();
    }

