        let qr = run(&ex, "SELECT a.name, COUNT(b.amount) as cnt, COALESCE(SUM(b.amount), 0) as total FROM inv953a a LEFT JOIN inv953b b ON a.id = b.aid GROUP BY a.name ORDER BY a.name");

