        // Y: cnt=0, total=0
        let y_cnt = val(&qr.rows[1][1]).unwrap_or(-1.0);
        let y_total = val(&qr.rows[1][2]).unwrap_or(-1.0);
        r.check("y-cnt-0", (y_cnt - 0.0).abs() < 0.5, &format!("y_cnt={}", y_cnt));
