    /// INV-983: Window DENSE_RANK with partition
    #[tokio::test]
    async fn inv983_dense_rank_partition() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        setup_standard_schema(&ex);

        let qr = run(&ex, "SELECT name, dept_id, DENSE_RANK() OVER (PARTITION BY dept_id ORDER BY salary DESC) as dr FROM employees ORDER BY dept_id, dr");

        // First in each partition should be dr=1
        let mut seen = std::collections::HashSet::new();
        for row in &qr.rows {
            let dept = val(&row[1]).unwrap_or(0.0) as i64;
            let dr = val(&row[2]).unwrap_or(0.0) as i64;
            if !seen.contains(&dept) {
                r.check(&format!("d{}-first-dr1", dept), dr == 1, &format!("dr={}", dr));
                seen.insert(dept);
            }
        }

        r.finish();
    }

