    /// INV-985: LEFT JOIN with WHERE on right table eliminates NULLs
    #[tokio::test]
    async fn inv985_left_join_where_right() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv985a (id INT)");
        run(&ex, "CREATE TABLE inv985b (aid INT, val INT)");
        run(&ex, "INSERT INTO inv985a VALUES (1), (2), (3)");
        run(&ex, "INSERT INTO inv985b VALUES (1, 100), (3, 300)");

        // LEFT JOIN + WHERE on right side effectively becomes INNER JOIN
        let lj_where = run_rows(&ex, "SELECT a.id FROM inv985a a LEFT JOIN inv985b b ON a.id = b.aid WHERE b.val IS NOT NULL");
        let inner = run_rows(&ex, "SELECT a.id FROM inv985a a JOIN inv985b b ON a.id = b.aid");

        r.check("lj-where-eq-inner", lj_where == inner,
            &format!("lj_where={}, inner={}", lj_where, inner));

        r.finish();
    }

