    /// INV-1000: Milestone test — verify complete standard schema integrity
    #[tokio::test]
    async fn inv1000_milestone() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        setup_standard_schema(&ex);

        // Verify all tables exist with correct row counts
        r.check("employees-6", run_rows(&ex, "SELECT id FROM employees") == 6, "employees");
        r.check("departments-3", run_rows(&ex, "SELECT id FROM departments") == 3, "departments");
        r.check("projects-4", run_rows(&ex, "SELECT id FROM projects") == 4, "projects");
        r.check("orders-7", run_rows(&ex, "SELECT id FROM orders") == 7, "orders");

        // Verify referential consistency
        let orphans = run_rows(&ex, "SELECT e.id FROM employees e WHERE NOT EXISTS (SELECT 1 FROM departments d WHERE d.id = e.dept_id)");
        r.check("no-orphan-employees", orphans == 0, &format!("orphans={}", orphans));

        // Verify aggregate identities
        let qr = run(&ex, "SELECT COUNT(*), SUM(salary), AVG(salary), MIN(salary), MAX(salary) FROM employees");
        let cnt = val(&qr.rows[0][0]).unwrap_or(0.0);
        let sum = val(&qr.rows[0][1]).unwrap_or(0.0);
        let avg = val(&qr.rows[0][2]).unwrap_or(0.0);
        let mn = val(&qr.rows[0][3]).unwrap_or(0.0);
        let mx = val(&qr.rows[0][4]).unwrap_or(0.0);

        r.check("avg-identity", (avg - sum / cnt).abs() < 0.5, &format!("avg={}, sum/cnt={}", avg, sum / cnt));
        r.check("min-le-max", mn <= mx + 0.5, &format!("min={}, max={}", mn, mx));
        r.check("sum-630k", (sum - 630000.0).abs() < 0.5, &format!("sum={}", sum));

        // Verify window functions work
        let wf = run(&ex, "SELECT ROW_NUMBER() OVER (ORDER BY id) as rn FROM employees");
        r.check("window-6-rows", wf.rows.len() == 6, &format!("wf_rows={}", wf.rows.len()));

        // Verify set operations work
        let union_cnt = run_rows(&ex, "SELECT name FROM employees WHERE dept_id = 1 UNION SELECT name FROM employees WHERE dept_id = 2");
        r.check("union-5", union_cnt == 5, &format!("union={}", union_cnt));

        r.finish();
    }

