        let qr = run(&ex, "SELECT COALESCE(a, b, c) as v FROM inv1003 ORDER BY c, b, a");
        // Row 1: NULL,NULL,3 → 3; Row 2: NULL,2,3 → 2; Row 3: 1,2,3 → 1
        let vals: Vec<f64> = qr.rows.iter().filter_map(|row| val(&row[0])).collect();
        r.check("coalesce-count", vals.len() == 3, &format!("len={}", vals.len()));
