    /// INV-1016: DENSE_RANK with ties produces correct ranking
    #[tokio::test]
    async fn inv1016_dense_rank_ties() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1016 (name TEXT, score INT)");
        run(&ex, "INSERT INTO inv1016 VALUES ('A', 100), ('B', 90), ('C', 90), ('D', 80)");

        let qr = run(&ex, "SELECT name, DENSE_RANK() OVER (ORDER BY score DESC) as dr FROM inv1016 ORDER BY score DESC, name");
        r.check("4-rows", qr.rows.len() == 4, &format!("rows={}", qr.rows.len()));
        if qr.rows.len() == 4 {
            let r1 = val(&qr.rows[0][1]).unwrap_or(0.0); // A=100 → rank 1
            let r2 = val(&qr.rows[1][1]).unwrap_or(0.0); // B=90 → rank 2
            let r3 = val(&qr.rows[2][1]).unwrap_or(0.0); // C=90 → rank 2
            let r4 = val(&qr.rows[3][1]).unwrap_or(0.0); // D=80 → rank 3
            r.check("a-rank-1", (r1 - 1.0).abs() < 0.5, &format!("r1={}", r1));
            r.check("bc-same", (r2 - r3).abs() < 0.5, &format!("r2={} r3={}", r2, r3));
            r.check("bc-rank-2", (r2 - 2.0).abs() < 0.5, &format!("r2={}", r2));
            // DENSE_RANK: no gap → next is 3
            r.check("d-rank-3", (r4 - 3.0).abs() < 0.5, &format!("r4={}", r4));
        }

        r.finish();
    }

