    /// INV-1021: Multiple ORDER BY columns (secondary sort) — fresh table
    #[tokio::test]
    async fn inv1021_multi_order_by() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1021 (grp INT, val INT, name TEXT)");
        run(&ex, "INSERT INTO inv1021 VALUES (1, 30, 'a')");
        run(&ex, "INSERT INTO inv1021 VALUES (1, 10, 'b')");
        run(&ex, "INSERT INTO inv1021 VALUES (1, 20, 'c')");
        run(&ex, "INSERT INTO inv1021 VALUES (2, 20, 'd')");
        run(&ex, "INSERT INTO inv1021 VALUES (2, 10, 'e')");

        let qr = run(&ex, "SELECT name, grp, val FROM inv1021 ORDER BY grp ASC, val DESC");
        r.check("5-rows", qr.rows.len() == 5, &format!("rows={}", qr.rows.len()));
        if qr.rows.len() == 5 {
            // grp=1: val DESC → 30(a), 20(c), 10(b). grp=2: val DESC → 20(d), 10(e)
            let names: Vec<&str> = qr.rows.iter().map(|row| row[0].as_str().unwrap_or("?")).collect();
            let expected = vec!["a", "c", "b", "d", "e"];
            r.check("order-correct", names == expected,
                &format!("names={:?} expected={:?}", names, expected));
            // At minimum, grp should be non-decreasing
            let grps: Vec<f64> = qr.rows.iter().filter_map(|row| val(&row[1])).collect();
            let grp_sorted = grps.windows(2).all(|w| w[0] <= w[1]);
            r.check("grp-sorted", grp_sorted, &format!("grps={:?}", grps));
        }

        r.finish();
    }

