    /// INV-1023: Window SUM with ORDER BY gives running total
    #[tokio::test]
    async fn inv1023_window_running_sum() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1023 (id INT, val INT)");
        run(&ex, "INSERT INTO inv1023 VALUES (1, 10), (2, 20), (3, 30), (4, 40)");

        let qr = run(&ex, "SELECT id, val, SUM(val) OVER (ORDER BY id) as running FROM inv1023 ORDER BY id");
        r.check("4-rows", qr.rows.len() == 4, &format!("rows={}", qr.rows.len()));
        if qr.rows.len() == 4 {
            let r1 = val(&qr.rows[0][2]).unwrap_or(0.0);
            let r2 = val(&qr.rows[1][2]).unwrap_or(0.0);
            let r3 = val(&qr.rows[2][2]).unwrap_or(0.0);
            let r4 = val(&qr.rows[3][2]).unwrap_or(0.0);
            r.check("run1-10", (r1 - 10.0).abs() < 0.5, &format!("r1={}", r1));
            r.check("run2-30", (r2 - 30.0).abs() < 0.5, &format!("r2={}", r2));
            r.check("run3-60", (r3 - 60.0).abs() < 0.5, &format!("r3={}", r3));
            r.check("run4-100", (r4 - 100.0).abs() < 0.5, &format!("r4={}", r4));
            // Running total is monotonically increasing for positive values
            r.check("monotonic", r1 <= r2 && r2 <= r3 && r3 <= r4,
                &format!("r1={} r2={} r3={} r4={}", r1, r2, r3, r4));
        }

        r.finish();
    }

