    /// INV-1026: NTILE distributes rows into buckets
    #[tokio::test]
    async fn inv1026_ntile_distribution() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1026 (id INT)");
        run(&ex, "INSERT INTO inv1026 VALUES (1), (2), (3), (4), (5), (6), (7)");

        let qr = run(&ex, "SELECT id, NTILE(3) OVER (ORDER BY id) as bucket FROM inv1026 ORDER BY id");
        r.check("7-rows", qr.rows.len() == 7, &format!("rows={}", qr.rows.len()));
        if qr.rows.len() == 7 {
            let buckets: Vec<f64> = qr.rows.iter().filter_map(|row| val(&row[1])).collect();
            // 7 rows / 3 buckets: first bucket gets 3, next 2 get 2 each
            // Bucket 1: ids 1,2,3. Bucket 2: ids 4,5. Bucket 3: ids 6,7
            r.check("all-assigned", buckets.len() == 7, &format!("len={}", buckets.len()));
            let min_b = buckets.iter().cloned().fold(f64::INFINITY, f64::min);
            let max_b = buckets.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
            r.check("min-1", (min_b - 1.0).abs() < 0.5, &format!("min={}", min_b));
            r.check("max-3", (max_b - 3.0).abs() < 0.5, &format!("max={}", max_b));
            // Buckets should be non-decreasing
            let sorted = buckets.windows(2).all(|w| w[0] <= w[1]);
            r.check("non-decreasing", sorted, &format!("buckets={:?}", buckets));
        }

        r.finish();
    }

