    /// INV-1036: LIKE pattern matching with wildcards
    #[tokio::test]
    async fn inv1036_like_wildcards() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1036 (name TEXT)");
        run(&ex, "INSERT INTO inv1036 VALUES ('Alice'), ('Bob'), ('Anna'), ('Amy'), ('Betty')");

        // Starts with A
        let cnt = run_rows(&ex, "SELECT * FROM inv1036 WHERE name LIKE 'A%'");
        r.check("starts-a-3", cnt == 3, &format!("cnt={}", cnt));

        // Contains 'b' (case matters)
        let cnt2 = run_rows(&ex, "SELECT * FROM inv1036 WHERE name LIKE '%o%'");
        r.check("contains-o-1", cnt2 == 1, &format!("cnt2={}", cnt2));

        // Single char wildcard
        let cnt3 = run_rows(&ex, "SELECT * FROM inv1036 WHERE name LIKE 'A___'");
        // 4-char names starting with A: Anna, but not Alice (5 chars) or Amy (3 chars)
        r.check("four-char-a", cnt3 == 1, &format!("cnt3={}", cnt3));

        r.finish();
    }

    /// INV-1037: OR conditions in WHERE
