    /// INV-1040: Aggregate with empty table returns expected values
    #[tokio::test]
    async fn inv1040_agg_empty_table() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1040 (val INT)");
        // No inserts — table is empty

        let qr = run(&ex, "SELECT COUNT(*) as c, SUM(val) as s, AVG(val) as a, MIN(val) as mn, MAX(val) as mx FROM inv1040");
        r.check("1-row", qr.rows.len() == 1, &format!("rows={}", qr.rows.len()));
        if !qr.rows.is_empty() {
            let c = val(&qr.rows[0][0]).unwrap_or(-1.0);
            r.check("count-0", (c - 0.0).abs() < 0.5, &format!("c={}", c));
            // SUM, AVG, MIN, MAX of empty set should be NULL
            r.check("sum-null", qr.rows[0][1].is_null(), &format!("sum={:?}", qr.rows[0][1]));
            r.check("avg-null", qr.rows[0][2].is_null(), &format!("avg={:?}", qr.rows[0][2]));
            r.check("min-null", qr.rows[0][3].is_null(), &format!("min={:?}", qr.rows[0][3]));
            r.check("max-null", qr.rows[0][4].is_null(), &format!("max={:?}", qr.rows[0][4]));
        }

        r.finish();
    }

    /// INV-1041: Window PARTITION BY separates calculations
    #[tokio::test]
    async fn inv1041_window_partition_by() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1041 (grp INT, val INT)");
        run(&ex, "INSERT INTO inv1041 VALUES (1, 10), (1, 20), (1, 30), (2, 100), (2, 200)");

        let qr = run(&ex, "SELECT grp, val, SUM(val) OVER (PARTITION BY grp) as grp_sum FROM inv1041 ORDER BY grp, val");
        r.check("5-rows", qr.rows.len() == 5, &format!("rows={}", qr.rows.len()));
        if qr.rows.len() == 5 {
            // grp=1: sum=60 for all 3 rows
            let s1 = val(&qr.rows[0][2]).unwrap_or(0.0);
            let s2 = val(&qr.rows[1][2]).unwrap_or(0.0);
            let s3 = val(&qr.rows[2][2]).unwrap_or(0.0);
            r.check("grp1-all-60", (s1 - 60.0).abs() < 0.5 && (s2 - 60.0).abs() < 0.5 && (s3 - 60.0).abs() < 0.5,
                &format!("s1={} s2={} s3={}", s1, s2, s3));
            // grp=2: sum=300 for both rows
            let s4 = val(&qr.rows[3][2]).unwrap_or(0.0);
            let s5 = val(&qr.rows[4][2]).unwrap_or(0.0);
            r.check("grp2-all-300", (s4 - 300.0).abs() < 0.5 && (s5 - 300.0).abs() < 0.5,
                &format!("s4={} s5={}", s4, s5));
        }

        r.finish();
    }

