    /// INV-1043: Window COUNT with PARTITION BY
    #[tokio::test]
    async fn inv1043_window_count_partition() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1043 (grp INT, val INT)");
        run(&ex, "INSERT INTO inv1043 VALUES (1, 10), (1, 20), (1, 30), (2, 40), (2, 50)");

        let qr = run(&ex, "SELECT grp, val, COUNT(*) OVER (PARTITION BY grp) as grp_cnt FROM inv1043 ORDER BY grp, val");
        r.check("5-rows", qr.rows.len() == 5, &format!("rows={}", qr.rows.len()));
        if qr.rows.len() == 5 {
            // grp=1 has 3 rows, grp=2 has 2 rows
            let c1 = val(&qr.rows[0][2]).unwrap_or(0.0);
            let c2 = val(&qr.rows[2][2]).unwrap_or(0.0);
            let c3 = val(&qr.rows[3][2]).unwrap_or(0.0);
            r.check("grp1-cnt-3", (c1 - 3.0).abs() < 0.5, &format!("c1={}", c1));
            r.check("grp1-same", (c1 - c2).abs() < 0.5, &format!("c1={} c2={}", c1, c2));
            r.check("grp2-cnt-2", (c3 - 2.0).abs() < 0.5, &format!("c3={}", c3));
        }

        r.finish();
    }

    /// INV-1044: ROW_NUMBER is unique within partition
    #[tokio::test]
    async fn inv1044_row_number_unique() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1044 (grp INT, val INT)");
        run(&ex, "INSERT INTO inv1044 VALUES (1, 10), (1, 20), (1, 30), (2, 40), (2, 50)");

        let qr = run(&ex, "SELECT grp, val, ROW_NUMBER() OVER (PARTITION BY grp ORDER BY val) as rn FROM inv1044 ORDER BY grp, val");
        r.check("5-rows", qr.rows.len() == 5, &format!("rows={}", qr.rows.len()));
        if qr.rows.len() == 5 {
            // grp=1: rn=1,2,3. grp=2: rn=1,2
            let rn1 = val(&qr.rows[0][2]).unwrap_or(0.0);
            let rn2 = val(&qr.rows[1][2]).unwrap_or(0.0);
            let rn3 = val(&qr.rows[2][2]).unwrap_or(0.0);
            let rn4 = val(&qr.rows[3][2]).unwrap_or(0.0);
            let rn5 = val(&qr.rows[4][2]).unwrap_or(0.0);
            r.check("grp1-1", (rn1 - 1.0).abs() < 0.5, &format!("rn1={}", rn1));
            r.check("grp1-2", (rn2 - 2.0).abs() < 0.5, &format!("rn2={}", rn2));
            r.check("grp1-3", (rn3 - 3.0).abs() < 0.5, &format!("rn3={}", rn3));
            // Partition resets for grp=2
            r.check("grp2-reset-1", (rn4 - 1.0).abs() < 0.5, &format!("rn4={}", rn4));
            r.check("grp2-2", (rn5 - 2.0).abs() < 0.5, &format!("rn5={}", rn5));
        }

        r.finish();
    }

