    /// INV-1047: Arithmetic precedence — multiplication before addition
    #[tokio::test]
    async fn inv1047_arithmetic_precedence() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1047 (a INT, b INT, c INT)");
        run(&ex, "INSERT INTO inv1047 VALUES (2, 3, 4)");

        let qr = run(&ex, "SELECT a + b * c as result FROM inv1047");
        let result = val(&qr.rows[0][0]).unwrap_or(0.0);
        // 2 + 3*4 = 2 + 12 = 14 (not (2+3)*4 = 20)
        r.check("precedence-14", (result - 14.0).abs() < 0.5, &format!("result={}", result));

        // With explicit parentheses
        let qr2 = run(&ex, "SELECT (a + b) * c as result FROM inv1047");
        let result2 = val(&qr2.rows[0][0]).unwrap_or(0.0);
        r.check("parens-20", (result2 - 20.0).abs() < 0.5, &format!("result2={}", result2));

        r.finish();
    }

    /// INV-1048: Multiple JOINs — three-table join with fresh tables
    #[tokio::test]
    async fn inv1048_three_table_join() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1048a (id INT, name TEXT)");
        run(&ex, "CREATE TABLE inv1048b (id INT, aid INT, label TEXT)");
        run(&ex, "CREATE TABLE inv1048c (id INT, bid INT, tag TEXT)");
        run(&ex, "INSERT INTO inv1048a VALUES (1, 'X'), (2, 'Y')");
        run(&ex, "INSERT INTO inv1048b VALUES (10, 1, 'p'), (20, 1, 'q'), (30, 2, 'r')");
        run(&ex, "INSERT INTO inv1048c VALUES (100, 10, 't1'), (200, 20, 't2')");

        // a JOIN b ON b.aid = a.id → (1,X,10,p), (1,X,20,q), (2,Y,30,r) = 3 rows
        // then JOIN c ON c.bid = b.id → (1,X,10,p,100,t1), (1,X,20,q,200,t2) = 2 rows
        let cnt = run_rows(&ex, "SELECT a.name, b.label, c.tag FROM inv1048a a JOIN inv1048b b ON b.aid = a.id JOIN inv1048c c ON c.bid = b.id");
        r.check("three-join-2", cnt == 2, &format!("cnt={}", cnt));

        r.finish();
    }

