    /// INV-1060: INSERT then UPDATE then SELECT consistency
    #[tokio::test]
    async fn inv1060_crud_consistency() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1060 (id INT, val INT)");
        run(&ex, "INSERT INTO inv1060 VALUES (1, 100), (2, 200), (3, 300)");

        // Update one row
        run(&ex, "UPDATE inv1060 SET val = 999 WHERE id = 2");

        // Delete one row
        run(&ex, "DELETE FROM inv1060 WHERE id = 3");

        let qr = run(&ex, "SELECT id, val FROM inv1060 ORDER BY id");
        r.check("2-rows", qr.rows.len() == 2, &format!("rows={}", qr.rows.len()));
        if qr.rows.len() == 2 {
            let v1 = val(&qr.rows[0][1]).unwrap_or(0.0);
            let v2 = val(&qr.rows[1][1]).unwrap_or(0.0);
            r.check("id1-unchanged", (v1 - 100.0).abs() < 0.5, &format!("v1={}", v1));
            r.check("id2-updated", (v2 - 999.0).abs() < 0.5, &format!("v2={}", v2));
        }

        // SUM should reflect changes
        let qr2 = run(&ex, "SELECT SUM(val) FROM inv1060");
        let total = val(&qr2.rows[0][0]).unwrap_or(0.0);
        r.check("sum-1099", (total - 1099.0).abs() < 0.5, &format!("total={}", total));

        r.finish();
    }

    /// INV-1061: Window function with empty partition
    #[tokio::test]
    async fn inv1061_window_single_row_partition() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1061 (grp INT, val INT)");
        run(&ex, "INSERT INTO inv1061 VALUES (1, 10), (2, 20), (3, 30)");

        let qr = run(&ex, "SELECT grp, val, ROW_NUMBER() OVER (PARTITION BY grp ORDER BY val) as rn, SUM(val) OVER (PARTITION BY grp) as part_sum FROM inv1061 ORDER BY grp");
        r.check("3-rows", qr.rows.len() == 3, &format!("rows={}", qr.rows.len()));
        if qr.rows.len() == 3 {
            // Each partition has exactly 1 row → ROW_NUMBER always 1
            for (i, row) in qr.rows.iter().enumerate() {
                let rn = val(&row[2]).unwrap_or(0.0);
                r.check(&format!("rn-{}-is-1", i), (rn - 1.0).abs() < 0.5, &format!("rn={}", rn));
                // SUM of single row = the row value itself
                let v = val(&row[1]).unwrap_or(0.0);
                let s = val(&row[3]).unwrap_or(0.0);
                r.check(&format!("sum-eq-val-{}", i), (s - v).abs() < 0.5,
                    &format!("sum={} val={}", s, v));
            }
        }

        r.finish();
    }

    /// INV-1062: EXCEPT ALL preserves left-side duplicates minus right-side
