        run(&ex, "CREATE TABLE inv1065 (id INT, val INT)");
        run(&ex, "INSERT INTO inv1065 VALUES (1, 10), (2, 20), (3, 30), (4, 40)");

        let qr = run(&ex, "SELECT id, val, ROW_NUMBER() OVER (ORDER BY id) as rn, SUM(val) OVER (ORDER BY id) as running, AVG(val) OVER () as total_avg FROM inv1065 ORDER BY id");
