    /// INV-1083: Window DENSE_RANK with PARTITION BY
    #[tokio::test]
    async fn inv1083_dense_rank_partition() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1083 (grp INT, score INT)");
        run(&ex, "INSERT INTO inv1083 VALUES (1, 100), (1, 90), (1, 90), (2, 80), (2, 80), (2, 70)");

        let qr = run(&ex, "SELECT grp, score, DENSE_RANK() OVER (PARTITION BY grp ORDER BY score DESC) as dr FROM inv1083 ORDER BY grp, score DESC");
        r.check("6-rows", qr.rows.len() == 6, &format!("rows={}", qr.rows.len()));
        if qr.rows.len() == 6 {
            // grp=1: 100→1, 90→2, 90→2
            let dr1 = val(&qr.rows[0][2]).unwrap_or(0.0);
            let dr2 = val(&qr.rows[1][2]).unwrap_or(0.0);
            let dr3 = val(&qr.rows[2][2]).unwrap_or(0.0);
            r.check("g1-first-1", (dr1 - 1.0).abs() < 0.5, &format!("dr1={}", dr1));
            r.check("g1-tied-2", (dr2 - 2.0).abs() < 0.5 && (dr3 - 2.0).abs() < 0.5,
                &format!("dr2={} dr3={}", dr2, dr3));
            // grp=2: 80→1, 80→1, 70→2 (partition resets)
            let dr4 = val(&qr.rows[3][2]).unwrap_or(0.0);
            let dr6 = val(&qr.rows[5][2]).unwrap_or(0.0);
            r.check("g2-reset-1", (dr4 - 1.0).abs() < 0.5, &format!("dr4={}", dr4));
            r.check("g2-next-2", (dr6 - 2.0).abs() < 0.5, &format!("dr6={}", dr6));
        }

        r.finish();
    }

