    /// INV-1102: Aggregate identity — SUM of single value equals itself
    #[tokio::test]
    async fn inv1102_agg_identity() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1102 (val INT)");
        run(&ex, "INSERT INTO inv1102 VALUES (42)");

        let qr = run(&ex, "SELECT SUM(val) as s, AVG(val) as a, MIN(val) as mn, MAX(val) as mx, COUNT(*) as c FROM inv1102");
        if !qr.rows.is_empty() {
            let s = val(&qr.rows[0][0]).unwrap_or(0.0);
            let a = val(&qr.rows[0][1]).unwrap_or(0.0);
            let mn = val(&qr.rows[0][2]).unwrap_or(0.0);
            let mx = val(&qr.rows[0][3]).unwrap_or(0.0);
            let c = val(&qr.rows[0][4]).unwrap_or(0.0);
            // For single value: SUM=AVG=MIN=MAX=val, COUNT=1
            r.check("sum-42", (s - 42.0).abs() < 0.5, &format!("s={}", s));
            r.check("avg-42", (a - 42.0).abs() < 0.5, &format!("a={}", a));
            r.check("min-42", (mn - 42.0).abs() < 0.5, &format!("mn={}", mn));
            r.check("max-42", (mx - 42.0).abs() < 0.5, &format!("mx={}", mx));
            r.check("count-1", (c - 1.0).abs() < 0.5, &format!("c={}", c));
            // All equal each other
            r.check("all-equal", (s - a).abs() < 0.5 && (a - mn).abs() < 0.5 && (mn - mx).abs() < 0.5,
                "not all equal");
        }

        r.finish();
    }

