    /// INV-1115: FLOOR and CEIL functions
    #[tokio::test]
    async fn inv1115_floor_ceil() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1115 (val FLOAT)");
        run(&ex, "INSERT INTO inv1115 VALUES (3.7), (-2.3)");

        let qr = run(&ex, "SELECT FLOOR(val) as f, CEIL(val) as c FROM inv1115 ORDER BY val");
        r.check("2-rows", qr.rows.len() == 2, &format!("rows={}", qr.rows.len()));
        if qr.rows.len() == 2 {
            // -2.3: floor=-3, ceil=-2
            let f1 = val(&qr.rows[0][0]).unwrap_or(0.0);
            let c1 = val(&qr.rows[0][1]).unwrap_or(0.0);
            r.check("neg-floor", (f1 - (-3.0)).abs() < 0.5, &format!("f1={}", f1));
            r.check("neg-ceil", (c1 - (-2.0)).abs() < 0.5, &format!("c1={}", c1));
            // 3.7: floor=3, ceil=4
            let f2 = val(&qr.rows[1][0]).unwrap_or(0.0);
            let c2 = val(&qr.rows[1][1]).unwrap_or(0.0);
            r.check("pos-floor", (f2 - 3.0).abs() < 0.5, &format!("f2={}", f2));
            r.check("pos-ceil", (c2 - 4.0).abs() < 0.5, &format!("c2={}", c2));
        }

        r.finish();
    }

