    /// INV-1122: Complex WHERE with parenthesized OR inside AND
    #[tokio::test]
    async fn inv1122_complex_where() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1122 (a INT, b INT, c INT)");
        run(&ex, "INSERT INTO inv1122 VALUES (1, 2, 3), (1, 3, 3), (2, 2, 3), (2, 3, 4)");

        // a = 1 AND (b = 2 OR c = 4)
        let cnt = run_rows(&ex, "SELECT * FROM inv1122 WHERE a = 1 AND (b = 2 OR c = 4)");
        // (1,2,3): a=1, b=2 → yes. (1,3,3): a=1, b!=2 AND c!=4 → no. Others: a!=1 → no.
        r.check("complex-1", cnt == 1, &format!("cnt={}", cnt));

        // Without parens: a = 1 AND b = 2 OR c = 4 → (a=1 AND b=2) OR c=4
        let cnt2 = run_rows(&ex, "SELECT * FROM inv1122 WHERE a = 1 AND b = 2 OR c = 4");
        // (1,2,3): a=1 AND b=2 → yes. (2,3,4): c=4 → yes. Total = 2
        r.check("no-parens-2", cnt2 == 2, &format!("cnt2={}", cnt2));

        r.finish();
    }

