    /// INV-1123: Window RANK with PARTITION BY
    #[tokio::test]
    async fn inv1123_rank_partition() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1123 (grp INT, score INT)");
        run(&ex, "INSERT INTO inv1123 VALUES (1, 100), (1, 80), (1, 80), (2, 50), (2, 70)");

        let qr = run(&ex, "SELECT grp, score, RANK() OVER (PARTITION BY grp ORDER BY score DESC) as rk FROM inv1123 ORDER BY grp, score DESC");
        r.check("5-rows", qr.rows.len() == 5, &format!("rows={}", qr.rows.len()));
        if qr.rows.len() == 5 {
            // grp=1: 100→1, 80→2, 80→2. grp=2: 70→1, 50→2
            let rk1 = val(&qr.rows[0][2]).unwrap_or(0.0);
            let rk2 = val(&qr.rows[1][2]).unwrap_or(0.0);
            let rk3 = val(&qr.rows[2][2]).unwrap_or(0.0);
            r.check("g1-top-1", (rk1 - 1.0).abs() < 0.5, &format!("rk1={}", rk1));
            r.check("g1-tied-2", (rk2 - 2.0).abs() < 0.5 && (rk3 - 2.0).abs() < 0.5,
                &format!("rk2={} rk3={}", rk2, rk3));
            // grp=2 resets
            let rk4 = val(&qr.rows[3][2]).unwrap_or(0.0);
            r.check("g2-reset-1", (rk4 - 1.0).abs() < 0.5, &format!("rk4={}", rk4));
        }

        r.finish();
    }

