    /// INV-1138: CROSS JOIN with WHERE = equivalent to inner join
    #[tokio::test]
    async fn inv1138_cross_join_where() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1138a (id INT, name TEXT)");
        run(&ex, "CREATE TABLE inv1138b (aid INT, val INT)");
        run(&ex, "INSERT INTO inv1138a VALUES (1, 'A'), (2, 'B')");
        run(&ex, "INSERT INTO inv1138b VALUES (1, 10), (2, 20), (1, 30)");

        // CROSS JOIN + WHERE = INNER JOIN
        let cross = run_rows(&ex, "SELECT a.name, b.val FROM inv1138a a CROSS JOIN inv1138b b WHERE a.id = b.aid");
        let inner = run_rows(&ex, "SELECT a.name, b.val FROM inv1138a a JOIN inv1138b b ON a.id = b.aid");
        r.check("cross-eq-inner", cross == inner, &format!("cross={} inner={}", cross, inner));
        r.check("count-3", cross == 3, &format!("cross={}", cross));

        r.finish();
    }

