    /// INV-1159: Aggregate invariant: SUM = COUNT * AVG
    #[tokio::test]
    async fn inv1159_sum_count_avg() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1159 (val INT)");
        run(&ex, "INSERT INTO inv1159 VALUES (10), (20), (30), (40), (50)");

        let qr = run(&ex, "SELECT SUM(val) as s, COUNT(*) as c, AVG(val) as a FROM inv1159");
        if !qr.rows.is_empty() {
            let s = val(&qr.rows[0][0]).unwrap_or(0.0);
            let c = val(&qr.rows[0][1]).unwrap_or(1.0);
            let a = val(&qr.rows[0][2]).unwrap_or(0.0);
            // SUM = COUNT * AVG
            r.check("sum-eq-count-times-avg", (s - c * a).abs() < 1.0,
                &format!("s={} c*a={}", s, c * a));
            r.check("sum-150", (s - 150.0).abs() < 0.5, &format!("s={}", s));
            r.check("avg-30", (a - 30.0).abs() < 0.5, &format!("a={}", a));
        }

        r.finish();
    }

