    /// INV-1162: Window MAX with running frame
    #[tokio::test]
    async fn inv1162_window_running_max() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1162 (id INT, val INT)");
        run(&ex, "INSERT INTO inv1162 VALUES (1, 10), (2, 50), (3, 20), (4, 40), (5, 30)");

        let qr = run(&ex, "SELECT id, val, MAX(val) OVER (ORDER BY id) as running_max FROM inv1162 ORDER BY id");
        r.check("5-rows", qr.rows.len() == 5, &format!("rows={}", qr.rows.len()));
        if qr.rows.len() == 5 {
            // Running max: 10, 50, 50, 50, 50
            let m1 = val(&qr.rows[0][2]).unwrap_or(0.0);
            let m2 = val(&qr.rows[1][2]).unwrap_or(0.0);
            let m5 = val(&qr.rows[4][2]).unwrap_or(0.0);
            r.check("rm1-10", (m1 - 10.0).abs() < 0.5, &format!("m1={}", m1));
            r.check("rm2-50", (m2 - 50.0).abs() < 0.5, &format!("m2={}", m2));
            r.check("rm5-50", (m5 - 50.0).abs() < 0.5, &format!("m5={}", m5));
            // Running max should be non-decreasing
            let maxes: Vec<f64> = qr.rows.iter().filter_map(|row| val(&row[2])).collect();
            let nondec = maxes.windows(2).all(|w| w[0] <= w[1] + 0.5);
            r.check("non-decreasing", nondec, &format!("maxes={:?}", maxes));
        }

        r.finish();
    }

