    /// INV-1163: Window running MIN is non-increasing
    #[tokio::test]
    async fn inv1163_window_running_min() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1163 (id INT, val INT)");
        run(&ex, "INSERT INTO inv1163 VALUES (1, 50), (2, 10), (3, 40), (4, 20), (5, 30)");

        let qr = run(&ex, "SELECT id, val, MIN(val) OVER (ORDER BY id) as running_min FROM inv1163 ORDER BY id");
        r.check("5-rows", qr.rows.len() == 5, &format!("rows={}", qr.rows.len()));
        if qr.rows.len() == 5 {
            // Running min: 50, 10, 10, 10, 10
            let m1 = val(&qr.rows[0][2]).unwrap_or(0.0);
            let m2 = val(&qr.rows[1][2]).unwrap_or(0.0);
            r.check("rm1-50", (m1 - 50.0).abs() < 0.5, &format!("m1={}", m1));
            r.check("rm2-10", (m2 - 10.0).abs() < 0.5, &format!("m2={}", m2));
            // Running min should be non-increasing
            let mins: Vec<f64> = qr.rows.iter().filter_map(|row| val(&row[2])).collect();
            let noninc = mins.windows(2).all(|w| w[0] >= w[1] - 0.5);
            r.check("non-increasing", noninc, &format!("mins={:?}", mins));
        }

        r.finish();
    }

