    /// INV-1200: Milestone — comprehensive aggregate + window + join invariants
    #[tokio::test]
    async fn inv1200_milestone() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1200_items (id INT, grp INT, val INT)");
        run(&ex, "CREATE TABLE inv1200_meta (grp INT, label TEXT)");
        run(&ex, "INSERT INTO inv1200_items VALUES (1, 1, 10), (2, 1, 20), (3, 2, 30), (4, 2, 40), (5, 3, 50)");
        run(&ex, "INSERT INTO inv1200_meta VALUES (1, 'alpha'), (2, 'beta'), (3, 'gamma')");

        // Aggregate invariants
        let qr = run(&ex, "SELECT COUNT(*) as c, SUM(val) as s, AVG(val) as a, MIN(val) as mn, MAX(val) as mx FROM inv1200_items");
        let c = val(&qr.rows[0][0]).unwrap_or(0.0);
        let s = val(&qr.rows[0][1]).unwrap_or(0.0);
        let a = val(&qr.rows[0][2]).unwrap_or(0.0);
        let mn = val(&qr.rows[0][3]).unwrap_or(0.0);
        let mx = val(&qr.rows[0][4]).unwrap_or(0.0);
        r.check("count-5", (c - 5.0).abs() < 0.5, &format!("c={}", c));
        r.check("sum-150", (s - 150.0).abs() < 0.5, &format!("s={}", s));
        r.check("avg-30", (a - 30.0).abs() < 0.5, &format!("a={}", a));
        r.check("min-10", (mn - 10.0).abs() < 0.5, &format!("mn={}", mn));
        r.check("max-50", (mx - 50.0).abs() < 0.5, &format!("mx={}", mx));
        r.check("sum-eq-cnt-avg", (s - c * a).abs() < 1.0, "SUM != COUNT*AVG");
        r.check("min-le-avg-le-max", mn <= a + 0.5 && a <= mx + 0.5, "ordering violated");

        // JOIN check
        let jcnt = run_rows(&ex, "SELECT i.id, m.label FROM inv1200_items i JOIN inv1200_meta m ON i.grp = m.grp");
        r.check("join-5", jcnt == 5, &format!("jcnt={}", jcnt));

        // Window check
        let wqr = run(&ex, "SELECT id, val, ROW_NUMBER() OVER (ORDER BY id) as rn FROM inv1200_items ORDER BY id");
        if wqr.rows.len() == 5 {
            let rn5 = val(&wqr.rows[4][1 + 1]).unwrap_or(0.0);
            r.check("rn5-is-5", (rn5 - 5.0).abs() < 0.5, &format!("rn5={}", rn5));
        }

        r.finish();
    }

    /// INV-1201: GROUP BY on expression with aggregate
    #[tokio::test]
    async fn inv1201_group_expr_agg() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1201 (val INT)");
        run(&ex, "INSERT INTO inv1201 VALUES (1), (2), (3), (4), (5), (6)");

        // Group by even/odd
        let qr = run(&ex, "SELECT val % 2 as parity, COUNT(*) as cnt FROM inv1201 GROUP BY val % 2 ORDER BY parity");
        r.check("2-groups", qr.rows.len() == 2, &format!("rows={}", qr.rows.len()));
        if qr.rows.len() == 2 {
            // Each parity group has 3 members
            let c1 = val(&qr.rows[0][1]).unwrap_or(0.0);
            let c2 = val(&qr.rows[1][1]).unwrap_or(0.0);
            r.check("even-3", (c1 - 3.0).abs() < 0.5, &format!("c1={}", c1));
            r.check("odd-3", (c2 - 3.0).abs() < 0.5, &format!("c2={}", c2));
        }

        r.finish();
    }

    /// INV-1202: WHERE with nested NOT
    #[tokio::test]
    async fn inv1202_nested_not() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1202 (val INT)");
        run(&ex, "INSERT INTO inv1202 VALUES (1), (2), (3), (4), (5)");

        let cnt = run_rows(&ex, "SELECT * FROM inv1202 WHERE NOT (val > 3)");
        // NOT (val > 3) = val <= 3 → 1, 2, 3 = 3
        r.check("not-gt3-3", cnt == 3, &format!("cnt={}", cnt));

        let cnt2 = run_rows(&ex, "SELECT * FROM inv1202 WHERE NOT (val < 2 OR val > 4)");
        // NOT (val < 2 OR val > 4) = val >= 2 AND val <= 4 → 2, 3, 4 = 3
        r.check("not-or-3", cnt2 == 3, &format!("cnt2={}", cnt2));

        r.finish();
    }

