    /// INV-1212: Deeply nested expression parsing
    #[tokio::test]
    async fn inv1212_deeply_nested_expr() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1212 (val INT)");
        run(&ex, "INSERT INTO inv1212 VALUES (10)");

        // Deeply nested arithmetic
        let res = try_run(&ex, "SELECT ((((val + 1) * 2) - 3) / 2) FROM inv1212");
        r.check("nested-arith-ok", res.is_ok(), &format!("res={:?}", res));

        if let Ok(ref qr) = res {
            // (((10+1)*2)-3)/2 = ((11*2)-3)/2 = (22-3)/2 = 19/2 = 9 (integer division)
            let v = val(&qr.rows[0][0]);
            r.check("nested-result", v == Some(9.0), &format!("v={:?}", v));
        }

        r.finish();
    }

