    /// INV-1227: CQL INSERT IF NOT EXISTS — duplicate prevention
    #[tokio::test]
    async fn inv1227_cql_insert_if_not_exists() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        try_run(&ex, "CREATE KEYSPACE inv1227ks WITH REPLICATION = {'class': 'SimpleStrategy'}").ok();
        try_run(&ex, "CREATE TABLE inv1227ks.uniq (id INT PRIMARY KEY, name TEXT)").ok();
        try_run(&ex, "INSERT INTO inv1227ks.uniq (id, name) VALUES (1, 'Alice')").ok();

        // Second insert with same PK should not overwrite (IF NOT EXISTS)
        let res = try_run(&ex, "INSERT INTO inv1227ks.uniq (id, name) VALUES (1, 'Replacement') IF NOT EXISTS");
        r.check("ine-ok", res.is_ok(), &format!("res={:?}", res));
        if let Ok(ref qr) = res {
            // Should return [applied] = false, affected_rows = 0
            r.check("not-applied", qr.affected_rows == Some(0), &format!("affected={:?}", qr.affected_rows));
        }

        // Original value should remain
        let res2 = try_run(&ex, "SELECT name FROM inv1227ks.uniq WHERE id = 1");
        if let Ok(ref qr) = res2 {
            if !qr.rows.is_empty() {
                let v = qr.rows[0][0].as_str().unwrap_or("");
                r.check("still-alice", v == "Alice", &format!("v={}", v));
            }
        }

        r.finish();
    }

