    /// INV-1232: CQL counter increment/decrement
    #[tokio::test]
    async fn inv1232_cql_counter() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        try_run(&ex, "CREATE KEYSPACE inv1232ks WITH REPLICATION = {'class': 'SimpleStrategy'}").ok();
        try_run(&ex, "CREATE TABLE inv1232ks.counters (id INT PRIMARY KEY, hits COUNTER)").ok();
        // Initialize counter
        try_run(&ex, "INSERT INTO inv1232ks.counters (id, hits) VALUES (1, 0)").ok();

        // Increment
        let res = try_run(&ex, "UPDATE inv1232ks.counters SET hits = hits + 5 WHERE id = 1");
        r.check("incr-ok", res.is_ok(), &format!("res={:?}", res));

        let res2 = try_run(&ex, "SELECT hits FROM inv1232ks.counters WHERE id = 1");
        r.check("sel-ok", res2.is_ok(), &format!("res2={:?}", res2));
        if let Ok(ref qr) = res2 {
            if !qr.rows.is_empty() {
                let v = val(&qr.rows[0][0]);
                r.check("hits-5", v == Some(5.0), &format!("v={:?}", v));
            }
        }

        // Decrement
        let res3 = try_run(&ex, "UPDATE inv1232ks.counters SET hits = hits - 2 WHERE id = 1");
        r.check("decr-ok", res3.is_ok(), &format!("res3={:?}", res3));

        let res4 = try_run(&ex, "SELECT hits FROM inv1232ks.counters WHERE id = 1");
        if let Ok(ref qr) = res4 {
            if !qr.rows.is_empty() {
                let v = val(&qr.rows[0][0]);
                r.check("hits-3", v == Some(3.0), &format!("v={:?}", v));
            }
        }

        r.finish();
    }

