        try_run(&ex, "CREATE KEYSPACE inv1241ks WITH REPLICATION = {'class': 'SimpleStrategy'}").ok();
        try_run(&ex, "CREATE TABLE inv1241ks.cache (id INT PRIMARY KEY, val TEXT)").ok();

