    /// INV-1244: Cypher MATCH with WHERE comparison operators
    #[tokio::test]
    async fn inv1244_cypher_where_operators() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        try_run(&ex, "CREATE (n:Inv1244 {name: 'Alice', age: 30})").ok();
        try_run(&ex, "CREATE (n:Inv1244 {name: 'Bob', age: 25})").ok();
        try_run(&ex, "CREATE (n:Inv1244 {name: 'Carol', age: 35})").ok();

        // Greater than
        let res1 = try_run(&ex, "MATCH (n:Inv1244) WHERE n.age > 28 RETURN n.name");
        r.check("gt-ok", res1.is_ok(), &format!("res1={:?}", res1));
        if let Ok(ref qr) = res1 {
            r.check("gt-2", qr.rows.len() == 2, &format!("len={}", qr.rows.len()));
        }

        // Less than
        let res2 = try_run(&ex, "MATCH (n:Inv1244) WHERE n.age < 30 RETURN n.name");
        r.check("lt-ok", res2.is_ok(), &format!("res2={:?}", res2));
        if let Ok(ref qr) = res2 {
            r.check("lt-1", qr.rows.len() == 1, &format!("len={}", qr.rows.len()));
        }

        // Equality
        let res3 = try_run(&ex, "MATCH (n:Inv1244) WHERE n.age = 30 RETURN n.name");
        r.check("eq-ok", res3.is_ok(), &format!("res3={:?}", res3));
        if let Ok(ref qr) = res3 {
            r.check("eq-1", qr.rows.len() == 1, &format!("len={}", qr.rows.len()));
        }

        r.finish();
    }

