    /// INV-1278: CQL INSERT IF NOT EXISTS (idempotent)
    #[tokio::test]
    async fn inv1278_cql_insert_if_not_exists() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        try_run(&ex, "CREATE TABLE inv1278ks.data (id INT PRIMARY KEY, val TEXT)").ok();
        let ins1 = try_run(&ex, "INSERT INTO inv1278ks.data (id, val) VALUES (1, 'first') IF NOT EXISTS");
        r.check("ins1-ok", ins1.is_ok(), &format!("ins1={:?}", ins1));

        // Second insert with same key should not fail
        let ins2 = try_run(&ex, "INSERT INTO inv1278ks.data (id, val) VALUES (1, 'second') IF NOT EXISTS");
        r.check("ins2-ok", ins2.is_ok(), &format!("ins2={:?}", ins2));

        // Value should still be 'first' (not overwritten)
        let res = try_run(&ex, "SELECT val FROM inv1278ks.data WHERE id = 1");
        r.check("select-ok", res.is_ok(), &format!("res={:?}", res));
        if let Ok(ref qr) = res {
            r.check("1-row", qr.rows.len() == 1, &format!("len={}", qr.rows.len()));
            if qr.rows.len() == 1 {
                let v = qr.rows[0][0].as_str().unwrap_or("");
                r.check("val-first", v == "first", &format!("val={}", v));
            }
        }

        r.finish();
    }

