    // ==================== BATCH 101: STORAGE/CONCURRENCY STRESS (INV-1303 to INV-1322) ====================

    /// INV-1303: Concurrent SQL inserts from multiple tasks
    #[tokio::test]
    async fn inv1303_concurrent_sql_inserts() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1303_stress (id INT PRIMARY KEY, val TEXT)");
        let ex_arc = std::sync::Arc::new(ex);
        let mut handles = Vec::new();
        for i in 0..20 {
            let e = ex_arc.clone();
            handles.push(tokio::spawn(async move {
                let sql = format!("INSERT INTO inv1303_stress (id, val) VALUES ({}, 'v{}')", i, i);
                try_run(&e, &sql)
            }));
        }
        for h in handles {
            let _ = h.await;
        }

        let qr = run(&*ex_arc, "SELECT COUNT(*) FROM inv1303_stress");
        let cnt = val(&qr.rows[0][0]).unwrap_or(0.0);
        r.check("20-inserted", cnt == 20.0, &format!("cnt={}", cnt));

        r.finish();
    }

    /// INV-1304: Concurrent SQL reads during writes
    #[tokio::test]
    async fn inv1304_concurrent_read_write() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1304_rw (id INT PRIMARY KEY, val INT)");
        for i in 1..=100 {
            try_run(&ex, &format!("INSERT INTO inv1304_rw (id, val) VALUES ({}, {})", i, i)).ok();
        }

        let ex_arc = std::sync::Arc::new(ex);
        let mut handles = Vec::new();
        // 10 readers
        for _ in 0..10 {
            let e = ex_arc.clone();
            handles.push(tokio::spawn(async move {
                try_run(&e, "SELECT COUNT(*) FROM inv1304_rw")
            }));
        }
        for h in handles {
            let res = h.await.unwrap();
            r.check("read-ok", res.is_ok(), &format!("res={:?}", res));
        }

        r.finish();
    }

