    /// INV-1306: SQL transaction-like multi-statement consistency
    #[tokio::test]
    async fn inv1306_multi_statement_consistency() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1306_acct (id INT PRIMARY KEY, balance INT)");
        run(&ex, "INSERT INTO inv1306_acct (id, balance) VALUES (1, 1000)");
        run(&ex, "INSERT INTO inv1306_acct (id, balance) VALUES (2, 500)");

        // Transfer 200 from account 1 to account 2
        run(&ex, "UPDATE inv1306_acct SET balance = 800 WHERE id = 1");
        run(&ex, "UPDATE inv1306_acct SET balance = 700 WHERE id = 2");

        let qr = run(&ex, "SELECT SUM(balance) FROM inv1306_acct");
        let total = val(&qr.rows[0][0]).unwrap_or(0.0);
        r.check("total-1500", total == 1500.0, &format!("total={}", total));

        r.finish();
    }

