    /// INV-1315: SQL aggregate chain — SUM, AVG, MIN, MAX, COUNT in one query
    #[tokio::test]
    async fn inv1315_aggregate_chain() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1315_agg (id INT PRIMARY KEY, val INT)");
        for i in 1..=10 {
            try_run(&ex, &format!("INSERT INTO inv1315_agg (id, val) VALUES ({}, {})", i, i * 10)).ok();
        }

        let qr = run(&ex, "SELECT SUM(val), AVG(val), MIN(val), MAX(val), COUNT(*) FROM inv1315_agg");
        r.check("1-row", qr.rows.len() == 1, &format!("len={}", qr.rows.len()));
        if qr.rows.len() == 1 {
            let sum = val(&qr.rows[0][0]).unwrap_or(0.0);
            let avg = val(&qr.rows[0][1]).unwrap_or(0.0);
            let min = val(&qr.rows[0][2]).unwrap_or(0.0);
            let max = val(&qr.rows[0][3]).unwrap_or(0.0);
            let cnt = val(&qr.rows[0][4]).unwrap_or(0.0);
            r.check("sum-550", sum == 550.0, &format!("sum={}", sum));
            r.check("avg-55", avg == 55.0, &format!("avg={}", avg));
            r.check("min-10", min == 10.0, &format!("min={}", min));
            r.check("max-100", max == 100.0, &format!("max={}", max));
            r.check("cnt-10", cnt == 10.0, &format!("cnt={}", cnt));
        }

        r.finish();
    }

