    async fn inv1317_group_by_having() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1317_grp (id INT PRIMARY KEY, dept TEXT, salary INT)");
        try_run(&ex, "INSERT INTO inv1317_grp (id, dept, salary) VALUES (1, 'eng', 100)").ok();
        try_run(&ex, "INSERT INTO inv1317_grp (id, dept, salary) VALUES (2, 'eng', 120)").ok();
        try_run(&ex, "INSERT INTO inv1317_grp (id, dept, salary) VALUES (3, 'sales', 80)").ok();
        try_run(&ex, "INSERT INTO inv1317_grp (id, dept, salary) VALUES (4, 'sales', 90)").ok();
        try_run(&ex, "INSERT INTO inv1317_grp (id, dept, salary) VALUES (5, 'hr', 70)").ok();

        let qr = run(&ex, "SELECT dept, SUM(salary) FROM inv1317_grp GROUP BY dept HAVING SUM(salary) > 100");
        // eng: 220, sales: 170, hr: 70 → eng and sales qualify
        r.check("2-groups", qr.rows.len() == 2, &format!("len={}", qr.rows.len()));

        r.finish();
    }

    /// INV-1318: SQL UNION combines results
