        try_run(&ex, "INSERT INTO inv1318_a (id, name) VALUES (2, 'Bob')").ok();
        try_run(&ex, "INSERT INTO inv1318_b (id, name) VALUES (1, 'Carol')").ok();
        try_run(&ex, "INSERT INTO inv1318_b (id, name) VALUES (2, 'Bob')").ok();

        let qr = run(&ex, "SELECT name FROM inv1318_a UNION SELECT name FROM inv1318_b");
        // UNION deduplicates: Alice, Bob, Carol = 3
