    /// INV-1320: SQL window function ROW_NUMBER
    #[tokio::test]
    async fn inv1320_sql_row_number() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1320_win (id INT PRIMARY KEY, dept TEXT, salary INT)");
        try_run(&ex, "INSERT INTO inv1320_win (id, dept, salary) VALUES (1, 'eng', 100)").ok();
        try_run(&ex, "INSERT INTO inv1320_win (id, dept, salary) VALUES (2, 'eng', 120)").ok();
        try_run(&ex, "INSERT INTO inv1320_win (id, dept, salary) VALUES (3, 'sales', 80)").ok();

        let qr = run(&ex, "SELECT id, ROW_NUMBER() OVER (ORDER BY salary DESC) AS rn FROM inv1320_win ORDER BY rn");
        r.check("3-rows", qr.rows.len() == 3, &format!("len={}", qr.rows.len()));
        if qr.rows.len() == 3 {
            // Highest salary (120, id=2) should get rn=1, ordered first
            let rn1 = val(&qr.rows[0][1]).unwrap_or(0.0);
            r.check("rn-1", rn1 == 1.0, &format!("rn1={}", rn1));
        }

        r.finish();
    }

    /// INV-1321: Mixed SQL and CQL on same executor
    #[tokio::test]
    async fn inv1321_mixed_sql_cql() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL table
        run(&ex, "CREATE TABLE inv1321_sql (id INT PRIMARY KEY, val TEXT)");
        run(&ex, "INSERT INTO inv1321_sql (id, val) VALUES (1, 'sql_data')");

        // CQL table (keyspace-qualified triggers CQL routing)
        try_run(&ex, "CREATE TABLE inv1321ks.data (id INT PRIMARY KEY, val TEXT)").ok();
        try_run(&ex, "INSERT INTO inv1321ks.data (id, val) VALUES (1, 'cql_data')").ok();

        let sql_res = run(&ex, "SELECT * FROM inv1321_sql");
        r.check("sql-1", sql_res.rows.len() == 1, &format!("sql-len={}", sql_res.rows.len()));

        let cql_res = try_run(&ex, "SELECT * FROM inv1321ks.data");
        r.check("cql-ok", cql_res.is_ok(), &format!("cql={:?}", cql_res));
        if let Ok(ref qr) = cql_res {
            r.check("cql-1", qr.rows.len() == 1, &format!("cql-len={}", qr.rows.len()));
        }

        r.finish();
    }

    /// INV-1322: Mixed SQL, CQL, and Cypher on same executor
    #[tokio::test]
    async fn inv1322_mixed_all_three() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL
        run(&ex, "CREATE TABLE inv1322_sql (id INT PRIMARY KEY, val TEXT)");
        run(&ex, "INSERT INTO inv1322_sql (id, val) VALUES (1, 'sql')");

        // CQL
        try_run(&ex, "CREATE TABLE inv1322ks.data (id INT PRIMARY KEY, val TEXT)").ok();
        try_run(&ex, "INSERT INTO inv1322ks.data (id, val) VALUES (1, 'cql')").ok();

        // Cypher
        try_run(&ex, "CREATE (n:Inv1322 {val: 'cypher'})").ok();

        // Query all three
        let sql = run(&ex, "SELECT * FROM inv1322_sql");
        let cql = try_run(&ex, "SELECT * FROM inv1322ks.data");
        let cypher = try_run(&ex, "MATCH (n:Inv1322) RETURN n.val");

        r.check("sql-1", sql.rows.len() == 1, &format!("sql-len={}", sql.rows.len()));
        r.check("cql-ok", cql.is_ok(), &format!("cql={:?}", cql));
        r.check("cypher-ok", cypher.is_ok(), &format!("cypher={:?}", cypher));

        if let Ok(ref qr) = cql {
            r.check("cql-1", qr.rows.len() == 1, &format!("cql-len={}", qr.rows.len()));
        }
        if let Ok(ref qr) = cypher {
            r.check("cypher-1", qr.rows.len() == 1, &format!("cypher-len={}", qr.rows.len()));
        }

        r.finish();
    }

