        run(&ex, "CREATE TABLE inv1352_emp (id INT PRIMARY KEY, name TEXT, dept_id INT)");
        run(&ex, "INSERT INTO inv1352_emp (id, name, dept_id) VALUES (1, 'Alice', 10)");
