        run(&ex, "INSERT INTO inv1370_data (id, score) VALUES (3, 90)");

        let qr = run(&ex, "SELECT id, DENSE_RANK() OVER (ORDER BY score DESC) AS dr FROM inv1370_data ORDER BY id");
