    /// INV-1400: Large concurrent mixed workload
    #[tokio::test]
    async fn inv1400_concurrent_mixed() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        run(&ex, "CREATE TABLE inv1400_data (id INT PRIMARY KEY, val INT)");
        for i in 1..=100 {
            run(&ex, &format!("INSERT INTO inv1400_data (id, val) VALUES ({}, {})", i, i));
        }

        let ex_arc = std::sync::Arc::new(ex);
        let mut handles = Vec::new();
        // Mix of reads and writes
        for i in 0..10 {
            let e = ex_arc.clone();
            handles.push(tokio::spawn(async move {
                if i % 2 == 0 {
                    try_run(&e, "SELECT COUNT(*) FROM inv1400_data")
                } else {
                    try_run(&e, "SELECT AVG(val) FROM inv1400_data")
                }
            }));
        }

        let mut ok_count = 0;
        for h in handles {
            if h.await.unwrap().is_ok() { ok_count += 1; }
        }
        r.check("all-ok", ok_count == 10, &format!("ok={}", ok_count));

        r.finish();
    }

