    /// INV-1402: Mixed CQL + Cypher + SQL in single session with data isolation
    #[tokio::test]
    async fn inv1402_full_polyglot() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL
        run(&ex, "CREATE TABLE inv1402_sql (id INT PRIMARY KEY, val INT)");
        for i in 1..=5 {
            run(&ex, &format!("INSERT INTO inv1402_sql (id, val) VALUES ({}, {})", i, i * 10));
        }

        // CQL
        try_run(&ex, "CREATE TABLE inv1402ks.data (id INT PRIMARY KEY, val INT)").ok();
        for i in 1..=3 {
            try_run(&ex, &format!("INSERT INTO inv1402ks.data (id, val) VALUES ({}, {})", i, i * 100)).ok();
        }

        // Cypher
        for i in 1..=4 {
            try_run(&ex, &format!("CREATE (n:Inv1402 {{idx: {}}})", i)).ok();
        }

        // Query all three
        let sql = run(&ex, "SELECT SUM(val) FROM inv1402_sql");
        let cql = try_run(&ex, "SELECT COUNT(*) FROM inv1402ks.data");
        let cypher = try_run(&ex, "MATCH (n:Inv1402) RETURN count(n) AS cnt");

        let sql_sum = val(&sql.rows[0][0]).unwrap_or(0.0);
        r.check("sql-150", sql_sum == 150.0, &format!("sql={}", sql_sum));

        if let Ok(ref qr) = cql {
            let cql_cnt = val(&qr.rows[0][0]).unwrap_or(0.0);
            r.check("cql-3", cql_cnt == 3.0, &format!("cql={}", cql_cnt));
        }

        if let Ok(ref qr) = cypher {
            let cy_cnt = val(&qr.rows[0][0]).unwrap_or(0.0);
            r.check("cypher-4", cy_cnt == 4.0, &format!("cypher={}", cy_cnt));
        }

        r.finish();
    }

