    #[test]
    fn inv1446_window_rank_partition() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv1446 (id INT, dept TEXT, salary INT)");
        run(&ex, "INSERT INTO inv1446 VALUES (1, 'eng', 120)");
        run(&ex, "INSERT INTO inv1446 VALUES (2, 'eng', 110)");
        run(&ex, "INSERT INTO inv1446 VALUES (3, 'eng', 110)");
        run(&ex, "INSERT INTO inv1446 VALUES (4, 'sales', 100)");
        run(&ex, "INSERT INTO inv1446 VALUES (5, 'sales', 90)");
        let qr = run(&ex, "SELECT id, dept, salary, RANK() OVER (PARTITION BY dept ORDER BY salary DESC) AS rnk FROM inv1446 ORDER BY dept, rnk, id");
        r.check("rows-5", qr.rows.len() == 5, &format!("len={}", qr.rows.len()));
        // eng: 120→rank1, 110→rank2(tie), 110→rank2(tie)
        if qr.rows.len() == 5 {
            let r1 = val(&qr.rows[0][3]).unwrap_or(-1.0);
            let r2 = val(&qr.rows[1][3]).unwrap_or(-1.0);
            let r3 = val(&qr.rows[2][3]).unwrap_or(-1.0);
            r.check("eng-r1", r1 == 1.0, &format!("r1={}", r1));
            r.check("eng-r2-tie", r2 == 2.0, &format!("r2={}", r2));
            r.check("eng-r3-tie", r3 == 2.0, &format!("r3={}", r3));
            // sales: 100→rank1, 90→rank2
            let r4 = val(&qr.rows[3][3]).unwrap_or(-1.0);
            let r5 = val(&qr.rows[4][3]).unwrap_or(-1.0);
            r.check("sales-r1", r4 == 1.0, &format!("r4={}", r4));
            r.check("sales-r2", r5 == 2.0, &format!("r5={}", r5));
        }
        r.finish();
    }

