    #[test]
    fn inv1449_window_ntile_partition() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv1449 (id INT, val INT)");
        for i in 1..=6 {
            run(&ex, &format!("INSERT INTO inv1449 VALUES ({}, {})", i, i * 10));
        }
        let qr = run(&ex, "SELECT id, NTILE(2) OVER (ORDER BY id) AS bucket FROM inv1449 ORDER BY id");
        r.check("rows-6", qr.rows.len() == 6, &format!("len={}", qr.rows.len()));
        if qr.rows.len() == 6 {
            // 6 rows / 2 buckets = 3 per bucket: ids 1,2,3→bucket1, ids 4,5,6→bucket2
            let b1 = val(&qr.rows[0][1]).unwrap_or(-1.0);
            let b3 = val(&qr.rows[2][1]).unwrap_or(-1.0);
            let b4 = val(&qr.rows[3][1]).unwrap_or(-1.0);
            let b6 = val(&qr.rows[5][1]).unwrap_or(-1.0);
            r.check("first-bucket1", b1 == 1.0, &format!("b1={}", b1));
            r.check("third-bucket1", b3 == 1.0, &format!("b3={}", b3));
            r.check("fourth-bucket2", b4 == 2.0, &format!("b4={}", b4));
            r.check("sixth-bucket2", b6 == 2.0, &format!("b6={}", b6));
        }
        r.finish();
    }

