    fn inv1462_window_with_group_by() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv1462 (id INT, dept TEXT, salary INT)");
        run(&ex, "INSERT INTO inv1462 VALUES (1, 'eng', 100)");
        run(&ex, "INSERT INTO inv1462 VALUES (2, 'eng', 200)");
        run(&ex, "INSERT INTO inv1462 VALUES (3, 'sales', 150)");
        run(&ex, "INSERT INTO inv1462 VALUES (4, 'hr', 120)");
        // CTE: aggregate first, then window over result
        let qr = run(&ex, "WITH dept_totals AS (SELECT dept, SUM(salary) AS total FROM inv1462 GROUP BY dept) SELECT dept, total, RANK() OVER (ORDER BY total DESC) AS rnk FROM dept_totals ORDER BY rnk");
        r.check("rows-3", qr.rows.len() == 3, &format!("len={}", qr.rows.len()));
        if qr.rows.len() == 3 {
            // eng=300 → rank1, sales=150 → rank2, hr=120 → rank3
            let rnk1 = val(&qr.rows[0][2]).unwrap_or(-1.0);
            let rnk3 = val(&qr.rows[2][2]).unwrap_or(-1.0);
            r.check("rank-1", rnk1 == 1.0, &format!("rnk1={}", rnk1));
            r.check("rank-3", rnk3 == 3.0, &format!("rnk3={}", rnk3));
            let top = val(&qr.rows[0][1]).unwrap_or(-1.0);
            r.check("eng-total-300", top == 300.0, &format!("top={}", top));
        }
        r.finish();
    }

