    #[test]
    fn inv1482_polyglot_full() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        // SQL table
        run(&ex, "CREATE TABLE inv1482_users (id INT, name TEXT, score INT)");
        run(&ex, "INSERT INTO inv1482_users VALUES (1, 'Alice', 100)");
        run(&ex, "INSERT INTO inv1482_users VALUES (2, 'Bob', 200)");
        // CQL table (using keyspace prefix)
        run(&ex, "CREATE TABLE inv1482ks__sessions (id INT, user_id INT, duration INT)");
        run(&ex, "INSERT INTO inv1482ks__sessions (id, user_id, duration) VALUES (1, 1, 60)");
        run(&ex, "INSERT INTO inv1482ks__sessions (id, user_id, duration) VALUES (2, 2, 120)");
        // Cypher graph
        try_run(&ex, "CREATE (n:Inv1482 {user_id: 1, badge: 'gold'})").ok();
        try_run(&ex, "CREATE (n:Inv1482 {user_id: 2, badge: 'silver'})").ok();

        // SQL queries
        let sql_q = run(&ex, "SELECT name, score, RANK() OVER (ORDER BY score DESC) AS rnk FROM inv1482_users ORDER BY rnk");
        r.check("sql-rows-2", sql_q.rows.len() == 2, &format!("sql_len={}", sql_q.rows.len()));

        // CQL query
        let cql_q = run(&ex, "SELECT * FROM inv1482ks.sessions WHERE user_id = 1 ALLOW FILTERING");
        r.check("cql-rows-1", cql_q.rows.len() == 1, &format!("cql_len={}", cql_q.rows.len()));

        // Cypher query
        let cy_q = try_run(&ex, "MATCH (n:Inv1482) WHERE n.badge = 'gold' RETURN n.user_id");
        if let Ok(ref q) = cy_q {
            r.check("cypher-rows-1", q.rows.len() == 1, &format!("cy_len={}", q.rows.len()));
        } else {
            r.check("cypher-ok", false, &format!("err={:?}", cy_q));
        }

        r.finish();
    }

