    #[test]
    fn inv1600_milestone_5200() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        // Milestone test: full polyglot DB with window, CTE, subquery, CQL, Cypher
        run(&ex, "CREATE TABLE inv1600 (id INT, val INT)");
        for i in 1..=5 { run(&ex, &format!("INSERT INTO inv1600 VALUES ({}, {})", i, i * 100)); }
        // CTE + window
        let q1 = run(&ex, "WITH base AS (SELECT id, val FROM inv1600) SELECT id, val, RANK() OVER (ORDER BY val DESC) AS rnk FROM base ORDER BY rnk");
        r.check("cte-window-5", q1.rows.len() == 5, &format!("q1_len={}", q1.rows.len()));
        // Subquery
        let q2 = run(&ex, "SELECT COUNT(*) FROM inv1600 WHERE val > (SELECT AVG(val) FROM inv1600)");
        let c2 = val(&q2.rows[0][0]).unwrap_or(-1.0);
        r.check("above-avg-2", c2 == 2.0, &format!("c2={}", c2));
        // CQL
        run(&ex, "CREATE TABLE inv1600ks__kv (id INT, data TEXT)");
        run(&ex, "INSERT INTO inv1600ks__kv (id, data) VALUES (1, 'milestone')");
        let q3 = run(&ex, "SELECT * FROM inv1600ks.kv ALLOW FILTERING");
        r.check("cql-1", q3.rows.len() == 1, &format!("q3_len={}", q3.rows.len()));
        // Cypher
        try_run(&ex, "CREATE (n:Inv1600 {milestone: true})").ok();
        let q4 = try_run(&ex, "MATCH (n:Inv1600) RETURN count(n) AS cnt");
        if let Ok(ref q) = q4 {
            r.check("cypher-1", val(&q.rows[0][0]).unwrap_or(0.0) == 1.0, "cypher");
        }
        r.finish();
    }

