        let qr = run(&ex, "WITH RECURSIVE tree AS (SELECT id, name, 1 AS depth FROM inv1601 WHERE parent_id = 0 UNION ALL SELECT c.id, c.name, t.depth + 1 FROM inv1601 c JOIN tree t ON c.parent_id = t.id) SELECT COUNT(*) FROM tree");
        let cnt = val(&qr.rows[0][0]).unwrap_or(-1.0);
