    #[test]
    fn inv1622_full_polyglot_milestone() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        // SQL with CTE, window, subquery
        run(&ex, "CREATE TABLE inv1622 (id INT, dept TEXT, salary INT)");
        run(&ex, "INSERT INTO inv1622 VALUES (1, 'eng', 100)");
        run(&ex, "INSERT INTO inv1622 VALUES (2, 'eng', 200)");
        run(&ex, "INSERT INTO inv1622 VALUES (3, 'sales', 150)");
        let q1 = run(&ex, "WITH ranked AS (SELECT dept, salary, RANK() OVER (PARTITION BY dept ORDER BY salary DESC) AS rnk FROM inv1622) SELECT dept, salary FROM ranked WHERE rnk = 1 ORDER BY dept");
        r.check("sql-cte-window-2", q1.rows.len() == 2, &format!("q1={}", q1.rows.len()));
        // CQL aggregate
        run(&ex, "CREATE TABLE inv1622ks__metrics (id INT, region TEXT, val INT)");
        run(&ex, "INSERT INTO inv1622ks__metrics (id, region, val) VALUES (1, 'us', 100)");
        run(&ex, "INSERT INTO inv1622ks__metrics (id, region, val) VALUES (2, 'us', 200)");
        let q2 = run(&ex, "SELECT SUM(val) FROM inv1622ks.metrics WHERE region = 'us' ALLOW FILTERING");
        let s = val(&q2.rows[0][0]).unwrap_or(-1.0);
        r.check("cql-sum-300", s == 300.0, &format!("s={}", s));
        // Cypher with string predicate
        try_run(&ex, "CREATE (n:Inv1622 {name: 'Alice', role: 'admin'})").ok();
        try_run(&ex, "CREATE (n:Inv1622 {name: 'Bob', role: 'user'})").ok();
        let q3 = try_run(&ex, "MATCH (n:Inv1622) WHERE n.name CONTAINS 'li' RETURN n.name");
        if let Ok(ref q) = q3 {
            r.check("cypher-contains-1", q.rows.len() == 1, &format!("q3={}", q.rows.len()));
        }
        r.finish();
    }

