    #[test]
    fn inv1624_sql_null_arithmetic() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv1624 (id INT, a INT, b INT)");
        run(&ex, "INSERT INTO inv1624 VALUES (1, 10, NULL)");
        let qr = run(&ex, "SELECT a + b, a * b, a - b FROM inv1624");
        r.check("rows-1", qr.rows.len() == 1, &format!("len={}", qr.rows.len()));
        if !qr.rows.is_empty() {
            // NULL propagates: anything op NULL = NULL
            r.check("add-null", qr.rows[0][0].is_null(), &format!("add={:?}", qr.rows[0][0]));
            r.check("mul-null", qr.rows[0][1].is_null(), &format!("mul={:?}", qr.rows[0][1]));
            r.check("sub-null", qr.rows[0][2].is_null(), &format!("sub={:?}", qr.rows[0][2]));
        }
        r.finish();
    }

