    fn inv1625_sql_null_comparison() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv1625 (id INT, val INT)");
        run(&ex, "INSERT INTO inv1625 VALUES (1, 10)");
        run(&ex, "INSERT INTO inv1625 VALUES (2, NULL)");
        // NULL = NULL should NOT match (SQL standard)
        let qr = run(&ex, "SELECT COUNT(*) FROM inv1625 WHERE val = NULL");
        let cnt = val(&qr.rows[0][0]).unwrap_or(-1.0);
        r.check("eq-null-0", cnt == 0.0, &format!("cnt={}", cnt));
        // IS NULL should match
        let qr2 = run(&ex, "SELECT COUNT(*) FROM inv1625 WHERE val IS NULL");
        let cnt2 = val(&qr2.rows[0][0]).unwrap_or(-1.0);
        r.check("is-null-1", cnt2 == 1.0, &format!("cnt2={}", cnt2));
        r.finish();
    }

