    #[test]
    fn inv1647_sql_window_then_case_via_cte() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv1647 (id INT, dept TEXT, val INT)");
        run(&ex, "INSERT INTO inv1647 VALUES (1, 'eng', 100)");
        run(&ex, "INSERT INTO inv1647 VALUES (2, 'eng', 200)");
        run(&ex, "INSERT INTO inv1647 VALUES (3, 'sales', 150)");
        // CTE computes window, outer query uses CASE on result
        let qr = run(&ex, "WITH ranked AS (SELECT id, dept, val, RANK() OVER (PARTITION BY dept ORDER BY val DESC) AS rnk FROM inv1647) SELECT id, dept, CASE WHEN rnk = 1 THEN 'top' ELSE 'other' END AS position FROM ranked ORDER BY id");
        r.check("rows-3", qr.rows.len() == 3, &format!("len={}", qr.rows.len()));
        if qr.rows.len() == 3 {
            let p2 = qr.rows[1][2].as_str().unwrap_or("");
            let p3 = qr.rows[2][2].as_str().unwrap_or("");
            r.check("eng-top", p2 == "top", &format!("p2={}", p2));
            r.check("sales-top", p3 == "top", &format!("p3={}", p3));
        }
        r.finish();
    }

