    #[test]
    fn inv1668_cypher_create_chain() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        // Create a chain: A→B→C→D
        try_run(&ex, "CREATE (a:Inv1668 {name: 'A'})").ok();
        try_run(&ex, "CREATE (b:Inv1668 {name: 'B'})").ok();
        try_run(&ex, "CREATE (c:Inv1668 {name: 'C'})").ok();
        try_run(&ex, "CREATE (d:Inv1668 {name: 'D'})").ok();
        try_run(&ex, "MATCH (a:Inv1668 {name: 'A'}), (b:Inv1668 {name: 'B'}) CREATE (a)-[:NEXT]->(b)").ok();
        try_run(&ex, "MATCH (b:Inv1668 {name: 'B'}), (c:Inv1668 {name: 'C'}) CREATE (b)-[:NEXT]->(c)").ok();
        try_run(&ex, "MATCH (c:Inv1668 {name: 'C'}), (d:Inv1668 {name: 'D'}) CREATE (c)-[:NEXT]->(d)").ok();
        let qr = try_run(&ex, "MATCH (n:Inv1668) RETURN count(n) AS cnt");
        if let Ok(ref q) = qr {
            r.check("4-nodes", val(&q.rows[0][0]).unwrap_or(0.0) == 4.0, "nodes");
        }
        // Traverse one hop from B
        let qr2 = try_run(&ex, "MATCH (b:Inv1668 {name: 'B'})-[:NEXT]->(c) RETURN c.name");
        if let Ok(ref q) = qr2 {
            r.check("b-to-c", q.rows.len() == 1, &format!("len={}", q.rows.len()));
            if !q.rows.is_empty() {
                r.check("c-name", q.rows[0][0].as_str() == Some("C"), &format!("n={:?}", q.rows[0][0]));
            }
        }
        r.finish();
    }

