    #[test]
    fn inv1702_sql_window_ntile_4() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv1702_t (id INT, val INT)");
        for i in 1..=12 {
            run(&ex, &format!("INSERT INTO inv1702_t VALUES ({}, {})", i, i * 10));
        }
        // NTILE(4) splits 12 rows into 4 groups of 3
        let q = run(&ex, "SELECT id, NTILE(4) OVER (ORDER BY id) AS tile FROM inv1702_t ORDER BY id");
        r.check("rows-12", q.rows.len() == 12, &format!("rows={}", q.rows.len()));
        // id=1 → tile 1, id=4 → tile 2, id=7 → tile 3, id=10 → tile 4
        let t1 = val(&q.rows[0][1]).unwrap_or(0.0);
        let t4 = val(&q.rows[3][1]).unwrap_or(0.0);
        let t7 = val(&q.rows[6][1]).unwrap_or(0.0);
        let t10 = val(&q.rows[9][1]).unwrap_or(0.0);
        r.check("tile-1", t1 == 1.0, &format!("t1={}", t1));
        r.check("tile-2", t4 == 2.0, &format!("t4={}", t4));
        r.check("tile-3", t7 == 3.0, &format!("t7={}", t7));
        r.check("tile-4", t10 == 4.0, &format!("t10={}", t10));
        r.finish();
    }

