    #[test]
    fn inv1706_sql_window_row_number_partition() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv1706_t (id INT, grp TEXT, val INT)");
        run(&ex, "INSERT INTO inv1706_t VALUES (1, 'a', 30)");
        run(&ex, "INSERT INTO inv1706_t VALUES (2, 'a', 10)");
        run(&ex, "INSERT INTO inv1706_t VALUES (3, 'a', 20)");
        run(&ex, "INSERT INTO inv1706_t VALUES (4, 'b', 50)");
        run(&ex, "INSERT INTO inv1706_t VALUES (5, 'b', 40)");
        let q = run(&ex, "SELECT id, grp, ROW_NUMBER() OVER (PARTITION BY grp ORDER BY val) AS rn FROM inv1706_t ORDER BY grp, rn");
        r.check("rows-5", q.rows.len() == 5, &format!("rows={}", q.rows.len()));
        // grp a: val 10(id=2)→rn1, 20(id=3)→rn2, 30(id=1)→rn3
        let rn1 = val(&q.rows[0][2]).unwrap_or(0.0);
        let rn3 = val(&q.rows[2][2]).unwrap_or(0.0);
        // grp b: val 40(id=5)→rn1, 50(id=4)→rn2
        let rn_b1 = val(&q.rows[3][2]).unwrap_or(0.0);
        r.check("a-rn1", rn1 == 1.0, &format!("rn1={}", rn1));
        r.check("a-rn3", rn3 == 3.0, &format!("rn3={}", rn3));
        r.check("b-rn1", rn_b1 == 1.0, &format!("b-rn1={}", rn_b1));
        r.finish();
    }

