        let q = run(&ex, "WITH stats AS (SELECT grp, AVG(val) AS avg_val FROM inv1720_t GROUP BY grp) SELECT t.id, t.val, s.avg_val FROM inv1720_t t JOIN stats s ON t.grp = s.grp ORDER BY t.id");
