    #[test]
    fn inv1722_polyglot_stress_50() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        // SQL: 20 rows with aggregation
        run(&ex, "CREATE TABLE inv1722_t (id INT, grp TEXT, val INT)");
        for i in 1..=20 {
            let grp = if i % 2 == 0 { "even" } else { "odd" };
            run(&ex, &format!("INSERT INTO inv1722_t VALUES ({}, '{}', {})", i, grp, i * 5));
        }
        let q1 = run(&ex, "SELECT grp, COUNT(*) AS cnt, SUM(val) AS total FROM inv1722_t GROUP BY grp ORDER BY grp");
        r.check("sql-groups", q1.rows.len() == 2, &format!("sql={}", q1.rows.len()));
        let even_cnt = val(&q1.rows[0][1]).unwrap_or(0.0);
        r.check("even-10", even_cnt == 10.0, &format!("even={}", even_cnt));

        // CQL: simple CRUD
        run(&ex, "CREATE TABLE inv1722ks__data (k TEXT, value INT, PRIMARY KEY (k))");
        run(&ex, "INSERT INTO inv1722ks__data (k, value) VALUES ('alpha', 1)");
        run(&ex, "INSERT INTO inv1722ks__data (k, value) VALUES ('beta', 2)");
        let q2 = run(&ex, "SELECT COUNT(*) FROM inv1722ks.data ALLOW FILTERING");
        r.check("cql-count", val(&q2.rows[0][0]).unwrap_or(0.0) == 2.0, "cql");

        // Cypher: create + grouped aggregate
        try_run(&ex, "CREATE (n:Inv1722 {tier: 'gold', pts: 100})").ok();
        try_run(&ex, "CREATE (n:Inv1722 {tier: 'gold', pts: 200})").ok();
        try_run(&ex, "CREATE (n:Inv1722 {tier: 'silver', pts: 50})").ok();
        let q3 = try_run(&ex, "MATCH (n:Inv1722) RETURN n.tier AS tier, SUM(n.pts) AS total ORDER BY tier");
        if let Ok(ref res) = q3 {
            r.check("cypher-groups", res.rows.len() == 2, &format!("cypher={}", res.rows.len()));
            let gold = val(&res.rows[0][1]).unwrap_or(0.0);
            r.check("gold-300", gold == 300.0, &format!("gold={}", gold));
        } else {
            r.check("cypher-ok", false, &format!("err={:?}", q3));
        }
        r.finish();
    }

