    #[test]
    fn inv1762_sql_2000_row_join_agg() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv1762_orders (oid INT, cid INT)");
        run(&ex, "CREATE TABLE inv1762_items (iid INT, oid INT, amount INT)");
        for i in 1..=100 {
            run(&ex, &format!("INSERT INTO inv1762_orders VALUES ({}, {})", i, i % 10));
        }
        for i in 1..=2000 {
            run(&ex, &format!("INSERT INTO inv1762_items VALUES ({}, {}, {})", i, (i % 100) + 1, i % 50));
        }
        let q = run(&ex, "SELECT o.cid, SUM(it.amount) AS total FROM inv1762_orders o JOIN inv1762_items it ON o.oid = it.oid GROUP BY o.cid ORDER BY total DESC LIMIT 5");
        r.check("top-5", q.rows.len() == 5, &format!("rows={}", q.rows.len()));
        // Verify descending order
        let vals: Vec<f64> = q.rows.iter().filter_map(|r| val(&r[1])).collect();
        let sorted = vals.windows(2).all(|w| w[0] >= w[1]);
        r.check("desc-order", sorted, &format!("vals={:?}", vals));
        r.finish();
    }

