    #[test]
    fn inv1764_sql_window_lag_partition() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv1764_t (id INT, grp TEXT, val INT)");
        run(&ex, "INSERT INTO inv1764_t VALUES (1, 'a', 10)");
        run(&ex, "INSERT INTO inv1764_t VALUES (2, 'a', 20)");
        run(&ex, "INSERT INTO inv1764_t VALUES (3, 'a', 30)");
        run(&ex, "INSERT INTO inv1764_t VALUES (4, 'b', 40)");
        run(&ex, "INSERT INTO inv1764_t VALUES (5, 'b', 50)");
        let q = run(&ex, "SELECT id, grp, LAG(val) OVER (PARTITION BY grp ORDER BY id) AS prev_val FROM inv1764_t ORDER BY id");
        r.check("rows-5", q.rows.len() == 5, &format!("rows={}", q.rows.len()));
        // id=1: first in 'a' partition → NULL
        r.check("first-null", q.rows[0][2].is_null(), &format!("{:?}", q.rows[0][2]));
        // id=2: prev is 10
        let prev2 = val(&q.rows[1][2]).unwrap_or(-1.0);
        r.check("lag-10", prev2 == 10.0, &format!("prev2={}", prev2));
        // id=4: first in 'b' partition → NULL
        r.check("b-first-null", q.rows[3][2].is_null(), &format!("{:?}", q.rows[3][2]));
        r.finish();
    }

