    #[test]
    fn inv1774_sql_cte_recursive_hierarchy() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv1774_cats (cat_id INT, parent_id INT, name TEXT)");
        run(&ex, "INSERT INTO inv1774_cats VALUES (1, NULL, 'Root')");
        run(&ex, "INSERT INTO inv1774_cats VALUES (2, 1, 'Child1')");
        run(&ex, "INSERT INTO inv1774_cats VALUES (3, 1, 'Child2')");
        run(&ex, "INSERT INTO inv1774_cats VALUES (4, 2, 'Grandchild')");
        let q = try_run(&ex, "WITH RECURSIVE tree(cat_id, name, depth) AS (SELECT cat_id, name, 0 FROM inv1774_cats WHERE parent_id IS NULL UNION ALL SELECT c.cat_id, c.name, t.depth + 1 FROM inv1774_cats c JOIN tree t ON c.parent_id = t.cat_id) SELECT cat_id, name, depth FROM tree ORDER BY depth, cat_id");
        if let Ok(res) = q {
            r.check("rows-4", res.rows.len() == 4, &format!("rows={}", res.rows.len()));
            let root_depth = val(&res.rows[0][2]).unwrap_or(-1.0);
            let grand_depth = val(&res.rows[3][2]).unwrap_or(-1.0);
            r.check("root-0", root_depth == 0.0, &format!("root={}", root_depth));
            r.check("grand-2", grand_depth == 2.0, &format!("grand={}", grand_depth));
        } else {
            r.check("recursive-cte", false, &format!("err={:?}", q));
        }
        r.finish();
    }

