    #[test]
    fn inv1782_polyglot_milestone_5333() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: CTE + window + join
        run(&ex, "CREATE TABLE inv1782_sales (id INT, region TEXT, amount INT)");
        run(&ex, "INSERT INTO inv1782_sales VALUES (1, 'north', 100)");
        run(&ex, "INSERT INTO inv1782_sales VALUES (2, 'north', 200)");
        run(&ex, "INSERT INTO inv1782_sales VALUES (3, 'south', 300)");
        let q1 = run(&ex, "WITH totals AS (SELECT region, SUM(amount) AS total FROM inv1782_sales GROUP BY region) SELECT region, total, RANK() OVER (ORDER BY total DESC) AS rnk FROM totals ORDER BY rnk");
        r.check("sql-cte-window", q1.rows.len() == 2, &format!("q1={}", q1.rows.len()));

        // CQL
        run(&ex, "CREATE TABLE inv1782ks__kv (tag TEXT, num INT, PRIMARY KEY (tag))");
        run(&ex, "INSERT INTO inv1782ks__kv (tag, num) VALUES ('milestone', 5333)");
        let q2 = run(&ex, "SELECT num FROM inv1782ks.kv WHERE tag = 'milestone' ALLOW FILTERING");
        r.check("cql-ok", val(&q2.rows[0][0]).unwrap_or(0.0) == 5333.0, "cql");

        // Cypher: grouped aggregation (using the new engine fix)
        try_run(&ex, "CREATE (n:Inv1782 {cat: 'x', v: 10})").ok();
        try_run(&ex, "CREATE (n:Inv1782 {cat: 'x', v: 20})").ok();
        try_run(&ex, "CREATE (n:Inv1782 {cat: 'y', v: 30})").ok();
        let q3 = try_run(&ex, "MATCH (n:Inv1782) RETURN n.cat AS cat, SUM(n.v) AS total ORDER BY cat");
        if let Ok(res) = q3 {
            r.check("cypher-groups", res.rows.len() == 2, &format!("q3={}", res.rows.len()));
            r.check("x-30", val(&res.rows[0][1]).unwrap_or(0.0) == 30.0, &format!("{:?}", res.rows[0][1]));
        } else {
            r.check("cypher-ok", false, &format!("err={:?}", q3));
        }
        r.finish();
    }

