    #[test]
    fn inv1793_sql_window_ntile_uneven() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv1793_t (id INT)");
        for i in 1..=7 {
            run(&ex, &format!("INSERT INTO inv1793_t VALUES ({})", i));
        }
        // NTILE(3) on 7 rows: 3,2,2 distribution
        let q = run(&ex, "SELECT id, NTILE(3) OVER (ORDER BY id) AS tile FROM inv1793_t ORDER BY id");
        r.check("rows-7", q.rows.len() == 7, &format!("rows={}", q.rows.len()));
        let tiles: Vec<f64> = q.rows.iter().filter_map(|r| val(&r[1])).collect();
        // First 3 get tile 1, next 2 get tile 2, last 2 get tile 3
        r.check("tile1-count", tiles.iter().filter(|&&t| t == 1.0).count() == 3, &format!("{:?}", tiles));
        r.check("tile2-count", tiles.iter().filter(|&&t| t == 2.0).count() == 2, &format!("{:?}", tiles));
        r.check("tile3-count", tiles.iter().filter(|&&t| t == 3.0).count() == 2, &format!("{:?}", tiles));
        r.finish();
    }

