    #[test]
    fn inv1819_sql_where_or_and_precedence() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv1819_t (id INT, a INT, b INT)");
        run(&ex, "INSERT INTO inv1819_t VALUES (1, 1, 1)");
        run(&ex, "INSERT INTO inv1819_t VALUES (2, 1, 0)");
        run(&ex, "INSERT INTO inv1819_t VALUES (3, 0, 1)");
        run(&ex, "INSERT INTO inv1819_t VALUES (4, 0, 0)");
        // AND has higher precedence than OR: a=1 OR b=1 AND id>2 → a=1 OR (b=1 AND id>2)
        let q = run(&ex, "SELECT id FROM inv1819_t WHERE a = 1 OR b = 1 AND id > 2 ORDER BY id");
        // id=1: a=1 → yes; id=2: a=1 → yes; id=3: b=1 AND id>2 → yes; id=4: neither → no
        r.check("precedence-3", q.rows.len() == 3, &format!("rows={}", q.rows.len()));
        let ids: Vec<f64> = q.rows.iter().filter_map(|r| val(&r[0])).collect();
        r.check("ids-1-2-3", ids == vec![1.0, 2.0, 3.0], &format!("{:?}", ids));
        r.finish();
    }

