    #[test]
    fn inv1822_polyglot_full_coverage() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: self-join + window
        run(&ex, "CREATE TABLE inv1822_emp (eid INT, name TEXT, mgr_eid INT, sal INT)");
        run(&ex, "INSERT INTO inv1822_emp VALUES (1, 'Alice', NULL, 100)");
        run(&ex, "INSERT INTO inv1822_emp VALUES (2, 'Bob', 1, 80)");
        run(&ex, "INSERT INTO inv1822_emp VALUES (3, 'Carol', 1, 90)");
        let q1 = run(&ex, "SELECT e.name, RANK() OVER (ORDER BY e.sal DESC) AS rnk FROM inv1822_emp e ORDER BY rnk");
        r.check("sql-ranked", q1.rows.len() == 3, &format!("q1={}", q1.rows.len()));

        // CQL
        run(&ex, "CREATE TABLE inv1822ks__flags (fid TEXT, active INT, PRIMARY KEY (fid))");
        run(&ex, "INSERT INTO inv1822ks__flags (fid, active) VALUES ('f1', 1)");
        let q2 = run(&ex, "SELECT fid FROM inv1822ks.flags WHERE active = 1 ALLOW FILTERING");
        r.check("cql-1", q2.rows.len() == 1, "cql");

        // Cypher: WITH grouped aggregation
        try_run(&ex, "CREATE (n:Inv1822 {cat: 'p', score: 10})").ok();
        try_run(&ex, "CREATE (n:Inv1822 {cat: 'p', score: 20})").ok();
        try_run(&ex, "CREATE (n:Inv1822 {cat: 'q', score: 30})").ok();
        let q3 = try_run(&ex, "MATCH (n:Inv1822) WITH n.cat AS cat, AVG(n.score) AS avg_s RETURN cat, avg_s ORDER BY cat");
        if let Ok(res) = q3 {
            r.check("cypher-avg-groups", res.rows.len() == 2, &format!("q3={}", res.rows.len()));
            r.check("p-avg-15", val(&res.rows[0][1]).unwrap_or(0.0) == 15.0, &format!("{:?}", res.rows[0][1]));
        } else {
            r.check("cypher-ok", false, &format!("err={:?}", q3));
        }
        r.finish();
    }

