    #[test]
    fn inv1823_sql_window_nth_value() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv1823_t (id INT, val INT)");
        run(&ex, "INSERT INTO inv1823_t VALUES (1, 10)");
        run(&ex, "INSERT INTO inv1823_t VALUES (2, 20)");
        run(&ex, "INSERT INTO inv1823_t VALUES (3, 30)");
        run(&ex, "INSERT INTO inv1823_t VALUES (4, 40)");
        let q = run(&ex, "SELECT id, NTH_VALUE(val, 2) OVER (ORDER BY id) AS second FROM inv1823_t ORDER BY id");
        r.check("rows-4", q.rows.len() == 4, &format!("rows={}", q.rows.len()));
        // NTH_VALUE(val, 2) = 20 for rows where frame includes at least 2 rows
        // id=1: frame has 1 row → NULL; id>=2: frame has >=2 → 20
        let nth2 = val(&q.rows[1][1]).unwrap_or(-1.0);
        r.check("nth2-20", nth2 == 20.0, &format!("nth2={}", nth2));
        r.finish();
    }

