    #[test]
    fn inv1842_polyglot_milestone_5413() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: recursive CTE
        let q1 = try_run(&ex, "WITH RECURSIVE seq(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM seq WHERE n < 5) SELECT SUM(n) AS total FROM seq");
        if let Ok(res) = q1 {
            r.check("recursive-15", val(&res.rows[0][0]).unwrap_or(0.0) == 15.0, "recursive");
        }

        // SQL: window with partition
        run(&ex, "CREATE TABLE inv1842_t (id INT, dept TEXT, sal INT)");
        run(&ex, "INSERT INTO inv1842_t VALUES (1, 'a', 50)");
        run(&ex, "INSERT INTO inv1842_t VALUES (2, 'a', 60)");
        run(&ex, "INSERT INTO inv1842_t VALUES (3, 'b', 70)");
        let q2 = run(&ex, "SELECT id, SUM(sal) OVER (PARTITION BY dept) AS dt FROM inv1842_t ORDER BY id");
        r.check("window-ok", val(&q2.rows[0][1]).unwrap_or(0.0) == 110.0, &format!("dt={:?}", q2.rows[0]));

        // CQL
        run(&ex, "CREATE TABLE inv1842ks__milestone (tag TEXT, cnt INT, PRIMARY KEY (tag))");
        run(&ex, "INSERT INTO inv1842ks__milestone (tag, cnt) VALUES ('tests', 5413)");
        let q3 = run(&ex, "SELECT cnt FROM inv1842ks.milestone WHERE tag = 'tests' ALLOW FILTERING");
        r.check("cql-5413", val(&q3.rows[0][0]).unwrap_or(0.0) == 5413.0, "cql");

        // Cypher: COLLECT grouped
        try_run(&ex, "CREATE (n:Inv1842 {team: 'x', member: 'A'})").ok();
        try_run(&ex, "CREATE (n:Inv1842 {team: 'x', member: 'B'})").ok();
        try_run(&ex, "CREATE (n:Inv1842 {team: 'y', member: 'C'})").ok();
        let q4 = try_run(&ex, "MATCH (n:Inv1842) RETURN n.team AS team, COUNT(n) AS cnt ORDER BY team");
        if let Ok(res) = q4 {
            r.check("cypher-groups", res.rows.len() == 2, &format!("q4={}", res.rows.len()));
        } else {
            r.check("cypher-ok", false, &format!("err={:?}", q4));
        }
        r.finish();
    }

