    #[test]
    fn inv1902_polyglot_milestone_5453() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: top-N per group via CTE+window
        run(&ex, "CREATE TABLE inv1902_scores (id INT, dept TEXT, score INT)");
        run(&ex, "INSERT INTO inv1902_scores VALUES (1, 'eng', 90)");
        run(&ex, "INSERT INTO inv1902_scores VALUES (2, 'eng', 80)");
        run(&ex, "INSERT INTO inv1902_scores VALUES (3, 'eng', 70)");
        run(&ex, "INSERT INTO inv1902_scores VALUES (4, 'hr', 95)");
        run(&ex, "INSERT INTO inv1902_scores VALUES (5, 'hr', 85)");
        let q1 = run(&ex, "WITH ranked AS (SELECT dept, score, ROW_NUMBER() OVER (PARTITION BY dept ORDER BY score DESC) AS rn FROM inv1902_scores) SELECT dept, score FROM ranked WHERE rn <= 2 ORDER BY dept, score DESC");
        r.check("top2-per-dept", q1.rows.len() == 4, &format!("q1={}", q1.rows.len()));

        // CQL
        run(&ex, "CREATE TABLE inv1902ks__meta (mkey TEXT, mval TEXT, PRIMARY KEY (mkey))");
        run(&ex, "INSERT INTO inv1902ks__meta (mkey, mval) VALUES ('milestone', '5453')");
        let q2 = run(&ex, "SELECT mval FROM inv1902ks.meta WHERE mkey = 'milestone' ALLOW FILTERING");
        r.check("cql-milestone", q2.rows[0][0].as_str().unwrap_or("") == "5453", "cql");

        // Cypher: graph + aggregate
        try_run(&ex, "CREATE (a:Inv1902A {name: 'Team'})-[:HAS]->(m:Inv1902M {member: 'X', pts: 10})").ok();
        try_run(&ex, "MATCH (a:Inv1902A {name: 'Team'}) CREATE (a)-[:HAS]->(m:Inv1902M {member: 'Y', pts: 20})").ok();
        try_run(&ex, "MATCH (a:Inv1902A {name: 'Team'}) CREATE (a)-[:HAS]->(m:Inv1902M {member: 'Z', pts: 30})").ok();
        let q3 = try_run(&ex, "MATCH (a:Inv1902A)-[:HAS]->(m) RETURN SUM(m.pts) AS total");
        if let Ok(res) = q3 {
            r.check("cypher-60", val(&res.rows[0][0]).unwrap_or(0.0) == 60.0, &format!("{:?}", res.rows[0][0]));
        } else {
            r.check("cypher-ok", false, &format!("err={:?}", q3));
        }
        r.finish();
    }

