        run(&ex, "INSERT INTO inv1912_t VALUES (3, 'paid', 300)");
        run(&ex, "INSERT INTO inv1912_t VALUES (4, 'unpaid', 400)");
        // Conditional aggregation: SUM(CASE WHEN...)
        let q = run(&ex, "SELECT SUM(CASE WHEN status = 'paid' THEN amount ELSE 0 END) AS paid_total, SUM(CASE WHEN status = 'unpaid' THEN amount ELSE 0 END) AS unpaid_total FROM inv1912_t");
