    #[test]
    fn inv1918_sql_window_over_all_functions() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv1918_t (id INT, val INT)");
        run(&ex, "INSERT INTO inv1918_t VALUES (1, 10)");
        run(&ex, "INSERT INTO inv1918_t VALUES (2, 20)");
        run(&ex, "INSERT INTO inv1918_t VALUES (3, 30)");
        // Multiple window functions in one query
        let q = run(&ex, "SELECT id, ROW_NUMBER() OVER (ORDER BY id) AS rn, RANK() OVER (ORDER BY val DESC) AS rnk, DENSE_RANK() OVER (ORDER BY val DESC) AS dr, LAG(val) OVER (ORDER BY id) AS prev FROM inv1918_t ORDER BY id");
        r.check("rows-3", q.rows.len() == 3, &format!("rows={}", q.rows.len()));
        // id=1: rn=1, rnk=3, dr=3, prev=NULL
        let rn1 = val(&q.rows[0][1]).unwrap_or(0.0);
        let rnk1 = val(&q.rows[0][2]).unwrap_or(0.0);
        r.check("rn1", rn1 == 1.0, &format!("rn1={}", rn1));
        r.check("rnk3", rnk1 == 3.0, &format!("rnk1={}", rnk1));
        r.check("prev-null", q.rows[0][4].is_null(), &format!("{:?}", q.rows[0][4]));
        r.finish();
    }

