    #[test]
    fn inv1922_polyglot_milestone_5493() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: conditional aggregation + window
        run(&ex, "CREATE TABLE inv1922_t (id INT, cat TEXT, val INT)");
        run(&ex, "INSERT INTO inv1922_t VALUES (1, 'x', 10)");
        run(&ex, "INSERT INTO inv1922_t VALUES (2, 'x', 20)");
        run(&ex, "INSERT INTO inv1922_t VALUES (3, 'y', 30)");
        let q1 = run(&ex, "SELECT SUM(CASE WHEN cat = 'x' THEN val ELSE 0 END) AS x_total, SUM(CASE WHEN cat = 'y' THEN val ELSE 0 END) AS y_total FROM inv1922_t");
        r.check("x-30", val(&q1.rows[0][0]).unwrap_or(0.0) == 30.0, "x");
        r.check("y-30", val(&q1.rows[0][1]).unwrap_or(0.0) == 30.0, "y");

        // CQL
        run(&ex, "CREATE TABLE inv1922ks__kv (tag TEXT, n INT, PRIMARY KEY (tag))");
        run(&ex, "INSERT INTO inv1922ks__kv (tag, n) VALUES ('batch', 131)");
        let q2 = run(&ex, "SELECT n FROM inv1922ks.kv WHERE tag = 'batch' ALLOW FILTERING");
        r.check("cql-131", val(&q2.rows[0][0]).unwrap_or(0.0) == 131.0, "cql");

        // Cypher: complex grouped aggregation with filter
        try_run(&ex, "CREATE (n:Inv1922 {tier: 'gold', pts: 100})").ok();
        try_run(&ex, "CREATE (n:Inv1922 {tier: 'gold', pts: 200})").ok();
        try_run(&ex, "CREATE (n:Inv1922 {tier: 'silver', pts: 50})").ok();
        try_run(&ex, "CREATE (n:Inv1922 {tier: 'bronze', pts: 10})").ok();
        let q3 = try_run(&ex, "MATCH (n:Inv1922) WITH n.tier AS tier, SUM(n.pts) AS total WHERE total >= 50 RETURN tier, total ORDER BY total DESC");
        if let Ok(res) = q3 {
            r.check("cypher-2-tiers", res.rows.len() == 2, &format!("q3={}", res.rows.len()));
            r.check("gold-300", val(&res.rows[0][1]).unwrap_or(0.0) == 300.0, &format!("{:?}", res.rows[0][1]));
        } else {
            r.check("cypher-ok", false, &format!("err={:?}", q3));
        }
        r.finish();
    }

