    #[test]
    fn inv1942_polyglot_milestone_5513() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: EXISTS subquery
        run(&ex, "CREATE TABLE inv1942_a (id INT)");
        run(&ex, "CREATE TABLE inv1942_b (aid INT)");
        run(&ex, "INSERT INTO inv1942_a VALUES (1), (2), (3)");
        run(&ex, "INSERT INTO inv1942_b VALUES (1)");
        let q1 = run(&ex, "SELECT id FROM inv1942_a WHERE EXISTS (SELECT 1 FROM inv1942_b WHERE inv1942_b.aid = inv1942_a.id)");
        r.check("sql-exists", q1.rows.len() == 1, &format!("q1={}", q1.rows.len()));

        // CQL: read-back
        run(&ex, "CREATE TABLE inv1942ks__log (id INT, msg TEXT, PRIMARY KEY (id))");
        run(&ex, "INSERT INTO inv1942ks__log (id, msg) VALUES (1, 'batch132')");
        let q2 = run(&ex, "SELECT msg FROM inv1942ks.log WHERE id = 1 ALLOW FILTERING");
        r.check("cql-batch132", q2.rows.len() == 1 && q2.rows[0][0] == serde_json::json!("batch132"), &format!("{:?}", q2.rows));

        // Cypher: grouped aggregation
        try_run(&ex, "CREATE (n:Inv1942 {cat: 'x', v: 10})").ok();
        try_run(&ex, "CREATE (n:Inv1942 {cat: 'x', v: 20})").ok();
        try_run(&ex, "CREATE (n:Inv1942 {cat: 'y', v: 100})").ok();
        let q3 = try_run(&ex, "MATCH (n:Inv1942) RETURN n.cat AS cat, SUM(n.v) AS total ORDER BY cat");
        if let Ok(res) = q3 {
            r.check("cypher-2-groups", res.rows.len() == 2, &format!("q3={}", res.rows.len()));
            if res.rows.len() == 2 {
                r.check("x-30", val(&res.rows[0][1]).unwrap_or(0.0) == 30.0, &format!("{:?}", res.rows[0]));
                r.check("y-100", val(&res.rows[1][1]).unwrap_or(0.0) == 100.0, &format!("{:?}", res.rows[1]));
            }
        } else {
            r.check("cypher-ok", false, &format!("err={:?}", q3));
        }

        r.finish();
    }

