    #[test]
    fn inv1962_polyglot_milestone_5533() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: recursive CTE + window in same query pipeline
        run(&ex, "CREATE TABLE inv1962_data (id INT, val INT)");
        run(&ex, "INSERT INTO inv1962_data VALUES (1, 100), (2, 200), (3, 300)");
        let q1 = run(&ex, "WITH base AS (SELECT id, val FROM inv1962_data) SELECT id, val, SUM(val) OVER (ORDER BY id) AS running FROM base ORDER BY id");
        r.check("sql-running-sum", q1.rows.len() == 3, &format!("q1={}", q1.rows.len()));
        if q1.rows.len() == 3 {
            r.check("running-600", val(&q1.rows[2][2]).unwrap_or(0.0) == 600.0, &format!("{:?}", q1.rows[2]));
        }

        // CQL: insert + select
        run(&ex, "CREATE TABLE inv1962ks__meta (tag TEXT, n INT, PRIMARY KEY (tag))");
        run(&ex, "INSERT INTO inv1962ks__meta (tag, n) VALUES ('batch', 133)");
        let q2 = run(&ex, "SELECT n FROM inv1962ks.meta WHERE tag = 'batch' ALLOW FILTERING");
        r.check("cql-133", val(&q2.rows[0][0]).unwrap_or(0.0) == 133.0, &format!("{:?}", q2.rows));

        // Cypher: SET + verify
        try_run(&ex, "CREATE (n:Inv1962 {name: 'test', version: 1})").ok();
        try_run(&ex, "MATCH (n:Inv1962 {name: 'test'}) SET n.version = 2").ok();
        let q3 = try_run(&ex, "MATCH (n:Inv1962 {name: 'test'}) RETURN n.version");
        if let Ok(res) = q3 {
            r.check("cypher-v2", val(&res.rows[0][0]).unwrap_or(0.0) == 2.0, &format!("{:?}", res.rows));
        } else {
            r.check("cypher-ok", false, &format!("err={:?}", q3));
        }

        r.finish();
    }

