    #[test]
    fn inv1976_sql_window_lag_partition() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv1976 (dept TEXT, month INT, revenue INT)");
        run(&ex, "INSERT INTO inv1976 VALUES ('eng', 1, 100), ('eng', 2, 120), ('eng', 3, 150)");
        run(&ex, "INSERT INTO inv1976 VALUES ('sales', 1, 200), ('sales', 2, 180), ('sales', 3, 220)");
        let q = run(&ex, "SELECT dept, month, revenue, LAG(revenue, 1, 0) OVER (PARTITION BY dept ORDER BY month) AS prev FROM inv1976 ORDER BY dept, month");
        r.check("6-rows", q.rows.len() == 6, &format!("rows={}", q.rows.len()));
        if q.rows.len() == 6 {
            // eng month=1: prev=0 (no previous)
            r.check("eng-m1-prev0", val(&q.rows[0][3]).unwrap_or(-1.0) == 0.0, &format!("{:?}", q.rows[0]));
            // eng month=2: prev=100
            r.check("eng-m2-prev100", val(&q.rows[1][3]).unwrap_or(-1.0) == 100.0, &format!("{:?}", q.rows[1]));
            // sales month=1: prev=0 (partition boundary)
            r.check("sales-m1-prev0", val(&q.rows[3][3]).unwrap_or(-1.0) == 0.0, &format!("{:?}", q.rows[3]));
            // sales month=2: prev=200
            r.check("sales-m2-prev200", val(&q.rows[4][3]).unwrap_or(-1.0) == 200.0, &format!("{:?}", q.rows[4]));
        }
        r.finish();
    }

