    #[test]
    fn inv1982_polyglot_milestone_5553() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: subquery in FROM + window
        run(&ex, "CREATE TABLE inv1982_data (grp TEXT, val INT)");
        run(&ex, "INSERT INTO inv1982_data VALUES ('a', 10), ('a', 20), ('b', 30)");
        let q1 = run(&ex, "SELECT grp, total, ROW_NUMBER() OVER (ORDER BY total DESC) AS rnk FROM (SELECT grp, SUM(val) AS total FROM inv1982_data GROUP BY grp) sub ORDER BY rnk");
        r.check("sql-2-rows", q1.rows.len() == 2, &format!("q1={}", q1.rows.len()));

        // CQL
        run(&ex, "CREATE TABLE inv1982ks__ver (tag TEXT, n INT, PRIMARY KEY (tag))");
        run(&ex, "INSERT INTO inv1982ks__ver (tag, n) VALUES ('batch', 134)");
        let q2 = run(&ex, "SELECT n FROM inv1982ks.ver WHERE tag = 'batch' ALLOW FILTERING");
        r.check("cql-134", val(&q2.rows[0][0]).unwrap_or(0.0) == 134.0, &format!("{:?}", q2.rows));

        // Cypher: relationship property query
        try_run(&ex, "CREATE (a:Inv1982 {name: 'x'})-[:RATED {stars: 5}]->(b:Inv1982 {name: 'y'})").ok();
        let q3 = try_run(&ex, "MATCH (a:Inv1982)-[r:RATED]->(b:Inv1982) RETURN a.name, r.stars, b.name");
        if let Ok(res) = q3 {
            r.check("cypher-1-rel", res.rows.len() == 1, &format!("q3={}", res.rows.len()));
            if res.rows.len() == 1 {
                r.check("5-stars", val(&res.rows[0][1]).unwrap_or(0.0) == 5.0, &format!("{:?}", res.rows[0]));
            }
        } else {
            r.check("cypher-ok", false, &format!("err={:?}", q3));
        }

        r.finish();
    }

    // ==================== BATCH 135 (INV-1983 to INV-2002) ====================
    // Focus: Complex CTEs with multiple references, window frames, Cypher MERGE,
    //        CQL counter patterns, IS NULL/IS NOT NULL, type edge cases

    #[test]
    fn inv1983_sql_cte_with_aggregation_and_filter() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv1983 (id INT, cat TEXT, val INT)");
        run(&ex, "INSERT INTO inv1983 VALUES (1, 'a', 10), (2, 'a', 20), (3, 'b', 30), (4, 'b', 40), (5, 'c', 5)");
        // CTE with aggregation, then filter in outer query
        let q = run(&ex, "WITH totals AS (SELECT cat, SUM(val) AS s FROM inv1983 GROUP BY cat) SELECT cat, s FROM totals WHERE s > 15 ORDER BY cat");
        r.check("2-rows", q.rows.len() == 2, &format!("rows={}", q.rows.len()));
        if q.rows.len() == 2 {
            r.check("a-30", val(&q.rows[0][1]).unwrap_or(0.0) == 30.0, &format!("{:?}", q.rows[0]));
            r.check("b-70", val(&q.rows[1][1]).unwrap_or(0.0) == 70.0, &format!("{:?}", q.rows[1]));
        }
        r.finish();
    }

