    #[test]
    fn inv2001_cypher_shortest_path_equiv() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        // Diamond: A->B, A->C, B->D, C->D
        try_run(&ex, "CREATE (a:Inv2001 {name: 'A'})-[:LINK]->(b:Inv2001 {name: 'B'})").ok();
        try_run(&ex, "MATCH (a:Inv2001 {name: 'A'}) CREATE (a)-[:LINK]->(c:Inv2001 {name: 'C'})").ok();
        try_run(&ex, "MATCH (b:Inv2001 {name: 'B'}) CREATE (b)-[:LINK]->(d:Inv2001 {name: 'D'})").ok();
        try_run(&ex, "MATCH (c:Inv2001 {name: 'C'}), (d:Inv2001 {name: 'D'}) CREATE (c)-[:LINK]->(d)").ok();
        // Find 2-hop paths from A to D
        let q = try_run(&ex, "MATCH (a:Inv2001 {name: 'A'})-[:LINK]->(mid:Inv2001)-[:LINK]->(d:Inv2001 {name: 'D'}) RETURN mid.name ORDER BY mid.name");
        if let Ok(res) = q {
            r.check("2-paths", res.rows.len() == 2, &format!("rows={}", res.rows.len()));
            if res.rows.len() == 2 {
                r.check("via-B", res.rows[0][0] == serde_json::json!("B"), &format!("{:?}", res.rows[0]));
                r.check("via-C", res.rows[1][0] == serde_json::json!("C"), &format!("{:?}", res.rows[1]));
            }
        } else {
            r.check("path-ok", false, &format!("err={:?}", q));
        }
        r.finish();
    }

    #[test]
    fn inv2002_polyglot_milestone_5573() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: NULLIF + COALESCE combo
        run(&ex, "CREATE TABLE inv2002_s (id INT, val INT)");
        run(&ex, "INSERT INTO inv2002_s VALUES (1, 0), (2, 42)");
        let q1 = run(&ex, "SELECT id, COALESCE(NULLIF(val, 0), -1) AS result FROM inv2002_s ORDER BY id");
        r.check("sql-2", q1.rows.len() == 2, &format!("q1={}", q1.rows.len()));
        if q1.rows.len() == 2 {
            r.check("id1-neg1", val(&q1.rows[0][1]).unwrap_or(0.0) == -1.0, &format!("{:?}", q1.rows[0]));
            r.check("id2-42", val(&q1.rows[1][1]).unwrap_or(0.0) == 42.0, &format!("{:?}", q1.rows[1]));
        }

        // CQL
        run(&ex, "CREATE TABLE inv2002ks__bat (tag TEXT, n INT, PRIMARY KEY (tag))");
        run(&ex, "INSERT INTO inv2002ks__bat (tag, n) VALUES ('batch', 135)");
        let q2 = run(&ex, "SELECT n FROM inv2002ks.bat WHERE tag = 'batch' ALLOW FILTERING");
        r.check("cql-135", val(&q2.rows[0][0]).unwrap_or(0.0) == 135.0, &format!("{:?}", q2.rows));

        // Cypher: diamond path count
        try_run(&ex, "CREATE (a:Inv2002 {name: 'A'})-[:E]->(b:Inv2002 {name: 'B'})").ok();
        try_run(&ex, "MATCH (a:Inv2002 {name: 'A'}) CREATE (a)-[:E]->(c:Inv2002 {name: 'C'})").ok();
        try_run(&ex, "MATCH (b:Inv2002 {name: 'B'}) CREATE (b)-[:E]->(d:Inv2002 {name: 'D'})").ok();
        try_run(&ex, "MATCH (c:Inv2002 {name: 'C'}), (d:Inv2002 {name: 'D'}) CREATE (c)-[:E]->(d)").ok();
        let q3 = try_run(&ex, "MATCH (a:Inv2002 {name: 'A'})-[:E]->(m:Inv2002)-[:E]->(d:Inv2002 {name: 'D'}) RETURN COUNT(m) AS paths");
        if let Ok(res) = q3 {
            r.check("cypher-2-paths", val(&res.rows[0][0]).unwrap_or(0.0) == 2.0, &format!("{:?}", res.rows));
        } else {
            r.check("cypher-ok", false, &format!("err={:?}", q3));
        }

        r.finish();
    }

