    #[test]
    fn inv2014_sql_window_nth_value() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv2014 (id INT, val INT)");
        run(&ex, "INSERT INTO inv2014 VALUES (1, 10), (2, 20), (3, 30), (4, 40), (5, 50)");
        let q = run(&ex, "SELECT id, NTH_VALUE(val, 3) OVER (ORDER BY id ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS nth FROM inv2014 ORDER BY id");
        r.check("5-rows", q.rows.len() == 5, &format!("rows={}", q.rows.len()));
        if q.rows.len() == 5 {
            // NTH_VALUE(3) = 30 for all rows
            r.check("nth-30", val(&q.rows[0][1]).unwrap_or(0.0) == 30.0, &format!("{:?}", q.rows[0][1]));
            r.check("nth-same", q.rows[0][1] == q.rows[4][1], &format!("0={:?} 4={:?}", q.rows[0][1], q.rows[4][1]));
        }
        r.finish();
    }

