    #[test]
    fn inv2022_polyglot_milestone_5593() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: string functions + window
        run(&ex, "CREATE TABLE inv2022_s (name TEXT, score INT)");
        run(&ex, "INSERT INTO inv2022_s VALUES ('Alice', 90), ('Bob', 85), ('Carol', 95)");
        let q1 = run(&ex, "SELECT UPPER(name) AS uname, ROW_NUMBER() OVER (ORDER BY score DESC) AS rnk FROM inv2022_s ORDER BY rnk");
        r.check("sql-3", q1.rows.len() == 3, &format!("q1={}", q1.rows.len()));
        if q1.rows.len() >= 1 {
            r.check("top-carol", q1.rows[0][0] == serde_json::json!("CAROL"), &format!("{:?}", q1.rows[0]));
        }

        // CQL
        run(&ex, "CREATE TABLE inv2022ks__v (tag TEXT, n INT, PRIMARY KEY (tag))");
        run(&ex, "INSERT INTO inv2022ks__v (tag, n) VALUES ('batch', 136)");
        let q2 = run(&ex, "SELECT n FROM inv2022ks.v WHERE tag = 'batch' ALLOW FILTERING");
        r.check("cql-136", val(&q2.rows[0][0]).unwrap_or(0.0) == 136.0, &format!("{:?}", q2.rows));

        // Cypher: fan-out count
        try_run(&ex, "CREATE (r:Inv2022 {name: 'hub'})-[:SPOKE]->(s1:Inv2022 {name: 's1'})").ok();
        try_run(&ex, "MATCH (r:Inv2022 {name: 'hub'}) CREATE (r)-[:SPOKE]->(s2:Inv2022 {name: 's2'})").ok();
        try_run(&ex, "MATCH (r:Inv2022 {name: 'hub'}) CREATE (r)-[:SPOKE]->(s3:Inv2022 {name: 's3'})").ok();
        let q3 = try_run(&ex, "MATCH (:Inv2022 {name: 'hub'})-[:SPOKE]->(s:Inv2022) RETURN COUNT(s) AS spokes");
        if let Ok(res) = q3 {
            r.check("3-spokes", val(&res.rows[0][0]).unwrap_or(0.0) == 3.0, &format!("{:?}", res.rows));
        } else {
            r.check("cypher-ok", false, &format!("err={:?}", q3));
        }

        r.finish();
    }

