    fn inv2042_polyglot_milestone_5613() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: complex expression + string function
        run(&ex, "CREATE TABLE inv2042_s (word TEXT, freq INT)");
        run(&ex, "INSERT INTO inv2042_s VALUES ('hello', 5), ('world', 3), ('test', 8)");
        let q1 = run(&ex, "SELECT UPPER(word) AS w, freq * 10 AS score FROM inv2042_s ORDER BY score DESC");
        r.check("sql-3", q1.rows.len() == 3, &format!("q1={}", q1.rows.len()));
        if q1.rows.len() >= 1 {
            r.check("top-TEST-80", q1.rows[0][0] == serde_json::json!("TEST") && val(&q1.rows[0][1]).unwrap_or(0.0) == 80.0, &format!("{:?}", q1.rows[0]));
        }

        // CQL
        run(&ex, "CREATE TABLE inv2042ks__t (tag TEXT, n INT, PRIMARY KEY (tag))");
        run(&ex, "INSERT INTO inv2042ks__t (tag, n) VALUES ('batch', 137)");
        let q2 = run(&ex, "SELECT n FROM inv2042ks.t WHERE tag = 'batch' ALLOW FILTERING");
        r.check("cql-137", val(&q2.rows[0][0]).unwrap_or(0.0) == 137.0, &format!("{:?}", q2.rows));

        // Cypher: filter + aggregate
        try_run(&ex, "CREATE (n:Inv2042 {cat: 'a', v: 10})").ok();
        try_run(&ex, "CREATE (n:Inv2042 {cat: 'a', v: 5})").ok();
        try_run(&ex, "CREATE (n:Inv2042 {cat: 'b', v: 100})").ok();
        let q3 = try_run(&ex, "MATCH (n:Inv2042) WHERE n.v > 7 RETURN n.cat AS cat, SUM(n.v) AS total ORDER BY cat");
        if let Ok(res) = q3 {
            r.check("cypher-2", res.rows.len() == 2, &format!("q3={}", res.rows.len()));
            if res.rows.len() == 2 {
                r.check("a-10", val(&res.rows[0][1]).unwrap_or(0.0) == 10.0, &format!("{:?}", res.rows[0]));
                r.check("b-100", val(&res.rows[1][1]).unwrap_or(0.0) == 100.0, &format!("{:?}", res.rows[1]));
            }
        } else {
            r.check("cypher-ok", false, &format!("err={:?}", q3));
        }

        r.finish();
    }

