    #[test]
    fn inv2054_sql_cte_in_union_both_branches() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv2054 (id INT, val INT)");
        run(&ex, "INSERT INTO inv2054 VALUES (1, 10), (2, 20), (3, 30)");
        // CTE referenced in both sides of UNION ALL
        let q = run(&ex, "WITH base AS (SELECT id, val FROM inv2054) SELECT id, val FROM base WHERE val > 20 UNION ALL SELECT id, val FROM base WHERE val < 20");
        r.check("2-rows", q.rows.len() == 2, &format!("rows={}", q.rows.len()));
        // Should have id=3 (val=30>20) and id=1 (val=10<20)
        let mut ids: Vec<f64> = q.rows.iter().filter_map(|row| val(&row[0])).collect();
        ids.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        r.check("ids-1-3", ids == vec![1.0, 3.0], &format!("ids={:?}", ids));
        r.finish();
    }

