    #[test]
    fn inv2062_polyglot_fix_validation() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // Fix 1: Cypher IN [list]
        try_run(&ex, "CREATE (n:Inv2062 {x: 1})").ok();
        try_run(&ex, "CREATE (n:Inv2062 {x: 2})").ok();
        try_run(&ex, "CREATE (n:Inv2062 {x: 3})").ok();
        let q1 = try_run(&ex, "MATCH (n:Inv2062) WHERE n.x IN [1, 3] RETURN COUNT(n) AS cnt");
        if let Ok(res) = q1 {
            r.check("fix1-in-list", val(&res.rows[0][0]).unwrap_or(0.0) == 2.0, &format!("{:?}", res.rows));
        } else {
            r.check("fix1-ok", false, &format!("err={:?}", q1));
        }

        // Fix 2: Cypher IS NOT NULL
        try_run(&ex, "CREATE (n:Inv2062B {val: 10})").ok();
        try_run(&ex, "CREATE (n:Inv2062B {})").ok();
        let q2 = try_run(&ex, "MATCH (n:Inv2062B) WHERE n.val IS NOT NULL RETURN COUNT(n) AS cnt");
        if let Ok(res) = q2 {
            r.check("fix2-is-not-null", val(&res.rows[0][0]).unwrap_or(0.0) == 1.0, &format!("{:?}", res.rows));
        } else {
            r.check("fix2-ok", false, &format!("err={:?}", q2));
        }

        // Fix 3: month/year as columns
        run(&ex, "CREATE TABLE inv2062_dates (year INT, month INT, day INT)");
        run(&ex, "INSERT INTO inv2062_dates VALUES (2025, 3, 11)");
        let q3 = run(&ex, "SELECT year, month, day FROM inv2062_dates");
        r.check("fix3-year-month-day", q3.rows.len() == 1, &format!("q3={}", q3.rows.len()));
        if q3.rows.len() == 1 {
            r.check("year-2025", val(&q3.rows[0][0]).unwrap_or(0.0) == 2025.0, &format!("{:?}", q3.rows[0]));
            r.check("month-3", val(&q3.rows[0][1]).unwrap_or(0.0) == 3.0, &format!("{:?}", q3.rows[0]));
            r.check("day-11", val(&q3.rows[0][2]).unwrap_or(0.0) == 11.0, &format!("{:?}", q3.rows[0]));
        }

        // Fix 4: CTE in UNION branches
        run(&ex, "CREATE TABLE inv2062_nums (id INT)");
        run(&ex, "INSERT INTO inv2062_nums VALUES (1), (2), (3), (4), (5)");
        let q4 = run(&ex, "WITH base AS (SELECT id FROM inv2062_nums) SELECT id FROM base WHERE id <= 2 UNION ALL SELECT id FROM base WHERE id >= 4");
        r.check("fix4-cte-union", q4.rows.len() == 4, &format!("q4={}", q4.rows.len()));

        r.finish();
    }

