    #[test]
    fn inv2115_sql_group_concat() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv2115_tags (item TEXT, tag TEXT)");
        run(&ex, "INSERT INTO inv2115_tags VALUES ('a', 'red'), ('a', 'blue'), ('b', 'green')");
        let q = try_run(&ex, "SELECT item, GROUP_CONCAT(tag) AS tags FROM inv2115_tags GROUP BY item ORDER BY item");
        if let Ok(res) = q {
            r.check("2-groups", res.rows.len() == 2, &format!("len={}", res.rows.len()));
        } else {
            // GROUP_CONCAT may not be implemented — STRING_AGG is the SQL standard
            let q2 = try_run(&ex, "SELECT item, STRING_AGG(tag, ',') AS tags FROM inv2115_tags GROUP BY item ORDER BY item");
            if let Ok(res) = q2 {
                r.check("2-groups-agg", res.rows.len() == 2, &format!("len={}", res.rows.len()));
            } else {
                r.check("group-concat-or-string-agg", false, &format!("gc={:?} sa={:?}", q, q2));
            }
        }
        r.finish();
    }

