    #[test]
    fn inv2119_cypher_merge_create() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        // MERGE should create if not exists, skip if exists
        let q1 = try_run(&ex, "MERGE (n:Inv2119 {name: 'unique'}) RETURN n.name");
        if let Ok(res) = q1 {
            r.check("merge-created", res.rows.len() == 1, &format!("{:?}", res.rows));
            // MERGE again should not duplicate
            let q2 = try_run(&ex, "MERGE (n:Inv2119 {name: 'unique'}) RETURN n.name");
            if let Ok(res2) = q2 {
                let cnt = try_run(&ex, "MATCH (n:Inv2119) RETURN COUNT(n) AS cnt");
                if let Ok(c) = cnt {
                    r.check("no-dupe", val(&c.rows[0][0]).unwrap_or(0.0) == 1.0, &format!("{:?}", c.rows));
                }
                let _ = res2;
            }
        } else {
            r.check("merge-supported", false, &format!("err={:?}", q1));
        }
        r.finish();
    }

