    #[test]
    fn inv2203_sql_window_ntile_uneven() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv2203_data (val INT)");
        for i in 1..=7 {
            run(&ex, &format!("INSERT INTO inv2203_data VALUES ({})", i));
        }
        let q = run(&ex, "SELECT val, NTILE(3) OVER (ORDER BY val) AS bucket FROM inv2203_data ORDER BY val");
        r.check("7-rows", q.rows.len() == 7, &format!("len={}", q.rows.len()));
        // 7 rows / 3 buckets: 3,2,2 distribution
        // vals 1-3 → bucket 1, 4-5 → bucket 2, 6-7 → bucket 3
        r.check("val1-b1", val(&q.rows[0][1]).unwrap_or(0.0) == 1.0, &format!("{:?}", q.rows[0]));
        r.check("val3-b1", val(&q.rows[2][1]).unwrap_or(0.0) == 1.0, &format!("{:?}", q.rows[2]));
        r.check("val4-b2", val(&q.rows[3][1]).unwrap_or(0.0) == 2.0, &format!("{:?}", q.rows[3]));
        r.check("val7-b3", val(&q.rows[6][1]).unwrap_or(0.0) == 3.0, &format!("{:?}", q.rows[6]));
        r.finish();
    }

