    #[test]
    fn inv2222_polyglot_window_cte_cypher() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: CTE + window function
        run(&ex, "CREATE TABLE inv2222_ts (t INT, val REAL)");
        run(&ex, "INSERT INTO inv2222_ts VALUES (1, 10), (2, 30), (3, 20), (4, 40), (5, 50)");
        let q = run(&ex, "WITH ranked AS (SELECT t, val, RANK() OVER (ORDER BY val DESC) AS rnk FROM inv2222_ts) SELECT t, val FROM ranked WHERE rnk <= 2 ORDER BY val DESC");
        // Top 2 by val: 50(t=5), 40(t=4)
        r.check("sql-top2", q.rows.len() == 2, &format!("len={}", q.rows.len()));
        r.check("sql-first-50", val(&q.rows[0][1]).unwrap_or(0.0) == 50.0, &format!("{:?}", q.rows[0]));

        // Cypher: aggregation
        for v in &[100, 200, 300] {
            try_run(&ex, &format!("CREATE (n:Inv2222 {{v: {}}})", v)).ok();
        }
        let cy = try_run(&ex, "MATCH (n:Inv2222) RETURN MIN(n.v) AS lo, MAX(n.v) AS hi");
        if let Ok(res) = cy {
            r.check("cy-min-100", val(&res.rows[0][0]).unwrap_or(0.0) == 100.0, &format!("{:?}", res.rows));
            r.check("cy-max-300", val(&res.rows[0][1]).unwrap_or(0.0) == 300.0, &format!("{:?}", res.rows));
        }

        r.finish();
    }

