    fn inv2282_polyglot_cte_window_cypher_cql() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: CTE + window + derived table
        run(&ex, "CREATE TABLE inv2282_perf (team TEXT, score INT)");
        run(&ex, "INSERT INTO inv2282_perf VALUES ('a', 80), ('a', 90), ('b', 70), ('b', 85), ('b', 95)");
        let q = run(&ex, "WITH ranked AS (SELECT team, score, DENSE_RANK() OVER (PARTITION BY team ORDER BY score DESC) AS dr FROM inv2282_perf) SELECT team, score FROM ranked WHERE dr = 1 ORDER BY team");
        // Top per team: a=90, b=95
        r.check("2-tops", q.rows.len() == 2, &format!("len={}", q.rows.len()));
        r.check("a-90", val(&q.rows[0][1]).unwrap_or(0.0) == 90.0, &format!("{:?}", q.rows[0]));
        r.check("b-95", val(&q.rows[1][1]).unwrap_or(0.0) == 95.0, &format!("{:?}", q.rows[1]));

        // Cypher: group aggregation
        for (t, s) in &[("x", 100), ("x", 200), ("y", 300)] {
            try_run(&ex, &format!("CREATE (n:Inv2282 {{team: '{}', score: {}}})", t, s)).ok();
        }
        let cy = try_run(&ex, "MATCH (n:Inv2282) RETURN n.team AS t, MAX(n.score) AS mx ORDER BY t");
        if let Ok(res) = cy {
            r.check("cy-2-groups", res.rows.len() == 2, &format!("len={}", res.rows.len()));
        }

        // CQL: simple read
        run(&ex, "CREATE TABLE inv2282ks__cfg (k TEXT, v TEXT, PRIMARY KEY (k))");
        run(&ex, "INSERT INTO inv2282ks__cfg (k, v) VALUES ('mode', 'fast')");
        let cql = try_run(&ex, "SELECT v FROM inv2282ks.cfg WHERE k = 'mode' ALLOW FILTERING");
        if let Ok(res) = cql {
            r.check("cql-fast", res.rows[0][0].as_str() == Some("fast"), &format!("{:?}", res.rows));
        }

        r.finish();
    }

