    #[test]
    fn inv2302_polyglot_comprehensive() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: complex CTE + GROUP BY ordinal + window
        run(&ex, "CREATE TABLE inv2302_metrics (host TEXT, metric TEXT, val REAL)");
        run(&ex, "INSERT INTO inv2302_metrics VALUES ('h1', 'cpu', 80), ('h1', 'mem', 60), ('h1', 'cpu', 90), ('h2', 'cpu', 50), ('h2', 'mem', 70)");
        let q = try_run(&ex, "WITH host_stats AS (SELECT host, metric, AVG(val) AS avg_val FROM inv2302_metrics GROUP BY 1, 2) SELECT host, metric, avg_val FROM host_stats ORDER BY host, metric");
        if let Ok(res) = q {
            r.check("sql-4-groups", res.rows.len() == 4, &format!("len={}", res.rows.len()));
            // h1-cpu avg=85
            r.check("h1-cpu-85", val(&res.rows[0][2]).unwrap_or(0.0) == 85.0, &format!("{:?}", res.rows[0]));
        } else {
            r.check("ordinal-cte-ok", false, &format!("err={:?}", q));
        }

        // Cypher: CONTAINS + NOT IN
        try_run(&ex, "CREATE (n:Inv2302 {tag: 'rust-lang', score: 10})").ok();
        try_run(&ex, "CREATE (n:Inv2302 {tag: 'python-lang', score: 20})").ok();
        try_run(&ex, "CREATE (n:Inv2302 {tag: 'go-lang', score: 30})").ok();
        let cy = try_run(&ex, "MATCH (n:Inv2302) WHERE n.tag CONTAINS 'lang' AND n.score NOT IN [20] RETURN COUNT(n) AS cnt");
        if let Ok(res) = cy {
            r.check("cy-contains-not-in-2", val(&res.rows[0][0]).unwrap_or(0.0) == 2.0, &format!("{:?}", res.rows));
        }

        // CQL: composite key + range
        run(&ex, "CREATE TABLE inv2302ks__ts (device TEXT, ts INT, reading REAL, PRIMARY KEY (device, ts))");
        run(&ex, "INSERT INTO inv2302ks__ts (device, ts, reading) VALUES ('sensor1', 1, 10.0)");
        run(&ex, "INSERT INTO inv2302ks__ts (device, ts, reading) VALUES ('sensor1', 2, 20.0)");
        run(&ex, "INSERT INTO inv2302ks__ts (device, ts, reading) VALUES ('sensor1', 3, 30.0)");
        let cql = try_run(&ex, "SELECT AVG(reading) FROM inv2302ks.ts WHERE device = 'sensor1' ALLOW FILTERING");
        if let Ok(res) = cql {
            r.check("cql-avg-20", val(&res.rows[0][0]).unwrap_or(0.0) == 20.0, &format!("{:?}", res.rows));
        }

        r.finish();
    }

