    #[test]
    fn inv2322_polyglot_nested_window_cte_cypher_cql() {
        // Comprehensive: nested window expr + CTE + Cypher + CQL
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: nested window function in CTE
        run(&ex, "CREATE TABLE inv2322_metrics (sensor TEXT, reading REAL)");
        run(&ex, "INSERT INTO inv2322_metrics VALUES ('s1', 10.0), ('s2', 20.0), ('s3', 30.0), ('s4', 40.0)");
        let q = run(&ex, "WITH ranked AS (SELECT sensor, reading, reading - AVG(reading) OVER () AS deviation FROM inv2322_metrics) SELECT sensor, deviation FROM ranked ORDER BY deviation");
        r.check("sql-4-rows", q.rows.len() == 4, &format!("len={}", q.rows.len()));
        // avg=25. s1: -15, s2: -5, s3: 5, s4: 15
        r.check("sql-s1-neg15", val(&q.rows[0][1]).unwrap_or(0.0) == -15.0, &format!("{:?}", q.rows[0]));
        r.check("sql-s4-15", val(&q.rows[3][1]).unwrap_or(0.0) == 15.0, &format!("{:?}", q.rows[3]));

        // Cypher: create + match with ORDER BY
        try_run(&ex, "CREATE (n:Inv2322Metric {name: 'temp', value: 42})").ok();
        try_run(&ex, "CREATE (n:Inv2322Metric {name: 'humidity', value: 65})").ok();
        let cy = try_run(&ex, "MATCH (n:Inv2322Metric) RETURN n.name, n.value ORDER BY n.value DESC");
        if let Ok(res) = &cy {
            r.check("cypher-2-rows", res.rows.len() == 2, &format!("len={}", res.rows.len()));
            r.check("cypher-top-humidity", res.rows[0][0] == "humidity", &format!("{:?}", res.rows[0]));
        }

        // CQL: basic query
        run(&ex, "CREATE TABLE inv2322ks__readings (id TEXT, val REAL, PRIMARY KEY (id))");
        run(&ex, "INSERT INTO inv2322ks__readings (id, val) VALUES ('r1', 100.0)");
        run(&ex, "INSERT INTO inv2322ks__readings (id, val) VALUES ('r2', 200.0)");
        let cql = try_run(&ex, "SELECT id, val FROM inv2322ks.readings ALLOW FILTERING");
        if let Ok(res) = cql {
            r.check("cql-2-rows", res.rows.len() == 2, &format!("{:?}", res.rows));
        }

        r.finish();
    }

