    #[test]
    fn inv2342_polyglot_window_join_cypher_cql() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: window function with single table
        run(&ex, "CREATE TABLE inv2342_emp (id INT, dept TEXT, salary INT)");
        run(&ex, "INSERT INTO inv2342_emp VALUES (10, 'eng', 100), (20, 'eng', 120), (30, 'sales', 90), (40, 'sales', 110)");
        let q = run(&ex, "SELECT dept, salary, RANK() OVER (ORDER BY salary DESC) AS rnk FROM inv2342_emp ORDER BY rnk");
        r.check("sql-4-rows", q.rows.len() == 4, &format!("len={}", q.rows.len()));
        r.check("sql-top-120", val(&q.rows[0][1]).unwrap_or(0.0) == 120.0, &format!("{:?}", q.rows[0]));

        // Cypher: count nodes
        for i in 0..3 {
            try_run(&ex, &format!("CREATE (n:Inv2342Tag {{label: 'tag{}'}})", i)).ok();
        }
        let cy = try_run(&ex, "MATCH (n:Inv2342Tag) RETURN COUNT(n) AS cnt");
        if let Ok(res) = cy {
            r.check("cypher-3", val(&res.rows[0][0]).unwrap_or(0.0) == 3.0, &format!("{:?}", res.rows));
        }

        // CQL: simple lookup
        run(&ex, "CREATE TABLE inv2342ks__config (param TEXT, val TEXT, PRIMARY KEY (param))");
        run(&ex, "INSERT INTO inv2342ks__config (param, val) VALUES ('mode', 'production')");
        let cql = try_run(&ex, "SELECT val FROM inv2342ks.config WHERE param = 'mode' ALLOW FILTERING");
        if let Ok(res) = cql {
            r.check("cql-production", res.rows[0][0] == "production", &format!("{:?}", res.rows));
        }

        r.finish();
    }

