    #[test]
    fn inv2362_polyglot_comprehensive_b153() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: nested window + GROUP BY ordinal
        run(&ex, "CREATE TABLE inv2362_metrics (sensor TEXT, reading INT)");
        run(&ex, "INSERT INTO inv2362_metrics VALUES ('s1', 10), ('s2', 20), ('s3', 30), ('s4', 40), ('s5', 50)");
        let q = run(&ex, "SELECT sensor, reading + MIN(reading) OVER () AS boosted FROM inv2362_metrics ORDER BY sensor");
        r.check("sql-5-rows", q.rows.len() == 5, &format!("len={}", q.rows.len()));
        // MIN=10. s1: 10+10=20, s5: 50+10=60
        r.check("sql-s1-20", val(&q.rows[0][1]).unwrap_or(0.0) == 20.0, &format!("{:?}", q.rows[0]));
        r.check("sql-s5-60", val(&q.rows[4][1]).unwrap_or(0.0) == 60.0, &format!("{:?}", q.rows[4]));

        // SQL: SUM(DISTINCT)
        run(&ex, "CREATE TABLE inv2362_dupes (grp TEXT, val INT)");
        run(&ex, "INSERT INTO inv2362_dupes VALUES ('x', 5), ('x', 5), ('x', 10), ('y', 20), ('y', 20)");
        let q2 = run(&ex, "SELECT grp, SUM(DISTINCT val) AS sd FROM inv2362_dupes GROUP BY grp ORDER BY grp");
        r.check("sumd-x-15", val(&q2.rows[0][1]).unwrap_or(0.0) == 15.0, &format!("{:?}", q2.rows[0]));
        r.check("sumd-y-20", val(&q2.rows[1][1]).unwrap_or(0.0) == 20.0, &format!("{:?}", q2.rows[1]));

        // Cypher: create + count
        for i in 0..4 {
            try_run(&ex, &format!("CREATE (n:Inv2362Node {{seq: {}}})", i)).ok();
        }
        let cy = try_run(&ex, "MATCH (n:Inv2362Node) RETURN COUNT(n) AS cnt");
        if let Ok(res) = cy {
            r.check("cypher-4", val(&res.rows[0][0]).unwrap_or(0.0) == 4.0, &format!("{:?}", res.rows));
        }

        r.finish();
    }

