    #[test]
    fn inv2382_polyglot_comprehensive_b154() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: nested window with two window functions
        run(&ex, "CREATE TABLE inv2382_data (x INT)");
        run(&ex, "INSERT INTO inv2382_data VALUES (5), (10), (15), (20), (25)");
        let q = run(&ex, "SELECT x, x - AVG(x) OVER () AS dev, x * 100 / SUM(x) OVER () AS pct FROM inv2382_data ORDER BY x");
        r.check("sql-5-rows", q.rows.len() == 5, &format!("len={}", q.rows.len()));
        // AVG=15, SUM=75. x=5: dev=-10, pct=6 (5*100/75=6.67→6 as int)
        r.check("sql-x5-dev", val(&q.rows[0][1]).unwrap_or(0.0) == -10.0, &format!("{:?}", q.rows[0]));

        // SQL: PERCENT_RANK + DISTINCT
        let q2 = run(&ex, "SELECT DISTINCT x FROM inv2382_data WHERE x > 10 ORDER BY x");
        r.check("sql-3-distinct", q2.rows.len() == 3, &format!("len={}", q2.rows.len()));

        // Cypher
        for i in 0..3 {
            try_run(&ex, &format!("CREATE (n:Inv2382Item {{seq: {}, active: true}})", i)).ok();
        }
        let cy = try_run(&ex, "MATCH (n:Inv2382Item) WHERE n.active = true RETURN COUNT(n) AS cnt");
        if let Ok(res) = cy {
            r.check("cypher-3", val(&res.rows[0][0]).unwrap_or(0.0) == 3.0, &format!("{:?}", res.rows));
        }

        // CQL
        run(&ex, "CREATE TABLE inv2382ks__log (id TEXT, level TEXT, PRIMARY KEY (id))");
        run(&ex, "INSERT INTO inv2382ks__log (id, level) VALUES ('l1', 'error')");
        run(&ex, "INSERT INTO inv2382ks__log (id, level) VALUES ('l2', 'warn')");
        let cql = try_run(&ex, "SELECT COUNT(*) FROM inv2382ks.log ALLOW FILTERING");
        if let Ok(res) = cql {
            r.check("cql-2", val(&res.rows[0][0]).unwrap_or(0.0) == 2.0, &format!("{:?}", res.rows));
        }

        r.finish();
    }

