    #[test]
    fn inv2422_polyglot_comprehensive_b156() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: nested window with multiple nested exprs in different columns
        run(&ex, "CREATE TABLE inv2422_vals (name TEXT, val INT)");
        run(&ex, "INSERT INTO inv2422_vals VALUES ('a', 20), ('b', 40), ('c', 60), ('d', 80), ('e', 100)");
        let q = run(&ex, "SELECT name, val - AVG(val) OVER () AS dev, val * 100 / SUM(val) OVER () AS share FROM inv2422_vals ORDER BY name");
        r.check("sql-5-rows", q.rows.len() == 5, &format!("len={}", q.rows.len()));
        r.check("sql-a-dev-neg40", val(&q.rows[0][1]).unwrap_or(0.0) == -40.0, &format!("{:?}", q.rows[0]));

        // CTE + aggregate
        let q2 = run(&ex, "WITH totals AS (SELECT SUM(val) AS s FROM inv2422_vals) SELECT s FROM totals");
        r.check("sql-sum-300", val(&q2.rows[0][0]).unwrap_or(0.0) == 300.0, &format!("{:?}", q2.rows));

        // Cypher
        for i in 0..3 {
            try_run(&ex, &format!("CREATE (n:Inv2422Log {{idx: {}, level: 'info'}})", i)).ok();
        }
        let cy = try_run(&ex, "MATCH (n:Inv2422Log) WHERE n.level = 'info' RETURN COUNT(n) AS cnt");
        if let Ok(res) = cy {
            r.check("cypher-3", val(&res.rows[0][0]).unwrap_or(0.0) == 3.0, &format!("{:?}", res.rows));
        }

        // CQL
        run(&ex, "CREATE TABLE inv2422ks__kv (k TEXT, v INT, PRIMARY KEY (k))");
        run(&ex, "INSERT INTO inv2422ks__kv (k, v) VALUES ('alpha', 1)");
        run(&ex, "INSERT INTO inv2422ks__kv (k, v) VALUES ('beta', 2)");
        let cql = try_run(&ex, "SELECT AVG(v) FROM inv2422ks.kv ALLOW FILTERING");
        if let Ok(res) = cql {
            r.check("cql-avg-1.5", (val(&res.rows[0][0]).unwrap_or(0.0) - 1.5).abs() < 0.01, &format!("{:?}", res.rows));
        }

        r.finish();
    }

