    #[test]
    fn inv2442_polyglot_comprehensive_b157() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: CTE with window + LEFT JOIN aggregate
        run(&ex, "CREATE TABLE inv2442_metrics (ts INT, val INT)");
        run(&ex, "INSERT INTO inv2442_metrics VALUES (1, 10), (2, 30), (3, 20), (4, 50), (5, 40)");
        let q = run(&ex, "WITH stats AS (SELECT ts, val, AVG(val) OVER (ORDER BY ts) AS running_avg FROM inv2442_metrics) SELECT ts, running_avg FROM stats WHERE ts = 5");
        r.check("sql-t5-avg30", val(&q.rows[0][1]).unwrap_or(0.0) == 30.0, &format!("{:?}", q.rows[0]));

        // SQL: GROUP BY ordinal with HAVING
        run(&ex, "CREATE TABLE inv2442_orders (region TEXT, amount INT)");
        run(&ex, "INSERT INTO inv2442_orders VALUES ('a', 100), ('a', 200), ('b', 50), ('c', 300), ('c', 400)");
        let q2 = run(&ex, "SELECT region, SUM(amount) AS total FROM inv2442_orders GROUP BY 1 HAVING SUM(amount) > 200 ORDER BY total DESC");
        r.check("sql-c-700", val(&q2.rows[0][1]).unwrap_or(0.0) == 700.0, &format!("{:?}", q2.rows[0]));
        r.check("sql-a-300", val(&q2.rows[1][1]).unwrap_or(0.0) == 300.0, &format!("{:?}", q2.rows[1]));

        // Cypher: create + filter
        for i in 0..5 {
            try_run(&ex, &format!("CREATE (n:Inv2442Record {{score: {}}})", i * 20)).ok();
        }
        let cy = try_run(&ex, "MATCH (n:Inv2442Record) WHERE n.score >= 40 RETURN COUNT(n) AS cnt");
        if let Ok(res) = cy {
            r.check("cypher-3", val(&res.rows[0][0]).unwrap_or(0.0) == 3.0, &format!("{:?}", res.rows));
        }

        r.finish();
    }

