    #[test]
    fn inv2462_polyglot_comprehensive_b158() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: nested window with cumulative % and deviation
        run(&ex, "CREATE TABLE inv2462_revenue (month INT, amount INT)");
        run(&ex, "INSERT INTO inv2462_revenue VALUES (1, 100), (2, 200), (3, 300), (4, 400)");
        let q = run(&ex, "SELECT month, amount - AVG(amount) OVER () AS dev FROM inv2462_revenue ORDER BY month");
        r.check("sql-4-rows", q.rows.len() == 4, &format!("len={}", q.rows.len()));
        // AVG=250. m1: -150, m4: 150
        r.check("sql-m1-dev", val(&q.rows[0][1]).unwrap_or(0.0) == -150.0, &format!("{:?}", q.rows[0]));
        r.check("sql-m4-dev", val(&q.rows[3][1]).unwrap_or(0.0) == 150.0, &format!("{:?}", q.rows[3]));

        // SQL: complex GROUP BY ordinal
        let q2 = run(&ex, "SELECT month, SUM(amount) AS total FROM inv2462_revenue GROUP BY 1 HAVING SUM(amount) >= 300 ORDER BY 1");
        r.check("sql-ge300-2", q2.rows.len() == 2, &format!("len={}", q2.rows.len()));

        // Cypher: STARTS WITH
        try_run(&ex, "CREATE (n:Inv2462File {name: 'report.pdf'})").ok();
        try_run(&ex, "CREATE (n:Inv2462File {name: 'readme.md'})").ok();
        try_run(&ex, "CREATE (n:Inv2462File {name: 'data.csv'})").ok();
        let cy = try_run(&ex, "MATCH (n:Inv2462File) WHERE n.name STARTS WITH 're' RETURN n.name ORDER BY n.name");
        if let Ok(res) = cy {
            r.check("cypher-2-re", res.rows.len() == 2, &format!("{:?}", res.rows));
        }

        // CQL
        run(&ex, "CREATE TABLE inv2462ks__stats (metric TEXT, val INT, PRIMARY KEY (metric))");
        run(&ex, "INSERT INTO inv2462ks__stats (metric, val) VALUES ('cpu', 80)");
        run(&ex, "INSERT INTO inv2462ks__stats (metric, val) VALUES ('mem', 60)");
        run(&ex, "INSERT INTO inv2462ks__stats (metric, val) VALUES ('disk', 40)");
        let cql = try_run(&ex, "SELECT COUNT(*) FROM inv2462ks.stats ALLOW FILTERING");
        if let Ok(res) = cql {
            r.check("cql-3", val(&res.rows[0][0]).unwrap_or(0.0) == 3.0, &format!("{:?}", res.rows));
        }

        r.finish();
    }

