    #[test]
    fn inv2482_polyglot_comprehensive_b159() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: CTE + window
        run(&ex, "CREATE TABLE inv2482_metrics (ts INT, val INT)");
        run(&ex, "INSERT INTO inv2482_metrics VALUES (1, 10), (2, 20), (3, 30), (4, 40), (5, 50)");
        let q = run(&ex, "WITH running AS (SELECT ts, val, SUM(val) OVER (ORDER BY ts) AS cumsum FROM inv2482_metrics) SELECT ts, cumsum FROM running WHERE cumsum >= 30 ORDER BY ts");
        r.check("sql-4-rows", q.rows.len() == 4, &format!("len={}", q.rows.len()));
        // ts=2: cumsum=30, ts=3: 60, ts=4: 100, ts=5: 150
        r.check("sql-ts2-30", val(&q.rows[0][0]).unwrap_or(0.0) == 2.0 && val(&q.rows[0][1]).unwrap_or(0.0) == 30.0, &format!("{:?}", q.rows[0]));

        // Cypher: create + match + where
        let _ = try_run(&ex, "CREATE (x:Metric2482 {name: 'cpu', val: 90})");
        let _ = try_run(&ex, "CREATE (y:Metric2482 {name: 'mem', val: 45})");
        let cypher = try_run(&ex, "MATCH (m:Metric2482) WHERE m.val > 50 RETURN m.name");
        if let Ok(res) = cypher {
            r.check("cypher-1-row", res.rows.len() == 1, &format!("len={}", res.rows.len()));
            r.check("cypher-cpu", res.rows[0][0] == "cpu", &format!("{:?}", res.rows[0]));
        } else {
            r.check("cypher-ok", false, &format!("err={:?}", cypher));
        }

        // CQL
        run(&ex, "CREATE TABLE inv2482ks__logs (id INT, msg TEXT, PRIMARY KEY (id))");
        run(&ex, "INSERT INTO inv2482ks__logs (id, msg) VALUES (1, 'boot')");
        run(&ex, "INSERT INTO inv2482ks__logs (id, msg) VALUES (2, 'ready')");
        let cql = try_run(&ex, "SELECT msg FROM inv2482ks.logs WHERE id = 2 ALLOW FILTERING");
        if let Ok(res) = cql {
            r.check("cql-ready", res.rows.len() == 1 && res.rows[0][0] == "ready", &format!("{:?}", res.rows));
        } else {
            r.check("cql-ok", false, &format!("err={:?}", cql));
        }

        r.finish();
    }

