    #[test]
    fn inv2500_sql_milestone_subquery_join() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv2500_products (id INT, name TEXT, category TEXT, price INT)");
        run(&ex, "INSERT INTO inv2500_products VALUES (1, 'laptop', 'electronics', 999), (2, 'phone', 'electronics', 699), (3, 'desk', 'furniture', 299), (4, 'chair', 'furniture', 199), (5, 'tablet', 'electronics', 499)");
        // Correlated subquery: products above their category average
        let q = run(&ex, "SELECT p.name, p.price, p.category FROM inv2500_products p WHERE p.price > (SELECT AVG(p2.price) FROM inv2500_products p2 WHERE p2.category = p.category) ORDER BY p.category, p.price DESC");
        // electronics avg = (999+699+499)/3 = 732.33. Above: laptop(999)
        // furniture avg = (299+199)/2 = 249. Above: desk(299)
        r.check("2-above-avg", q.rows.len() == 2, &format!("len={}", q.rows.len()));
        r.check("laptop", q.rows[0][0] == "laptop", &format!("{:?}", q.rows[0]));
        r.check("desk", q.rows[1][0] == "desk", &format!("{:?}", q.rows[1]));
        r.finish();
    }

