    #[test]
    fn inv2502_polyglot_comprehensive_b160() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: correlated subquery + window
        run(&ex, "CREATE TABLE inv2502_data (grp TEXT, val INT)");
        run(&ex, "INSERT INTO inv2502_data VALUES ('a', 10), ('a', 20), ('a', 30), ('b', 40), ('b', 50)");
        let q = run(&ex, "SELECT grp, val, RANK() OVER (PARTITION BY grp ORDER BY val DESC) AS rnk FROM inv2502_data ORDER BY grp, rnk");
        r.check("sql-5-rows", q.rows.len() == 5, &format!("len={}", q.rows.len()));
        r.check("sql-a-rank1-30", q.rows[0][0] == "a" && val(&q.rows[0][1]).unwrap_or(0.0) == 30.0 && val(&q.rows[0][2]).unwrap_or(0.0) == 1.0, &format!("{:?}", q.rows[0]));
        r.check("sql-b-rank1-50", q.rows[3][0] == "b" && val(&q.rows[3][1]).unwrap_or(0.0) == 50.0 && val(&q.rows[3][2]).unwrap_or(0.0) == 1.0, &format!("{:?}", q.rows[3]));

        // Cypher: delete
        let _ = try_run(&ex, "CREATE (n:TempNode2502 {val: 1})");
        let _ = try_run(&ex, "CREATE (n:TempNode2502 {val: 2})");
        let _ = try_run(&ex, "MATCH (n:TempNode2502 {val: 1}) DELETE n");
        let cypher = try_run(&ex, "MATCH (n:TempNode2502) RETURN n.val");
        if let Ok(res) = cypher {
            r.check("cypher-1-left", res.rows.len() == 1, &format!("len={}", res.rows.len()));
            r.check("cypher-val-2", val(&res.rows[0][0]).unwrap_or(0.0) == 2.0, &format!("{:?}", res.rows[0]));
        } else {
            r.check("cypher-ok", false, &format!("err={:?}", cypher));
        }

        // CQL: delete
        run(&ex, "CREATE TABLE inv2502ks__cache (k INT, v TEXT, PRIMARY KEY (k))");
        run(&ex, "INSERT INTO inv2502ks__cache (k, v) VALUES (1, 'one')");
        run(&ex, "INSERT INTO inv2502ks__cache (k, v) VALUES (2, 'two')");
        let del = try_run(&ex, "DELETE FROM inv2502ks.cache WHERE k = 1");
        if del.is_ok() {
            let cql = try_run(&ex, "SELECT COUNT(*) FROM inv2502ks.cache ALLOW FILTERING");
            if let Ok(res) = cql {
                r.check("cql-1-left", val(&res.rows[0][0]).unwrap_or(0.0) == 1.0, &format!("{:?}", res.rows));
            }
        }

        r.finish();
    }

