    #[test]
    fn inv2522_polyglot_comprehensive_b161() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: correlated subquery with SUM
        run(&ex, "CREATE TABLE inv2522_budgets (dept TEXT, budget INT)");
        run(&ex, "CREATE TABLE inv2522_expenses (dept TEXT, amount INT)");
        run(&ex, "INSERT INTO inv2522_budgets VALUES ('eng', 1000), ('sales', 500)");
        run(&ex, "INSERT INTO inv2522_expenses VALUES ('eng', 300), ('eng', 400), ('sales', 600)");
        let q = run(&ex, "SELECT b.dept FROM inv2522_budgets b WHERE b.budget >= (SELECT SUM(e.amount) FROM inv2522_expenses e WHERE e.dept = b.dept) ORDER BY b.dept");
        // eng: budget=1000, spent=700 → qualifies. sales: budget=500, spent=600 → over budget
        r.check("sql-1-under", q.rows.len() == 1, &format!("len={}", q.rows.len()));
        r.check("sql-eng", q.rows[0][0] == "eng", &format!("{:?}", q.rows[0]));

        // Cypher: relationship + filter
        let _ = try_run(&ex, "CREATE (a:Dev2522 {name: 'alice'})-[:WORKS_ON]->(p:Proj2522 {name: 'alpha'})");
        let _ = try_run(&ex, "CREATE (b:Dev2522 {name: 'bob'})-[:WORKS_ON]->(q:Proj2522 {name: 'beta'})");
        let cypher = try_run(&ex, "MATCH (d:Dev2522)-[:WORKS_ON]->(p:Proj2522) WHERE p.name = 'alpha' RETURN d.name");
        if let Ok(res) = cypher {
            r.check("cypher-1", res.rows.len() == 1, &format!("len={}", res.rows.len()));
            r.check("cypher-alice", res.rows[0][0] == "alice", &format!("{:?}", res.rows[0]));
        } else {
            r.check("cypher-ok", false, &format!("err={:?}", cypher));
        }

        // CQL: SUM aggregate
        run(&ex, "CREATE TABLE inv2522ks__metrics (id INT, val INT, PRIMARY KEY (id))");
        run(&ex, "INSERT INTO inv2522ks__metrics (id, val) VALUES (1, 10)");
        run(&ex, "INSERT INTO inv2522ks__metrics (id, val) VALUES (2, 20)");
        run(&ex, "INSERT INTO inv2522ks__metrics (id, val) VALUES (3, 30)");
        let cql = try_run(&ex, "SELECT SUM(val) FROM inv2522ks.metrics ALLOW FILTERING");
        if let Ok(res) = cql {
            r.check("cql-sum-60", val(&res.rows[0][0]).unwrap_or(0.0) == 60.0, &format!("{:?}", res.rows));
        } else {
            r.check("cql-ok", false, &format!("err={:?}", cql));
        }

        r.finish();
    }

