    #[test]
    fn inv2542_polyglot_comprehensive_b162() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();

        // SQL: correlated subquery with COUNT + window
        run(&ex, "CREATE TABLE inv2542_projects (proj TEXT, team TEXT)");
        run(&ex, "CREATE TABLE inv2542_tasks (proj TEXT, status TEXT)");
        run(&ex, "INSERT INTO inv2542_projects VALUES ('alpha', 'eng'), ('beta', 'sales')");
        run(&ex, "INSERT INTO inv2542_tasks VALUES ('alpha', 'done'), ('alpha', 'done'), ('alpha', 'open'), ('beta', 'done')");
        let q = run(&ex, "SELECT p.proj, (SELECT COUNT(*) FROM inv2542_tasks t WHERE t.proj = p.proj) AS task_cnt FROM inv2542_projects p ORDER BY p.proj");
        r.check("sql-2-rows", q.rows.len() == 2, &format!("len={}", q.rows.len()));
        r.check("sql-alpha-3", q.rows[0][0] == "alpha" && val(&q.rows[0][1]).unwrap_or(0.0) == 3.0, &format!("{:?}", q.rows[0]));
        r.check("sql-beta-1", q.rows[1][0] == "beta" && val(&q.rows[1][1]).unwrap_or(0.0) == 1.0, &format!("{:?}", q.rows[1]));

        // Cypher: COUNT aggregation
        let _ = try_run(&ex, "CREATE (n:Log2542 {level: 'info', msg: 'boot'})");
        let _ = try_run(&ex, "CREATE (n:Log2542 {level: 'error', msg: 'fail'})");
        let _ = try_run(&ex, "CREATE (n:Log2542 {level: 'info', msg: 'ready'})");
        let cypher = try_run(&ex, "MATCH (n:Log2542) RETURN n.level, COUNT(n) AS cnt ORDER BY n.level");
        if let Ok(res) = cypher {
            r.check("cypher-2-groups", res.rows.len() == 2, &format!("len={}", res.rows.len()));
            r.check("cypher-error-1", res.rows[0][0] == "error" && val(&res.rows[0][1]).unwrap_or(0.0) == 1.0, &format!("{:?}", res.rows[0]));
            r.check("cypher-info-2", res.rows[1][0] == "info" && val(&res.rows[1][1]).unwrap_or(0.0) == 2.0, &format!("{:?}", res.rows[1]));
        } else {
            r.check("cypher-ok", false, &format!("err={:?}", cypher));
        }

        // CQL: AVG aggregate
        run(&ex, "CREATE TABLE inv2542ks__temps (id INT, temp INT, PRIMARY KEY (id))");
        run(&ex, "INSERT INTO inv2542ks__temps (id, temp) VALUES (1, 20)");
        run(&ex, "INSERT INTO inv2542ks__temps (id, temp) VALUES (2, 30)");
        run(&ex, "INSERT INTO inv2542ks__temps (id, temp) VALUES (3, 40)");
        let cql = try_run(&ex, "SELECT AVG(temp) FROM inv2542ks.temps ALLOW FILTERING");
        if let Ok(res) = cql {
            let avg = val(&res.rows[0][0]).unwrap_or(0.0);
            r.check("cql-avg-30", (avg - 30.0).abs() < 0.1, &format!("avg={}", avg));
        } else {
            r.check("cql-ok", false, &format!("err={:?}", cql));
        }

        r.finish();
    }

