        run(&ex, "INSERT INTO inv2561_members VALUES ('alpha','a1'),('alpha','a2'),('alpha','a3'),('beta','b1'),('beta','b2'),('gamma','g1')");
        let q = run(&ex, "SELECT t.name FROM inv2561_teams t WHERE (SELECT COUNT(*) FROM inv2561_members m WHERE m.team = t.name) >= t.min_members ORDER BY t.name");
