/// INV-2570: LEFT JOIN with COALESCE
    #[test]
    fn inv2570_left_join_coalesce() {
        let ex = SimpleQueryExecutor::new();
        let mut r = InvariantReport::new();
        run(&ex, "CREATE TABLE inv2570_customers (id INT, name TEXT)");
        run(&ex, "CREATE TABLE inv2570_orders (cust_id INT, amount REAL)");
        run(&ex, "INSERT INTO inv2570_customers VALUES (1,'alice'),(2,'bob'),(3,'carol')");
        run(&ex, "INSERT INTO inv2570_orders VALUES (1,100),(1,200),(2,50)");
        let q = run(&ex, "SELECT c.name, COALESCE(SUM(o.amount),0) AS total FROM inv2570_customers c LEFT JOIN inv2570_orders o ON c.id=o.cust_id GROUP BY c.name ORDER BY c.name");
        r.check("3-rows", q.rows.len()==3, &format!("rows={}", q.rows.len()));
        r.check("alice-300", val(&q.rows[0][1]).unwrap_or(0.0)==300.0, &format!("alice={:?}", q.rows[0][1]));
        r.check("bob-50", val(&q.rows[1][1]).unwrap_or(0.0)==50.0, &format!("bob={:?}", q.rows[1][1]));
        r.check("carol-0", val(&q.rows[2][1]).unwrap_or(-1.0)==0.0, &format!("carol={:?}", q.rows[2][1]));
        r.finish();
    }

